/// Which outcome a gNB returned for an AMF-initiated MBS procedure.
///
/// Distinguished by the outer NGAP CHOICE index: `0x20` SuccessfulOutcome,
/// `0x40` UnsuccessfulOutcome (TS 38.413 §9.1).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MbsOutcome {
    Successful,
    Unsuccessful,
}

/// Connected gNB session
#[derive(Debug)]
pub struct GnbSession {
    /// gNB ID (assigned by AMF)
    pub id: u64,
    /// SCTP association ID
    pub association_id: u64,
    /// Remote address
    pub addr: SocketAddr,
    /// NGAP FSM for this gNB
    pub fsm: NgapFsm,
    /// gNB context
    pub gnb: AmfGnb,
    /// SCTP info
    pub sctp_info: NextgcoreSctpInfo,
}

impl GnbSession {
    pub fn new(id: u64, association_id: u64, addr: SocketAddr) -> Self {
        Self {
            id,
            association_id,
            addr,
            fsm: NgapFsm::new(id),
            gnb: AmfGnb::new(id, &addr.to_string()),
            sctp_info: NextgcoreSctpInfo::default(),
        }
    }
}

/// #747: the most UE RADIO CAPABILITY ID MAPPING Resolves at the UCMF that run at
/// once. Each is one SBI request; more than this means a gNB is presenting IDs
/// faster than any capability enquiry could produce them.
const MAX_MAPPING_RESOLVES_IN_FLIGHT: usize = 16;

/// A mapping Resolve older than this has its slot released even though its job
/// never reported, so a job that was aborted or panicked cannot hold a slot for
/// the life of the process (#925 review MINOR 2). Comfortably past the SBI
/// client's own request timeout.
const STALE_MAPPING_RESOLVE: Duration = Duration::from_secs(60);

/// One UE radio capability ID being resolved at the UCMF off the NGAP task.
#[derive(Debug)]
pub(crate) struct MappingResolve {
    /// Every association that asked for this ID and has not been answered.
    pub(crate) waiting: Vec<u64>,
    pub(crate) started: Instant,
}

/// GMM procedure timers with retransmission (TS 24.501 Table 10.2.1)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NasProcTimer {
    /// Registration Accept sent, waiting for Registration Complete
    T3550,
    /// Authentication Request / Security Mode Command sent
    T3560,
    /// Identity Request sent
    T3570,
    /// Network-initiated Deregistration Request sent
    T3522,
    /// Configuration Update Command sent, waiting for Configuration Update Complete
    /// (TS 24.501 §5.4.4)
    T3555,
}

impl NasProcTimer {
    fn timer_id(self) -> AmfTimerId {
        match self {
            Self::T3550 => AmfTimerId::T3550,
            Self::T3560 => AmfTimerId::T3560,
            Self::T3570 => AmfTimerId::T3570,
            Self::T3522 => AmfTimerId::T3522,
            Self::T3555 => AmfTimerId::T3555,
        }
    }

    fn config(self, configs: &AmfTimerConfigs) -> (u32, Duration) {
        configs
            .get(self.timer_id())
            .map(|c| (c.max_count, c.duration))
            .unwrap_or((4, Duration::from_secs(6)))
    }

    /// Issue #18 (non-normative NTN research): extend `base` by the UE's
    /// satellite round-trip delay when a valid TimingAdvance is present.
    #[cfg(feature = "ntn")]
    fn ntn_compensated(
        self,
        configs: &AmfTimerConfigs,
        base: Duration,
        ta: Option<nextgcore_proto::TimingAdvance>,
    ) -> Duration {
        // Per-UE advance wins; otherwise fall back to the per-AMF default.
        let Some(ta) = ta.or(configs.ntn_default_timing_advance) else {
            return base;
        };
        // Prefer the TimerConfig method; if a future timer has no config
        // entry (config() substitutes a fallback duration for that case),
        // compensate the passed-in base directly instead of silently
        // skipping the extension.
        let compensated = match configs.get(self.timer_id()) {
            Some(config) => config.with_ntn_compensation(&ta),
            None if ta.valid => base + Duration::from_micros(u64::from(ta.value_us) * 2),
            None => base,
        };
        if compensated != base {
            log::debug!(
                "NTN: {} duration {:?} -> {:?} (timing advance {}us)",
                self.timer_id().name(),
                base,
                compensated,
                ta.value_us
            );
        }
        compensated
    }
}

/// Choose an ngKSI for a new NAS security context that the UE is not already using
/// (TS 24.501 §5.4.1.3.2).
///
/// `ue_ksi` is the value the UE reported in its Registration Request. ngKSI values
/// 0..=6 identify a key set; 7 is the reserved "no key is available" value and is
/// therefore never SELECTED, only accepted as input.
///
/// Returns `ue_ksi + 1` modulo the 0..=6 range, which is the smallest change that is
/// guaranteed distinct. Distinctness is the whole requirement: the spec asks for "a
/// value different from any in use", and the UE holds at most one 5G context.
fn select_ngksi(ue_ksi: u8) -> u8 {
    const NO_KEY_AVAILABLE: u8 = 7;
    if ue_ksi >= NO_KEY_AVAILABLE {
        // The UE holds no key, so every identifier is free; 0 is the conventional first.
        return 0;
    }
    (ue_ksi + 1) % NO_KEY_AVAILABLE
}

/// What TS 24.501 §4.4.4.3 says to do with a message whose integrity check failed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum IntegrityFailureAction {
    /// Re-run authentication; nothing from the message is applied.
    Reauthenticate,
    /// Answer SERVICE REJECT with 5GMM cause #9.
    ServiceReject,
    /// Discard, which is the rule for everything §4.4.4.3 does not except.
    Discard,
}

/// Map a MAC-failed message to its §4.4.4.3 action.
///
/// Pure, and separate from the handler, because this mapping IS the conformance
/// requirement: it can then be asserted over its whole domain rather than by driving one
/// message through a server. `has_context` distinguishes the two cases the spec does --
/// the exceptions apply to a message arriving on an EXISTING security context; without
/// one there is nothing to have failed against and nothing to re-authenticate.
fn integrity_failure_action(msg_type: u8, has_context: bool) -> IntegrityFailureAction {
    if !has_context {
        return IntegrityFailureAction::Discard;
    }
    match msg_type {
        message_type::REGISTRATION_REQUEST => IntegrityFailureAction::Reauthenticate,
        message_type::SERVICE_REQUEST => IntegrityFailureAction::ServiceReject,
        _ => IntegrityFailureAction::Discard,
    }
}

/// Whether NAS-based 5G-GUTI reallocation (the UE Configuration Update procedure) is
/// enabled. Off unless `AMF_GUTI_REALLOCATION` is set to a truthy value.
/// T3513, the paging timer (TS 24.501 §5.6.2.2.1, Table 10.2.2: "network
/// dependent"). 5 s unless `AMF_T3513_SECS` overrides it; `AMF_T3513_MILLIS`
/// exists so tests can run the full retransmission ladder quickly.
fn paging_t3513() -> Duration {
    if let Some(ms) = std::env::var("AMF_T3513_MILLIS")
        .ok()
        .and_then(|v| v.trim().parse::<u64>().ok())
    {
        return Duration::from_millis(ms);
    }
    let secs = std::env::var("AMF_T3513_SECS")
        .ok()
        .and_then(|v| v.trim().parse::<u64>().ok())
        .unwrap_or(5);
    Duration::from_secs(secs)
}

/// The plain SERVICE REQUEST inside an initial NAS message, if that is what it is:
/// either sent plain, or integrity protected (security header type 1, TS 24.501
/// §9.3.1) with the plain message after the 6-octet MAC/SQN header.
fn initial_service_request_plain(nas: &[u8]) -> Option<Vec<u8>> {
    match nas.get(1).copied()? {
        security_header::PLAIN_NAS_MESSAGE
            if nas.get(2) == Some(&message_type::SERVICE_REQUEST) =>
        {
            Some(nas.to_vec())
        }
        0x01 if nas.len() >= 10 && nas[7] == 0x7E && nas[9] == message_type::SERVICE_REQUEST => {
            Some(nas[7..].to_vec())
        }
        _ => None,
    }
}

/// The cleartext REGISTRATION REQUEST inside an integrity-protected initial NAS
/// message (security header type 1, TS 24.501 §4.4.6, §9.3.1): the plain message after
/// the 6-octet MAC/SQN header. A UE with a NAS security context sends its mobility and
/// periodic registration updates from 5GMM-IDLE in this form (#609).
fn initial_protected_registration_request(nas: &[u8]) -> Option<&[u8]> {
    (nas.len() >= 10
        && nas[1] == 0x01
        && nas[7] == 0x7E
        && nas[8] == security_header::PLAIN_NAS_MESSAGE
        && nas[9] == message_type::REGISTRATION_REQUEST)
        .then(|| &nas[7..])
}

/// The NAS message container IE of a plain REGISTRATION REQUEST (IEI 0x71, TLV-E,
/// TS 24.501 §9.11.3.33): the byte span of the whole IE in `plain`, and its value.
/// Decoded with the shared NAS codec, so the IE is found by structure rather than by
/// scanning for its IEI.
fn registration_request_container(plain: &[u8]) -> Option<(std::ops::Range<usize>, Vec<u8>)> {
    use nextgcore_nas::fiveg::message::{parse_5gmm_message, FiveGmmMessage};
    let Ok(FiveGmmMessage::RegistrationRequest(req)) =
        parse_5gmm_message(&mut bytes::Bytes::copy_from_slice(plain))
    else {
        return None;
    };
    let value = req.nas_message_container?.data;
    let len = u16::try_from(value.len()).ok()?;
    let mut ie = vec![0x71];
    ie.extend_from_slice(&len.to_be_bytes());
    ie.extend_from_slice(&value);
    let start = plain.windows(ie.len()).rposition(|w| w == ie.as_slice())?;
    Some((start..start + ie.len(), value))
}

/// The Service type of a plain SERVICE REQUEST (TS 24.501 §9.11.3.50). Octet 4
/// carries two half-octet IEs; Table 8.2.16.1.1 lists ngKSI first and §8.1 puts
/// the first of a half-octet run in bits 1-4, so ngKSI is bits 1-4 and Service
/// type bits 5-8 (0x20 = mobile terminated services, ngKSI 0). #537.
fn service_request_service_type(plain: &[u8]) -> Option<u8> {
    plain.get(3).map(|octet| (octet >> 4) & 0x0F)
}

/// The 5G-S-TMSI a SERVICE REQUEST identifies the UE with (TS 24.501 §8.2.16:
/// a 5GS mobile identity LV-E after the ngKSI/service-type octet; §9.11.3.4:
/// type 0b100, AMF Set ID 10 bits, AMF Pointer 6 bits, 5G-TMSI 32 bits).
/// Returns (AMF Set ID, AMF Pointer, 5G-TMSI).
fn service_request_s_tmsi(plain: &[u8]) -> Option<(u16, u8, u32)> {
    let len = u16::from_be_bytes([*plain.get(4)?, *plain.get(5)?]) as usize;
    let id = plain.get(6..6 + len)?;
    if len != 7 || id[0] & 0x07 != 0x04 {
        return None;
    }
    let amf_set_id = (u16::from(id[1]) << 2) | u16::from(id[2] >> 6);
    let amf_pointer = id[2] & 0x3F;
    let tmsi = u32::from_be_bytes([id[3], id[4], id[5], id[6]]);
    Some((amf_set_id, amf_pointer, tmsi))
}

/// Record PDU session `psi` of `amf_ue_ngap_id` in the AMF context's session
/// store -- where the Namf N1N2MessageTransfer handler and the Service Request's
/// re-activation find it (#540) -- unless it is already there. Returns whether the
/// session is recorded: `false` when the table is full (#756).
fn record_amf_session(
    amf_ue_ngap_id: u64,
    psi: u8,
    sm_context_ref: &str,
    sst: u8,
    sd: Option<u32>,
) -> bool {
    let ctx = crate::context::amf_self();
    let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
    let sess = match guard.sess_find_by_psi(amf_ue_ngap_id, psi) {
        Some(sess) => Some(sess),
        None => guard.sess_add(amf_ue_ngap_id, psi),
    };
    match sess {
        Some(mut sess) => {
            sess.sm_context_ref = Some(sm_context_ref.to_string());
            sess.s_nssai.sst = sst;
            sess.s_nssai.sd = sd;
            guard.sess_update(&sess);
            true
        }
        // #756: not silent. Without this record, paging, N1N2 and Service Request
        // re-activation cannot find the session; the caller refuses it.
        None => {
            log::error!(
                "UE {amf_ue_ngap_id}: PDU session {psi} (SM context {sm_context_ref}) NOT \
                 recorded: the AMF session table is full"
            );
            false
        }
    }
}

/// Clear the paging state the N1N2 transfer set on the paged PDU session
/// (`AmfSess::store_paging_info`), once paging has ended either way.
fn clear_session_paging(paging: &crate::context::PagingContext) {
    let Some(psi) = paging.pdu_session_id else {
        return;
    };
    let ctx = crate::context::amf_self();
    let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
    if let Some(mut sess) = guard.sess_find_by_psi(paging.amf_ue_ngap_id, psi) {
        sess.clear_paging_info();
        guard.sess_update(&sess);
    }
}

fn guti_reallocation_enabled() -> bool {
    std::env::var("AMF_GUTI_REALLOCATION")
        .map(|v| matches!(v.trim(), "1" | "true" | "TRUE" | "yes" | "on"))
        .unwrap_or(false)
}

/// Pending retransmission of a downlink NAS message
#[derive(Debug, Clone)]
struct NasRetx {
    /// Which procedure timer this is
    timer: NasProcTimer,
    /// When the timer expires next
    deadline: Instant,
    /// Number of retransmissions already performed
    retries: u32,
    /// The complete NGAP Downlink NAS Transport PDU to resend
    ngap_pdu: Vec<u8>,
}

/// Which reachability supervision timer is running for an idle registered UE
/// (TS 24.501 §5.3.7).
///
/// The two run in sequence, never together: the mobile reachable timer bounds how long
/// the network waits for a UE that has gone idle, and only when THAT expires does the
/// implicit deregistration timer start. Modelling them as one deadline plus a phase makes
/// the ordering structural rather than something two independent timers have to agree on.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReachabilityPhase {
    /// Mobile reachable timer running; on expiry the implicit-dereg timer starts.
    MobileReachable,
    /// Implicit deregistration timer running; on expiry the UE is deregistered.
    ImplicitDeregistration,
}

/// A running reachability timer for one idle UE.
#[derive(Debug, Clone, Copy)]
struct Reachability {
    phase: ReachabilityPhase,
    deadline: Instant,
}

/// Per-UE NAS/registration state for the live NGAP path.
///
/// `amf_ue` carries the full 5G NAS security context (keys, COUNTs,
/// replayed UE security capabilities, GUTI) so that all downlink NAS is
/// built by gmm_build and protected by nas_security — there is no inline
/// plain-NAS path.
#[derive(Clone)]
pub struct UeNasContext {
    /// Full AMF UE context (security keys, capabilities, GUTI, NSSAI).
    ///
    /// `pub(crate)` so `AmfContext::amf_ue_update` can write THROUGH to the live
    /// store (#341): a Namf handler that mutated a UE and stored it only in
    /// `amf_ue_list` would not see its own change on the next resolve. The rest of
    /// the record stays private -- the NAS/registration fields belong to this
    /// module's state machine, not to the SBI layer.
    pub(crate) amf_ue: AmfUe,
    /// AUSF auth context ID (for 5G-AKA confirmation)
    auth_ctx_id: String,
    /// RAN UE NGAP ID (for building DL NAS Transport)
    ran_ue_ngap_id: u32,
    /// SCTP association ID
    association_id: u64,
    /// SUCI string
    suci: String,
    /// AUTN of the last authentication vector (for resync bookkeeping)
    autn: [u8; 16],
    /// Registration procedure completed (Registration Complete received)
    registered: bool,
    /// Identity Request for PEI outstanding
    pei_requested: bool,
    /// Count of authentication failures (MAC #20 / sync #21) seen
    auth_failure_count: u8,
    /// Pending NAS retransmission (T3550/T3555/T3560/T3570/T3522)
    retx: Option<NasRetx>,
    /// Running reachability supervision (TS 24.501 §5.3.7). `None` while the UE has a
    /// live N1 signalling connection: a UE the AMF can reach needs no supervision.
    reachability: Option<Reachability>,
    /// CM-IDLE (TS 23.501 §5.3.3.2.2): the N1 signalling connection was released
    /// (UE Context Release Complete) and the UE has not come back with a Service
    /// Request. Independent of `reachability`, whose timer can be disabled.
    cm_idle: bool,
    /// UDM SDM subscription ID (from Nudm_SDM_Subscribe)
    sdm_subscription_id: Option<String>,
    /// PCF AM policy association ID (from Npcf_AMPolicyControl_Create)
    policy_association_id: Option<String>,
    /// PCF UE Policy Association ID (from Npcf_UEPolicyControl_Create,
    /// TS 29.525 — Wave-6 E7); deleted at deregistration
    ue_policy_association_id: Option<String>,
    /// Per-UE GMM state machine (TS 24.501): tracks the registration phase,
    /// including the InitialContextSetup wait after the ICS Request is sent.
    gmm_fsm: GmmFsm,
    /// Initial Context Setup Request has been sent to the gNB; the registration
    /// is only established once the ICS Response arrives (TS 38.413 §8.3.1).
    initial_context_setup_request_sent: bool,
    /// Initial Context Setup Response received from the gNB.
    initial_context_setup_response_received: bool,
    /// Whether the Registration Accept has left the AMF for this UE (#91).
    ///
    /// Gates the UE-policy association create, because creating it is what makes the
    /// PCF deliver the DL MANAGE UE POLICY COMMAND, and that must not precede the
    /// Accept (TS 23.502 §4.2.4.3 against §4.2.2.2.2). A flag rather than trusting the
    /// call order: an invariant a future caller cannot accidentally break is worth one
    /// bool, and it makes the ordering assertable without an SCTP peer.
    registration_accept_sent: bool,
    /// The UE policy container from the Registration Request, if the UE sent one
    /// (#91, TS 24.501 §5.5.1.2.2).
    ///
    /// Held here rather than acted on at parse time because the PCF association it
    /// belongs to is created later in the procedure, and because it must survive the
    /// authentication round trips in between.
    ue_policy_container: Option<Vec<u8>>,
}

/// Manual `Debug` (no-auth-material-in-logs): the authentication material in
/// this type (autn) prints as `<redacted>`, so a future
/// `{:?}` in a log line cannot leak it.
impl std::fmt::Debug for UeNasContext {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mut d = f.debug_struct("UeNasContext");
        d.field("amf_ue", &self.amf_ue);
        d.field("auth_ctx_id", &self.auth_ctx_id);
        d.field("ran_ue_ngap_id", &self.ran_ue_ngap_id);
        d.field("association_id", &self.association_id);
        d.field("suci", &self.suci);
        d.field("autn", &"<redacted>");
        d.field("registered", &self.registered);
        d.field("pei_requested", &self.pei_requested);
        d.field("auth_failure_count", &self.auth_failure_count);
        d.field("retx", &self.retx);
        d.field("reachability", &self.reachability);
        d.field("cm_idle", &self.cm_idle);
        d.field("sdm_subscription_id", &self.sdm_subscription_id);
        d.field("policy_association_id", &self.policy_association_id);
        d.field("ue_policy_association_id", &self.ue_policy_association_id);
        d.field("gmm_fsm", &self.gmm_fsm);
        d.field(
            "initial_context_setup_request_sent",
            &self.initial_context_setup_request_sent,
        );
        d.field(
            "initial_context_setup_response_received",
            &self.initial_context_setup_response_received,
        );
        d.field("registration_accept_sent", &self.registration_accept_sent);
        d.field("ue_policy_container", &self.ue_policy_container);
        d.finish()
    }
}

impl UeNasContext {
    /// Publish an `AmfUe` into the live store as a registered UE (#341).
    ///
    /// The seam the Namf surface needs: before #341 a UE existed in
    /// `AmfContext::amf_ue_list` (which only tests wrote) and the SBI handlers
    /// resolved against that, so nothing a test seeded there was reachable from
    /// the live store and nothing the NGAP path registered was reachable from the
    /// handlers. One store means one publish path, and this is it.
    ///
    /// `registered` is set because a caller publishing a full `AmfUe` is
    /// describing a UE that has completed registration -- an unregistered UE has
    /// no SUPI to resolve by, which is the whole point of the derived resolvers.
    pub fn published(amf_ue: AmfUe, ran_ue_ngap_id: u32, association_id: u64) -> Self {
        let mut ctx = Self::new(
            amf_ue.id,
            ran_ue_ngap_id,
            association_id,
            amf_ue.use_nextgcore_nas_security,
        );
        ctx.suci = amf_ue.suci.clone().unwrap_or_default();
        // A record published without a RAN UE context has no N1 connection.
        ctx.cm_idle = amf_ue.ran_ue_id == crate::context::NEXTGCORE_INVALID_POOL_ID;
        ctx.amf_ue = amf_ue;
        ctx.registered = true;
        ctx
    }
}

impl crate::ue_store::UeIdentity for UeNasContext {
    fn amf_ue(&self) -> &AmfUe {
        &self.amf_ue
    }

    fn ran_ue_ngap_id(&self) -> u32 {
        self.ran_ue_ngap_id
    }
}

impl UeNasContext {
    /// CM-IDLE: the N1 connection was released (set at UE Context Release
    /// Complete, cleared when the UE comes back with a Service Request).
    pub(crate) fn is_cm_idle(&self) -> bool {
        self.cm_idle
    }

    /// Create a per-UE NAS context. `use_nextgcore_nas_security` is the Wave-6
    /// H9 runtime canary applied to the fresh `AmfUe`: the production caller
    /// passes `crate::context::nas_security_canary()` (the process-wide setting,
    /// default OFF); tests pass an explicit `false` to keep the legacy path.
    fn new(
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        association_id: u64,
        use_nextgcore_nas_security: bool,
    ) -> Self {
        let mut amf_ue = AmfUe::new(amf_ue_ngap_id, ran_ue_ngap_id as u64);
        amf_ue.use_nextgcore_nas_security = use_nextgcore_nas_security;
        Self {
            amf_ue,
            auth_ctx_id: String::new(),
            ran_ue_ngap_id,
            association_id,
            suci: String::new(),
            autn: [0u8; 16],
            registered: false,
            pei_requested: false,
            auth_failure_count: 0,
            retx: None,
            reachability: None,
            sdm_subscription_id: None,
            policy_association_id: None,
            ue_policy_association_id: None,
            gmm_fsm: GmmFsm::new(amf_ue_ngap_id),
            initial_context_setup_request_sent: false,
            initial_context_setup_response_received: false,
            registration_accept_sent: false,
            ue_policy_container: None,
            cm_idle: false,
        }
    }
}

/// What [`NgapServer::create_ue_policy_association`] decided (#91).
///
/// Returned rather than only logged so the ORDERING invariant is assertable without an
/// SCTP peer or a live PCF: `Skipped` names why, and `Attempted` means the guard passed
/// and the SBI call was made. Whether that call SUCCEEDED is a property of the PCF and
/// not of this decision, which is the same split #70 recorded.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UePolicyCreate {
    /// The create was not attempted; the `&'static str` says why.
    Skipped(&'static str),
    /// The guard passed and `Npcf_UEPolicyControl_Create` was called.
    Attempted,
}

/// NGAP Server - handles all gNB connections via SCTP
pub struct NgapServer {
    /// SCTP transport (userspace sctp-proto or native kernel SCTP)
    transport: NgapTransport,
    /// Bind address
    bind_addr: SocketAddr,
    /// Connected gNB sessions (keyed by SCTP association ID)
    sessions: Arc<RwLock<HashMap<u64, GnbSession>>>,
    /// Association ID to address mapping
    assoc_to_addr: Arc<RwLock<HashMap<u64, SocketAddr>>>,
    /// Next gNB ID
    next_gnb_id: Arc<Mutex<u64>>,
    /// Test seam: the AMF UE NGAP ID the next Initial UE Message takes instead of
    /// one from the allocator, so a test can key its assertions on a known value.
    #[cfg(test)]
    forced_amf_ue_ngap_id: Option<u64>,
    /// Test seam: when `Some`, every NGAP PDU `send_to_association` would put on the
    /// wire is recorded here as `(association_id, sctp_stream_id, pdu)` instead, and
    /// the send succeeds. Lets a handler test assert what amfd SENDS, and to whom, without a
    /// live SCTP association. `None` (the default) keeps the real transport.
    #[cfg(test)]
    sent_ngap: Option<Vec<(u64, u16, Vec<u8>)>>,
    /// Each association's negotiated outbound stream count, asked of the transport once
    /// (#813); removed when the association closes.
    outbound_streams: std::collections::HashMap<u64, Option<u16>>,
    /// Test seam: the negotiated outbound stream count the capture reports for every
    /// association (a captured send has no SCTP association to ask). Default 2, amfd's
    /// configured count (#813).
    #[cfg(test)]
    test_outbound_streams: u16,
    /// Test seam: the next this-many NGAP sends fail as an SCTP send error would,
    /// so a test can drive a handler's send-failure branch (#760).
    #[cfg(test)]
    fail_next_sends: usize,
    /// Test seam: the next PDU session record fails as a full session table
    /// would (#756 review m1), without filling the process-global table.
    #[cfg(test)]
    fail_next_session_record: bool,
    /// Event sender for NGAP events
    event_tx: mpsc::Sender<AmfEvent>,
    /// Server event receiver
    server_event_rx: mpsc::UnboundedReceiver<ServerEvent>,
    /// The one authoritative live-UE store, keyed by AMF-UE-NGAP-ID (#341).
    ///
    /// Shared with [`crate::context::AmfContext`] rather than owned here: this map
    /// used to be a private `HashMap` on this struct, which the whole NGAP
    /// registration path wrote and only this receive loop read, while every Namf
    /// SBI handler resolved against a SECOND set of collections in the context
    /// that only tests ever wrote. Production reader, test-only writer -- so a UE
    /// that had really registered got `404 CONTEXT_NOT_FOUND` from
    /// N1N2MessageTransfer, EnableUeReachability, ProvideDomainSelectionInfo and
    /// per-UE EventExposure. One `Arc` to one store is what makes those answer.
    ///
    /// Accessed only through [`crate::ue_store::UeStore`]'s methods, none of which
    /// hands out a guard: the lock is `std::sync::RwLock`, so a guard held across
    /// an `.await` would not compile, and a closure that re-entered the store
    /// would deadlock without failing to compile. See that module's docs.
    ue_auth_state: std::sync::Arc<crate::ue_store::UeStore<UeNasContext>>,
    /// SM context reference the SMF returned from Nsmf_PDUSession_CreateSMContext,
    /// keyed by (AMF-UE-NGAP-ID, PSI).
    ///
    /// The ref is opaque and SMF-chosen (TS 29.502 §5.2.2.2.1: the AMF must use
    /// the URI/reference from the Create response). It is NOT derivable from the
    /// PSI: this SMF allocates a monotonic session index, so the second PDU
    /// session in an AMF's lifetime is ref="2" while its PSI is still 1.
    /// Fabricating `format!("{psi}")` therefore addressed session 1 forever --
    /// every SM Context Update after the first landed on the wrong N4 session,
    /// so the downlink FAR (gNB TEID) was installed on a stale session and
    /// downlink user traffic was silently black-holed.
    sm_context_refs: HashMap<(u64, u8), String>,
    /// #747: the UE RADIO CAPABILITY ID MAPPING Resolves running off this task
    /// (through `sbi_offload`), by the ID being resolved, each with the
    /// associations waiting for that ID's answer and when the lookup started.
    /// Capped at [`MAX_MAPPING_RESOLVES_IN_FLIGHT`] IDs.
    ///
    /// Keyed by ID rather than counted (#925 review MINOR 2 and 3): many gNBs
    /// asking for one popular ID start ONE Resolve and all get its answer, and
    /// the slot is released by the outcome the job always reports, so no counter
    /// can be left incremented. [`STALE_MAPPING_RESOLVE`] bounds a slot whose
    /// job never reports at all.
    pub(crate) mapping_resolves: HashMap<Vec<u8>, MappingResolve>,
    /// The SMF that holds each SM context, as (host, port) (#669). Written beside
    /// `sm_context_refs` at Create; Update/Release go here rather than to
    /// `SMF_SBI_ADDR`, which after an SMF restart may still route to the old pod
    /// and with several SMFs names the wrong one.
    sm_context_smfs: HashMap<(u64, u8), (String, u16)>,
    /// The target gNB's SCTP association for a UE with an N2 handover in flight,
    /// keyed by AMF-UE-NGAP-ID.
    ///
    /// Recorded when the target admits the UE (HandoverRequestAcknowledge) and
    /// dropped when the handover completes, is cancelled, or fails. It exists for
    /// UPLINK RAN STATUS TRANSFER (TS 38.413 §8.4.7): the source gNB sends the
    /// PDCP SN/HFN status *after* the HandoverCommand, and the AMF has to know
    /// where to forward it. `ue_auth_state` cannot answer that — it still names
    /// the SOURCE association until the UE arrives.
    ///
    /// The value is `(target association, target RAN UE NGAP ID)`. The RAN UE NGAP ID
    /// is the one the TARGET allocated and returned in the Acknowledge (TS 38.413
    /// §8.4.2.2, §9.2.3.5): each gNB allocates its own, so the DOWNLINK RAN STATUS
    /// TRANSFER to the target must carry it, not the source's (#740).
    handover_target_assoc: HashMap<u64, (u64, u32)>,
    /// The target gNB's per-session handover transfers, kept between
    /// HandoverRequestAcknowledge and HandoverNotify (#70).
    ///
    /// Keyed by `(amf_ue_ngap_id, pdu_session_id)`. TS 23.502 §4.9.1.3.3 has the AMF tell
    /// the SMF about the target DL tunnel only once the UE has ARRIVED (step 12,
    /// `HANDOVER_COMPLETE`) — switching earlier would blackhole downlink traffic while the
    /// UE is still on the source. So the transfer has to survive between the two messages,
    /// and before #70 nothing kept it: HandoverNotify mutated in-memory serving state and
    /// told the SMF nothing at all.
    handover_target_transfers: HashMap<(u64, u8), Vec<u8>>,
    /// The target association the current intra-5GS HANDOVER REQUEST of a UE went to,
    /// keyed by AMF-UE-NGAP-ID (#742 review). Recorded when the request is sent; an
    /// Acknowledge or a Failure from any OTHER association -- a target whose
    /// preparation was cancelled or superseded answering late -- is ignored, so it can
    /// neither command the source nor bring back that target's session transfers.
    handover_pending_target: HashMap<u64, u64>,
    /// The PDU sessions an intra-5GS HandoverRequest offered the target, per UE (#804,
    /// #964): the sessions a cancel or failure tells the SMF CANCELLED.
    handover_prepared_psis: HashMap<u64, Vec<u8>>,
    /// Intra-5GS preparations waiting for their SMFs' Handover Request Transfers (#964).
    ho_preparations: HashMap<u64, HoPreparation>,
    /// Acknowledges waiting for their SMFs' Handover Command Transfers (#964).
    ho_commands: HashMap<u64, HoCommandPending>,
    /// The PDU sessions the source listed in its HandoverRequired, per UE (#964): each
    /// one not handed over goes in the HANDOVER COMMAND's release list.
    handover_listed_psis: HashMap<u64, Vec<u8>>,
    /// The sessions a HANDOVER COMMAND released rather than handed over, per UE (#964):
    /// their user plane is deactivated at the SMF once the UE has moved.
    handover_dropped_psis: HashMap<u64, Vec<u8>>,
    /// Distinguishes one N2 handover step's SMF answers from a later one's (#964).
    ho_generation: u64,
    /// Source NG-RAN releases a HandoverNotify deferred to the step 6a timer (#806).
    pending_source_releases: Vec<PendingSourceRelease>,
    /// The step 6a timer (TS 23.502 §4.9.1.3.3): how long after the Handover Notify the
    /// source NG-RAN is kept before step 14a releases it (#806).
    /// `AMF_HANDOVER_SOURCE_HOLD_MS`, default 2000; 0 releases at the Notify.
    handover_source_hold: Duration,
    /// The sessions the target admitted that are not handed over, per UE (#964 review):
    /// released at the target, by PDU Session Resource Release Command, once the UE has
    /// arrived there.
    handover_target_release_psis: HashMap<u64, Vec<u8>>,
    /// The sessions of the current preparation already told CANCELLED, per UE, so a
    /// session is cancelled once whichever path gets there first (#964 review).
    handover_cancelled_psis: HashMap<u64, HashSet<u8>>,
    /// TS 23.502 §4.9.1.3.2 step 8: the longest the AMF waits for the SMFs' PREPARING
    /// answers before it continues with the sessions that answered (#964 review).
    /// `AMF_HANDOVER_PREPARATION_SMF_WAIT_MS`, default 1000.
    ho_preparation_wait: Duration,
    /// The same supervision for the PREPARED answers to a target's Acknowledge, which
    /// count against the source's TNGRELOCoverall (#964 review).
    /// `AMF_HANDOVER_COMMAND_SMF_WAIT_MS`, default 1000.
    ho_command_wait: Duration,
    /// EPS→5GS handovers in flight, keyed by the AMF UE NGAP ID allocated for the
    /// arriving UE (#418).
    ///
    /// Set when the HandoverRequest goes to the target gNB (TS 23.502 §4.11.1.2.2.2 step 9)
    /// and taken when the procedure ends: at HandoverFailure, or at HandoverNotify once the
    /// Forward Relocation Complete Notification has gone to the MME. It is what tells the
    /// HandoverRequestAcknowledge handler that the answer goes to an MME over N26 rather
    /// than to a source gNB as a HandoverCommand.
    eps_ho_in_flight: HashMap<u64, EpsHoInFlight>,
    /// GMM procedure timer configuration (T3550/T3560/T3570/T3522)
    timer_configs: AmfTimerConfigs,
    /// Emergency services state (TS 23.167, TS 24.501 §5.5.1.2). Held by the server so
    /// an emergency registration has somewhere to record its context; before this the
    /// handler was constructed only inside its own unit tests.
    emergency: crate::emergency::EmergencyHandler,
    /// Whether an NGAP Overload Start has been broadcast and not yet stopped, so the
    /// signal is sent on transitions only (TS 38.413 §8.7.6/§8.7.7).
    ngap_overload_declared: bool,
    /// When `sweep_orphaned_session_state` last ran (#756).
    last_session_sweep: std::time::Instant,
    /// PDU Session Establishment Requests whose CreateSMContext found no SMF
    /// reachable (#796), keyed by (AMF UE NGAP ID, PSI), retried until
    /// [`ESTABLISHMENT_RETRY_WINDOW`] has passed. See
    /// [`NgapServer::process_pending_establishments`].
    pending_establishments: HashMap<(u64, u8), PendingEstablishment>,
    /// SBI work run off this task (#796 review M1): the re-selection attempts.
    sbi_offload: crate::sbi_offload::SbiOffload,
    /// AMF UE NGAP IDs this AMF allocated to an NG connection that has no NAS
    /// context, with the (association, RAN UE NGAP ID) they were allocated on (#758).
    /// Today that is a CM-IDLE Service Request answered SERVICE REJECT #9: the UE,
    /// as told, registers afresh on the same connection, and only then may the
    /// Uplink NAS Transport create a context under the ID. Bounded by
    /// [`MAX_CONTEXTLESS_UE_IDS`], oldest first.
    contextless_ue_ids: std::collections::VecDeque<ContextlessUeId>,
}

/// A PDU Session Establishment Request waiting for a reachable SMF (#796).
#[derive(Debug, Clone)]
struct PendingEstablishment {
    association_id: u64,
    ran_ue_ngap_id: u32,
    /// The UE's 5GSM message, sent again unchanged.
    sm_pdu: Vec<u8>,
    dnn_override: Option<String>,
    /// When the first attempt failed. The window is measured from here, so a
    /// UE retransmission (T3580) does not extend it.
    first_failure: std::time::Instant,
    /// When the next attempt is due.
    next_attempt: std::time::Instant,
    /// Whether an attempt is running off the NGAP task. Its outcome comes back
    /// through [`NgapServer::process_sbi_outcomes`].
    in_flight: bool,
    /// Identifies this waiting request, so a late outcome of an attempt for an
    /// earlier one (answered #90, then requested again) is not applied to it.
    generation: u64,
    /// The establishment's `3gpp-Sbi-Origination-Timestamp`, stamped when its
    /// first CreateSMContext went out and sent unchanged on every retry (#980
    /// review, TS 29.502 §6.1.2.3.2).
    origination_timestamp: String,
}

/// Source of [`PendingEstablishment::generation`].
static ESTABLISHMENT_GENERATION: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(1);

/// One off-task re-selection attempt for a waiting PDU Session Establishment
/// (#796), as it comes back to the NGAP task.
#[derive(Debug)]
pub(crate) struct EstablishmentAttempt {
    amf_ue_ngap_id: u64,
    psi: u8,
    generation: u64,
    sst: u8,
    sd: Option<u32>,
    dnn: Option<String>,
    /// The SMF the attempt was sent to, for releasing a context nobody wants.
    smf: (String, u16),
    result: Result<crate::sbi_path::SmContextCreateResponse, crate::sbi_path::SbiError>,
}

/// The longest a re-activation waits for an NG Reset's DEACTIVATED still on the wire
/// for the same session (#754, with #877's bounded `settle_key`): inside the UE's T3517
/// (15 s), so the Service Accept still arrives in time.
const NG_RESET_SETTLE_MAX_WAIT: Duration = Duration::from_secs(5);

/// How many SBI exchanges run off the NGAP task at once (#796 review M1).
const MAX_OFFLOADED_SBI: usize = 16;

/// How long the AMF keeps re-selecting an SMF for an establishment it could not
/// deliver (#796). Below the UE's T3580 (16 s, TS 24.501 §10.3), so the UE gets
/// an answer before it retransmits. An SMF restarting in place is back well
/// within it.
const ESTABLISHMENT_RETRY_WINDOW: Duration = Duration::from_secs(12);
/// The spacing of the re-selection attempts within the window.
const ESTABLISHMENT_RETRY_INTERVAL: Duration = Duration::from_secs(1);
/// At most this many establishments wait at once. Beyond it, one is answered
/// at once (5GMM #90), as before the window existed.
const MAX_PENDING_ESTABLISHMENTS: usize = 1024;

/// Whether a CreateSMContext failure means no SMF could be reached, as opposed to
/// an SMF that answered (#796). Only the former is worth re-selecting for.
fn smf_unreachable(e: &crate::sbi_path::SbiError) -> bool {
    use crate::sbi_path::SbiError;
    match e {
        SbiError::Timeout
        | SbiError::GatewayTimeout
        | SbiError::NfInstanceNotFound
        | SbiError::ServiceNotFound(_) => true,
        // `call_smf_create_sm_context` reports a transport failure as "SMF request
        // failed: ..." and an SMF that answered as "SMF returned status ...".
        SbiError::RequestFailed(m) => m.starts_with("SMF request failed"),
        _ => false,
    }
}

/// What [`NgapServer::take_contextless_ue_id`] found (#758).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContextlessLookup {
    /// Allocated to this association and RAN UE NGAP ID.
    Matches,
    /// Allocated to this association, but to another RAN UE NGAP ID.
    Inconsistent,
    /// Never allocated without a context on this association (or no longer
    /// remembered).
    Unknown,
}

/// An AMF UE NGAP ID allocated to an NG connection that has no NAS context (#758).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct ContextlessUeId {
    amf_ue_ngap_id: u64,
    association_id: u64,
    ran_ue_ngap_id: u32,
}

/// How many [`ContextlessUeId`]s the AMF remembers (#758). A UE re-registers
/// within seconds of its SERVICE REJECT. The bound only stops a gNB that sends
/// Service Requests nobody can resolve from growing the list without limit.
const MAX_CONTEXTLESS_UE_IDS: usize = 4096;

impl NgapServer {
    /// Create a new NGAP server on the selected SCTP backend.
    ///
    /// Reads the AMF context through [`crate::context::amf_self`] rather than taking an
    /// injected one. Before #363 it took an `Arc<tokio::sync::RwLock<AmfContext>>` that
    /// was a *second, distinct* instance from the global, so this module read two
    /// different `AmfContext`s a few lines apart -- 8 sites from the injected one and 23
    /// from the global -- and every setting the config loader wrote had to be written
    /// twice or be inert on one side.
    pub async fn new(
        bind_addr: SocketAddr,
        backend: SctpBackend,
        event_tx: mpsc::Sender<AmfEvent>,
    ) -> Result<Self> {
        // Configure SCTP server
        let config = SctpServerConfig {
            max_inbound_streams: 2,
            max_outbound_streams: 2,
            max_message_size: MAX_NGAP_MSG_SIZE as u32,
            receive_buffer_size: 262144,
            // NGAP PPID 60 (TS 38.412) — the default, named explicitly here so
            // the contrast with the S1AP server's PPID 18 is visible.
            ppid: nextgcore_sctp::NGAP_PPID,
        };

        let mut transport = NgapTransport::bind(backend, bind_addr, config).await?;

        let local_addr = transport.local_addr();

        // Set up event channel for server events
        let (server_event_tx, server_event_rx) = mpsc::unbounded_channel();
        transport.set_event_sender(server_event_tx);

        log::info!(
            "NGAP server listening on {local_addr} ({})",
            backend.label()
        );

        // What `new` needs from the AMF context, read under ONE guard that is dropped
        // at the end of this statement (#645). A guard taken inside the struct
        // expression below would be a temporary of it, alive until the whole
        // expression ends; a second `read()` there is a recursive read, which
        // deadlocks as soon as a writer queues between the two.
        //
        // The reachability timers derive from the CONFIGURED T3512
        // (`amf.time.t3512.value`), per TS 24.501 §5.3.7.
        let (ue_auth_state, t3512_secs) = {
            let handle = crate::context::amf_self();
            let ctx = handle.read().unwrap_or_else(|e| e.into_inner());
            (ctx.ue_store(), ctx.t3512_value)
        };

        Ok(Self {
            transport,
            bind_addr: local_addr,
            sessions: Arc::new(RwLock::new(HashMap::new())),
            assoc_to_addr: Arc::new(RwLock::new(HashMap::new())),
            next_gnb_id: Arc::new(Mutex::new(1)),
            #[cfg(test)]
            forced_amf_ue_ngap_id: None,
            #[cfg(test)]
            sent_ngap: None,
            #[cfg(test)]
            test_outbound_streams: 2,
            outbound_streams: std::collections::HashMap::new(),
            #[cfg(test)]
            fail_next_sends: 0,
            #[cfg(test)]
            fail_next_session_record: false,
            event_tx,
            server_event_rx,
            ue_auth_state,
            sm_context_refs: HashMap::new(),
            mapping_resolves: HashMap::new(),
            sm_context_smfs: HashMap::new(),
            handover_target_assoc: HashMap::new(),
            handover_target_transfers: HashMap::new(),
            handover_pending_target: HashMap::new(),
            handover_prepared_psis: HashMap::new(),
            pending_source_releases: Vec::new(),
            handover_source_hold: handover_source_hold_from_env(),
            ho_preparations: HashMap::new(),
            ho_commands: HashMap::new(),
            handover_dropped_psis: HashMap::new(),
            handover_listed_psis: HashMap::new(),
            ho_generation: 0,
            handover_target_release_psis: HashMap::new(),
            handover_cancelled_psis: HashMap::new(),
            ho_preparation_wait: handover_smf_wait_from_env("AMF_HANDOVER_PREPARATION_SMF_WAIT_MS"),
            ho_command_wait: handover_smf_wait_from_env("AMF_HANDOVER_COMMAND_SMF_WAIT_MS"),
            eps_ho_in_flight: HashMap::new(),
            emergency: crate::emergency::EmergencyHandler::new(),
            ngap_overload_declared: false,
            last_session_sweep: std::time::Instant::now(),
            pending_establishments: HashMap::new(),
            sbi_offload: crate::sbi_offload::SbiOffload::new(MAX_OFFLOADED_SBI),
            contextless_ue_ids: std::collections::VecDeque::new(),
            timer_configs: {
                // Reachability timers derive from the CONFIGURED T3512
                // (`amf.time.t3512.value`), per TS 24.501 §5.3.7, with
                // AMF_MOBILE_REACHABLE_SECS / AMF_IMPLICIT_DEREG_SECS as overrides.
                let configs = AmfTimerConfigs::default().with_reachability_from(t3512_secs);
                #[cfg(feature = "ntn")]
                let configs = {
                    let mut configs = configs;
                    configs.ntn_default_timing_advance = std::env::var("AMF_NTN_TIMING_ADVANCE_US")
                        .ok()
                        .and_then(|v| v.parse::<u32>().ok())
                        .map(nextgcore_proto::TimingAdvance::new);
                    if let Some(ta) = configs.ntn_default_timing_advance {
                        log::info!(
                            "NTN: per-AMF default timing advance {}us (GMM retransmission timers extended by {}us round trip)",
                            ta.value_us,
                            u64::from(ta.value_us) * 2
                        );
                    }
                    configs
                };
                configs
            },
        })
    }

    /// Get the bind address
    pub fn local_addr(&self) -> SocketAddr {
        self.bind_addr
    }

    /// Get number of connected gNBs
    pub async fn num_gnbs(&self) -> usize {
        self.sessions.read().await.len()
    }

    /// Poll for incoming NGAP messages and server events
    pub async fn poll(&mut self) -> Result<bool> {
        // Check GMM procedure timers (T3550/T3555/T3560/T3570/T3522 retransmission)
        self.process_nas_timers().await?;

        // Reachability supervision for idle registered UEs (TS 24.501 §5.3.7):
        // mobile reachable -> implicit deregistration. Dormant when no UE is idle.
        self.process_reachability_timers().await?;

        // #806: source NG-RAN releases waiting for the step 6a timer.
        self.process_pending_source_releases().await;

        // Keep the RAN's view of overload in step with the NAS congestion posture.
        // A no-op unless the posture just changed, and the posture is off by default.
        self.sync_ngap_overload().await?;

        // Deliver any LCS positioning downlinks the Namf SBI handler enqueued
        // (TS 23.273): NRPPa→gNB (N2) / LPP→UE (N1). Dormant when none pending.
        self.process_positioning_downlinks().await;

        // Execute any network-initiated deregistrations the Namf_Callback
        // dereg-notify handler enqueued (WSB-4, TS 23.502 §4.2.2.3.3 /
        // TS 24.501 §5.5.2.3): protected DEREGISTRATION REQUEST + T3522.
        // Dormant when none pending.
        self.process_network_deregs().await;

        // Deliver every N1N2MessageTransfer the Namf handler queued for a
        // CM-CONNECTED UE (#666): PDU SESSION RESOURCE RELEASE COMMAND and/or the
        // N1 in a DOWNLINK NAS TRANSPORT. Dormant when none pending.
        self.process_connected_downlinks().await;

        self.process_sbi_outcomes().await;
        self.process_handover_deadlines().await;
        self.process_pending_establishments().await;

        // Relay any PWS warning containers the Namf non-UE N2 transfer handler
        // enqueued (#396, TS 29.518 §5.2.2.4.1.3 / TS 38.413 §8.12) to the
        // NG-RAN nodes the consumer targeted. Dormant when none pending.
        self.process_pws_n2_transfers().await;

        // Relay non-UE-associated NRPPa an LMF handed the Namf transfer handler
        // (#807, TS 29.518 §5.2.2.4.1.2 / TS 38.413 §8.15.4). Dormant when none.
        self.process_non_ue_nrppa_transfers().await;

        // Page every CM-IDLE UE a Namf N1N2MessageTransfer queued (#512, TS 23.502
        // §4.2.3.3): PAGING to the gNBs serving its registration area, T3513
        // retransmission, and the failure notification on final expiry.
        self.process_paging().await;

        // Send the HandoverRequest for every EPS→5GS handover the N26 leg prepared
        // (#418, TS 23.502 §4.11.1.2.2.2 step 9). Dormant when none is queued.
        self.process_eps_to_5gs_preparations().await;

        // Release every EPS→5GS preparation the source MME cancelled (#592, TS 23.502
        // §4.11.1.2.3). AFTER the preparations, so a cancel for one queued in this same tick
        // finds it.
        self.process_eps_to_5gs_cancels().await;

        // Send the HandoverCommand (or HandoverPreparationFailure) for every 5GS→EPS
        // preparation the target MME answered (#476, TS 23.502 §4.11.1.2.1 step 11).
        self.process_fivegs_to_eps_answers().await;

        // #756: drop per-session state whose end this task never saw (e.g. the SMF's
        // RELEASED status notification, handled on the SBI task). Every 10 s: a scan,
        // and nothing depends on it being prompt.
        if self.last_session_sweep.elapsed() >= SESSION_SWEEP_INTERVAL {
            self.last_session_sweep = std::time::Instant::now();
            let dropped = self.sweep_orphaned_session_state();
            if dropped > 0 {
                log::info!("Dropped {dropped} orphaned per-session entries (#756)");
            }
        }

        // Process any pending server events
        while let Ok(event) = self.server_event_rx.try_recv() {
            self.handle_server_event(event).await?;
        }

        // Poll SCTP server for incoming data
        match self.transport.recv(SCTP_RECV_TIMEOUT).await {
            Ok(true) => {
                // Data was received, process any new events
                while let Ok(event) = self.server_event_rx.try_recv() {
                    self.handle_server_event(event).await?;
                }
                Ok(true)
            }
            Ok(false) => Ok(false), // Timeout, no data
            Err(e) => Err(anyhow::anyhow!("SCTP receive error: {e}")),
        }
    }

    /// Handle SCTP server events
    async fn handle_server_event(&mut self, event: ServerEvent) -> Result<()> {
        match event {
            ServerEvent::NewAssociation {
                association_id,
                remote_addr,
            } => {
                // #870 follow-up: a new association has its own negotiated streams; a
                // count cached under a reused id is not its count.
                self.outbound_streams.remove(&association_id);
                self.handle_new_association(association_id, remote_addr)
                    .await?;
            }
            ServerEvent::AssociationRestarted { association_id } => {
                // RFC 9260 §5.2.2: the peer restarted and the streams were negotiated
                // afresh, so the cached count is asked again. The gNB itself restarted:
                // it re-runs NG Setup, and the UE contexts it served are gone with it.
                self.outbound_streams.remove(&association_id);
                log::warn!(
                    "NG association {association_id} restarted by the gNB; its outbound \
                     stream count is re-read"
                );
            }
            ServerEvent::AssociationClosed {
                association_id,
                reason,
            } => {
                self.outbound_streams.remove(&association_id);
                // #758: the connections allocated there are gone with it.
                self.contextless_ue_ids
                    .retain(|c| c.association_id != association_id);
                self.handle_association_closed(association_id, &reason)
                    .await?;
            }
            ServerEvent::DataReceived {
                association_id,
                message,
            } => {
                self.handle_data_received(association_id, &message.data)
                    .await?;
            }
        }
        Ok(())
    }

    /// Handle new SCTP association (gNB connection)
    async fn handle_new_association(
        &self,
        association_id: u64,
        remote_addr: SocketAddr,
    ) -> Result<()> {
        let gnb_id = {
            let mut id = self.next_gnb_id.lock().await;
            let current = *id;
            *id += 1;
            current
        };

        log::info!("New gNB connection from {remote_addr} (gNB ID: {gnb_id}, association: {association_id})");

        let mut session = GnbSession::new(gnb_id, association_id, remote_addr);
        session.fsm.init();

        self.sessions.write().await.insert(association_id, session);
        self.assoc_to_addr
            .write()
            .await
            .insert(association_id, remote_addr);

        Ok(())
    }

    /// Handle SCTP association closure
    async fn handle_association_closed(&self, association_id: u64, reason: &str) -> Result<()> {
        if let Some(session) = self.sessions.write().await.remove(&association_id) {
            log::info!(
                "gNB {} disconnected (association {}): {}",
                session.id,
                association_id,
                reason
            );
            self.assoc_to_addr.write().await.remove(&association_id);
        }
        Ok(())
    }

    /// Handle received NGAP data
    async fn handle_data_received(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        let addr = self
            .assoc_to_addr
            .read()
            .await
            .get(&association_id)
            .copied();

        if let Some(addr) = addr {
            log::debug!(
                "Received {} bytes NGAP data from {} (association {})",
                data.len(),
                addr,
                association_id
            );

            // Process the NGAP message
            self.process_ngap_message(association_id, data).await?;
        } else {
            log::warn!("Received data for unknown association {association_id}");
        }

        Ok(())
    }

    /// Process an NGAP message
    async fn process_ngap_message(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        if data.len() < 3 {
            log::warn!("NGAP message too short from association {association_id}");
            return Ok(());
        }

        // Log raw message header for debugging
        log::debug!(
            "NGAP message from association {}: {} bytes, header: {:02x?}",
            association_id,
            data.len(),
            &data[..data.len().min(8)]
        );

        // Check for NGAP message type
        let procedure_code = self.extract_procedure_code(data);

        log::info!(
            "NGAP message from association {association_id}: procedure_code={procedure_code:?}"
        );

        match procedure_code {
            Some(21) => {
                // NGSetupRequest (procedure code 21)
                self.handle_ng_setup_request(association_id, data).await?;
            }
            Some(15) => {
                // InitialUEMessage (procedure code 15)
                self.handle_initial_ue_message(association_id, data).await?;
            }
            Some(46) => {
                // UplinkNASTransport (procedure code 46)
                log::info!("Dispatching to handle_uplink_nas_transport");
                self.handle_uplink_nas_transport(association_id, data)
                    .await?;
            }
            Some(14) => {
                // InitialContextSetup (procedure code 14)
                if data[0] == 0x20 {
                    // SuccessfulOutcome = InitialContextSetupResponse from gNB
                    log::info!("Initial Context Setup Response from gNB");
                    self.handle_initial_context_setup_response(association_id, data)
                        .await?;
                } else if data[0] == 0x40 {
                    // UnsuccessfulOutcome = InitialContextSetupFailure from gNB
                    log::warn!("Initial Context Setup Failure from gNB");
                    self.handle_initial_context_setup_failure(association_id, data)
                        .await?;
                }
            }
            Some(29) => {
                // PDU Session Resource Setup (procedure code 29)
                // SuccessfulOutcome = gNB response with gNB TEID
                if data[0] == 0x20 {
                    log::info!("PDU Session Resource Setup Response from gNB");
                    self.handle_pdu_session_resource_setup_response(association_id, data)
                        .await?;
                }
            }
            Some(26) => {
                // PDU Session Resource Modify (procedure code 26, TS 38.413 §8.2.2)
                if data[0] == 0x20 {
                    // SuccessfulOutcome = gNB confirmed resource modification.
                    // The N2 SM Modify Response Transfer must reach the SMF; this
                    // used to be logged and dropped.
                    self.handle_pdu_session_resource_modify_response(association_id, data)
                        .await?;
                } else if data[0] == 0x40 {
                    // UnsuccessfulOutcome = gNB rejected modification
                    log::warn!("PDU Session Resource Modify Failure from gNB");
                }
            }
            Some(28) => {
                // PDU Session Resource Release (procedure code 28, TS 38.413 §8.2.3)
                if data[0] == 0x20 {
                    self.handle_pdu_session_resource_release_response(association_id, data)
                        .await?;
                }
            }
            Some(42) => {
                // UEContextReleaseRequest (procedure code 42, `id-UEContextReleaseRequest`,
                // TS 38.413 §8.3.2): a class-2 gNB->AMF InitiatingMessage with no outcome.
                // #451: this used to be keyed on 41, which is UEContextRelease -- so every
                // conformant Release Request fell to the `_` arm and was answered with an
                // Error Indication, and nothing was released.
                if data[0] == 0x00 {
                    log::info!("UE Context Release Request from gNB");
                    self.handle_ue_context_release(association_id, data).await?;
                } else {
                    log::warn!(
                        "UEContextReleaseRequest has no outcome messages; unexpected \
                         outcome byte {:#04x} from association {association_id}",
                        data[0]
                    );
                }
            }
            Some(41) => {
                // UEContextRelease (procedure code 41, `id-UEContextRelease`, TS 38.413
                // §8.3.3): the Command is AMF->gNB, so what arrives here is the gNB's
                // SuccessfulOutcome, UEContextReleaseComplete.
                if data[0] == 0x00 {
                    log::warn!(
                        "UEContextReleaseCommand is AMF->gNB; unexpected from association \
                         {association_id}"
                    );
                } else if data[0] == 0x20 {
                    // SuccessfulOutcome = UEContextReleaseComplete from gNB
                    log::info!("UE Context Release Complete from gNB");
                    // TS 24.501 §5.3.7: the N1 signalling connection is now gone. For a
                    // UE that is still REGISTERED this is the moment the mobile reachable
                    // timer starts -- the AMF can no longer reach it, and something has
                    // to bound how long it holds the context before deciding the UE is
                    // gone. Before this nothing started either reachability timer, so a
                    // UE that never came back was held forever.
                    self.handle_ue_context_release_complete(association_id, data)
                        .await?;
                }
            }
            Some(20) => {
                // NGReset (procedure code 20)
                if data[0] == 0x00 {
                    // InitiatingMessage = NGReset from gNB
                    self.handle_ng_reset(association_id, data).await?;
                } else if data[0] == 0x20 {
                    // SuccessfulOutcome = NGResetAcknowledge for an AMF-initiated reset
                    log::info!("NG Reset Acknowledge from association {association_id}");
                }
            }
            Some(proc_code::OVERLOAD_START) | Some(proc_code::OVERLOAD_STOP) => {
                // OverloadStart/OverloadStop are AMF->gNB procedures (TS 38.413
                // Sections 8.7.6/8.7.7); receiving one from a gNB is a logical
                // error. Acknowledge with an ErrorIndication carrying
                // protocol/message-not-compatible (TS 38.413 Section 8.7.5).
                log::warn!(
                    "Overload{} received from association {association_id}: not applicable in gNB->AMF direction",
                    if procedure_code == Some(proc_code::OVERLOAD_START) {
                        "Start"
                    } else {
                        "Stop"
                    }
                );
                self.send_error_indication(
                    association_id,
                    None,
                    None,
                    ngap_gen::Cause::Protocol(ngap_gen::CauseProtocol(
                        ngap_gen::CauseProtocol::MESSAGE_NOT_COMPATIBLE_WITH_RECEIVER_STATE,
                    )),
                )
                .await?;
            }
            Some(proc_code::ERROR_INDICATION) => {
                // ErrorIndication from the gNB (TS 38.413 Section 8.7.5). The AMF
                // never replies to an ErrorIndication; it logs the diagnosis.
                self.handle_error_indication(association_id, data).await?;
            }
            Some(proc_code::HANDOVER_PREPARATION) => {
                // HandoverPreparation: InitiatingMessage = HandoverRequired from
                // the source gNB (TS 38.413 Section 8.4.1). HandoverCommand /
                // HandoverPreparationFailure are AMF->gNB.
                if data[0] == 0x00 {
                    self.handle_handover_required(association_id, data).await?;
                } else {
                    log::warn!(
                        "Unexpected HandoverPreparation outcome from association {association_id}"
                    );
                }
            }
            Some(proc_code::HANDOVER_RESOURCE_ALLOCATION) => {
                // HandoverResourceAllocation: SuccessfulOutcome =
                // HandoverRequestAcknowledge, UnsuccessfulOutcome =
                // HandoverFailure, both from the target gNB (TS 38.413 8.4.2).
                if data[0] == 0x20 {
                    self.handle_handover_request_acknowledge(association_id, data)
                        .await?;
                } else if data[0] == 0x40 {
                    self.handle_handover_failure(association_id, data).await?;
                } else {
                    log::warn!(
                        "HandoverRequest InitiatingMessage is AMF->gNB; unexpected from association {association_id}"
                    );
                }
            }
            Some(proc_code::PATH_SWITCH_REQUEST) => {
                // PathSwitchRequest: InitiatingMessage from the target gNB for
                // an Xn-based handover (TS 38.413 Section 8.4.4).
                if data[0] == 0x00 {
                    self.handle_path_switch_request(association_id, data)
                        .await?;
                } else {
                    log::warn!(
                        "PathSwitch ack/failure are AMF->gNB; unexpected from association {association_id}"
                    );
                }
            }
            Some(proc_code::HANDOVER_CANCEL) => {
                // HandoverCancel: InitiatingMessage = HandoverCancel from the
                // source gNB (TS 38.413 Section 8.4.5).
                if data[0] == 0x00 {
                    self.handle_handover_cancel(association_id, data).await?;
                } else {
                    log::info!(
                        "HandoverCancelAcknowledge is AMF->gNB; ignoring from association {association_id}"
                    );
                }
            }
            Some(proc_code::HANDOVER_NOTIFICATION) => {
                // HandoverNotification: HandoverNotify from the target gNB
                // confirms the UE arrived (TS 38.413 Section 8.4.3).
                self.handle_handover_notify(association_id, data).await?;
            }
            Some(50) => {
                // UplinkUEAssociatedNRPPaTransport (TS 38.413 Section 8.15.3,
                // procedure 50 = proc_code::UPLINK_UE_ASSOCIATED_NRPPA_TRANSPORT):
                // the gNB's uplink leg of the LCS NRPPa relay (TS 23.273
                // Section 6.11). Relayed verbatim to the LMF registered via
                // N1N2MessageSubscribe as an Namf N2InfoNotify (TS 29.518);
                // never answered on N2 — before this arm existed the `_`
                // fallthrough actively broke the procedure by replying with
                // ErrorIndication(AbstractSyntaxErrorReject).
                self.handle_uplink_ue_associated_nrppa_transport(association_id, data)
                    .await?;
            }
            Some(47) => {
                // UplinkNonUEAssociatedNRPPaTransport (TS 38.413 Section
                // 8.15.5, procedure 47 =
                // proc_code::UPLINK_NON_UE_ASSOCIATED_NRPPA_TRANSPORT): same
                // relay without a UE association (TRP/assistance information),
                // keyed off the RoutingID echo + the subscription registry.
                self.handle_uplink_non_ue_associated_nrppa_transport(association_id, data)
                    .await?;
            }
            Some(35) => {
                // RAN CONFIGURATION UPDATE (TS 38.413 §8.7.2): gNB->AMF
                // InitiatingMessage. Acknowledge it instead of rejecting it with
                // an Error Indication (which would break NG-C config sync).
                if data[0] == 0x00 {
                    self.handle_ran_configuration_update(association_id, data)
                        .await?;
                }
            }
            Some(49) => {
                // UPLINK RAN STATUS TRANSFER (TS 38.413 §8.4.7): relay the PDCP
                // status to the handover target as DOWNLINK RAN STATUS TRANSFER.
                // Accepting and dropping it made handover lossy.
                if data[0] == 0x00 {
                    // The relay target is returned for testability; dispatch has
                    // no further use for it.
                    let _relayed_to = self
                        .handle_uplink_ran_status_transfer(association_id, data)
                        .await?;
                } else {
                    log::warn!(
                        "UplinkRANStatusTransfer has no outcome messages; unexpected \
                         from association {association_id}"
                    );
                }
            }
            Some(27) => {
                // PDU SESSION RESOURCE MODIFY INDICATION (TS 38.413 §8.2.4): the
                // gNB asks for a modification, carrying an N2 SM container per
                // session that the SMF must see.
                if data[0] == 0x00 {
                    self.handle_pdu_session_resource_modify_indication(association_id, data)
                        .await?;
                } else {
                    log::warn!(
                        "PDUSessionResourceModifyConfirm is AMF->gNB; unexpected from \
                         association {association_id}"
                    );
                }
            }
            Some(30) => {
                // PDU SESSION RESOURCE NOTIFY (TS 38.413 §8.2.5): per-session
                // notify/released containers that must reach the SMF.
                if data[0] == 0x00 {
                    self.handle_pdu_session_resource_notify(association_id, data)
                        .await?;
                } else {
                    log::warn!(
                        "PDUSessionResourceNotify has no outcome messages; unexpected \
                         from association {association_id}"
                    );
                }
            }
            Some(68) | Some(71) | Some(72) | Some(73) | Some(74) => {
                // MBS procedures (TS 23.247, TS 38.413 §9.2.9): BroadcastSessionSetup
                // (68), MulticastSession{Activation,Deactivation,Update} (71/72/73)
                // and MulticastGroupPaging (74). All are AMF->NG-RAN initiating
                // messages, so what arrives here is the gNB's OUTCOME.
                //
                // Before this arm they fell to the `_` fallthrough and were answered
                // with an ErrorIndication, which told a conformant gNB the AMF does
                // not implement MBS at all.
                self.handle_mbs_outcome(association_id, procedure_code, data)
                    .await?;
            }
            Some(51) | Some(32) => {
                // PWS responses (#399, TS 38.413 §9.2.8.2 / §9.2.8.4):
                // WRITE-REPLACE WARNING RESPONSE (procedure 51,
                // `38413-j30.txt:59115`) and PWS CANCEL RESPONSE (32, `:59077`).
                //
                // Both are the NG-RAN's answer to an AMF-INITIATED class-1
                // procedure, so what arrives is a SuccessfulOutcome (0x20). Keying
                // these on InitiatingMessage instead would leave them falling to
                // the `_` arm and still earning the Error Indication this arm
                // exists to stop.
                if data[0] == 0x20 {
                    self.handle_pws_response(association_id, procedure_code, data)
                        .await?;
                } else {
                    log::warn!(
                        "WriteReplaceWarning/PWSCancel initiating messages are AMF->gNB; \
                         unexpected {procedure_code:?} outcome byte {:#04x} from association \
                         {association_id}",
                        data[0]
                    );
                }
            }
            Some(34) | Some(33) => {
                // PWS indications (#399, TS 38.413 §9.2.8.5 / §9.2.8.6): PWS
                // RESTART INDICATION (procedure **34**, `38413-j30.txt:59081`) and
                // PWS FAILURE INDICATION (**33**, `:59079`).
                //
                // Note the ordering trap: the ASN.1 table is alphabetical, so
                // Failure is 33 and Restart is 34 — the REVERSE of the clause order
                // (Restart is §9.2.8.5, Failure is §9.2.8.6). Reading the codes off
                // the clause order swaps them.
                //
                // Unlike 51/32 above these are NG-RAN-initiated class-2 procedures,
                // so they arrive as InitiatingMessage (0x00) and are never
                // answered on N2.
                if data[0] == 0x00 {
                    self.handle_pws_indication(association_id, procedure_code, data)
                        .await?;
                } else {
                    log::warn!(
                        "PWS Restart/Failure Indication has no outcome messages; unexpected \
                         {procedure_code:?} outcome byte {:#04x} from association \
                         {association_id}",
                        data[0]
                    );
                }
            }
            // #570: UE Radio Capability Info Indication (TS 38.413 §8.14.1), an
            // NG-RAN-initiated class-2 procedure: store the capability and, for a RACS
            // UE, have the UCMF assign an ID.
            Some(44) if data[0] == 0x00 => {
                self.handle_ue_radio_capability_info_indication(association_id, data)
                    .await?;
            }
            // #570: UE Radio Capability ID Mapping (TS 38.413 §8.14.3), non UE-associated.
            Some(60) if data[0] == 0x00 => {
                self.handle_ue_radio_capability_id_mapping(association_id, data)
                    .await?;
            }
            Some(19) | Some(44) | Some(48) | Some(52) => {
                // Expected gNB-initiated procedures the AMF accepts without a
                // response (TS 38.413): NAS Non Delivery Indication (19), UE Radio
                // Capability Info Indication (44), Uplink RAN Configuration
                // Transfer (48), Secondary RAT Data Usage Report (52). Accept and
                // log rather than answering with an (incorrect) Error Indication.
                //
                // Deliberately still log-only. 19 and 44 terminate at the AMF and
                // need no relay; 48 is an inter-gNB transfer with no target
                // resolution defined for this deployment, and 52 needs a charging
                // consumer that does not exist here. Each would otherwise be a
                // sender into a path with no receiver — the failure mode of adding
                // a caller to a stub. See the spec for why they were left.
                log::info!(
                    "NGAP procedure {procedure_code:?} from association {association_id} accepted (no AMF response required)"
                );
            }
            _ => {
                // Unknown / unsupported procedure: the PDU is either undecodable
                // or for a procedure the AMF does not implement. Per TS 38.413
                // Section 10.3, respond with an ErrorIndication carrying the
                // appropriate protocol cause rather than silently dropping it.
                log::warn!(
                    "Unhandled NGAP procedure_code={procedure_code:?} from association {association_id}; emitting ErrorIndication"
                );
                let (amf_ue_ngap_id, ran_ue_ngap_id, cause) =
                    Self::unhandled_procedure_error_indication(procedure_code, data);
                self.send_error_indication(association_id, amf_ue_ngap_id, ran_ue_ngap_id, cause)
                    .await?;
            }
        }

        Ok(())
    }

    /// The Error Indication answering a PDU for a procedure the AMF does not handle
    /// (TS 38.413 §10.3): abstract-syntax-error-reject when the procedure code was
    /// read, transfer-syntax-error when it was not, and -- for a UE-associated
    /// message -- the AMF and RAN UE NGAP IDs it carries (§9.2.7.1), located by IE
    /// id whatever the procedure (#447). Pure, so the IDs are testable without an
    /// outbound capture.
    fn unhandled_procedure_error_indication(
        procedure_code: Option<u16>,
        data: &[u8],
    ) -> (Option<u64>, Option<u32>, ngap_gen::Cause) {
        let cause = ngap_gen::Cause::Protocol(ngap_gen::CauseProtocol(match procedure_code {
            Some(_) => ngap_gen::CauseProtocol::ABSTRACT_SYNTAX_ERROR_REJECT,
            None => ngap_gen::CauseProtocol::TRANSFER_SYNTAX_ERROR,
        }));
        (
            crate::ngap_asn1::extract_amf_ue_ngap_id(data),
            crate::ngap_asn1::extract_ran_ue_ngap_id(data),
            cause,
        )
    }

    /// Extract procedure code from NGAP message
    ///
    /// NGAP PDU is a CHOICE with 3 options:
    /// - InitiatingMessage (0x00)
    /// - SuccessfulOutcome (0x20)
    /// - UnsuccessfulOutcome (0x40)
    ///
    /// In APER encoding:
    /// - Byte 0: CHOICE index (0x00, 0x20, or 0x40 with extension bit)
    /// - Byte 1: Procedure code (0-255)
    fn extract_procedure_code(&self, data: &[u8]) -> Option<u16> {
        if data.len() < 3 {
            log::warn!(
                "NGAP message too short to extract procedure code: {} bytes",
                data.len()
            );
            return None;
        }

        let byte0 = data[0];
        let procedure_code = data[1];

        log::trace!(
            "NGAP header bytes: [{:#04x}, {:#04x}, {:#04x}]",
            byte0,
            data[1],
            data[2]
        );

        // Check for valid NGAP PDU choice values
        match byte0 {
            0x00 => {
                // InitiatingMessage
                log::trace!("InitiatingMessage with procedure code {procedure_code}");
                Some(procedure_code as u16)
            }
            0x20 => {
                // SuccessfulOutcome
                log::trace!("SuccessfulOutcome with procedure code {procedure_code}");
                Some(procedure_code as u16)
            }
            0x40 => {
                // UnsuccessfulOutcome
                log::trace!("UnsuccessfulOutcome with procedure code {procedure_code}");
                Some(procedure_code as u16)
            }
            _ => {
                log::warn!(
                    "Unknown NGAP PDU type: {:#04x}, bytes: {:02x?}",
                    byte0,
                    &data[..data.len().min(16)]
                );
                None
            }
        }
    }

    /// Handle NG Setup Request
    async fn handle_ng_setup_request(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        log::info!(
            "NG Setup Request from association {} ({} bytes)",
            association_id,
            data.len()
        );

        // Decode with the generated codec, which also sorts any not-comprehended
        // or missing IEs by criticality (TS 38.413 §10.3.4.2, §10.3.5).
        let (request, notify) = match ngap_asn1::decode_ng_setup_request_asn1(data) {
            ngap_asn1::NgSetupRequestDecode::Proceed {
                request: req,
                notify,
            } => {
                log::info!(
                    "Parsed NG Setup Request: gNB ID={}, PLMN={}{}{}-{}{}{}",
                    req.gnb_id,
                    req.plmn_id.mcc1,
                    req.plmn_id.mcc2,
                    req.plmn_id.mcc3,
                    req.plmn_id.mnc1,
                    req.plmn_id.mnc2,
                    if req.plmn_id.mnc3 == 0xf {
                        "".to_string()
                    } else {
                        req.plmn_id.mnc3.to_string()
                    }
                );
                (req, notify)
            }
            ngap_asn1::NgSetupRequestDecode::Reject(diagnostics) => {
                // §10.3.4.2 / §10.3.5: an IE marked "reject" that the AMF does not
                // comprehend, or a missing one: execute none of the request, and
                // report the IEs in the message for the unsuccessful outcome.
                log::warn!(
                    "NG Setup Request from association {association_id} has {} \
                     not-comprehended or missing IE(s) marked reject; sending NG SETUP FAILURE",
                    diagnostics.len()
                );
                let failure = ngap_asn1::build_ng_setup_failure_with_diagnostics_asn1(
                    ngap_handler::cause_group::PROTOCOL,
                    ngap_handler::protocol_cause::ABSTRACT_SYNTAX_ERROR_REJECT,
                    Some(time_to_wait::V1S),
                    &diagnostics,
                );
                if !failure.is_empty() {
                    self.send_to_association(association_id, &failure).await?;
                }
                return Ok(());
            }
            ngap_asn1::NgSetupRequestDecode::Undecodable => {
                // TS 38.413 §8.7.3: an undecodable / unacceptable NG SETUP
                // REQUEST must be answered with NG SETUP FAILURE — never a
                // fabricated request accepted with NG SETUP RESPONSE.
                log::warn!(
                    "Undecodable NG Setup Request from association {association_id}; sending NG SETUP FAILURE"
                );
                let failure = ngap_asn1::build_ng_setup_failure_asn1(
                    ngap_handler::cause_group::PROTOCOL,
                    4, // Protocol / SemanticError
                    Some(time_to_wait::V1S),
                );
                if !failure.is_empty() {
                    self.send_to_association(association_id, &failure).await?;
                }
                return Ok(());
            }
        };

        // Process request and build response with locks held, then release before sending
        let response_data: Option<Vec<u8>> = {
            let mut sessions = self.sessions.write().await;
            if let Some(session) = sessions.get_mut(&association_id) {
                let ctx_arc = crate::context::amf_self();
                // Read THROUGH the poison: this replaced a `tokio::sync::RwLock`,
                // which cannot poison, so bailing here would be a new failure mode
                // rather than a preserved one (#363).
                let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());

                // Handle the request
                let result =
                    ngap_handler::handle_ng_setup_request(&mut session.gnb, &ctx, &request);

                match result {
                    NgapHandlerResult::Success => {
                        log::info!(
                            "NG Setup successful for gNB {} (association {})",
                            session.gnb.gnb_id,
                            association_id
                        );

                        // Build NG Setup Response with proper ASN.1 APER encoding,
                        // reporting any "notify" IEs it ignored (§10.3.4.2).
                        if let Some(response) =
                            ngap_asn1::build_ng_setup_response_with_diagnostics_asn1(&ctx, &notify)
                        {
                            log::debug!(
                                "Built NG Setup Response: {} bytes, hex: {:02x?}",
                                response.len(),
                                &response[..response.len().min(32)]
                            );
                            Some(response)
                        } else {
                            log::error!("Failed to build NG Setup Response");
                            None
                        }
                    }
                    NgapHandlerResult::Failure(cause) => {
                        log::warn!(
                            "NG Setup failed for association {}: cause group={}, cause={}",
                            association_id,
                            cause.group,
                            cause.cause
                        );

                        // Build NG Setup Failure with proper ASN.1 encoding and
                        // the real cause group/value from the handler
                        Some(ngap_asn1::build_ng_setup_failure_with_diagnostics_asn1(
                            cause.group,
                            cause.cause,
                            Some(time_to_wait::V1S),
                            &notify,
                        ))
                    }
                    _ => None,
                }
            } else {
                None
            }
        }; // All locks released here

        // Now send the response with &mut self available
        if let Some(response) = response_data {
            self.send_to_association(association_id, &response).await?;
            log::info!(
                "Sent NG Setup Response to association {} ({} bytes)",
                association_id,
                response.len()
            );
        }

        Ok(())
    }

    /// Handle NG Reset from a gNB (TS 38.413 Section 8.7.4.2)
    ///
    /// Releases the affected UE contexts and responds with NG Reset Acknowledge.
    async fn handle_ng_reset(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        use crate::ngap_asn1::NgResetDecode;
        use nextgcore_ngap::types::ResetType;

        // #417: the GENERATED codec, with TS 38.413 §10.3.4.2 applied.
        let (reset, notify) = match ngap_asn1::decode_ng_reset_asn1(data) {
            NgResetDecode::Proceed { reset, notify } => (reset, notify),
            NgResetDecode::Reject(report) => {
                // No unsuccessful outcome exists for NG Reset, so the procedure
                // is terminated with an Error Indication and nothing is reset.
                log::warn!("NG Reset from association {association_id} rejected: {report:?}");
                if let Some(ei) = ngap_asn1::build_criticality_error_indication_asn1(&report) {
                    self.send_to_association(association_id, &ei).await?;
                }
                return Ok(());
            }
            NgResetDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(association_id, "NG Reset")
                    .await
            }
        };

        let gnb_pool_id = self
            .sessions
            .read()
            .await
            .get(&association_id)
            .map(|s| s.id);
        let Some(gnb_pool_id) = gnb_pool_id else {
            log::warn!("NG Reset from unknown association {association_id}");
            return Ok(());
        };
        // #758: a reset connection's contextless allocation goes with it.
        self.drop_contextless_ue_ids_for_reset(association_id, &reset.reset_type);

        // #754: the UE-associated logical NG-connections the reset names, resolved on the
        // LIVE store (`ue_auth_state`), and only those served by THIS association: TS
        // 38.413 §8.7.4.2.2 scopes a reset to the sending NG-RAN node's connections, so a
        // gNB cannot list another gNB's UE (the NG Reset site of #739). When an item
        // carries both ids the pair must match.
        let affected: Vec<u64> = match &reset.reset_type {
            // `snapshot` and not `iter`: the loop below re-enters the store, so a live
            // guard here would DEADLOCK. See `ue_store`'s module docs.
            ResetType::NgInterface => self
                .ue_auth_state
                .snapshot()
                .into_iter()
                .filter(|(_, state)| state.association_id == association_id)
                .map(|(amf_ue_ngap_id, _)| amf_ue_ngap_id)
                .collect(),
            ResetType::PartOfNgInterface(connections) => {
                let on_this_gnb: Vec<(u64, u32)> = self
                    .ue_auth_state
                    .snapshot()
                    .into_iter()
                    .filter(|(_, state)| state.association_id == association_id)
                    .map(|(id, state)| (id, state.ran_ue_ngap_id))
                    .collect();
                connections
                    .iter()
                    .filter_map(|item| {
                        let found = on_this_gnb.iter().find(|(id, ran)| {
                            match (item.amf_ue_ngap_id, item.ran_ue_ngap_id) {
                                (Some(amf), Some(r)) => *id == amf && *ran == r,
                                (Some(amf), None) => *id == amf,
                                (None, Some(r)) => *ran == r,
                                (None, None) => false,
                            }
                        });
                        if found.is_none() {
                            log::warn!(
                                "NG Reset from association {association_id}: no connection of \
                                 this gNB matches AMF-UE-NGAP-ID={:?}, RAN-UE-NGAP-ID={:?}; \
                                 ignored",
                                item.amf_ue_ngap_id,
                                item.ran_ue_ngap_id
                            );
                        }
                        found.map(|(id, _)| *id)
                    })
                    .collect()
            }
        };

        // #754: an NG Reset releases the NG resources only (TS 38.413 §8.7.4.2.2). A
        // REGISTERED UE goes CM-IDLE exactly as at a UE Context Release Complete: it keeps
        // its registration, NAS security context and PDU sessions; each session's user
        // plane is deactivated at its owning SMF (TS 23.502 §4.2.6 step 5), so the UPF
        // buffers downlink data and pages instead of forwarding to the reset gNB's dead
        // tunnels; and the mobile reachable timer starts (TS 24.501 §5.3.7). Before, every
        // affected UE was FORGOTTEN: its next Service Request got #9, the SMF kept
        // forwarding to the dead tunnels, and the PCF/UDM records leaked. A UE whose
        // registration had not completed has nothing to keep and is still dropped
        // (`forget_ue`, which also frees an emergency context, #356).
        //
        // §8.7.4.2.2 also has "any other ongoing procedure ... related to a UE association
        // ... indicated ... in the NG RESET message" ABORTED: see `abort_on_ng_release`.
        //
        // The SMF calls are NOT made here. This handler runs on the one NGAP task that
        // serves every gNB, and a whole-interface reset can name hundreds of UEs: serial
        // SMF round trips would stall N2 for all of them, and hold the Acknowledge, which
        // §8.7.4.2.2 gates on the NG resources alone. They are collected and run after the
        // Acknowledge, off this task, through the shared `sbi_offload` (its permits bound
        // every offloaded SBI exchange of this AMF, not just this reset's).
        let mut smf_work: Vec<NgResetSmfCall> = Vec::new();
        let mut idled = 0usize;
        for amf_ue_ngap_id in affected {
            let outcome = self
                .ue_auth_state
                .with_mut(amf_ue_ngap_id, |s| {
                    s.registered.then(|| {
                        let went_idle = !s.cm_idle;
                        s.cm_idle = true;
                        (went_idle, abort_on_ng_release(amf_ue_ngap_id, s))
                    })
                })
                .flatten();
            // The handover relay state of a preparation the reset ended (§8.7.4.2.2).
            self.handover_target_assoc.remove(&amf_ue_ngap_id);
            self.handover_target_transfers
                .retain(|(ue, _), _| *ue != amf_ue_ngap_id);
            match outcome {
                // TS 24.501 §5.5.2.3.5 b): a lower layer failure during a network-initiated
                // de-registration aborts it and the network enters 5GMM-DEREGISTERED. The
                // NG connection is gone, so no UE Context Release Command either.
                Some((_, AbortedProcedure::Deregistration)) => {
                    smf_work.extend(self.ue_sm_contexts(amf_ue_ngap_id).into_iter().map(
                        |(psi, sm_ref, host, port)| NgResetSmfCall::Release {
                            amf_ue_ngap_id,
                            psi,
                            sm_ref,
                            host,
                            port,
                        },
                    ));
                    self.terminate_policy_associations(amf_ue_ngap_id);
                    self.forget_ue(amf_ue_ngap_id);
                }
                Some((true, _)) => {
                    idled += 1;
                    smf_work.extend(self.ue_sm_contexts(amf_ue_ngap_id).into_iter().map(
                        |(psi, sm_ref, host, port)| NgResetSmfCall::Deactivate {
                            amf_ue_ngap_id,
                            psi,
                            sm_ref,
                            host,
                            port,
                        },
                    ));
                    self.start_reachability_supervision(amf_ue_ngap_id).await;
                }
                // Already CM-IDLE (and supervised since): nothing more to release.
                Some((false, _)) => {}
                None => self.forget_ue(amf_ue_ngap_id),
            }
        }
        crate::metrics::global().add(crate::metrics::GlobalMetric::NgResetUeIdled, idled as u64);

        // Release the affected UE contexts and get the list to echo in the Ack
        let ack_connections = ngap_handler::handle_ng_reset(gnb_pool_id, &reset);

        if let Some(ack) = ngap_asn1::build_ng_reset_acknowledge_asn1(ack_connections, &notify) {
            self.send_to_association(association_id, &ack).await?;
            log::info!(
                "NG Reset Acknowledge sent to association {association_id} ({idled} UE(s) \
                 moved to CM-IDLE, {} SMF update(s) to follow)",
                smf_work.len()
            );
        } else {
            log::error!("Failed to build NG Reset Acknowledge");
        }

        for call in smf_work {
            self.offload_ng_reset_smf_call(call);
        }

        Ok(())
    }

    /// Parse NG Setup Request (fallback when ASN.1 parsing fails)
    /// Handle an inbound RAN CONFIGURATION UPDATE (TS 38.413 §8.7.2) by replying
    /// with RAN CONFIGURATION UPDATE ACKNOWLEDGE. The advertised TA list is
    /// logged; persisting it into the stored gNB context is tracked as follow-up.
    async fn handle_ran_configuration_update(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        // #417: the GENERATED codec, TS 38.413 §10.3.4.2 for a Class 1 initiating
        // message. Before, an update that did not decode -- or carried a
        // not-comprehended "reject" IE -- was still ACKNOWLEDGED, telling the gNB
        // the AMF had taken a configuration it never read.
        let (upd, notify) = match crate::ngap_asn1::decode_ran_configuration_update_asn1(data) {
            crate::ngap_asn1::RanConfigurationUpdateDecode::Proceed { update, notify } => {
                (update, notify)
            }
            crate::ngap_asn1::RanConfigurationUpdateDecode::Reject(diagnostics) => {
                log::warn!(
                    "RAN Configuration Update from association {association_id} has {} \
                     not-comprehended IE(s) marked reject; sending RAN CONFIGURATION UPDATE FAILURE",
                    diagnostics.len()
                );
                if let Some(failure) =
                    crate::ngap_asn1::build_ran_configuration_update_failure_generated(
                        nextgcore_ngap::types::Cause::Protocol(
                            nextgcore_ngap::types::CauseProtocol::AbstractSyntaxErrorReject,
                        ),
                        None,
                        &diagnostics,
                    )
                {
                    self.send_to_association(association_id, &failure).await?;
                }
                return Ok(());
            }
            crate::ngap_asn1::RanConfigurationUpdateDecode::Undecodable => {
                // #752: TS 38.413 §10.2, a Transfer Syntax Error is reported with the
                // Error Indication procedure, not with the procedure's own failure
                // message: an undecodable message has no procedure the AMF could
                // say it failed.
                log::warn!(
                    "Undecodable RAN Configuration Update from association {association_id}; \
                     sending Error Indication (transfer-syntax-error, TS 38.413 §10.2)"
                );
                self.send_error_indication(
                    association_id,
                    None,
                    None,
                    ngap_gen::Cause::Protocol(ngap_gen::CauseProtocol(
                        ngap_gen::CauseProtocol::TRANSFER_SYNTAX_ERROR,
                    )),
                )
                .await?;
                return Ok(());
            }
        };
        log::info!(
            "RAN Configuration Update from association {}: ran_node_name={:?}, ta_list_len={}",
            association_id,
            upd.ran_node_name,
            upd.supported_ta_list.as_ref().map_or(0, |l| l.len())
        );

        // TS 38.413 §8.7.2: the update carries the gNB's *new* configuration, and
        // the AMF "shall overwrite" the corresponding stored values. Acknowledging
        // without storing was the subtler half of an earlier bug: NG-C looked
        // synchronised while the AMF went on serving the TAC/slice set from NG
        // Setup. The list is SIZE(1..), so a present one always replaces.
        {
            let mut sessions = self.sessions.write().await;
            if let Some(session) = sessions.get_mut(&association_id) {
                match upd.supported_ta_list {
                    Some(converted) => {
                        log::info!(
                            "Applying {} Supported TA entries from RAN Configuration Update to \
                             gNB {} (was {})",
                            converted.len(),
                            session.gnb.gnb_id,
                            session.gnb.num_of_supported_ta_list
                        );
                        session.gnb.num_of_supported_ta_list = converted.len();
                        session.gnb.supported_ta_list = converted;
                    }
                    None => log::debug!(
                        "RAN Configuration Update from association {association_id} carries no \
                         Supported TA List; keeping the stored {} entries",
                        session.gnb.num_of_supported_ta_list
                    ),
                }
                if let Some(ref name) = upd.ran_node_name {
                    log::debug!(
                        "gNB {} renamed itself to {name:?} in a RAN Configuration Update",
                        session.gnb.gnb_id
                    );
                }
            } else {
                log::warn!(
                    "RAN Configuration Update from unknown association {association_id}; \
                     acknowledging but storing nothing"
                );
            }
        }
        match crate::ngap_asn1::build_ran_configuration_update_acknowledge_generated(&notify) {
            Some(ack) => self.send_to_association(association_id, &ack).await?,
            None => log::error!("Failed to build RAN Configuration Update Acknowledge"),
        }
        Ok(())
    }

    /// Handle Initial UE Message
    ///
    /// Parses the contained NAS PDU and starts the appropriate 5GMM
    /// procedure (TS 24.501 Section 5.5.1 registration, Section 5.6.1
    /// service request). No blanket Identity Request: identification is
    /// only initiated when the UE identified itself with a GUTI unknown
    /// to this AMF (TS 23.502 Section 4.2.2.2.2 step 4).
    /// The AMF UE NGAP ID (TS 38.413 §9.3.3.1) for a UE this AMF meets over N2.
    ///
    /// From the AMF context's allocator, the one every other UE id comes from: the
    /// RAN UE pool, Namf-created UEs (`amf_ue_add`, #600) and the EPS→5GS target UE.
    /// They all key the one live UE store. Before #600 this drew from the server's
    /// gNB-id counter, which starts at 1 like the context allocator does, so an
    /// N2-registered UE and a Namf-created one could take the same key and the second
    /// overwrote the first.
    fn allocate_amf_ue_ngap_id(&mut self) -> u64 {
        #[cfg(test)]
        if let Some(forced) = self.forced_amf_ue_ngap_id.take() {
            return forced;
        }
        crate::context::amf_self()
            .read()
            .unwrap_or_else(|e| e.into_inner())
            .next_amf_ue_ngap_id()
    }

    async fn handle_initial_ue_message(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        log::info!(
            "Initial UE Message from association {} ({} bytes)",
            association_id,
            data.len()
        );

        // §10.3.4.2/§10.3.5 for a procedure with no response message: a message the
        // AMF must reject is terminated with an Error Indication; "ignore IE and
        // notify sender" IEs are reported in one and the NAS is still delivered.
        let initial_ue = match crate::ngap_asn1::decode_initial_ue_message_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                // Best effort: the report must not stop the procedure it reports on.
                if let Some(report) = error_indication {
                    if let Err(e) = self
                        .send_criticality_error_indication(association_id, &report)
                        .await
                    {
                        log::warn!("Failed to send ErrorIndication: {e}");
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!(
                    "Initial UE Message rejected (TS 38.413 §10.3.4.2/§10.3.5): {:?}",
                    report.diagnostics
                );
                return self
                    .send_criticality_error_indication(association_id, &report)
                    .await;
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(association_id, "Initial UE Message")
                    .await;
            }
        };

        log::info!(
            "Initial UE Message: ran_ue_ngap_id={}, nas_pdu_len={}, tac={}, nci=0x{:x}",
            initial_ue.ran_ue_ngap_id,
            initial_ue.nas_pdu.len(),
            initial_ue.tac,
            initial_ue.nr_cell_identity
        );

        // Allocate AMF-UE-NGAP-ID for this UE
        let amf_ue_ngap_id = self.allocate_amf_ue_ngap_id();

        let nas = initial_ue.nas_pdu.clone();
        if nas.len() < 3 || nas[0] != 0x7E {
            log::warn!("Initial UE Message NAS PDU is not 5GMM, ignoring");
            return Ok(());
        }
        let msg_type = nas[2];

        // A SERVICE REQUEST in an Initial UE Message is a UE coming back from
        // CM-IDLE -- possibly answering a page (#512). It is sent integrity
        // protected (TS 24.501 §4.4.6), so its message type is inside the security
        // header, not at octet 3; recognised here before the plain dispatch.
        if let Some(plain_sr) = initial_service_request_plain(&nas) {
            return self
                .handle_idle_service_request(
                    association_id,
                    amf_ue_ngap_id,
                    &initial_ue,
                    &nas,
                    &plain_sr,
                )
                .await;
        }

        // A REGISTRATION REQUEST from 5GMM-IDLE over a NAS security context is sent
        // integrity protected too (TS 24.501 §4.4.6), with the full request in a
        // ciphered NAS message container. Opened here, before the plain dispatch,
        // which would read a MAC octet as the message type (#609).
        let idle_registration = initial_protected_registration_request(&nas).map(|cleartext| {
            self.open_idle_registration_request(
                association_id,
                amf_ue_ngap_id,
                &initial_ue,
                &nas,
                cleartext,
            )
        });
        let msg_type = if idle_registration.is_some() {
            message_type::REGISTRATION_REQUEST
        } else {
            msg_type
        };

        match msg_type {
            message_type::REGISTRATION_REQUEST => {
                let (registration_request, integrity_protected) =
                    idle_registration.unwrap_or_else(|| (nas.clone(), false));
                // A verified request already moved the UE's own context to this id.
                if !integrity_protected {
                    let mut state = UeNasContext::new(
                        amf_ue_ngap_id,
                        initial_ue.ran_ue_ngap_id,
                        association_id,
                        crate::context::nas_security_canary(),
                    );
                    state.amf_ue.nr_tai = crate::context::Tai5gs {
                        plmn_id: initial_ue.plmn_id.clone(),
                        tac: initial_ue.tac,
                    };
                    // #406, the THIRD instance of the class: store the cell identity too.
                    //
                    // `parse_initial_ue_message_asn1` decodes `nr_cell_identity` off the
                    // InitialUEMessage's own `UserLocationInformation`
                    // (`ngap_asn1.rs:357-368`); before this it was LOGGED at `:1602-1607` and
                    // then dropped, so `amf_ue.nr_cgi` had exactly one production writer
                    // (`handle_handover_notify`) and an `ncgiList` Area of Interest could not
                    // resolve for a UE that had never handed over — #400 recorded that as a
                    // ceiling and #407 wrote a test pinning it.
                    //
                    // Worth doing because `ncgi` is not optional in what the AMF reports:
                    // TS 29.571 §5.4.4.9's `NrLocation` makes both `tai` and `ncgi` `M`
                    // (`29571-k00.txt:4674`, `:4689`), so without this half of a mandatory pair
                    // was a default for every UE that had only ever registered.
                    //
                    // `initial_ue.plmn_id` is decoded from `nr_cgi_plmn` (`ngap_asn1.rs:364`),
                    // so it is exactly the right source for `nr_cgi.plmn_id` — that IS the
                    // NR-CGI's PLMN.
                    //
                    // NOTE a PRE-EXISTING inexactness this write inherits rather than
                    // introduces: the `nr_tai` assignment immediately above uses the SAME
                    // value, so the registration path stores the NR-CGI's PLMN as the TAI's
                    // too. The IE carries them separately (`UserLocationInformation::Nr` has
                    // both `nr_cgi_plmn` and `tai_plmn`) and they can differ in a shared-RAN
                    // deployment, but `InitialUeMessageData` keeps only one and discards
                    // `tai_plmn` (`ngap_asn1.rs:357-368`). Not widened here: that is a
                    // different change, nothing in this tree distinguishes the two, and the
                    // three sites that go through `apply_user_location` do read them
                    // separately and get it right.
                    state.amf_ue.nr_cgi = crate::context::NrCgi {
                        plmn_id: initial_ue.plmn_id.clone(),
                        cell_id: initial_ue.nr_cell_identity,
                    };
                    state.amf_ue.access_type = 1; // 3GPP access
                    self.ue_auth_state.insert(amf_ue_ngap_id, state);
                }

                self.handle_registration_request_nas(
                    association_id,
                    amf_ue_ngap_id,
                    initial_ue.ran_ue_ngap_id,
                    &registration_request,
                    // An unprotected initial NAS message gets the §4.4.6 cleartext-IE
                    // gate; a verified one (#609) carries every IE legitimately.
                    integrity_protected,
                )
                .await?;
            }
            message_type::SERVICE_REQUEST => {
                // UE context unknown (fresh NGAP IDs) -> the UE identity cannot
                // be derived: Service Reject cause #9 forces re-registration
                // (TS 24.501 Section 5.6.1.5).
                log::warn!(
                    "Service Request in Initial UE Message without stored context: rejecting (#9)"
                );
                // #758: allocated to this connection with no NAS context, as in
                // `reject_idle_service_request`.
                self.remember_contextless_ue_id(
                    association_id,
                    amf_ue_ngap_id,
                    initial_ue.ran_ue_ngap_id,
                );
                let reject = gmm_build::build_service_reject(
                    &AmfUe::default(),
                    GmmCause::UeIdentityCannotBeDerivedByTheNetwork,
                );
                self.send_nas_pdu(
                    association_id,
                    amf_ue_ngap_id,
                    initial_ue.ran_ue_ngap_id,
                    &reject,
                )
                .await?;
            }
            other => {
                log::warn!("Unhandled NAS message type 0x{other:02x} in Initial UE Message");
            }
        }

        // Forward to event handler for FSM bookkeeping
        if let Some(session) = self.sessions.read().await.get(&association_id) {
            let event = AmfEvent::ngap_message(session.id, data.to_vec());
            let _ = self.event_tx.send(event).await;
        }

        Ok(())
    }

    /// Handle Uplink NAS Transport: decode security (if any) and dispatch
    async fn handle_uplink_nas_transport(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        // §10.3.4.2/§10.3.5, as for the Initial UE Message.
        let ul_nas = match crate::ngap_asn1::decode_uplink_nas_transport_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Err(e) = self
                        .send_criticality_error_indication(association_id, &report)
                        .await
                    {
                        log::warn!("Failed to send ErrorIndication: {e}");
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!(
                    "Uplink NAS Transport rejected (TS 38.413 §10.3.4.2/§10.3.5): {:?}",
                    report.diagnostics
                );
                return self
                    .send_criticality_error_indication(association_id, &report)
                    .await;
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(association_id, "Uplink NAS Transport")
                    .await;
            }
        };

        log::info!(
            "Uplink NAS Transport: amf_ue_ngap_id={}, ran_ue_ngap_id={}, nas_pdu_len={}",
            ul_nas.amf_ue_ngap_id,
            ul_nas.ran_ue_ngap_id,
            ul_nas.nas_pdu.len()
        );

        // #406: LEARN THE UE'S LOCATION. `UserLocationInformation` is MANDATORY on this
        // message (TS 38.413 §9.2.5.3, `38413-j30.txt:14672-14673`) precisely because a
        // UE that moved while in CM-IDLE reports where it now is on the way back up —
        // TS 23.502 §4.2.3.2 step 2: the location *"relates to the cell in which the UE
        // is camping"* (`23502-k20.txt:6155`), present tense, the current cell and not
        // the one it registered from.
        //
        // Before this the IE was decoded by the NGAP parser, refused if absent, and then
        // DISCARDED one assignment short of use: `UplinkNasTransportData` had no field
        // for it. So `handle_service_request_nas`'s `LOCATION_REPORT` (#402) reported the
        // TAI written at registration, and #400's presence events declined to fire from
        // that site rather than report an unchanged verdict as news.
        //
        // ORDERING IS LOAD-BEARING, and this is why the write is HERE rather than beside
        // the SERVICE REQUEST arm of the dispatch below:
        //
        // 1. `handle_service_request_nas` reads the UE back out of the store to build the
        //    Service Accept and to fire its events. A write placed after dispatch would
        //    leave `fire_location_report` reading the OLD TAI — the same defect, relocated.
        // 2. The legacy raw-5GSM branch (`epd == 0x2E`) and the MAC-failure branch both
        //    return early. Each is still an Uplink NAS Transport carrying a mandatory,
        //    already-validated location, and a UE whose PDU session signalling arrives
        //    from a new cell has still moved.
        // 3. The IE's validity does not depend on the NAS payload: it was decoded and
        //    accepted before `parse_uplink_nas_transport_asn1` returned. Nothing below can
        //    make it untrue.
        //
        // Safe despite the security-decode block's `remove`/`insert` round-trip further
        // down: that takes the same record out, mutates it and puts it back, so this
        // field write survives.
        //
        // `with_mut` and not `get`: `UeStore::get` returns a CLONE
        // (`ue_store.rs:113-115`), and this crate has twice had a handler mutate a clone
        // it then dropped. `None` means the UE is unknown, which the branches below
        // already answer for — a location for a UE with no context has nowhere to go.
        // An absent or non-NR location (now delivered rather than refused) leaves the
        // stored one in place.
        self.ue_auth_state.with_mut(ul_nas.amf_ue_ngap_id, |state| {
            let Some(location) = &ul_nas.user_location_info else {
                return;
            };
            apply_user_location(&mut state.amf_ue, location);
            log::debug!(
                "UE {} location refreshed from the Uplink NAS Transport (tac={}, nci=0x{:x})",
                ul_nas.amf_ue_ngap_id,
                state.amf_ue.nr_tai.tac,
                state.amf_ue.nr_cgi.cell_id
            );
        });

        // #675: an INITIAL registration on an NG connection that has no NAS context
        // yet -- the connection began with a Service Request the AMF rejected with #9
        // (`reject_idle_service_request` creates no context), and the UE, as told,
        // registers afresh with its SUCI on the same connection. An initial
        // registration needs no prior context (TS 24.501 §5.5.1.2), so it gets one
        // here, exactly as the Initial UE Message path creates it. Before #675 it fell
        // to the "unknown UE" branch and was answered REGISTRATION REJECT #9 on every
        // T3511 retry: after an AMF restart the UE could never register again.
        //
        // #758: only for an ID this AMF allocated to THIS connection (association and
        // RAN UE NGAP ID), which `reject_idle_service_request` recorded. An ID never
        // allocated, or allocated elsewhere, is answered with an Error Indication
        // (TS 38.413 §10.6), not given a context: such an ID could later be allocated
        // to a different UE, and one context per invented ID is unbounded.
        if !self.ue_auth_state.contains(ul_nas.amf_ue_ngap_id) {
            match self.take_contextless_ue_id(
                association_id,
                ul_nas.amf_ue_ngap_id,
                ul_nas.ran_ue_ngap_id,
            ) {
                ContextlessLookup::Matches => {
                    match fresh_context_for_initial_registration(association_id, &ul_nas) {
                        Some(state) => {
                            log::info!(
                                "UE {}: initial Registration Request on an NG connection with \
                                 no NAS context; creating one (TS 24.501 §5.5.1.2)",
                                ul_nas.amf_ue_ngap_id
                            );
                            self.ue_auth_state.insert(ul_nas.amf_ue_ngap_id, state);
                        }
                        // Not (yet) an initial registration: the connection keeps its
                        // allocation for the one that follows.
                        None => self.remember_contextless_ue_id(
                            association_id,
                            ul_nas.amf_ue_ngap_id,
                            ul_nas.ran_ue_ngap_id,
                        ),
                    }
                }
                lookup => {
                    // Known deviation from TS 38.413 §10.6, Inconsistent case: §10.6 has
                    // both nodes locally release the logical connection "having the
                    // erroneous AP ID". The allocation is kept instead, for the genuine
                    // connection it belongs to: a peer naming a wrong RAN UE NGAP ID
                    // must not be able to tear down another UE's pending registration.
                    // Only the Error Indication is sent.
                    let cause = match lookup {
                        ContextlessLookup::Inconsistent => {
                            ngap_gen::CauseRadioNetwork::INCONSISTENT_REMOTE_UE_NGAP_ID
                        }
                        _ => ngap_gen::CauseRadioNetwork::UNKNOWN_LOCAL_UE_NGAP_ID,
                    };
                    log::warn!(
                        "Uplink NAS Transport on association {association_id} names AMF UE NGAP \
                         ID {} (RAN UE NGAP ID {}), which has no context here: Error Indication \
                         ({lookup:?}, TS 38.413 §10.6)",
                        ul_nas.amf_ue_ngap_id,
                        ul_nas.ran_ue_ngap_id
                    );
                    return self
                        .send_error_indication(
                            association_id,
                            Some(ul_nas.amf_ue_ngap_id),
                            Some(ul_nas.ran_ue_ngap_id),
                            ngap_gen::Cause::RadioNetwork(ngap_gen::CauseRadioNetwork(cause)),
                        )
                        .await;
                }
            }
        }

        if ul_nas.nas_pdu.len() < 3 {
            return Ok(());
        }

        let epd = ul_nas.nas_pdu[0];

        // Legacy compatibility: raw 5GSM PDU not wrapped in UL NAS TRANSPORT
        if epd == 0x2E {
            self.handle_5gsm_message(
                association_id,
                ul_nas.amf_ue_ngap_id,
                ul_nas.ran_ue_ngap_id,
                &ul_nas.nas_pdu,
                None,
            )
            .await?;
            return Ok(());
        }

        if epd != 0x7E {
            log::warn!("Unknown NAS EPD 0x{epd:02x}, discarding");
            return Ok(());
        }

        let sec_hdr = ul_nas.nas_pdu[1];
        let inner: Vec<u8> = if sec_hdr == security_header::PLAIN_NAS_MESSAGE {
            ul_nas.nas_pdu.clone()
        } else {
            // Security-protected: decode with the UE's NAS security context
            let Some(mut state) = self.ue_auth_state.remove(ul_nas.amf_ue_ngap_id) else {
                log::warn!(
                    "Protected NAS from unknown UE {} discarded",
                    ul_nas.amf_ue_ngap_id
                );
                return Ok(());
            };
            let decoded =
                nas_security::nas_5gs_security_decode(&mut state.amf_ue, sec_hdr, &ul_nas.nas_pdu);
            let mac_failed = state.amf_ue.mac_failed;
            state.amf_ue.mac_failed = false;
            self.ue_auth_state.insert(ul_nas.amf_ue_ngap_id, state);
            match decoded {
                Ok(plain) => {
                    if mac_failed {
                        // TS 24.501 §4.4.4.3: a message that fails the integrity check is
                        // discarded, EXCEPT for the named cases. The old comment here
                        // claimed those exceptions were "handled before security
                        // establishment" -- but this discard runs AFTER the security
                        // context has been resolved, so a MAC-failed mobility
                        // REGISTRATION REQUEST or SERVICE REQUEST on an existing context
                        // reached it and was dropped, which is the one thing §4.4.4.3
                        // says must not happen to them.
                        return self
                            .handle_integrity_check_failure(
                                association_id,
                                &ul_nas,
                                &plain,
                                sec_hdr,
                            )
                            .await;
                    }
                    plain
                }
                Err(e) => {
                    log::warn!("NAS security decode failed: {e:?}, discarding");
                    return Ok(());
                }
            }
        };

        if inner.len() < 3 || inner[0] != 0x7E {
            log::warn!("Decoded NAS message malformed, discarding");
            return Ok(());
        }
        let msg_type = inner[2];

        match msg_type {
            message_type::REGISTRATION_REQUEST => {
                // Mobility / periodic registration update over existing connection.
                // Integrity-protected iff it arrived under a NAS security context
                // (a plain message has security-header PLAIN_NAS_MESSAGE).
                let integrity_protected = sec_hdr != security_header::PLAIN_NAS_MESSAGE;
                self.handle_registration_request_nas(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                    integrity_protected,
                )
                .await?;
            }
            message_type::IDENTITY_RESPONSE => {
                self.handle_identity_response_nas(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                )
                .await?;
            }
            message_type::AUTHENTICATION_RESPONSE => {
                self.handle_authentication_response_nas(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                )
                .await?;
            }
            message_type::AUTHENTICATION_FAILURE => {
                self.handle_authentication_failure_nas(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                )
                .await?;
            }
            message_type::SECURITY_MODE_COMPLETE => {
                self.handle_security_mode_complete_nas(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                )
                .await?;
            }
            message_type::SECURITY_MODE_REJECT => {
                let cause = inner.get(3).copied().unwrap_or(0);
                log::error!(
                    "Security Mode Reject from UE {} (5GMM cause #{cause}); aborting procedure",
                    ul_nas.amf_ue_ngap_id
                );
                // TS 24.501 Section 5.4.2.5: abort the procedure; the network
                // releases the N1 signalling connection.
                self.release_ue(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    1,
                )
                .await?;
            }
            message_type::REGISTRATION_COMPLETE => {
                self.ue_auth_state.with_mut(ul_nas.amf_ue_ngap_id, |state| {
                    if matches!(
                        state.retx,
                        Some(NasRetx {
                            timer: NasProcTimer::T3550,
                            ..
                        })
                    ) {
                        state.retx = None;
                    }
                    state.registered = true;
                    state.amf_ue.current_guti = state.amf_ue.next_guti.clone();
                    state.amf_ue.current_m_tmsi = Some(state.amf_ue.next_guti.tmsi);
                    log::info!(
                        "[{}] Registration Complete (5G-TMSI=0x{:08x})",
                        state.suci,
                        state.amf_ue.current_guti.tmsi
                    );
                });
                // #570: an ID the UCMF assigned while the registration was in progress
                // is delivered now, by a UE configuration update (TS 24.501 §5.4.4.2).
                self.send_racs_configuration_update(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                )
                .await?;
            }
            message_type::CONFIGURATION_UPDATE_COMPLETE => {
                // TS 24.501 §5.4.4.3: the COMPLETE stops T3555 and the procedure is
                // finished. Before this the type had no arm at all, so a conformant
                // UE's acknowledgement was logged as "Unhandled 5GMM message type
                // 0x55" and the AMF retransmitted the command four more times.
                self.ue_auth_state.with_mut(ul_nas.amf_ue_ngap_id, |state| {
                    let was_pending = matches!(
                        state.retx,
                        Some(NasRetx {
                            timer: NasProcTimer::T3555,
                            ..
                        })
                    );
                    if was_pending {
                        state.retx = None;
                        // #570: a command that only carried a UE radio capability ID
                        // left the GUTI alone; say so rather than claim a reallocation.
                        let reallocated = state.amf_ue.current_guti != state.amf_ue.next_guti;
                        // The UE accepted the new identity, so it becomes the current
                        // one (TS 33.501 §6.12.3).
                        state.amf_ue.current_guti = state.amf_ue.next_guti.clone();
                        state.amf_ue.current_m_tmsi = Some(state.amf_ue.next_guti.tmsi);
                        if reallocated {
                            log::info!(
                                "[{}] Configuration Update Complete: 5G-GUTI reallocated \
                                 (5G-TMSI=0x{:08x})",
                                state.suci,
                                state.amf_ue.current_guti.tmsi
                            );
                        } else {
                            log::info!(
                                "[{}] Configuration Update Complete: T3555 stopped",
                                state.suci
                            );
                        }
                    } else {
                        // Not an error: TS 24.501 permits a COMPLETE for a command the
                        // AMF has already given up on. Logged rather than dropped
                        // silently, because it also catches a UE acknowledging a command
                        // this AMF never sent.
                        log::info!(
                            "Configuration Update Complete from UE {} with no T3555 \
                             pending; nothing to stop",
                            ul_nas.amf_ue_ngap_id
                        );
                    }
                });
                // #746: a UE radio capability ID that arrived while this command was in
                // flight was deferred; it goes now, in a command of its own.
                self.send_racs_configuration_update(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                )
                .await?;
            }
            message_type::SERVICE_REQUEST => {
                self.handle_service_request_nas(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                )
                .await?;
            }
            message_type::DEREGISTRATION_REQUEST_FROM_UE => {
                self.handle_deregistration_request_nas(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                )
                .await?;
            }
            message_type::DEREGISTRATION_ACCEPT_TO_UE => {
                // UE acknowledged a network-initiated deregistration
                log::info!(
                    "Deregistration Accept from UE {} (network-initiated procedure done)",
                    ul_nas.amf_ue_ngap_id
                );
                self.finish_deregistration(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                )
                .await?;
            }
            message_type::UL_NAS_TRANSPORT => {
                self.handle_ul_nas_transport_nas(
                    association_id,
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                )
                .await?;
            }
            message_type::GMM_STATUS => {
                let cause = inner.get(3).copied().unwrap_or(0);
                log::warn!(
                    "5GMM Status from UE {}: cause #{cause}",
                    ul_nas.amf_ue_ngap_id
                );
            }
            message_type::UAV_TRACKING_REPORT => {
                // UAV tracking report (Rel-18, TS 23.256): an aerial UE's
                // position / Remote-ID report. Run the geofence against the
                // stored UAV authorization context.
                self.handle_uav_tracking_report_nas(
                    ul_nas.amf_ue_ngap_id,
                    ul_nas.ran_ue_ngap_id,
                    &inner,
                );
            }
            other => {
                log::warn!("Unhandled 5GMM message type 0x{other:02x}");
            }
        }

        // Forward to event handler for FSM bookkeeping
        if let Some(session) = self.sessions.read().await.get(&association_id) {
            let event = AmfEvent::ngap_message(session.id, data.to_vec());
            let _ = self.event_tx.send(event).await;
        }

        Ok(())
    }

    /// Handle a UAV tracking report (Rel-18, TS 23.256).
    ///
    /// Parses the UE-originated position report (CAA-level ID + lat/lon/alt +
    /// flight status, see the nextgsim UE `build_uav_tracking_report`) and runs
    /// it through the stored UAV authorization context's geofence. A position
    /// inside the geofence is allowed; an altitude or area violation produces a
    /// deny and revokes the flight authorization (TS 23.256: the network
    /// withdraws UAV authorization on a geofence breach).
    fn handle_uav_tracking_report_nas(
        &mut self,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        inner: &[u8],
    ) {
        let Some(report) = parse_uav_tracking_report(amf_ue_ngap_id, ran_ue_ngap_id, inner) else {
            log::warn!("Malformed UAV tracking report from UE {amf_ue_ngap_id}; discarding");
            return;
        };

        // Dispatch to the NGAP-layer tracking-report handler for logging /
        // bookkeeping (it verifies the NGAP IDs and records the position).
        log::info!(
            "[UAV Tracking] Dispatching report from UE {amf_ue_ngap_id} to handler: \
             CAA-ID={}, pos=({:.6}, {:.6}), alt={:.1}m, status={}",
            report.uav_id,
            report.latitude,
            report.longitude,
            report.altitude,
            report.flight_status
        );

        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(report.timestamp);

        // The whole decision runs inside `with_mut`, because the geofence check
        // MUTATES the UAV authorization on a violation: checking under one lock
        // acquisition and revoking under another would let a concurrent update
        // land in between. Nothing in here `.await`s, so holding the write lock
        // for the duration is safe -- and `with_mut` taking a plain closure is
        // what makes that structural rather than something to remember.
        let revoked = self
            .ue_auth_state
            .with_mut(amf_ue_ngap_id, |state| {
                let Some(uav) = state.amf_ue.uav_auth.as_mut() else {
                    log::warn!(
                        "UAV tracking report from UE {amf_ue_ngap_id} that is not \
                         UAV-authorized; discarding (no UAV authorization context)"
                    );
                    return false;
                };

                // Geofence check via the NGAP-layer UAV handler: returns true when the
                // position is within bounds and still authorized (allow), false on an
                // altitude/area violation or expired authorization (deny).
                let allowed = crate::ngap_handler::handle_uav_tracking_report(uav, &report, now);
                if allowed {
                    log::info!(
                        "[UAV Tracking] Geofence ALLOW: UAV {} at ({:.6}, {:.6}) alt={:.1}m \
                         within bounds",
                        report.uav_id,
                        report.latitude,
                        report.longitude,
                        report.altitude
                    );
                    return false;
                }
                log::warn!(
                    "[UAV Tracking] Geofence DENY: UAV {} at ({:.6}, {:.6}) alt={:.1}m violates \
                     flight authorization; revoking",
                    report.uav_id,
                    report.latitude,
                    report.longitude,
                    report.altitude
                );
                uav.revoke_authorization("geofence violation");
                true
            })
            .unwrap_or_else(|| {
                log::warn!("UAV tracking report from unknown UE {amf_ue_ngap_id}; discarding");
                false
            });

        if revoked {
            // TS 23.256: a real deployment would notify the USS/UTM and PCF of the
            // withdrawn authorization here (documented stub). Outside `with_mut`
            // so the store lock is not held across the notification, which is the
            // shape that would matter once this stops being a stub.
            notify_uss_authorization(&report.uav_id, "REVOKED");
        }
    }

    /// Handle a (plain) Registration Request NAS PDU
    async fn handle_registration_request_nas(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
        // True when this Registration Request arrived integrity-protected (a
        // mobility/periodic update over an existing NAS security context, or the
        // replay inside Security Mode Complete); false for an unprotected
        // initial NAS message (InitialUEMessage). Drives the §4.4.6 gate.
        integrity_protected: bool,
    ) -> Result<()> {
        let Some(req) = parse_registration_request_pdu(nas) else {
            log::error!("Malformed Registration Request: rejecting (#96)");
            let reject =
                gmm_build::build_registration_reject(GmmCause::InvalidMandatoryInformation);
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                .await?;
            return Ok(());
        };

        // TS 24.501 §4.4.6 / TS 33.501 §6.4.6: enforce cleartext-IE + integrity
        // rules BEFORE any IE influences UE context state. An unprotected initial
        // Registration Request carrying a non-cleartext IE (e.g. Requested NSSAI)
        // or a NAS message container is rejected with 5GMM #95.
        if let Some(cause) = validate_initial_registration_cleartext(&req, integrity_protected) {
            let reject = gmm_build::build_registration_reject(cause);
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                .await?;
            return Ok(());
        }

        // TS 24.501 §5.3.5: NAS-level congestion control. Under overload the AMF sheds
        // load by refusing the registration with 5GMM cause #22 and a T3346 back-off, so
        // the UE waits instead of retrying immediately. Without it the AMF has no
        // NAS-level defence at all: every refused UE comes straight back.
        //
        // EMERGENCY registrations are exempt, and that exemption is the reason this check
        // is here rather than at the reject sites: §5.3.5 forbids applying congestion
        // control to emergency services, and a regulatory obligation must not be shed.
        if req.registration_type != crate::gmm_build::registration_type::EMERGENCY {
            if let Some(backoff) = self.nas_congestion_backoff() {
                log::warn!(
                    "NAS congestion: rejecting registration from UE {amf_ue_ngap_id} with \
                     5GMM #22 and a {backoff}s T3346 back-off (TS 24.501 §5.3.5)"
                );
                let reject = gmm_build::build_registration_reject_with_backoff(
                    GmmCause::Congestion,
                    Some(backoff),
                );
                self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                    .await?;
                return Ok(());
            }
        }

        log::info!(
            "Registration Request: type={}, ngKSI={}/{}, identity_type={}, suci={:?}",
            req.registration_type,
            req.tsc,
            req.ksi,
            req.identity_type,
            req.suci
        );

        // MINT (Rel-18, TS 23.761 §4.2): a UE may register more than one
        // subscription (multi-SUPI). Each distinct registration arrives with
        // its own RAN/AMF UE NGAP ID and is handled as a separate AMF UE
        // context with its own 5G-GUTI — the second SUPI is NOT rejected. The
        // disaster-roaming indication, when present, marks the registration for
        // minimization-of-service-interruption handling.
        if req.disaster_roaming {
            log::info!(
                "MINT disaster-roaming indication present (amf_ue_ngap_id={amf_ue_ngap_id}, \
                 suci={:?}); accepting as a distinct multi-SUPI registration",
                req.suci
            );
        }

        // TS 24.501 §5.5.1.2 / TS 23.167: an EMERGENCY registration is not an ordinary
        // one. It is admitted without a verified subscription where regulation requires
        // it, and it must be recorded as an emergency context so the emergency DNN and
        // P-CSCF are used for its session. Before this the registration type was read
        // only by `nia0_permitted` and the handler had no caller outside its own tests,
        // so an emergency registration was processed as a normal one -- which is a
        // regulatory-grade gap, not a cosmetic one.
        if req.registration_type == crate::gmm_build::registration_type::EMERGENCY {
            // `authenticated: false`, unconditionally, because at THIS point in the procedure
            // nothing has been authenticated (#361). This argument used to be
            // `supi.is_some() || req.suci.is_some()`, which was the presence of an IDENTITY,
            // not an authentication outcome -- and `AmfUe::supi` is written only from the AUSF
            // confirmation much later, so the predicate reduced to "the UE sent some SUCI".
            // Every emergency registration carrying one, INCLUDING the ones the AUSF then
            // refused or could not be asked about, was recorded `authenticated: true`. That is
            // the field §10.2.2.1 requires to distinguish an unauthenticated emergency caller,
            // so it was wrong in exactly the case it exists for.
            //
            // The context is promoted by `emergency.mark_authenticated` when the AUSF actually
            // confirms, and left as-is (or explicitly demoted) when it does not.
            let ctx = self
                .emergency
                .handle_emergency_registration(amf_ue_ngap_id, false);
            log::warn!(
                "EMERGENCY registration from UE {amf_ue_ngap_id}: authenticated={} (pending), \
                 reg_type={:?}, emergency DNN '{}' (TS 24.501 §5.5.1.2, TS 23.167)",
                ctx.authenticated,
                ctx.reg_type,
                self.emergency.emergency_dnn()
            );
            // No new "is emergency" flag: `AmfUe.registration_type` is assigned from
            // this same request a few lines below and already carries the answer, which
            // is how `nas_security::nia0_permitted` reads it. A second field would be a
            // copy that can disagree with the first.
            //
            // Falls through to the normal registration flow deliberately: the
            // authentication, security-mode and Registration Accept steps are the same
            // procedure. What differs is that the emergency context now EXISTS, so the
            // emergency DNN / P-CSCF are available for the session that follows.
        }

        // Periodic registration updating with live security context: refresh
        if req.registration_type == crate::gmm_build::registration_type::PERIODIC_UPDATING {
            if let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) {
                if state.amf_ue.security_context_available && state.registered {
                    log::info!("Periodic Registration Update from UE {amf_ue_ngap_id}");
                    self.send_registration_accept(association_id, amf_ue_ngap_id, ran_ue_ngap_id)
                        .await?;
                    return Ok(());
                }
            }
            // No context: the UE identity cannot be derived (TS 24.501 5.5.1.3.5)
            let reject = gmm_build::build_registration_reject(
                GmmCause::UeIdentityCannotBeDerivedByTheNetwork,
            );
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                .await?;
            return Ok(());
        }

        let Some(mut state) = self.ue_auth_state.get(amf_ue_ngap_id) else {
            // Mobility update on an unknown UE: reject so it re-registers
            let reject = gmm_build::build_registration_reject(
                GmmCause::UeIdentityCannotBeDerivedByTheNetwork,
            );
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                .await?;
            return Ok(());
        };

        state.amf_ue.registration_type = req.registration_type;
        state.amf_ue.nas_ue_tsc = req.tsc;
        state.amf_ue.nas_ue_ksi = req.ksi;
        // #116: EPC NAS ("S1 mode") support from the UE's 5GMM capability IE
        // (TS 24.501 §9.11.3.1 octet 3 bit 1). `gmm_capability.s1_mode` had no writer
        // at all before this, so `build_registration_accept` could not obey
        // §5.5.1.2.4 -- which makes the IWK N26 indication conditional on precisely
        // this bit. Recorded here, with the other capability-shaped fields, so it is
        // set before any branch that reads it.
        state.amf_ue.gmm_capability.s1_mode = req.s1_mode;
        // #570: RACS (TS 24.501 §5.4.4.1). The bit is re-read on every registration;
        // an ID the UE presents is one it already holds.
        state.amf_ue.racs_supported = req.racs_supported;
        if let Some(id) = req.ue_radio_capability_id.clone() {
            state.amf_ue.ue_radio_capability_id = Some(id);
            state.amf_ue.ue_radio_capability_id_known_to_ue = true;
        }
        // Computed here, before anything moves a field out of `req` (the security
        // capability below is not `Copy`): this predicate reads three of them.
        let guti_mapped_from_eps = req.guti_is_mapped_from_eps();
        if req.s1_mode {
            log::info!(
                "UE claims S1 mode (EPC NAS) support: the Registration Accept will carry \
                 the 5GS network feature support IE with IWK N26 (TS 24.501 §5.5.1.2.4)"
            );
        }
        // #91: park the UE policy container for the Npcf_UEPolicyControl_Create that
        // happens later in the procedure. Overwritten, not merged, on a re-sent
        // Registration Request: the latest one is the UE's current installed set, and
        // a stale UPSI list would have the PCF compute the diff against the wrong
        // baseline. `None` clears it for the same reason.
        state.ue_policy_container = req.ue_policy_container().map(|c| c.to_vec());
        // Store the UE security capability EXACTLY as received so the
        // Security Mode Command replays it (TS 33.501 Section 6.7.2)
        if let Some(cap) = req.sec_cap {
            state.amf_ue.ue_security_capability = cap;
        } else {
            log::warn!(
                "Registration Request without UE security capability IE; \
                 assuming null algorithms only (no capability fabrication)"
            );
            state.amf_ue.ue_security_capability = UeSecurityCapability {
                ea: 0x80, // 5G-EA0 only
                ia: 0x80, // 5G-IA0 only
                eea: 0,
                eia: 0,
            };
        }
        // TS 24.501 §4.4.6: the Requested NSSAI is a NON-cleartext IE and MUST
        // NOT be taken from the unprotected initial Registration Request. It is
        // populated only from the integrity-protected replay inside Security
        // Mode Complete (`handle_security_mode_complete_nas`).

        match req.identity_type {
            t if t == mobile_identity_type::SUCI => {
                let Some(suci) = req.suci else {
                    let reject =
                        gmm_build::build_registration_reject(GmmCause::InvalidMandatoryInformation);
                    self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                        .await?;
                    return Ok(());
                };
                state.suci = suci.clone();
                state.amf_ue.suci = Some(suci.clone());
                if let Some(plmn) = req.plmn {
                    state.amf_ue.home_plmn_id = plmn;
                }

                // SNPN access authorization (Rel-17, TS 23.501 §5.30 / TS 24.501).
                // When the UE advertised an SNPN NID, validate it against the
                // AMF's configured allowed-NID list. A non-allowed NID is
                // rejected with the SNPN-specific 5GMM cause (#75, permanently
                // not authorized for this SNPN). An allowed NID drives the
                // SNPN auth context; an onboarding SUCI drives onboarding.
                if let Some(ref nid) = req.snpn_nid {
                    let allowed_nids = snpn_allowed_nids();
                    if !state.amf_ue.validate_nid(nid, &allowed_nids) {
                        log::warn!(
                            "SNPN registration rejected: NID={nid} not in allowed list {allowed_nids:?}"
                        );
                        let reject = gmm_build::build_registration_reject(
                            GmmCause::PermanentlyNotAuthorized,
                        );
                        self.reject_and_release(
                            association_id,
                            amf_ue_ngap_id,
                            ran_ue_ngap_id,
                            &reject,
                            1,
                        )
                        .await?;
                        return Ok(());
                    }
                    if is_snpn_onboarding_suci(&suci) {
                        // Onboarding SUCI (TS 23.003): provision initial
                        // credentials via the SNPN onboarding flow.
                        let creds = crate::context::SnpnSubscriptionCredentials::default();
                        state.amf_ue.handle_snpn_onboarding(nid, creds);
                        log::info!("SNPN onboarding registration accepted for NID={nid}");
                    } else {
                        state.amf_ue.start_snpn_auth(nid);
                        log::info!("SNPN registration authorized for NID={nid}");
                    }
                }

                // UAV flight authorization (Rel-18, TS 23.256). When the UE
                // registered as an aerial UE, create and grant a UAV
                // authorization context with the AMF's configured geofence so
                // subsequent UAV tracking reports are checked against it. UTM /
                // USS authorization is represented by the local grant here; an
                // external USS interface is a documented stub (see
                // `notify_uss_authorization`).
                if let Some(ref caa_id) = req.uav_indication {
                    let now = std::time::SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .map(|d| d.as_secs())
                        .unwrap_or(0);
                    let mut uav = crate::context::UavAuthorizationContext::new(caa_id, &suci);
                    let (min_lat, max_lat, min_lon, max_lon, min_alt, max_alt) =
                        uav_geofence_config();
                    uav.set_geofence(min_lat, max_lat, min_lon, max_lon, min_alt, max_alt);
                    // Authorize for a 1-hour flight window from now.
                    uav.grant_authorization(now, now + 3600);
                    notify_uss_authorization(caa_id, &suci);
                    log::info!(
                        "UAV registration: aerial UE authorized (CAA-ID={caa_id}); geofence \
                         lat=[{min_lat},{max_lat}] lon=[{min_lon},{max_lon}] alt=[{min_alt},{max_alt}]"
                    );
                    state.amf_ue.uav_auth = Some(uav);
                }

                // RedCap (Rel-17, TS 38.101): a reduced-capability UE gets a
                // capped UE-AMBR, and the indication is propagated to the SMF on
                // the N11 SM Context Create so the session-AMBR is reduced too.
                if req.redcap_indication {
                    state.amf_ue.redcap_indication = true;
                    if state.amf_ue.ue_ambr.downlink > 150_000_000 {
                        state.amf_ue.ue_ambr.downlink = 150_000_000; // 150 Mbps DL
                    }
                    if state.amf_ue.ue_ambr.uplink > 50_000_000 {
                        state.amf_ue.ue_ambr.uplink = 50_000_000; // 50 Mbps UL
                    }
                    log::info!("UE indicates RedCap (Reduced Capability) device");
                }

                // PERSIST before handing off (#361). `ue_auth_state.get` returns a CLONE --
                // deliberately, so no lock is held across an `.await` (see `ue_store`'s module
                // docs) -- and this handler is the one place that mutated the clone and never
                // wrote it back. Everything assigned above was therefore DISCARDED at the end
                // of this function: the registration type, the SUCI, the UE security
                // capability, the S1-mode capability, the UE policy container, the SNPN and
                // UAV contexts, the RedCap indication and the capped UE-AMBR.
                //
                // `start_authentication` opens by TAKING the record out of the store, so it
                // read the pre-registration context every time. That is why #361's own premise
                // -- "`state.amf_ue.registration_type` is right there and carries the answer"
                // -- was not actually true at the point the AUSF-failure arm runs: the field
                // was still 0 there, so a registration-type check would never have matched
                // EMERGENCY however it was written.
                //
                // Found by probing for it rather than by reading: the #361 branch appeared
                // correct and simply never fired. Verified at `89cb764` before this change, so
                // it is pre-existing and not introduced here.
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                self.start_authentication(association_id, amf_ue_ngap_id, ran_ue_ngap_id, None)
                    .await?;
            }
            t if t == mobile_identity_type::GUTI => {
                if guti_mapped_from_eps {
                    // EPS→5GS mobility (#116). The identity is a 5G-GUTI the UE MAPPED
                    // from its 4G-GUTI (TS 23.003 §2.10.2.2.2), not a native one, and
                    // the two are structurally indistinguishable -- so storing it in
                    // `old_guti` claimed a native context that never existed and threw
                    // away the only identity an MME could be asked about.
                    //
                    // Recover the 4G-GUTI by the reverse mapping §2.10.2.1.3 requires,
                    // and keep it where it cannot be mistaken for a native 5G-GUTI.
                    let mapped = req.guti.as_ref().map(|g| {
                        nextgcore_nas::interworking::five_g_guti_to_eps_guti(
                            &nextgcore_nas::fiveg::types::FiveGGuti {
                                plmn_id: crate::gmm_build::to_nextgcore_plmn(&g.plmn_id),
                                amf_region_id: g.amf_region_id,
                                amf_set_id: g.amf_set_id,
                                amf_pointer: g.amf_pointer,
                                tmsi: g.tmsi,
                            },
                        )
                    });
                    if let Some(ref eps_guti) = mapped {
                        log::info!(
                            "EPS→5GS registration: 5GS mobile identity is a 5G-GUTI mapped \
                             from EPS; recovered 4G-GUTI (MME GID={:#06x}, MME code={:#04x}, \
                             M-TMSI={:#010x}) from the reverse mapping (TS 23.003 §2.10.2.1.3). \
                             This AMF has no N26 leg, so the UE context is NOT retrieved from \
                             the old MME (#62); the UE is identified afresh by SUCI instead of \
                             the registration being rejected",
                            eps_guti.mme_gid,
                            eps_guti.mme_code,
                            eps_guti.m_tmsi
                        );
                    }
                    state.amf_ue.mapped_eps_guti = mapped;
                    // The Additional GUTI IE, when the UE included one, IS the native
                    // 5G-GUTI (§5.5.1.2.2) -- so that, and only that, may become
                    // `old_guti`.
                    if let Some(native) = req.additional_guti {
                        state.amf_ue.old_guti = native;
                    }
                    if let Some(ref container) = req.eps_nas_message_container {
                        // Not decoded: the ATTACH/TAU REQUEST inside is an EPS NAS
                        // message whose handling IS the N26 leg (#62). Recording its
                        // presence and size is the honest ceiling -- pretending to
                        // have processed it would be worse than saying it was not.
                        log::info!(
                            "EPS NAS message container present ({} octets): carries the \
                             ATTACH/TAU REQUEST the MME would handle. Not processed -- \
                             EPS NAS interpretation is the N26 leg (#62)",
                            container.len()
                        );
                    }
                } else if let Some(guti) = req.guti.clone() {
                    state.amf_ue.old_guti = guti;
                }
                // PERSIST before the send, for the same reason as the SUCI arm above (#361):
                // the mapped EPS GUTI, the native old-GUTI and the registration type all live
                // on the clone until this line. This arm is the worse of the two to lose,
                // because it goes on to await an Identity Response whose handler resolves the
                // UE from the store -- so a lost `registration_type` here is lost for the whole
                // GUTI-identified registration, not merely until the next message.
                //
                // Inserted BEFORE the `?` on the send, so a failed Identity Request leaves the
                // recorded registration behind rather than discarding it (the #359 lesson).
                //
                // #609: a mobility registration update whose integrity was verified under
                // the UE's current NAS security context needs neither identification nor
                // a fresh authentication (TS 23.502 §4.2.2.2.2 step 9: authentication is
                // optional). It is accepted under that context, as the periodic update
                // above is. Re-authenticating instead would send an AUTHENTICATION REQUEST
                // in the clear to a UE whose NAS security is active.
                let accept_under_current_context = integrity_protected
                    && !guti_mapped_from_eps
                    && req.registration_type
                        == crate::gmm_build::registration_type::MOBILITY_UPDATING
                    && state.registered
                    && state.amf_ue.security_context_available
                    && req.guti.as_ref() == Some(&state.amf_ue.current_guti);
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                if accept_under_current_context {
                    log::info!(
                        "Mobility Registration Update from UE {amf_ue_ngap_id}, integrity \
                         verified under its current NAS security context: accepted"
                    );
                    return self
                        .send_registration_accept(association_id, amf_ue_ngap_id, ran_ue_ngap_id)
                        .await;
                }

                // #352: decide what this 5G-GUTI actually is before asking for a SUCI.
                //
                // Until now this arm asked UNCONDITIONALLY -- "Registration with unknown
                // 5G-GUTI: requesting SUCI" was logged for every GUTI, including one this
                // very AMF had issued minutes earlier. TS 23.502 §4.2.2.2.2 skips the
                // identification entirely in that case, and steps 4-5 exist for the other
                // case, so a single unconditional branch could serve neither.
                //
                // A GUTI mapped from EPS is excluded: it is a 4G identity in 5G clothing
                // (TS 23.003 §2.10.2.2.2) and matching it against this AMF's GUAMIs or
                // against a peer AMF would resolve a native context that never existed.
                // Its handling is the N26 leg (#62), above.
                if !guti_mapped_from_eps
                    && self
                        .resolve_registration_by_guti(amf_ue_ngap_id, nas, req.registration_type)
                        .await
                {
                    // Identified: either locally or from a context fetched from the old
                    // AMF. No Identity Request, no T3570 -- the SUPI is already known,
                    // so authentication proceeds straight away (TS 23.502 §4.2.2.2.2
                    // step 9 follows step 5 directly).
                    self.start_authentication(association_id, amf_ue_ngap_id, ran_ue_ngap_id, None)
                        .await?;
                    return Ok(());
                }

                // GUTI unknown to this AMF instance: identify the UE by SUCI
                // (TS 24.501 Section 5.4.3) and arm T3570
                log::info!("Registration with unknown 5G-GUTI: requesting SUCI");
                let identity_request =
                    gmm_build::build_identity_request(mobile_identity_type::SUCI);
                let ngap_pdu = self
                    .send_nas_pdu(
                        association_id,
                        amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        &identity_request,
                    )
                    .await?;
                self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3570, ngap_pdu);
            }
            other => {
                log::error!("Unsupported mobile identity type {other} in Registration Request");
                // The registration is refused, so `state` is deliberately DROPPED rather than
                // persisted: an unsupported identity type means nothing above it was parsed
                // from a usable request, and keeping the partial context would leave a UE
                // recorded as mid-registration with no procedure running.
                let reject =
                    gmm_build::build_registration_reject(GmmCause::InvalidMandatoryInformation);
                self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                    .await?;
            }
        }

        Ok(())
    }

    /// Identify a UE that presented a 5G-GUTI, locally or from the AMF that issued
    /// it (#352; TS 23.502 §4.2.2.2.2 steps 4-5, TS 29.518 §5.2.2.2.1).
    ///
    /// Returns `true` when the UE has been identified — its SUPI is on the record
    /// in the store — and `false` when the caller must fall back to requesting a
    /// SUCI.
    ///
    /// **Identification only: the caller authenticates.** Keeping the AUSF call out
    /// of here is what makes the identification observable on its own, in a test
    /// with no AUSF and in a log when authentication later fails. The alternative —
    /// ending this function with `start_authentication` — folded "did the GUTI
    /// resolve?" into "did 5G-AKA succeed?", and `start_authentication`'s
    /// AUSF-failure arm releases the UE, so the resolved state was gone by the time
    /// anything could look at it.
    ///
    /// # The three cases, and why one branch could not serve them
    ///
    /// A 5G-GUTI carries the identity of the AMF that allocated it — TS 23.003
    /// §2.10 makes `<5G-GUTI> = <GUAMI><5G-TMSI>` — so "whose GUTI is this?" is
    /// answerable locally, with no round trip, and the answer decides everything:
    ///
    /// 1. **Mine, and I still hold the context.** The UE is already identified;
    ///    TS 23.502 §4.2.2.2.2 skips the identification. This is the ordinary
    ///    mobility/periodic update, and asking such a UE for its SUCI — which is
    ///    what happened before this — both wastes a round trip and defeats the
    ///    purpose of the GUTI, whose whole job per TS 23.501 §5.9.4 is to avoid
    ///    sending a permanent identity over the air.
    /// 2. **Mine, but the context is gone** (this AMF restarted). Nothing to
    ///    resolve and no peer to ask, so the SUCI request is correct — it was
    ///    simply being applied to all three cases.
    /// 3. **Another AMF's.** Fetch the context from it (steps 4-5). Only here does
    ///    a network round trip happen, and only here does it need to.
    ///
    /// # Both GUTIs are accepted, per TS 24.501 §5.4.4.6
    ///
    /// The resolver tries `current_guti` and then `next_guti`. After an aborted
    /// GUTI reallocation §5.4.4.6 a) defers to b)-1): "the old and the new 5G-GUTI
    /// shall be considered as valid until the old 5G-GUTI can be considered as
    /// invalid by the AMF" — because the CONFIGURATION UPDATE COMPLETE may simply
    /// have been lost and the UE may already have adopted the new one. b)-1) ii)
    /// then says the AMF "shall consider the new 5G-GUTI as valid **if it is used
    /// by the UE**", which is the collapse rule: whichever the UE presents becomes
    /// the sole valid identity. That commit is done below.
    ///
    /// (#352 cites §5.4.4.3 for this. That clause is the **UE's** side of the
    /// procedure and says nothing about what the AMF keeps valid; the network-side
    /// rule is §5.4.4.6, and it is narrower and more actionable than "both stay
    /// valid" — it comes with the rule for ending the ambiguity.)
    async fn resolve_registration_by_guti(
        &mut self,
        amf_ue_ngap_id: u64,
        registration_request: &[u8],
        registration_type: u8,
    ) -> bool {
        let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) else {
            return false;
        };
        let presented = state.amf_ue.old_guti.clone();
        if presented.tmsi == 0 {
            // No GUTI was actually parsed out of the request, so there is nothing
            // to resolve. Distinct from "unknown GUTI": the SUCI request is right.
            return false;
        }

        let served_guami = {
            let ctx_arc = crate::context::amf_self();
            // Read THROUGH the poison, as every other reader of this context does
            // since #363: bailing would be a new failure mode, not a preserved one.
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            ctx.served_guami.clone()
        };

        // Is the GUTI foreign? `registration_request_from_old_amf` already answers
        // exactly this -- it compares `old_guti` against every served GUAMI and
        // carries the all-zero-GUTI guard -- and until #352 it had only test
        // callers. This is its first production use; the alternative was a fourth
        // copy of the same comparison.
        if crate::gmm_handler::registration_request_from_old_amf(&state.amf_ue, &served_guami) {
            return self
                .fetch_ue_context_from_old_amf(
                    amf_ue_ngap_id,
                    &presented,
                    registration_request,
                    registration_type,
                )
                .await;
        }

        // The GUTI is one of ours. Resolve it against the live store's DERIVED
        // resolver (#341/PR #374): `find_by_guti` scans the one authoritative map,
        // so it sees whatever the registration path last committed as
        // `current_guti` -- there is no index that could be stale.
        //
        // `find_by_guti` matches on `current_guti` only, so the §5.4.4.6 b)-1)
        // "new GUTI is also valid" case is a second pass over the snapshot. It is
        // NOT a third store method: a resolver that silently accepted either would
        // make it impossible for a caller to know WHICH identity matched, and
        // b)-1) ii) requires exactly that in order to commit the right one.
        let resolved = {
            let ctx_arc = crate::context::amf_self();
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            match ctx.amf_ue_find_by_guti(&presented) {
                Some(ue) => Some((ue, false)),
                // The reallocated identity the UE may have adopted after an
                // aborted §5.4.4.6 reallocation.
                None => ctx
                    .amf_ue_find_by_pending_guti(&presented)
                    .map(|ue| (ue, true)),
            }
        };

        let Some((known, matched_next_guti)) = resolved else {
            log::info!(
                "Registration with a 5G-GUTI this AMF issued (5G-TMSI=0x{:08x}) but whose context \
                 is no longer held -- identifying the UE by SUCI (TS 24.501 §5.4.3)",
                presented.tmsi
            );
            return false;
        };

        let Some(supi) = known.supi.clone() else {
            // A held context with no SUPI is a registration that never got past
            // authentication. Nothing is adopted from it -- carrying its security
            // state forward would claim an authentication that did not complete.
            log::info!(
                "Registration with a locally-issued 5G-GUTI (5G-TMSI=0x{:08x}) whose context \
                 carries no SUPI (authentication never completed) -- identifying by SUCI",
                presented.tmsi
            );
            return false;
        };

        // Adopt the identity and the security context onto THIS registration's
        // record, then write back. `ue_auth_state.get` returned a clone
        // (`ue_store.rs`, deliberately, so no guard crosses an `.await`), and this
        // very handler was the site where #361/PR #389 found ~40 mutated fields
        // silently discarded for want of this insert.
        self.ue_auth_state.with_mut(amf_ue_ngap_id, |s| {
            s.amf_ue.supi = Some(supi.clone());
            s.amf_ue.pei = known.pei.clone();
            s.amf_ue.suci = known.suci.clone();
            if let Some(ref suci) = known.suci {
                s.suci = suci.clone();
            }
            // The NAS security context, so the mobility update can be integrity
            // protected without a fresh 5G-AKA run (TS 33.501 §6.9.3).
            s.amf_ue.kamf = known.kamf;
            s.amf_ue.knas_int = known.knas_int;
            s.amf_ue.knas_enc = known.knas_enc;
            s.amf_ue.selected_int_algorithm = known.selected_int_algorithm;
            s.amf_ue.selected_enc_algorithm = known.selected_enc_algorithm;
            s.amf_ue.security_context_available = known.security_context_available;
            s.amf_ue.ul_count = known.ul_count;
            s.amf_ue.dl_count = known.dl_count;
            // TS 24.501 §5.4.4.6 b)-1) ii): the identity the UE actually used
            // becomes the valid one and the other becomes invalid. Committed for
            // BOTH matches, not only the `next_guti` one -- when the UE presents
            // the old GUTI after an aborted reallocation, §5.4.4.6 b)-1) iii)
            // makes the old one the valid identity, so the dangling `next_guti`
            // must stop resolving too.
            s.amf_ue.current_guti = presented.clone();
            s.amf_ue.current_m_tmsi = Some(presented.tmsi);
            s.amf_ue.next_guti = presented.clone();
        });

        if matched_next_guti {
            log::info!(
                "[{supi}] Registration presents the REALLOCATED 5G-GUTI \
                 (5G-TMSI=0x{:08x}): the UE adopted it even though the Configuration Update \
                 Complete never arrived, so it is now the only valid identity and the old one \
                 is invalid (TS 24.501 §5.4.4.6 b)-1) ii))",
                presented.tmsi
            );
        } else {
            log::info!(
                "[{supi}] Registration with a 5G-GUTI this AMF issued \
                 (5G-TMSI=0x{:08x}): UE identified from the held context, no Identity Request \
                 needed (TS 23.502 §4.2.2.2.2)",
                presented.tmsi
            );
        }

        // The caller authenticates. This AMF always re-authenticates a mobility
        // update rather than reusing the transferred security context -- TS 33.501
        // §6.1.1.1 leaves that to the AMF -- and what resolving the GUTI bought is
        // that it runs with the SUPI already known, which is what spared the
        // Identity Request.
        true
    }

    /// Fetch a UE context from the AMF that issued the presented 5G-GUTI
    /// (#352; TS 23.502 §4.2.2.2.2 steps 4-5, TS 29.518 §5.2.2.2.1).
    ///
    /// Returns `true` when the context was transferred and the UE is therefore
    /// identified, `false` when the caller must fall back to requesting a SUCI.
    /// Identification only, for the reason documented on
    /// [`NgapServer::resolve_registration_by_guti`]: the caller authenticates.
    ///
    /// Every failure mode returns `false` rather than rejecting the registration.
    /// That is deliberate and is the whole risk posture of this feature: the SUCI
    /// path always works, so an unreachable or uncooperative old AMF must cost the
    /// UE one extra round trip, never its registration. TS 23.502 §4.2.2.2.2 makes
    /// the transfer conditional ("[Conditional] new AMF to old AMF") and step 4
    /// says the new AMF "**may** invoke" it.
    async fn fetch_ue_context_from_old_amf(
        &mut self,
        amf_ue_ngap_id: u64,
        presented: &crate::context::Guti5gs,
        registration_request: &[u8],
        registration_type: u8,
    ) -> bool {
        // `INIT_REG` vs `MOBI_REG` per TS 29.518 §5.2.2.2.1.1: the reason tells the
        // old AMF which representation to return -- `MOBI_REG` gets the complete MM
        // and PDU session contexts, `INIT_REG` omits the sessions for the access
        // type being registered. It is the UE's registration type, not a guess.
        let reason = if registration_type == crate::gmm_build::registration_type::MOBILITY_UPDATING
        {
            "MOBI_REG"
        } else {
            "INIT_REG"
        };

        log::info!(
            "Registration with a 5G-GUTI issued by ANOTHER AMF (PLMN {}-{}, AMF \
             region={:#04x} set={:#06x} pointer={:#04x}, 5G-TMSI=0x{:08x}): retrieving the UE \
             context over Namf_Communication_UEContextTransfer, reason={reason} \
             (TS 23.502 §4.2.2.2.2 step 4)",
            presented.plmn_id.mcc(),
            presented.plmn_id.mnc(),
            presented.amf_region_id,
            presented.amf_set_id,
            presented.amf_pointer,
            presented.tmsi,
        );

        let Some((peer_host, peer_port)) =
            crate::sbi_path::discover_peer_amf_by_guami(presented).await
        else {
            log::info!(
                "The AMF that issued 5G-TMSI 0x{:08x} could not be located, so there is nobody \
                 to transfer the context from -- identifying the UE by SUCI instead of rejecting \
                 the registration (TS 23.502 §4.2.2.2.2 step 4 is [Conditional])",
                presented.tmsi
            );
            return false;
        };

        // The integrity-protected Registration Request, which §5.2.2.2.1.1 step 1
        // requires so the OLD AMF can verify the MAC against the security context
        // it holds. This AMF does not and cannot verify it -- it has no key for
        // this UE yet, which is the reason the exchange exists.
        let transferred = match crate::sbi_path::call_amf_ue_context_transfer(
            &peer_host,
            peer_port,
            presented,
            reason,
            "3GPP_ACCESS",
            Some(registration_request),
        )
        .await
        {
            Ok(resp) => resp,
            Err(e) => {
                log::warn!(
                    "UEContextTransfer to {peer_host}:{peer_port} failed ({e}); identifying the \
                     UE by SUCI instead. A 403 here is the old AMF's integrity verdict on the \
                     Registration Request and is NOT overridden -- only it holds the key the MAC \
                     was computed under (TS 29.518 §5.2.2.2.1.1)"
                );
                return false;
            }
        };

        let Some(supi) = transferred.supi.clone() else {
            // §5.2.2.2.1.1 case b) permits a response carrying only `supi`, so a
            // response carrying NO supi has failed at the one thing the call is
            // for. Nothing usable was learned.
            log::warn!(
                "UEContextTransfer from {peer_host}:{peer_port} returned a UE context with no \
                 SUPI, which is the one attribute the transfer exists to obtain \
                 (TS 23.502 §4.2.2.2.2 step 5); identifying the UE by SUCI"
            );
            return false;
        };

        // Adopt what was transferred. Written back through `with_mut` for the
        // reason #361/PR #389 documents: `get` hands out a clone, and this handler
        // is where mutating one and dropping it silently disabled a whole branch.
        //
        // The SECURITY context is deliberately NOT adopted: the transferred
        // `mmContextList` carries the algorithms and NAS COUNTs, but TS 33.501
        // §6.9.3 has the target AMF either run a fresh authentication or derive a
        // new KAMF via horizontal key derivation from the old one. This AMF
        // authenticates, so importing the old NAS keys would seed a context that
        // is about to be replaced -- and doing it half-way (algorithms without
        // keys) is how a security context ends up self-inconsistent.
        self.ue_auth_state.with_mut(amf_ue_ngap_id, |s| {
            s.amf_ue.supi = Some(supi.clone());
            if let Some(ref pei) = transferred.pei {
                s.amf_ue.pei = Some(pei.clone());
            }
            s.amf_ue.amf_ue_context_transfer_state =
                crate::context::UeContextTransferState::TransferNewAmf;
            // The presented GUTI stays current until this AMF issues its own in
            // `complete_registration` (which calls `generate_new_guti` and stamps
            // this AMF's GUAMI), so the UE remains addressable in the meantime.
            s.amf_ue.current_guti = presented.clone();
            s.amf_ue.current_m_tmsi = Some(presented.tmsi);
        });

        log::info!(
            "[{supi}] UE context transferred from the old AMF at {peer_host}:{peer_port}: \
             {} PDU session(s) reported. The sessions are NOT re-established here -- moving the \
             N3 tunnels is Nsmf_PDUSession_UpdateSMContext toward each SMF (TS 23.502 \
             §4.2.2.2.2 step 21), which is the N2 relocation path and belongs to #74",
            transferred.pdu_session_ids.len()
        );

        // Close the procedure at the old AMF (TS 29.518 §5.2.2.2.2). Without this
        // the old AMF holds the context until the implementation-specific guard
        // timer TS 23.502 step 5 licenses it to start expires, and never learns
        // whether the UE registered here. Best-effort: the transfer has already
        // succeeded, so a failure to report it must not undo the registration.
        if let Err(e) = crate::sbi_path::call_amf_registration_status_update(
            &peer_host, peer_port, presented, true,
        )
        .await
        {
            log::warn!(
                "[{supi}] RegistrationStatusUpdate to {peer_host}:{peer_port} failed ({e}). The \
                 context transfer already succeeded, so the registration continues; the old AMF \
                 will release its copy on its own guard timer (TS 23.502 §4.2.2.2.2 step 5)"
            );
        }

        // The caller authenticates, with the SUPI now known -- which is what the
        // transfer bought: no Identity Request, no SUCI over the air.
        true
    }

    /// Start (or restart, on SQN resync) 5G-AKA via AUSF
    /// (TS 23.502 Section 4.2.2.2.2 step 9 / TS 33.501 Section 6.1.3.2)
    async fn start_authentication(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        resync: Option<([u8; 16], [u8; 14])>,
    ) -> Result<()> {
        let Some(mut state) = self.ue_auth_state.remove(amf_ue_ngap_id) else {
            return Ok(());
        };

        let (ausf_host, ausf_port) =
            crate::sbi_path::resolve_nf_endpoint_async(crate::sbi_path::SbiServiceType::NausfAuth)
                .await
                .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));

        // Serving network name from the serving PLMN (TS 24.501 / TS 33.501 6.1.1.4),
        // augmented with the NID when this is an SNPN (Annex I.3.2, #115).
        let snn = serving_network_name_for_ue(&state.amf_ue);

        match crate::sbi_path::call_ausf_authenticate_with_resync(
            &ausf_host,
            ausf_port,
            &state.suci,
            &snn,
            resync,
        )
        .await
        {
            Ok(auth_resp) => {
                state.auth_ctx_id = auth_resp.auth_ctx_id;
                state.amf_ue.rand = auth_resp.rand;
                state.autn = auth_resp.autn;
                state.amf_ue.autn = auth_resp.autn.to_vec();
                state.amf_ue.hxres_star = auth_resp.hxres_star;
                // Initial ABBA (TS 33.501 Annex A.7.1)
                state.amf_ue.abba = [0x00, 0x00];
                state.amf_ue.abba_len = 2;
                // TS 24.501 §5.4.1.3.2: the AMF selects an ngKSI DIFFERENT from any
                // the UE already holds. This used to force 0, so a UE whose current
                // ngKSI was 0 -- the value the AMF itself hands out first, making it
                // the common case -- was offered the key set identifier it was already
                // using, and the two ends could end up pointing the same identifier at
                // different keys.
                //
                // nas_tsc stays 0: this is a NATIVE 5G security context, not one mapped
                // from EPS (TS 24.501 §9.11.3.32).
                state.amf_ue.nas_tsc = 0;
                state.amf_ue.nas_ksi = select_ngksi(state.amf_ue.nas_ue_ksi);

                let auth_request = gmm_build::build_authentication_request(&state.amf_ue);
                // amfd-07: keep the reporting GmmState in step with the live
                // procedure stage (the authoritative state is imperative here).
                state.gmm_fsm.transition_to_authentication();
                self.ue_auth_state.insert(amf_ue_ngap_id, state);

                let ngap_pdu = self
                    .send_nas_pdu(
                        association_id,
                        amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        &auth_request,
                    )
                    .await?;
                self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3560, ngap_pdu);
                log::info!("Authentication Request sent to UE {amf_ue_ngap_id}");
            }
            Err(e) => {
                log::error!("AUSF authentication failed for {}: {e}", state.suci);
                // #361: an EMERGENCY registration is not refused for want of an AUSF where
                // the deployment's regulation requires unauthenticated emergency service.
                //
                // TS 33.501 §10.2.2.2 enumerates the AMF's obligations by condition, and the
                // FIRST one it names is this one: "If the AMF cannot identify the subscriber,
                // or cannot obtain authentication vector (when SUPI is provided), the AMF
                // shall send NAS SMC with NULL algorithms to the UE regardless of the
                // supported algorithms announced previously by the UE." An unreachable AUSF
                // IS "cannot obtain authentication vector" — §10.2.2.1(b) spells out the
                // availability case: "UEs that have valid subscription but SN cannot complete
                // authentication because of network failure or other reasons".
                //
                // The registration type is read from `state.amf_ue`, which is sound here:
                // `handle_registration_request_nas` assigns it from the live request before
                // dispatching to this function, so it is this registration's own type and not
                // a stale one.
                //
                // Gated on operator policy, because §5.1.2 makes unauthenticated emergency
                // service MANDATORY in some jurisdictions and FORBIDDEN in others, and
                // §10.2.2.2 requires the choice to be configurable. Default permits it; see
                // `emergency::EmergencyPolicy`.
                if state.amf_ue.registration_type == crate::gmm_build::registration_type::EMERGENCY
                    && self.emergency.policy().allow_unauthenticated
                {
                    return self
                        .continue_unauthenticated_emergency_registration(
                            association_id,
                            amf_ue_ngap_id,
                            ran_ue_ngap_id,
                            state,
                        )
                        .await;
                }
                if state.amf_ue.registration_type == crate::gmm_build::registration_type::EMERGENCY
                {
                    log::warn!(
                        "EMERGENCY registration from UE {amf_ue_ngap_id} REFUSED because the \
                         AUSF is unreachable and amf.emergency.allow_unauthenticated is false. \
                         TS 33.501 §10.2.2.2 would permit an unauthenticated emergency session \
                         here; §5.1.2 requires this configuration only where local regulation \
                         forbids one."
                    );
                }
                let cause = gmm_cause_from_sbi_error(&e);
                let reject = gmm_build::build_registration_reject(cause);
                // The state is deliberately NOT put back here, unlike in every sibling
                // failure arm (#359). Those arms re-insert because they refuse a UE the
                // caller may still be holding; this one has already decided the UE is gone,
                // and `reject_and_release` reads nothing from the map -- it builds the reject
                // from `cause`, and `release_ue` takes the ids as arguments. Re-inserting
                // would be one line whose removal changes no observable behaviour, which is
                // the kind of line that reads as load-bearing and is not.
                //
                // What makes that safe is that `release_ue` now runs unconditionally: before
                // this fix the `?` on the reject send returned first, so the state was gone
                // AND nothing had released it. `forget_ue`'s removal is a no-op on this arm
                // and its `release_emergency` is not, which is why the emergency context is
                // the observable in the test.
                self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                    .await?;
            }
        }
        Ok(())
    }

    /// Continue an EMERGENCY registration whose authentication could not be obtained, as an
    /// UNAUTHENTICATED limited-service registration (#361, TS 33.501 §10.2.2).
    ///
    /// Reached only from `start_authentication`'s AUSF-failure arm, only for
    /// `registration_type == EMERGENCY`, and only when the operator's policy permits it.
    /// `state` is the UE context that arm already removed from `ue_auth_state`; this function
    /// owns it and re-inserts it, so the caller must not.
    ///
    /// The three spec obligations discharged here, in order:
    ///
    /// 1. **NULL algorithms are FORCED, not negotiated.** §6.7.3.6: "the AMF shall use NIA0
    ///    and NEA0 as the integrity and ciphering algorithm respectively", and "Select NIA0
    ///    and NEA0, REGARDLESS of the supported algorithms announced previously by the UE".
    ///    So `select_integrity_algorithm` — whose whole job is to honour the UE's advertised
    ///    set — is deliberately bypassed. It would refuse this session: a UE advertising only
    ///    NIA2 yields `Some(2)`, not NIA0, and the fail-closed arm would then reject a UE the
    ///    spec says to admit. §10.2.2.2 repeats the point in its NOTE 1: the UE "still needs
    ///    to be prepared ... to accept a NAS SMC from the AMF requesting the use of the NULL
    ///    ciphering and integrity algorithms".
    ///
    /// 2. **K_AMF is generated locally.** §10.2.2.3.1: "When there has been no successful run
    ///    of Primary authentication of the UE, the UE and the AMF independently generate the
    ///    K_(AMF) in an implementation defined way ... All key derivations proceed as if they
    ///    were based on a K_(AMF) generated from a successful Primary authentication run."
    ///    That last sentence is why the Annex A.8 KDF below is the ORDINARY one and why no
    ///    downstream site needs to learn about a keyless context: the context is
    ///    normal-shaped, its root is just not the AUSF's. The UE derives its own, unrelated
    ///    K_AMF; they never have to match, because NIA0 computes no MAC to compare and NEA0
    ///    enciphers nothing — §10.2.2.3.1: "the UE and the network treat the 5G security
    ///    context with the independently generated K_(AMF) as if it contained a normally
    ///    generated K_(AMF)". A CSPRNG rather than a constant so that no two sessions, and no
    ///    two deployments, share a root — it is used to derive KgNB, which the RAN holds.
    ///
    /// 3. **No SUPI is invented.** §4.12.2.3 (TS 23.502): "if the UE was not successfully
    ///    authenticated, the AMF shall not update the UDM". `complete_registration` therefore
    ///    skips the UECM/SDM/PCF/NSACF block for this UE, so there is no identity to
    ///    fabricate — which is the objection #361 raised and the spec answers by removing the
    ///    call rather than by naming a placeholder. The SUCI the UE presented stays on the
    ///    context as the "unauthenticated SUPI retained in the network for recording
    ///    purposes" of §10.2.2.1.
    ///
    /// Ends by sending the Security Mode Command, so the procedure rejoins the ordinary path
    /// at `handle_security_mode_complete_nas` — the UE-facing message flow is the standard
    /// one, which is exactly what §10.2.2.2(a) describes ("The UE shall proceed as specified
    /// for the non-emergency case in except that the UE shall accept a NAS SMC selecting NEA0
    /// and NIA0 algorithms").
    async fn continue_unauthenticated_emergency_registration(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        mut state: UeNasContext,
    ) -> Result<()> {
        log::warn!(
            "EMERGENCY registration from UE {amf_ue_ngap_id} continuing UNAUTHENTICATED: no \
             authentication vector could be obtained, and this deployment permits \
             unauthenticated emergency service (TS 33.501 §10.2.2.2). NIA0/NEA0 forced; no UDM \
             update; emergency DNN '{}' only.",
            self.emergency.emergency_dnn()
        );

        // The emergency context now records the OUTCOME. `handle_registration_request_nas`
        // created it optimistically from the presence of a SUCI; authentication has since
        // failed to happen, so the context must say so — this is the field a PSAP and an
        // operator read to know whether the caller's identity was verified (§10.2.2.1).
        //
        // Re-created rather than mutated in place when absent: a UE that reached
        // `start_authentication` without an emergency context (a re-authentication, say)
        // still needs one before the restrictions below can be enforced against it.
        if !self.emergency.mark_unauthenticated(amf_ue_ngap_id) {
            self.emergency
                .handle_emergency_registration(amf_ue_ngap_id, false);
        }

        state.amf_ue.unauthenticated_emergency = true;

        // §6.7.3.6 / §10.2.2.2: NIA0 + NEA0, forced.
        state.amf_ue.selected_int_algorithm = 0;
        state.amf_ue.selected_enc_algorithm = 0;
        // A NATIVE 5G security context (nas_tsc 0, TS 24.501 §9.11.3.32) with an ngKSI the UE
        // is not already using, exactly as the authenticated path picks one — the UE has to be
        // able to name this context in later messages regardless of how its root was made.
        state.amf_ue.nas_tsc = 0;
        state.amf_ue.nas_ksi = select_ngksi(state.amf_ue.nas_ue_ksi);
        // Initial ABBA (TS 33.501 Annex A.7.1), as on the authenticated path: the SMC carries
        // it, and §10.2.2.3.1's "all key derivations proceed as if" covers this one too.
        state.amf_ue.abba = [0x00, 0x00];
        state.amf_ue.abba_len = 2;

        // §10.2.2.3.1's "implementation defined way". The OS CSPRNG, via the same source
        // `generate_random_tmsi` uses.
        state.amf_ue.kamf = crate::context::generate_local_kamf();
        let knas_int = nextgcore_crypt::kdf::nextgcore_kdf_nas_5gs(
            0x02, // N-NAS-int-alg (TS 33.501 Annex A.8)
            state.amf_ue.selected_int_algorithm,
            &state.amf_ue.kamf,
        );
        let knas_enc = nextgcore_crypt::kdf::nextgcore_kdf_nas_5gs(
            0x01, // N-NAS-enc-alg
            state.amf_ue.selected_enc_algorithm,
            &state.amf_ue.kamf,
        );
        state.amf_ue.knas_int.copy_from_slice(&knas_int);
        state.amf_ue.knas_enc.copy_from_slice(&knas_enc);

        let Some(smc_plain) = gmm_build::build_security_mode_command(&state.amf_ue) else {
            log::error!(
                "UE {amf_ue_ngap_id}: could not build the Security Mode Command for the \
                 unauthenticated emergency registration; refusing rather than leaving the UE \
                 mid-procedure"
            );
            let reject =
                gmm_build::build_registration_reject(GmmCause::SecurityModeRejectedUnspecified);
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                .await?;
            return Ok(());
        };
        // INTEGRITY_PROTECTED_WITH_NEW_5G_NAS_SECURITY_CONTEXT is the correct header type even
        // under NIA0: it is what tells the UE a new context is being activated and which
        // ngKSI names it. `nas_5gs_security_encode` sees `selected_int_algorithm == 0` and
        // emits a zero MAC, which is what NIA0 means (TS 33.501 Annex D.1).
        let Some(smc_protected) = nas_security::nas_5gs_security_encode(
            &mut state.amf_ue,
            &smc_plain,
            security_header::INTEGRITY_PROTECTED_WITH_NEW_5G_NAS_SECURITY_CONTEXT,
        ) else {
            log::error!(
                "UE {amf_ue_ngap_id}: could not encode the Security Mode Command for the \
                 unauthenticated emergency registration; refusing"
            );
            let reject =
                gmm_build::build_registration_reject(GmmCause::SecurityModeRejectedUnspecified);
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                .await?;
            return Ok(());
        };

        state.gmm_fsm.transition_to_security_mode();
        self.ue_auth_state.insert(amf_ue_ngap_id, state);
        let ngap_pdu = self
            .send_nas_pdu(
                association_id,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                &smc_protected,
            )
            .await?;
        self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3560, ngap_pdu);
        log::warn!(
            "Security Mode Command with NULL algorithms (NIA0/NEA0) sent to UE \
             {amf_ue_ngap_id}: this emergency session has NO NAS integrity or ciphering \
             protection (TS 33.501 §6.7.3.6)"
        );
        Ok(())
    }

    /// Handle Authentication Response: verify HXRES*, confirm with AUSF,
    /// derive the key hierarchy and send Security Mode Command
    async fn handle_authentication_response_nas(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
    ) -> Result<()> {
        // Authentication response parameter (IEI 0x2D, TLV, RES* 16 bytes)
        let mut res_star: Option<[u8; 16]> = None;
        let mut pos = 3;
        while pos + 1 < nas.len() {
            if nas[pos] == 0x2D {
                let len = nas[pos + 1] as usize;
                if len == 16 && pos + 2 + 16 <= nas.len() {
                    let mut rs = [0u8; 16];
                    rs.copy_from_slice(&nas[pos + 2..pos + 18]);
                    res_star = Some(rs);
                }
                break;
            }
            pos += 1;
        }

        let Some(rs) = res_star else {
            log::error!("Authentication Response without RES*");
            return Ok(());
        };

        let Some(mut state) = self.ue_auth_state.remove(amf_ue_ngap_id) else {
            log::warn!("Authentication Response for unknown UE {amf_ue_ngap_id}");
            return Ok(());
        };

        // Milestone in the registration procedure, and previously unlogged on
        // the success path: a complete 5G-AKA trace jumped from "Authentication
        // Request sent" straight to the AUSF confirmation.
        log::info!("Received Authentication Response from UE {amf_ue_ngap_id} (RES* 16 bytes)");

        // Stop T3560
        if matches!(
            state.retx,
            Some(NasRetx {
                timer: NasProcTimer::T3560,
                ..
            })
        ) {
            state.retx = None;
        }

        // Verify HRES* against HXRES* (TS 33.501 Section 6.1.3.2.0)
        use sha2::{Digest, Sha256};
        let mut hasher = Sha256::new();
        hasher.update(state.amf_ue.rand);
        hasher.update(rs);
        let digest = hasher.finalize();
        let mut hres_star = [0u8; 16];
        hres_star.copy_from_slice(&digest[16..32]);
        let mut expected = [0u8; 16];
        expected.copy_from_slice(&state.amf_ue.hxres_star[..16]);

        if hres_star != expected {
            log::error!("HXRES* verification failed - sending Authentication Reject");
            let auth_reject = gmm_build::build_authentication_reject();
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(
                association_id,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                &auth_reject,
                1,
            )
            .await?;
            return Ok(());
        }
        // Log the pass, not just the failure. HRES*/HXRES* comparison is where
        // the AMF concludes the UE proved knowledge of K (TS 33.501 §6.1.3.2.0),
        // so it is exactly as diagnostic as the reject branch above.
        log::info!("UE {amf_ue_ngap_id} HXRES* verification passed");

        // 5G-AKA confirmation toward AUSF -> KSEAF + SUPI
        let (ausf_host, ausf_port) =
            crate::sbi_path::resolve_nf_endpoint_async(crate::sbi_path::SbiServiceType::NausfAuth)
                .await
                .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));

        let confirm = match crate::sbi_path::call_ausf_5g_aka_confirm(
            &ausf_host,
            ausf_port,
            &state.auth_ctx_id,
            &rs,
        )
        .await
        {
            Ok(c) => c,
            Err(e) => {
                log::error!("AUSF 5G-AKA confirmation failed: {e}");
                let auth_reject = gmm_build::build_authentication_reject();
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                self.reject_and_release(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    &auth_reject,
                    1,
                )
                .await?;
                return Ok(());
            }
        };

        if confirm.auth_result != "AUTHENTICATION_SUCCESS" {
            log::error!(
                "AUSF reports {}: Authentication Reject",
                confirm.auth_result
            );
            let auth_reject = gmm_build::build_authentication_reject();
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(
                association_id,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                &auth_reject,
                1,
            )
            .await?;
            return Ok(());
        }

        // #361: 5G-AKA has succeeded, so an emergency registration held for this UE is an
        // AUTHENTICATED one -- promoted here rather than guessed at the Registration Request,
        // which is where the old `has_supi` predicate got it wrong. TS 33.501 §10.2.2.2 NOTE:
        // "In case of authentication success the AMF will send a NAS SMC selecting algorithms
        // with a non-NULL integrity algorithm". Returns false for a non-emergency
        // registration, which is the overwhelming majority and needs no branch.
        if self.emergency.mark_authenticated(amf_ue_ngap_id) {
            log::info!(
                "EMERGENCY registration for UE {amf_ue_ngap_id} is AUTHENTICATED: it keeps the \
                 real key hierarchy, its UDM subscription and a non-NULL integrity algorithm \
                 (TS 33.501 §10.2.1.2)"
            );
        }

        // SUPI (from AUSF) and key hierarchy:
        // KSEAF -> KAMF (A.7) -> KNASint/KNASenc (A.8)
        //
        // Fail-closed SUPI resolution (TS 33.501 Section 6.1.3): when the AUSF
        // omits the SUPI we may only fall back to the SUCI if that SUCI is
        // null-scheme, i.e. actually carries the MSIN in cleartext. For an
        // ECIES-protected SUCI there is no SUPI to recover here, and deriving
        // KAMF under a fabricated identity would key the whole NAS security
        // context to the wrong subscriber. Reject the registration instead --
        // same reasoning as the NIA selection below.
        let Some(supi) = confirm.supi.clone().or_else(|| supi_from_suci(&state.suci)) else {
            log::error!(
                "UE {amf_ue_ngap_id}: AUSF returned no SUPI and the SUCI is not null-scheme, \
                 so no SUPI can be recovered; rejecting registration rather than deriving \
                 KAMF under a fabricated identity (TS 33.501 Section 6.1.3 fail-closed)"
            );
            let reject =
                gmm_build::build_registration_reject(GmmCause::SecurityModeRejectedUnspecified);
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                .await?;
            return Ok(());
        };
        state.amf_ue.supi = Some(supi.clone());

        let abba_len = state.amf_ue.abba_len as usize;
        let kamf = nextgcore_crypt::kdf::nextgcore_kdf_kamf(
            &supi,
            &state.amf_ue.abba[..abba_len],
            &confirm.kseaf,
        );
        state.amf_ue.kamf = kamf;

        // Select NAS algorithms from the UE's replayed capabilities and the
        // AMF-supported set (configured order; default NIA2/NEA2 preference)
        let amf_int_mask = {
            let ctx_arc = crate::context::amf_self();
            // Read THROUGH the poison: this replaced a `tokio::sync::RwLock`,
            // which cannot poison, so bailing here would be a new failure mode
            // rather than a preserved one (#363).
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            algorithm_order_to_mask(&ctx.integrity_order, 0x0E) // NIA1-3, never NIA0 by preference
        };
        let amf_enc_mask = {
            let ctx_arc = crate::context::amf_self();
            // Read THROUGH the poison: this replaced a `tokio::sync::RwLock`,
            // which cannot poison, so bailing here would be a new failure mode
            // rather than a preserved one (#363).
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            algorithm_order_to_mask(&ctx.ciphering_order, 0x0F)
        };
        let ue_int_mask = wire_caps_to_mask(state.amf_ue.ue_security_capability.ia);
        let ue_enc_mask = wire_caps_to_mask(state.amf_ue.ue_security_capability.ea);

        // Fail-closed integrity-algorithm selection (TS 33.501 §5.5.2 / §6.7.2):
        // an empty UE/AMF NIA intersection yields None. We must NOT fabricate
        // NIA2 the UE never advertised — reject the registration and release the
        // UE. Ciphering is asymmetric: NEA0 (null) is a permitted selection, so
        // `select_encryption_algorithm` keeps returning NEA0 on empty
        // intersection and is left unchanged.
        let Some(selected_int) =
            nas_security::select_integrity_algorithm(ue_int_mask, amf_int_mask)
        else {
            log::error!(
                "UE {amf_ue_ngap_id}: no common NAS integrity algorithm \
                 (ue_ia={:#04x}, amf_mask={amf_int_mask:#06x}); rejecting registration \
                 (TS 33.501 §5.5.2 fail-closed)",
                state.amf_ue.ue_security_capability.ia
            );
            let reject =
                gmm_build::build_registration_reject(GmmCause::SecurityModeRejectedUnspecified);
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                .await?;
            return Ok(());
        };
        // NIA0 is EMERGENCY-ONLY (TS 33.501 §5.2.3, scoped by §10.2.2, #115; cite corrected
        // from §6.7.2 in #361 -- §6.7.2 is the SMC procedure and carries no such rule).
        //
        // The empty-intersection case above already fails closed. The residual hole is
        // NIA0 being *selected* and applied: `select_integrity_algorithm` returns
        // `Some(0)` when NIA0 is the only algorithm in the intersection, and the AMF
        // mask contains NIA0 whenever the operator lists it in `integrity_order` —
        // `algorithm_order_to_mask`'s `0x0E` is only the default for an EMPTY
        // configuration, not a ceiling on what a configured order may contain. So a
        // deployment that names NIA0 in its order, facing a UE that advertises only
        // NIA0, would run an ordinary registration with no NAS integrity protection
        // at all, and nothing said so.
        //
        // Checked HERE rather than inside `select_integrity_algorithm`: whether NIA0 is
        // permissible is a property of the SESSION, not of the algorithm sets, and the
        // selector is a pure function of two masks with no access to the registration
        // type. Putting the check in the selector would mean passing the session in, or
        // — worse — silently masking NIA0 out and reporting an empty intersection,
        // which would tell the operator their configuration is unsupported rather than
        // their request is refused.
        if selected_int == 0 && !nas_security::nia0_permitted(state.amf_ue.registration_type) {
            log::error!(
                "UE {amf_ue_ngap_id}: NIA0 (null integrity) selected for a NON-EMERGENCY \
                 registration (type={}, ue_ia={:#04x}, amf_mask={amf_int_mask:#06x}); \
                 rejecting registration — TS 33.501 §5.2.3 permits NIA0 only for an \
                 unauthenticated emergency session. Remove NIA0 from the AMF's \
                 integrity_order to stop offering it.",
                state.amf_ue.registration_type,
                state.amf_ue.ue_security_capability.ia
            );
            let reject =
                gmm_build::build_registration_reject(GmmCause::SecurityModeRejectedUnspecified);
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                .await?;
            return Ok(());
        }
        if selected_int == 0 {
            // Permitted, and worth a record: an emergency session running without NAS
            // integrity is a deliberate, spec-sanctioned exception, and an operator
            // reading the logs should be able to tell it from the defect above.
            log::warn!(
                "UE {amf_ue_ngap_id}: NIA0 (null integrity) accepted for an EMERGENCY \
                 registration (TS 33.501 §5.2.3 / §10.2.2) — this session has no NAS \
                 integrity protection"
            );
        }

        state.amf_ue.selected_int_algorithm = selected_int;
        state.amf_ue.selected_enc_algorithm =
            nas_security::select_encryption_algorithm(ue_enc_mask, amf_enc_mask);

        let knas_int = nextgcore_crypt::kdf::nextgcore_kdf_nas_5gs(
            0x02, // N-NAS-int-alg (TS 33.501 Annex A.8)
            state.amf_ue.selected_int_algorithm,
            &kamf,
        );
        let knas_enc = nextgcore_crypt::kdf::nextgcore_kdf_nas_5gs(
            0x01, // N-NAS-enc-alg
            state.amf_ue.selected_enc_algorithm,
            &kamf,
        );
        state.amf_ue.knas_int.copy_from_slice(&knas_int);
        state.amf_ue.knas_enc.copy_from_slice(&knas_enc);

        log::info!(
            "[{supi}] keys derived; selected NIA{} / NEA{}",
            state.amf_ue.selected_int_algorithm,
            state.amf_ue.selected_enc_algorithm
        );

        // Security Mode Command: plain inner built by gmm_build (replaying the
        // UE's actual capabilities), wrapped integrity-protected with the new
        // 5G NAS security context (TS 24.501 Section 5.4.2.2)
        let Some(smc_plain) = gmm_build::build_security_mode_command(&state.amf_ue) else {
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            return Ok(());
        };
        let Some(smc_protected) = nas_security::nas_5gs_security_encode(
            &mut state.amf_ue,
            &smc_plain,
            security_header::INTEGRITY_PROTECTED_WITH_NEW_5G_NAS_SECURITY_CONTEXT,
        ) else {
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            return Ok(());
        };

        // amfd-07: reflect the live SECURITY-MODE stage in the reporting GmmState.
        state.gmm_fsm.transition_to_security_mode();
        self.ue_auth_state.insert(amf_ue_ngap_id, state);
        let ngap_pdu = self
            .send_nas_pdu(
                association_id,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                &smc_protected,
            )
            .await?;
        self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3560, ngap_pdu);
        log::info!("Security Mode Command sent to UE {amf_ue_ngap_id} (protected)");
        Ok(())
    }

    /// Handle Authentication Failure (TS 24.501 Section 5.4.1.3.7):
    /// - cause #20 (MAC failure): one re-authentication attempt, then reject
    /// - cause #21 (synch failure): SQN resynchronisation toward AUSF using
    ///   the AUTS parameter, then a fresh Authentication Request
    async fn handle_authentication_failure_nas(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
    ) -> Result<()> {
        let cause = nas.get(3).copied().unwrap_or(0);
        log::warn!("Authentication Failure from UE {amf_ue_ngap_id}: 5GMM cause #{cause}");

        // Authentication failure parameter (IEI 0x30, TLV, AUTS 14 bytes)
        let mut auts: Option<[u8; 14]> = None;
        let mut pos = 4;
        while pos + 1 < nas.len() {
            if nas[pos] == 0x30 {
                let len = nas[pos + 1] as usize;
                if len == 14 && pos + 2 + 14 <= nas.len() {
                    let mut a = [0u8; 14];
                    a.copy_from_slice(&nas[pos + 2..pos + 16]);
                    auts = Some(a);
                }
                break;
            }
            pos += 1;
        }

        let (failure_count, rand) = match self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            state.auth_failure_count += 1;
            if matches!(
                state.retx,
                Some(NasRetx {
                    timer: NasProcTimer::T3560,
                    ..
                })
            ) {
                state.retx = None;
            }
            (state.auth_failure_count, state.amf_ue.rand)
        }) {
            Some(counted) => counted,
            None => return Ok(()),
        };

        if failure_count > 1 {
            log::error!("Repeated authentication failure: Authentication Reject");
            let auth_reject = gmm_build::build_authentication_reject();
            self.reject_and_release(
                association_id,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                &auth_reject,
                1,
            )
            .await?;
            return Ok(());
        }

        match cause {
            21 => {
                // Synch failure: re-resolve the vector with AUTS (resync)
                let Some(auts) = auts else {
                    log::error!("Synch failure without AUTS parameter: Authentication Reject");
                    let auth_reject = gmm_build::build_authentication_reject();
                    self.reject_and_release(
                        association_id,
                        amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        &auth_reject,
                        1,
                    )
                    .await?;
                    return Ok(());
                };
                self.start_authentication(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    Some((rand, auts)),
                )
                .await?;
            }
            20 | 26 | 71 => {
                // MAC failure / non-5G auth unacceptable / ngKSI in use:
                // one fresh authentication attempt
                self.start_authentication(association_id, amf_ue_ngap_id, ran_ue_ngap_id, None)
                    .await?;
            }
            _ => {
                log::error!("Unhandled auth failure cause #{cause}: Authentication Reject");
                let auth_reject = gmm_build::build_authentication_reject();
                self.reject_and_release(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    &auth_reject,
                    1,
                )
                .await?;
            }
        }
        Ok(())
    }

    /// Handle Identity Response (TS 24.501 Section 5.4.3): SUCI before
    /// authentication, or PEI (IMEI/IMEISV) after security establishment
    async fn handle_identity_response_nas(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
    ) -> Result<()> {
        if nas.len() < 5 {
            return Ok(());
        }
        let id_len = ((nas[3] as usize) << 8) | (nas[4] as usize);
        if id_len == 0 || nas.len() < 5 + id_len {
            log::error!("Malformed Identity Response");
            return Ok(());
        }
        let content = &nas[5..5 + id_len];
        let id_type = content[0] & 0x07;

        // Stop T3570. Persisted through `with_mut` before anything below `.await`s:
        // the identity the UE just supplied is read by `start_authentication` and
        // `complete_registration`, so a mutation dropped with a clone would send
        // the AMF to the AUSF with no SUCI at all.
        if self
            .ue_auth_state
            .with_mut(amf_ue_ngap_id, |state| {
                if matches!(
                    state.retx,
                    Some(NasRetx {
                        timer: NasProcTimer::T3570,
                        ..
                    })
                ) {
                    state.retx = None;
                }
            })
            .is_none()
        {
            return Ok(());
        }

        match id_type {
            t if t == mobile_identity_type::SUCI => {
                if let Some((suci, plmn)) = parse_suci_identity(content) {
                    log::info!("Identity Response: SUCI {suci}");
                    self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
                        state.suci = suci.clone();
                        state.amf_ue.suci = Some(suci);
                        state.amf_ue.home_plmn_id = plmn;
                    });
                    self.start_authentication(association_id, amf_ue_ngap_id, ran_ue_ngap_id, None)
                        .await?;
                } else {
                    log::error!("Failed to parse SUCI from Identity Response");
                }
            }
            t if t == mobile_identity_type::IMEISV || t == mobile_identity_type::IMEI => {
                match decode_pei(content) {
                    Some((pei, digits)) => {
                        log::info!("Identity Response: PEI {pei}");
                        self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
                            state.amf_ue.pei = Some(pei);
                            state.amf_ue.imeisv = Some(digits);
                        });
                    }
                    None => {
                        // Record no PEI rather than one that breaks the
                        // TS 29.571 `Pei` pattern downstream.
                        log::error!(
                            "Identity Response: malformed IMEI/IMEISV (type {id_type}, {} octets); \
                             no PEI recorded",
                            content.len()
                        );
                    }
                }
                // Clearing the flag and reading it are one acquisition, so the
                // registration cannot be completed twice if this arm is re-entered.
                let was_requested = self
                    .ue_auth_state
                    .with_mut(amf_ue_ngap_id, |state| {
                        let requested = state.pei_requested;
                        state.pei_requested = false;
                        requested
                    })
                    .unwrap_or(false);
                if was_requested {
                    self.complete_registration(association_id, amf_ue_ngap_id, ran_ue_ngap_id)
                        .await?;
                }
            }
            other => {
                log::error!("Unsupported identity type {other} in Identity Response");
            }
        }
        Ok(())
    }

    /// Handle Security Mode Complete (TS 24.501 Section 5.4.2.4):
    /// extract IMEISV if present (it was requested in the SMC), request PEI
    /// via Identity Request otherwise, then run the registration SBI calls
    async fn handle_security_mode_complete_nas(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
    ) -> Result<()> {
        log::info!("Security Mode Complete from UE {amf_ue_ngap_id}");

        // Anti-bidding-down check (TS 24.501 Section 4.4.2.4 / TS 33.501
        // Section 6.7.2): the UE replays its complete initial RegistrationRequest
        // inside the (now integrity-protected) NAS message container of the
        // Security Mode Complete. The AMF re-parses the UE security capabilities
        // from that protected copy and compares them against the capabilities it
        // received in the cleartext initial RegistrationRequest. A mismatch means
        // an attacker tampered with the unprotected initial message to downgrade
        // the algorithms; the AMF aborts with 5GMM cause #23.
        // TS 24.501 §4.4.6: the Requested NSSAI is a non-cleartext IE, so it is
        // taken ONLY from the integrity-protected replay here (never from the
        // unprotected initial Registration Request).
        let mut replayed_requested_nssai: Vec<SNssai> = Vec::new();
        if let Some(replayed) = extract_nas_message_container(nas) {
            if let Some(inner) = parse_registration_request_pdu(&replayed) {
                replayed_requested_nssai = inner.requested_nssai.clone();
                // #570: the UE radio capability ID is non-cleartext (TS 24.501
                // §4.4.6), so on an initial registration it arrives here, in the
                // replay, and the RACS bit with it.
                let (racs, presented) =
                    (inner.racs_supported, inner.ue_radio_capability_id.clone());
                self.ue_auth_state.with_mut(amf_ue_ngap_id, |s| {
                    s.amf_ue.racs_supported |= racs;
                    if let Some(id) = presented {
                        s.amf_ue.ue_radio_capability_id = Some(id);
                        s.amf_ue.ue_radio_capability_id_known_to_ue = true;
                    }
                });
                if let Some(replayed_caps) = inner.sec_cap {
                    let stored = self
                        .ue_auth_state
                        .get(amf_ue_ngap_id)
                        .map(|s| s.amf_ue.ue_security_capability.clone());
                    if let Some(stored) = stored {
                        if replayed_caps.ea != stored.ea
                            || replayed_caps.ia != stored.ia
                            || replayed_caps.eea != stored.eea
                            || replayed_caps.eia != stored.eia
                        {
                            log::error!(
                                "Bidding-down detected for UE {amf_ue_ngap_id}: replayed caps \
                                 (EA={:#04x},IA={:#04x},EEA={:#04x},EIA={:#04x}) != initial \
                                 (EA={:#04x},IA={:#04x},EEA={:#04x},EIA={:#04x})",
                                replayed_caps.ea,
                                replayed_caps.ia,
                                replayed_caps.eea,
                                replayed_caps.eia,
                                stored.ea,
                                stored.ia,
                                stored.eea,
                                stored.eia
                            );
                            // Security Mode Reject (#23), then abort the
                            // registration and release the UE context.
                            //
                            // The FIRST of the two sends is best-effort as well (#359):
                            // this is the only refusal path in the file that emits two NAS
                            // messages, so a `?` on the Security Mode Reject skipped the
                            // Registration Reject AND the release. Bidding-down is an
                            // ATTACK signal, which makes it the worst arm to abandon
                            // half-applied.
                            let reject = gmm_build::build_security_mode_reject(
                                GmmCause::UeSecurityCapabilitiesMismatch,
                            );
                            self.deliver_nas_best_effort(
                                association_id,
                                amf_ue_ngap_id,
                                ran_ue_ngap_id,
                                &reject,
                                "the Security Mode Reject",
                            )
                            .await;
                            let reg_reject = gmm_build::build_registration_reject(
                                GmmCause::UeSecurityCapabilitiesMismatch,
                            );
                            self.reject_and_release(
                                association_id,
                                amf_ue_ngap_id,
                                ran_ue_ngap_id,
                                &reg_reject,
                                23,
                            )
                            .await?;
                            return Ok(());
                        }
                        log::info!(
                            "UE {amf_ue_ngap_id} security capabilities verified against replayed \
                             RegistrationRequest (no bidding-down)"
                        );
                        // Security Mode Complete accepted and the anti-bidding-down
                        // check passed, so the NAS security context is now active in
                        // both directions (TS 33.501 §6.7.2). Logged explicitly: this
                        // is the boundary after which every NAS message is integrity
                        // protected, and it had no observable marker.
                        log::info!(
                            "UE {amf_ue_ngap_id} NAS security context established \
                             (integrity + ciphering active)"
                        );
                    }
                }
            } else {
                log::warn!(
                    "Security Mode Complete NAS message container did not contain a \
                     parseable RegistrationRequest for UE {amf_ue_ngap_id}"
                );
            }
        }

        // Applied IN PLACE (#570): this used `ue_auth_state.get`, which returns a
        // clone, so the PEI/IMEISV, the replayed Requested NSSAI and the T3560 stop
        // below were all written to a copy and dropped.
        let Some(need_pei) = self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            // Populate the Requested NSSAI from the integrity-protected replay
            // (TS 24.501 §4.4.6); the unprotected initial request no longer sets
            // it. Empty replay leaves it empty (subscription/PLMN config drive
            // the Allowed NSSAI downstream).
            state.amf_ue.requested_nssai = replayed_requested_nssai;
            // Stop T3560
            if matches!(
                state.retx,
                Some(NasRetx {
                    timer: NasProcTimer::T3560,
                    ..
                })
            ) {
                state.retx = None;
            }

            // IMEISV (mobile identity IEI 0x77, TLV-E) — requested in the SMC
            let mut pos = 3;
            while pos + 2 < nas.len() {
                if nas[pos] == 0x77 {
                    let len = ((nas[pos + 1] as usize) << 8) | (nas[pos + 2] as usize);
                    if len > 0 && pos + 3 + len <= nas.len() {
                        let content = &nas[pos + 3..pos + 3 + len];
                        if content[0] & 0x07 == mobile_identity_type::IMEISV {
                            match decode_pei(content) {
                                Some((pei, digits)) => {
                                    log::info!("IMEISV from Security Mode Complete: {digits}");
                                    state.amf_ue.imeisv = Some(digits);
                                    state.amf_ue.pei = Some(pei);
                                }
                                None => {
                                    log::error!(
                                        "Security Mode Complete: malformed IMEISV ({} octets); \
                                         no PEI recorded",
                                        content.len()
                                    );
                                }
                            }
                        }
                    }
                    break;
                }
                pos += 1;
            }

            let mut need_pei = false;
            if state.amf_ue.pei.is_none() {
                need_pei = true;
                state.pei_requested = true;
            }
            need_pei
        }) else {
            return Ok(());
        };

        if need_pei {
            // PEI not provided: Identity Request for IMEISV (protected),
            // TS 24.501 Section 5.4.3 / TS 23.502 step 11
            log::info!("No PEI yet: sending Identity Request (IMEISV)");
            let plain = gmm_build::build_identity_request(mobile_identity_type::IMEISV);
            let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) else {
                return Ok(());
            };
            let ngap_pdu = self
                .send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                .await?;
            self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3570, ngap_pdu);
            return Ok(());
        }

        self.complete_registration(association_id, amf_ue_ngap_id, ran_ue_ngap_id)
            .await
    }

    /// Run the three mandatory registration SBI calls and, only if all
    /// succeed, send the protected Registration Accept
    /// (TS 23.502 Section 4.2.2.2.2 steps 14a/14b/14c/16)
    async fn complete_registration(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
    ) -> Result<()> {
        let Some(mut state) = self.ue_auth_state.remove(amf_ue_ngap_id) else {
            return Ok(());
        };

        // #361: an UNAUTHENTICATED emergency registration takes none of the SBI steps below.
        //
        // TS 23.502 §4.12.2.3, verbatim: "if the UE was not successfully authenticated, the
        // AMF shall not update the UDM. Also for an Emergency Registration, the AMF shall not
        // check for access restrictions, regional restrictions or subscription restrictions",
        // and "Steps 16 and 21b of figure 4.2.2.2.2-1 are not performed since AM and UE policy
        // for the UE are not required for Emergency Registration."
        //
        // This is what answers #361's "what SUPI to register at the UECM when there is none":
        // the question does not arise, because the registration the SUPI was for is prohibited.
        // Every one of the four calls below is keyed on a SUPI this UE does not have, and each
        // would refuse and take the registration down with it -- the UDM has no subscription,
        // the PCF no policy and the NSACF no quota for a subscriber the network cannot name.
        //
        // The Allowed NSSAI is left EMPTY, also per §4.12.2.3: "NSSAI shall not be included by
        // the UE. The AMF shall not send the Allowed NSSAI in the Registration Accept message."
        // So the 5GMM #62 refusal on an empty Allowed NSSAI below is skipped with the rest --
        // for this UE an empty set is the specified outcome, not a misconfiguration. The
        // emergency session's DNN comes from the AMF's Emergency Configuration Data
        // (TS 23.501 §5.16.4.1), which `EmergencyHandler::emergency_dnn` holds.
        if state.amf_ue.unauthenticated_emergency {
            log::warn!(
                "UE {amf_ue_ngap_id}: unauthenticated EMERGENCY registration -- skipping \
                 Nudm_UECM_Registration, Nudm_SDM_Get/Subscribe, Npcf_AMPolicyControl_Create \
                 and the NSACF admission check, and sending no Allowed NSSAI \
                 (TS 23.502 §4.12.2.3)"
            );
            state.amf_ue.allowed_nssai.clear();
            // A 5G-GUTI is still assigned. §10.2.2.3.1 makes this security context
            // normal-shaped, and `generate_new_guti` builds the identity from a CSPRNG 5G-TMSI
            // plus this AMF's own GUAMI (TS 23.003 §2.10.1) -- it never derives anything from
            // subscriber identity, so there is nothing here that needs an authenticated one.
            // Withholding it would leave the UE unable to identify itself on the service
            // request that follows its emergency call.
            state.amf_ue.generate_new_guti();
            let (guami_plmn, amf_region, amf_set, amf_pointer) = {
                let ctx_arc = crate::context::amf_self();
                let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
                match ctx.served_guami.first() {
                    Some(g) => (
                        g.plmn_id.clone(),
                        g.amf_id.region,
                        g.amf_id.set,
                        g.amf_id.pointer,
                    ),
                    None => (state.amf_ue.nr_tai.plmn_id.clone(), 2, 1, 0),
                }
            };
            state.amf_ue.next_guti.plmn_id = guami_plmn;
            state.amf_ue.next_guti.amf_region_id = amf_region;
            state.amf_ue.next_guti.amf_set_id = amf_set;
            state.amf_ue.next_guti.amf_pointer = amf_pointer;
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            return self
                .send_registration_accept(association_id, amf_ue_ngap_id, ran_ue_ngap_id)
                .await;
        }

        // The authentication path always sets `supi`; this fallback only fires
        // if registration completed without it. Same fail-closed rule as there:
        // never register a UECM context or fetch subscription data under a SUPI
        // derived from a protected SUCI (TS 33.501 Section 6.1.3).
        let Some(supi) = state
            .amf_ue
            .supi
            .clone()
            .or_else(|| supi_from_suci(&state.suci))
        else {
            log::error!(
                "UE {amf_ue_ngap_id}: no SUPI available and the SUCI is not null-scheme; \
                 rejecting registration rather than registering a fabricated subscriber"
            );
            let reject =
                gmm_build::build_registration_reject(GmmCause::SecurityModeRejectedUnspecified);
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                .await?;
            return Ok(());
        };

        let (serving_mcc, serving_mnc) = plmn_mcc_mnc_strings(&state.amf_ue.nr_tai.plmn_id);

        // GUAMI of this AMF (for UECM registration)
        let (guami_plmn, amf_region, amf_set, amf_pointer) = {
            let ctx_arc = crate::context::amf_self();
            // Read THROUGH the poison: this replaced a `tokio::sync::RwLock`,
            // which cannot poison, so bailing here would be a new failure mode
            // rather than a preserved one (#363).
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            match ctx.served_guami.first() {
                Some(g) => (
                    g.plmn_id.clone(),
                    g.amf_id.region,
                    g.amf_id.set,
                    g.amf_id.pointer,
                ),
                None => (state.amf_ue.nr_tai.plmn_id.clone(), 2, 1, 0),
            }
        };
        // #92: through the SHARED packer, not a local `format!`. The PCF matches this
        // `amfId` against the `amfInfo.guamiList` this AMF registered with the NRF, so
        // two independent renderings of one AMF ID would never match and GUAMI-based
        // targeting would fall back to the first discovered AMF on every delivery — the
        // defect #92 is about, restored by a copy-paste that no test would catch. There
        // were TWO copies of this packing here, which is the argument by itself.
        let amf_id_hex = crate::sbi_path::amf_id_hex(&crate::context::AmfId {
            region: amf_region,
            set: amf_set,
            pointer: amf_pointer,
        });
        let (guami_mcc, guami_mnc) = plmn_mcc_mnc_strings(&guami_plmn);

        let (udm_host, udm_port) =
            crate::sbi_path::resolve_nf_endpoint_async(crate::sbi_path::SbiServiceType::NudmUecm)
                .await
                .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));

        // 1) Nudm_UECM_Registration (amf-3gpp-access), under this AMF's pinnable
        // nfInstanceId and a fresh deregCallbackUri token (#753).
        if let Err(e) = register_with_udm_uecm(
            &mut state.amf_ue,
            &udm_host,
            udm_port,
            &supi,
            &guami_mcc,
            &guami_mnc,
            &amf_id_hex,
        )
        .await
        {
            log::error!("[{supi}] Nudm_UECM_Registration failed: {e}");
            let reject = gmm_build::build_registration_reject(gmm_cause_from_sbi_error(&e));
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                .await?;
            return Ok(());
        }

        // 2) Nudm_SDM_Get (am-data) + Nudm_SDM_Subscribe
        let am_data = match crate::sbi_path::call_udm_sdm_get_am_data(&udm_host, udm_port, &supi)
            .await
        {
            Ok(d) => d,
            Err(e) => {
                log::error!("[{supi}] Nudm_SDM_Get failed: {e}");
                let reject = gmm_build::build_registration_reject(gmm_cause_from_sbi_error(&e));
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                    .await?;
                return Ok(());
            }
        };
        match crate::sbi_path::call_udm_sdm_subscribe(
            &udm_host,
            udm_port,
            &supi,
            &amf_instance_id(),
        )
        .await
        {
            Ok(sub_id) => state.sdm_subscription_id = Some(sub_id),
            Err(e) => {
                log::error!("[{supi}] Nudm_SDM_Subscribe failed: {e}");
                let reject = gmm_build::build_registration_reject(gmm_cause_from_sbi_error(&e));
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                    .await?;
                return Ok(());
            }
        }

        // 3) Npcf_AMPolicyControl_Create
        let (pcf_host, pcf_port) = crate::sbi_path::resolve_nf_endpoint_async(
            crate::sbi_path::SbiServiceType::NpcfAmPolicyControl,
        )
        .await
        .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));
        match crate::sbi_path::call_pcf_am_policy_create(
            &pcf_host,
            pcf_port,
            &supi,
            &serving_mcc,
            &serving_mnc,
        )
        .await
        {
            Ok(assoc) => {
                state.policy_association_id = Some(assoc.clone());
                state.amf_ue.policy_association.id = Some(assoc);
            }
            Err(e) => {
                log::error!("[{supi}] Npcf_AMPolicyControl_Create failed: {e}");
                let reject = gmm_build::build_registration_reject(gmm_cause_from_sbi_error(&e));
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                    .await?;
                return Ok(());
            }
        }

        // 3b) Npcf_UEPolicyControl_Create used to run HERE, at step 3b, which is
        // before the Registration Accept egresses -- and the PCF spawns the DL
        // MANAGE UE POLICY COMMAND the moment the association is created, so the
        // URSP delivery could overtake the Accept (#91, TS 23.502 §4.2.4.3 vs
        // §4.2.2.2.2). It now runs at the END of `send_registration_accept`, so the
        // association -- and therefore the delivery -- cannot precede the Accept.
        //
        // The PCF endpoint and the identifiers it needs are recomputed there rather
        // than threaded through: `send_registration_accept` already owns the state,
        // and carrying five strings across two functions to save one NRF-cached
        // lookup would be the more fragile arrangement.

        // amfd-06 — Allowed NSSAI (TS 23.502 §4.2.2.2.3 / TS 24.501 §9.11.3.37):
        // the authorized set comes ONLY from network-authoritative sources — the
        // UDM subscription, else the AMF's configured PLMN slice support. The
        // Requested NSSAI is the UE's *ask*, never an authorization, so it is
        // NEVER echoed back as the Allowed NSSAI. If no S-NSSAI is authorized the
        // registration is rejected with 5GMM cause #62 (No network slices
        // available); no Registration Accept is emitted.
        let subscribed: Vec<SNssai> = am_data
            .nssai
            .iter()
            .map(|(sst, sd)| SNssai { sst: *sst, sd: *sd })
            .collect();
        let plmn_default: Vec<SNssai> = {
            let ctx_arc = crate::context::amf_self();
            // Read THROUGH the poison: this replaced a `tokio::sync::RwLock`,
            // which cannot poison, so bailing here would be a new failure mode
            // rather than a preserved one (#363).
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            ctx.plmn_support
                .first()
                .map(|ps| ps.s_nssai.clone())
                .unwrap_or_default()
        };
        let allowed = select_allowed_nssai(&subscribed, &plmn_default);
        if allowed.is_empty() {
            log::warn!(
                "[{supi}] no authorized S-NSSAI (UDM subscription + PLMN support \
                 both empty); rejecting registration with 5GMM #62"
            );
            let reject = gmm_build::build_registration_reject(GmmCause::NoNetworkSlicesAvailable);
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                .await?;
            return Ok(());
        }
        state.amf_ue.allowed_nssai = allowed;

        // Network Slice Admission Control (TS 29.536 / TS 23.501 §5.15.11):
        // query the NSACF for each Allowed S-NSSAI subject to admission control
        // before accepting the registration. The NSACF answers 204 when the
        // S-NSSAI is admitted, and 403 (or 200 with this SUPI in acuFailureList)
        // when the per-slice UE quota is exhausted; in that case the
        // registration is rejected with 5GMM cause #69 (insufficient resources
        // for the specific slice, TS 24.501 Annex A). A missing/unreachable
        // NSACF degrades open (call_nsacf_ue_admission admits) so it never
        // blocks attach.
        {
            let (nsacf_host, nsacf_port) = crate::sbi_path::resolve_nf_endpoint_async(
                crate::sbi_path::SbiServiceType::NnsacfNsac,
            )
            .await
            .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));
            let access_type = if state.amf_ue.access_type == 0 || state.amf_ue.access_type == 1 {
                "3GPP_ACCESS"
            } else {
                "NON_3GPP_ACCESS"
            };
            let nf_id = amf_instance_id();
            let mut admission_denied: Option<SNssai> = None;
            for snssai in state.amf_ue.allowed_nssai.clone() {
                match crate::sbi_path::call_nsacf_ue_admission(
                    &nsacf_host,
                    nsacf_port,
                    &nf_id,
                    &supi,
                    snssai.sst,
                    snssai.sd,
                    access_type,
                    true, // updateFlag: enforce/increase the per-slice UE count
                )
                .await
                {
                    Ok(res) => {
                        state.amf_ue.slice_admission_granted = res.admitted;
                        if !res.admitted {
                            admission_denied = Some(snssai);
                            break;
                        }
                    }
                    Err(e) => {
                        // NSACF unreachable: admission control cannot be
                        // performed. Per TS 23.501 §5.15.11 the AMF treats the
                        // slice as not-admitted to avoid exceeding quotas.
                        log::error!(
                            "[{supi}] NSACF UE admission query failed for SST={}: {e}",
                            snssai.sst
                        );
                        state.amf_ue.slice_admission_granted = false;
                        admission_denied = Some(snssai);
                        break;
                    }
                }
            }
            if let Some(denied) = admission_denied {
                log::warn!(
                    "[{supi}] Slice admission denied by NSACF (SST={}, SD={:?}); rejecting registration",
                    denied.sst,
                    denied.sd
                );
                let reject = gmm_build::build_registration_reject(
                    GmmCause::InsufficientResourcesForSpecificSlice,
                );
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                self.reject_and_release(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject, 1)
                    .await?;
                return Ok(());
            }
        }

        // Subscribed UE-AMBR (UDM am-data, TS 29.571 BitRate strings) — carried
        // to the gNB in the Initial Context Setup Request (TS 38.413 §9.3.1.58).
        if let Some(dl) = am_data
            .ue_ambr_downlink
            .as_deref()
            .and_then(parse_bitrate_bps)
        {
            state.amf_ue.ue_ambr.downlink = dl;
        }
        if let Some(ul) = am_data
            .ue_ambr_uplink
            .as_deref()
            .and_then(parse_bitrate_bps)
        {
            state.amf_ue.ue_ambr.uplink = ul;
        }

        // GPSI (UDM am-data `gpsis`, TS 29.503 §5.2.2.2.1) — the UE's external
        // identity, conveyed onward on N11 (issue #205). Assigned unconditionally
        // from the response so that a subscription which STOPS carrying a GPSI
        // clears the stale one on re-registration rather than keeping it; the
        // parser has already dropped any entry that is not a well-formed
        // TS 29.571 `Gpsi`, so this is never a placeholder.
        state.amf_ue.gpsi = am_data.gpsi.clone();

        // New 5G-GUTI: GUAMI of this AMF + CSPRNG 5G-TMSI (TS 23.003 2.10.1)
        state.amf_ue.generate_new_guti();
        state.amf_ue.next_guti.plmn_id = guami_plmn;
        state.amf_ue.next_guti.amf_region_id = amf_region;
        state.amf_ue.next_guti.amf_set_id = amf_set;
        state.amf_ue.next_guti.amf_pointer = amf_pointer;

        self.ue_auth_state.insert(amf_ue_ngap_id, state);
        self.send_registration_accept(association_id, amf_ue_ngap_id, ran_ue_ngap_id)
            .await
    }

    /// Establish AS-layer security and deliver the initial Registration Accept.
    ///
    /// Per TS 23.502 §4.2.2.2.2 step 16 / TS 38.413 §8.3.1, the AMF derives
    /// KgNB (TS 33.501 Annex A.9) and sends NGAP InitialContextSetupRequest to
    /// the gNB carrying the GUAMI, the replayed UE security capabilities, the
    /// UE Security Key (KgNB), the Allowed NSSAI, the UE-AMBR and — piggybacked
    /// as the NAS-PDU — the protected Registration Accept. The registration is
    /// only considered established once the gNB returns
    /// InitialContextSetupResponse; T3550 is armed for the NAS-layer
    /// Registration Complete.
    async fn send_registration_accept(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
    ) -> Result<()> {
        let Some(mut state) = self.ue_auth_state.remove(amf_ue_ngap_id) else {
            return Ok(());
        };

        let Some(mut plain) = gmm_build::build_registration_accept(&state.amf_ue) else {
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            return Ok(());
        };
        // #570: the UE radio capability ID, or its deletion indication, for a UE that
        // set the RACS bit (TS 24.501 §5.5.1.2.4). T3550 is armed below in every case.
        plain.extend(crate::racs::nas_ies_for(
            &mut state.amf_ue,
            crate::racs::NasMessage::RegistrationAccept,
        ));
        let Some(protected) = nas_security::nas_5gs_security_encode(
            &mut state.amf_ue,
            &plain,
            security_header::INTEGRITY_PROTECTED_AND_CIPHERED,
        ) else {
            log::error!("Failed to protect Registration Accept (no security context?)");
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            return Ok(());
        };

        // Periodic / mobility registration update on a UE that ALREADY has an
        // established AS-security context: deliver the protected Registration
        // Accept over DownlinkNASTransport. A fresh InitialContextSetupRequest
        // is for the *initial* context only (TS 23.502 §4.2.2.2.2 step 16);
        // re-issuing it on a periodic update would needlessly re-establish AS
        // security. `registered` is false during initial registration (set only
        // after Registration Complete), so this branch is taken solely on update.
        if state.registered && state.amf_ue.security_context_available {
            let tmsi = state.amf_ue.next_guti.tmsi;
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                .await?;
            log::info!(
                "Registration Accept (update) sent via DownlinkNASTransport to UE \
                 {amf_ue_ngap_id} (5G-TMSI=0x{tmsi:08x})"
            );
            // #91: AFTER the Accept is on the wire, never before.
            self.ue_auth_state.with_mut(amf_ue_ngap_id, |s| {
                s.registration_accept_sent = true;
            });
            let _ = self.create_ue_policy_association(amf_ue_ngap_id).await;
            return Ok(());
        }

        // Derive KgNB (TS 33.501 Annex A.9): KDF(Kamf, uplink NAS COUNT, access
        // type distinguisher). The access type distinguisher is 0x01 for 3GPP
        // access and 0x02 for non-3GPP access — matching the stored access_type.
        let access_type_distinguisher = if state.amf_ue.access_type == 0 {
            ACCESS_TYPE_3GPP
        } else {
            state.amf_ue.access_type
        };
        let kgnb = nextgcore_crypt::kdf::nextgcore_kdf_kgnb_and_kn3iwf(
            &state.amf_ue.kamf,
            state.amf_ue.ul_count,
            access_type_distinguisher,
        );
        state.amf_ue.kgnb = kgnb;
        // Seed the {NH, NCC} forward-security chain from KgNB (TS 33.501 Annex
        // A.10): KgNB is the NCC=0 pair, NH = KDF(KAMF, KgNB) is NCC=1. Without
        // this the chain starts from a zero NH and every handover hands the
        // target a key the source can reproduce (#70).
        state.amf_ue.init_next_hop_chain();

        let tmsi = state.amf_ue.next_guti.tmsi;
        let allowed_nssai = state.amf_ue.allowed_nssai.clone();
        // #361: §6.7.3.6 requires the NGAP UE INITIAL CONTEXT SETUP to carry only the null
        // algorithms for an unauthenticated emergency session. Narrowed here, on the NAS
        // octets, because this is the one egress site that hands `ngap_asn1` the NAS-shaped
        // capability rather than an already-converted NGAP bitstring -- the other two go
        // through `ue_caps_to_ngap_for_ue`. `0x80` is the MSB, i.e. xEA0/xIA0 alone, which is
        // the NAS encoding of "the null algorithm and nothing else"; `ngap_asn1` then drops
        // that bit on conversion, yielding the same empty NGAP bitstring for the same reason.
        // The UE's real advertised set stays on the context for the SMC replay (§6.7.2).
        let ue_security_capability = if state.amf_ue.unauthenticated_emergency {
            UeSecurityCapability {
                ea: 0x80,  // 5G-EA0 (NEA0) only
                ia: 0x80,  // 5G-IA0 (NIA0) only
                eea: 0x80, // EEA0 only
                eia: 0x80, // EIA0 only
            }
        } else {
            state.amf_ue.ue_security_capability.clone()
        };
        // UE-AMBR from the subscription (UDM am-data, copied onto the context);
        // omitted when the subscription carries no aggregate bitrate.
        let ue_ambr = if state.amf_ue.ue_ambr.downlink > 0 || state.amf_ue.ue_ambr.uplink > 0 {
            Some((state.amf_ue.ue_ambr.downlink, state.amf_ue.ue_ambr.uplink))
        } else {
            None
        };

        // Build the Initial Context Setup Request carrying the protected
        // Registration Accept as the NAS-PDU.
        let ics = {
            let ctx_arc = crate::context::amf_self();
            // Read THROUGH the poison: this replaced a `tokio::sync::RwLock`,
            // which cannot poison, so bailing here would be a new failure mode
            // rather than a preserved one (#363).
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            crate::ngap_asn1::build_initial_context_setup_request_asn1(
                &ctx,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                &allowed_nssai,
                &ue_security_capability,
                &kgnb,
                Some(&protected),
                ue_ambr,
            )
        };
        let Some(ics) = ics else {
            log::error!(
                "Failed to build Initial Context Setup Request for UE {amf_ue_ngap_id} \
                 (no served GUAMI?)"
            );
            self.ue_auth_state.insert(amf_ue_ngap_id, state);
            return Ok(());
        };
        // #570: IE 264 when the UE has an ID, else IE 117 when the AMF holds the UE's
        // capability (TS 23.501 §5.4.4.1 / §5.4.4.1a).
        let ics = crate::racs::add_capability_ies(
            ics,
            state.amf_ue.ue_radio_capability_id.as_deref(),
            Some(&state.amf_ue.ue_radio_capability),
        );

        state.initial_context_setup_request_sent = true;
        state.gmm_fsm.transition_to_initial_context_setup();
        self.ue_auth_state.insert(amf_ue_ngap_id, state);

        self.send_to_association(association_id, &ics).await?;
        // Arm T3550 against the ICS PDU: until the gNB confirms with an ICS
        // Response, the retransmission carries the whole request (Registration
        // Accept included), so the UE still receives the NAS message on retx.
        self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3550, ics);
        log::info!(
            "Initial Context Setup Request sent to gNB for UE {amf_ue_ngap_id} \
             (KgNB derived, Registration Accept piggybacked, 5G-TMSI=0x{tmsi:08x})"
        );
        // #91: the Registration Accept rides this ICS, so it has now egressed and the
        // UE policy association -- whose creation triggers the PCF's DL MANAGE UE
        // POLICY COMMAND -- may safely be created.
        self.ue_auth_state.with_mut(amf_ue_ngap_id, |s| {
            s.registration_accept_sent = true;
        });
        // #74 criterion 5: ACCESS_TYPE_REPORT. TS 29.518 §6.2 has the consumer receive
        // "the current access type(s) of a UE... and updated access type(s)... when AMF
        // becomes aware of the access type change of the UE" -- and a Registration
        // Accept that has egressed is the moment this AMF becomes the UE's serving AMF
        // over this access.
        //
        // Fired HERE and not in `gmm_handler::handle_registration_request`, where the
        // other `fire_*` calls live: that function's only callers are inside `mod
        // tests`, as `the_live_parser_captures_ue_s1_mode_capability` records for the
        // same module. An emitter there would have been correct and unreachable.
        //
        // `3GPP_ACCESS` is stated rather than derived because this path IS the 3GPP one:
        // NGAP is N2 from an NG-RAN. A non-3GPP registration would arrive via an N3IWF,
        // for which this tree has no daemon at all.
        //
        // #397: REGISTRATION_STATE_REPORT and LOCATION_REPORT fire from the SAME
        // moment, for the same reason, and all three are read from one `get` so the
        // three reports describe one consistent snapshot of the UE.
        //
        // `REGISTERED`: TS 29.518 §6.2 (`29518-k00.txt:24000-24008`) has the consumer
        // receive "the current registration state of a UE... and report for updated
        // registration state... when AMF becomes aware of a registration state change".
        // The egressed Registration Accept IS that change (TS 24.501 §5.5.1.2.4: the UE
        // enters 5GMM-REGISTERED on receiving it) and it is the first moment the AMF can
        // truthfully say the UE is registered rather than registering.
        //
        // LOCATION_REPORT: §6.2 (`:23958-23966`) is "the Last Known Location or the
        // current Location of a UE... and Updated Location... when AMF becomes aware of
        // a location change". `amf_ue.nr_tai` was written from the InitialUEMessage's
        // own `UserLocationInformation` at `:1581`, so the reported TAI is what the gNB
        // sent for this UE and not a default.
        //
        // These two used to fire from `gmm_handler::handle_registration_request`
        // (`:158-159`), whose only three callers are inside `mod tests` -- so a
        // conformant NWDAF subscribing to LOCATION_REPORT received nothing. That is
        // #397's first criterion, and it is why they moved here rather than gaining a
        // production caller: the question is where the EVENT occurs on a live path, not
        // how to reach a particular function.
        //
        // #400: PRESENCE_IN_AOI_REPORT and UES_IN_AREA_REPORT join them, read from the
        // same `get` and so describing the same snapshot.
        //
        // This is the FIRST-NOTIFICATION site, which TS 29.518 §5.3.1 requires to carry
        // the current state rather than waiting for a transition: *"when the event
        // subscription is targeting a UE or a group of UEs, the AMF shall report the
        // current presence status of the target UE(s)"* (`29518-k00.txt:4879-4882`).
        // `amf_ue.nr_tai` was written from the InitialUEMessage's own
        // `UserLocationInformation` (`:1586-1589`), so the TAI the subscribed areas are
        // compared against is what the gNB reported for THIS UE, not a default.
        //
        // `UES_IN_AREA_REPORT` fires here too, and takes no UE argument: the type is
        // any-UE by definition (*"UE Type: any UE"*, `:5170`) and its report carries no
        // UE identity at all (Table 6.2.6.2.5-1 NOTE 1, `:22212`). A UE registering is a
        // UE entering the AMF's served population, so a per-area count the AMF
        // previously reported may have changed — the emitter re-derives it from the live
        // store.
        if let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) {
            crate::namf_server::fire_access_type_report(&state.amf_ue, "3GPP_ACCESS");
            crate::namf_server::fire_registration_state_report(&state.amf_ue, true);
            crate::namf_server::fire_location_report(&state.amf_ue);
            crate::namf_server::fire_presence_in_aoi_report(&state.amf_ue);
        }
        crate::namf_server::fire_ues_in_area_report();
        let _ = self.create_ue_policy_association(amf_ue_ngap_id).await;
        Ok(())
    }

    /// Create the UE's `Npcf_UEPolicyControl` association, carrying the UE policy
    /// container from the Registration Request when the UE sent one (#91).
    ///
    /// # Why this runs after the Registration Accept
    ///
    /// The PCF spawns its DL MANAGE UE POLICY COMMAND as soon as the association is
    /// created, so creating the association at registration step 3b -- where this used
    /// to live -- let the URSP delivery overtake the Accept (TS 23.502 §4.2.4.3
    /// against §4.2.2.2.2). Ordering it here needs no new protocol and no new flag:
    /// the create IS the trigger, so moving the create moves the delivery.
    ///
    /// Failures log a WARN and never affect the registration -- the UE is already
    /// accepted by this point, and the policy feature fails closed (no association,
    /// no URSP). `AMF_UE_POLICY_ASSOC=off` restores the pre-E7 byte-flow.
    async fn create_ue_policy_association(&mut self, amf_ue_ngap_id: u64) -> UePolicyCreate {
        if !crate::sbi_path::ue_policy_assoc_enabled() {
            return UePolicyCreate::Skipped("kill-switch off");
        }
        let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) else {
            return UePolicyCreate::Skipped("no UE context");
        };
        // The ordering invariant, enforced rather than assumed.
        if !state.registration_accept_sent {
            log::warn!(
                "UE {amf_ue_ngap_id}: refusing to create the UE policy association before the \
                 Registration Accept has egressed; the PCF would deliver URSP first (#91)"
            );
            return UePolicyCreate::Skipped("Registration Accept not yet sent");
        }
        let Some(supi) = state.amf_ue.supi.clone() else {
            return UePolicyCreate::Skipped("no SUPI");
        };
        let (serving_mcc, serving_mnc) = plmn_mcc_mnc_strings(&state.amf_ue.nr_tai.plmn_id);
        let ue_policy_container = state.ue_policy_container.clone();

        let (guami_plmn, amf_region, amf_set, amf_pointer) = {
            let ctx_arc = crate::context::amf_self();
            // Read THROUGH the poison: this replaced a `tokio::sync::RwLock`,
            // which cannot poison, so bailing here would be a new failure mode
            // rather than a preserved one (#363).
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            match ctx.served_guami.first() {
                Some(g) => (
                    g.plmn_id.clone(),
                    g.amf_id.region,
                    g.amf_id.set,
                    g.amf_id.pointer,
                ),
                None => {
                    let fallback = self
                        .ue_auth_state
                        .get(amf_ue_ngap_id)
                        .map(|s| s.amf_ue.nr_tai.plmn_id.clone())
                        .unwrap_or_default();
                    (fallback, 2, 1, 0)
                }
            }
        };
        // #92: through the SHARED packer, not a local `format!`. The PCF matches this
        // `amfId` against the `amfInfo.guamiList` this AMF registered with the NRF, so
        // two independent renderings of one AMF ID would never match and GUAMI-based
        // targeting would fall back to the first discovered AMF on every delivery — the
        // defect #92 is about, restored by a copy-paste that no test would catch. There
        // were TWO copies of this packing here, which is the argument by itself.
        let amf_id_hex = crate::sbi_path::amf_id_hex(&crate::context::AmfId {
            region: amf_region,
            set: amf_set,
            pointer: amf_pointer,
        });
        let (guami_mcc, guami_mnc) = plmn_mcc_mnc_strings(&guami_plmn);

        // The same PCF that serves AM policy: TS 29.525 and TS 29.507 are two
        // services of one NF, and this build has no separate UE-policy PCF. Reusing
        // the AM-policy service name is also what step 3b did.
        let (pcf_host, pcf_port) = crate::sbi_path::resolve_nf_endpoint_async(
            crate::sbi_path::SbiServiceType::NpcfAmPolicyControl,
        )
        .await
        .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));

        match crate::sbi_path::call_pcf_ue_policy_create(
            &pcf_host,
            pcf_port,
            &supi,
            &serving_mcc,
            &serving_mnc,
            &guami_mcc,
            &guami_mnc,
            &amf_id_hex,
            ue_policy_container.as_deref(),
        )
        .await
        {
            Ok(assoc) => {
                log::info!(
                    "[{supi}] UE policy association created after Registration Accept \
                     (polAssoId={assoc}, uePolReq={})",
                    if ue_policy_container.is_some() {
                        "present"
                    } else {
                        "absent"
                    }
                );
                self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
                    state.ue_policy_association_id = Some(assoc.clone());
                    state.amf_ue.ue_policy_association.id = Some(assoc);
                });
            }
            Err(e) => log::warn!(
                "[{supi}] Npcf_UEPolicyControl_Create failed \
                 (registration already accepted, unaffected): {e}"
            ),
        }
        UePolicyCreate::Attempted
    }

    /// Move a UE's PDU sessions and SM context refs from the AMF UE NGAP ID it held
    /// to the one its new N2 connection was given. A UE coming back from CM-IDLE
    /// arrives under a fresh id (#518, #609).
    fn rekey_ue_sessions(&mut self, old_id: u64, new_id: u64) {
        self.sbi_offload.rekey_ue(old_id, new_id);
        {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            guard.sess_rekey_ue(old_id, new_id);
        }
        let moved: Vec<(u8, String)> = self
            .sm_context_refs
            .iter()
            .filter(|((ue, _), _)| *ue == old_id)
            .map(|((_, psi), r)| (*psi, r.clone()))
            .collect();
        for (psi, r) in moved {
            self.sm_context_refs.remove(&(old_id, psi));
            self.sm_context_refs.insert((new_id, psi), r);
            if let Some(owner) = self.sm_context_smfs.remove(&(old_id, psi)) {
                self.sm_context_smfs.insert((new_id, psi), owner);
            }
        }
    }

    /// Open an integrity-protected REGISTRATION REQUEST that arrived as an initial NAS
    /// message, i.e. from 5GMM-IDLE over a NAS security context (#609).
    ///
    /// TS 24.501 §4.4.6: such a request carries the cleartext IEs only, integrity
    /// protected (security header type 1), and the full request rides ciphered in the
    /// NAS message container. The AMF finds the context by the cleartext 5G-GUTI,
    /// checks the MAC under it, and deciphers the container.
    ///
    /// Returns the message to process and whether it was verified:
    /// - `(full request, true)`: the MAC checked. The stored context has been moved to
    ///   `amf_ue_ngap_id`, with this N2 connection's identifiers and location, and
    ///   leaves CM-IDLE.
    /// - `(cleartext request without the container, false)`: no context holds the
    ///   5G-GUTI, or the MAC failed, or the container is not a REGISTRATION REQUEST.
    ///   §4.4.6: the AMF then treats the message as if it carried no NAS message
    ///   container, so it is processed as an unprotected initial request, which
    ///   identifies or authenticates the UE (§5.5.1.3.4).
    fn open_idle_registration_request(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        initial_ue: &crate::ngap_asn1::InitialUeMessageData,
        nas: &[u8],
        cleartext: &[u8],
    ) -> (Vec<u8>, bool) {
        let container = registration_request_container(cleartext);
        let unverified = || {
            let stripped = match &container {
                Some((span, _)) => {
                    let mut bytes = cleartext.to_vec();
                    bytes.drain(span.clone());
                    bytes
                }
                None => cleartext.to_vec(),
            };
            (stripped, false)
        };

        let guti = parse_registration_request_pdu(cleartext)
            .filter(|req| req.identity_type == mobile_identity_type::GUTI)
            .and_then(|req| req.guti);
        let resolved = guti.and_then(|guti| {
            self.ue_auth_state.snapshot().into_iter().find(|(_, st)| {
                st.registered
                    && st.amf_ue.security_context_available
                    && st.amf_ue.current_guti == guti
            })
        });
        let Some((old_id, mut state)) = resolved else {
            log::info!(
                "Integrity-protected Registration Request (initial UE {amf_ue_ngap_id}): no \
                 security context holds its 5G-GUTI; processed as unprotected \
                 (TS 24.501 §4.4.6)"
            );
            return unverified();
        };

        let decoded = nas_security::nas_5gs_security_decode(&mut state.amf_ue, nas[1], nas);
        let mac_failed = std::mem::take(&mut state.amf_ue.mac_failed);
        if decoded.is_err() || mac_failed {
            log::warn!(
                "Registration Request from CM-IDLE (UE {old_id}): integrity check failed; \
                 processed as unprotected (TS 24.501 §4.4.6)"
            );
            return unverified();
        }

        let full = match &container {
            Some((_, value)) => {
                let mut value = value.clone();
                if state.amf_ue.selected_enc_algorithm != 0 {
                    nas_security::nas_encrypt(
                        state.amf_ue.selected_enc_algorithm,
                        &state.amf_ue.knas_enc,
                        state.amf_ue.ul_count,
                        state.amf_ue.access_type,
                        nas_security::direction::UPLINK,
                        &mut value,
                    );
                }
                value
            }
            None => cleartext.to_vec(),
        };
        if full.get(2) != Some(&message_type::REGISTRATION_REQUEST)
            || parse_registration_request_pdu(&full).is_none()
        {
            log::warn!(
                "Registration Request from CM-IDLE (UE {old_id}): the NAS message container \
                 is not a REGISTRATION REQUEST; processed as unprotected"
            );
            return unverified();
        }

        log::info!(
            "Registration Request from CM-IDLE: UE {old_id} resumes as {amf_ue_ngap_id} \
             (integrity verified, TS 24.501 §4.4.6)"
        );
        self.ue_auth_state.remove(old_id);
        state.ran_ue_ngap_id = initial_ue.ran_ue_ngap_id;
        // #648: the AmfUe's own id is the key its sessions and store entry live under;
        // it moves with them, or a SUPI lookup returns the old id and misses both.
        state.amf_ue.id = amf_ue_ngap_id;
        state.association_id = association_id;
        state.reachability = None;
        state.cm_idle = false;
        state.amf_ue.nr_tai = crate::context::Tai5gs {
            plmn_id: initial_ue.plmn_id.clone(),
            tac: initial_ue.tac,
        };
        state.amf_ue.nr_cgi = crate::context::NrCgi {
            plmn_id: initial_ue.plmn_id.clone(),
            cell_id: initial_ue.nr_cell_identity,
        };
        self.ue_auth_state.insert(amf_ue_ngap_id, state);
        self.rekey_ue_sessions(old_id, amf_ue_ngap_id);
        (full, true)
    }

    /// Handle Service Request (TS 24.501 Section 5.6.1)
    /// A SERVICE REQUEST from a UE in CM-IDLE (TS 23.502 §4.2.3.2), arriving in an
    /// Initial UE Message with fresh NGAP IDs -- the response to a page (§4.2.3.3)
    /// or a UE-initiated return.
    ///
    /// The UE is found by the 5G-S-TMSI it presents, the message is integrity
    /// checked under that UE's stored NAS security context (TS 24.501 §4.4.4.3),
    /// and the UE's record moves to the new AMF-UE-NGAP-ID. The Service Accept then
    /// rides an INITIAL CONTEXT SETUP REQUEST with a fresh K_gNB (TS 23.502
    /// §4.2.3.2 step 12, TS 33.501 Annex A.9 over this message's uplink NAS COUNT),
    /// which also carries any N2 SM information the paging context held. Only an
    /// integrity-checked response stops T3513 (TS 24.501 §5.6.2.2.1): an unknown
    /// identity, an unprotected message or a failed MAC is answered with SERVICE
    /// REJECT #9 and the page keeps running.
    async fn handle_idle_service_request(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        initial_ue: &crate::ngap_asn1::InitialUeMessageData,
        nas: &[u8],
        plain: &[u8],
    ) -> Result<()> {
        let ran_ue_ngap_id = initial_ue.ran_ue_ngap_id;
        log::info!(
            "Service Request from CM-IDLE (initial UE {amf_ue_ngap_id}): service_type={}",
            service_request_service_type(plain).unwrap_or(0)
        );
        let resolved = service_request_s_tmsi(plain).and_then(|(set, ptr, tmsi)| {
            self.ue_auth_state.snapshot().into_iter().find(|(_, st)| {
                st.registered
                    && st.amf_ue.current_guti.amf_set_id == set
                    && st.amf_ue.current_guti.amf_pointer == ptr
                    && st.amf_ue.current_guti.tmsi == tmsi
            })
        });
        let Some((old_id, mut state)) = resolved else {
            return self
                .reject_idle_service_request(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    "no UE holds the presented 5G-S-TMSI",
                )
                .await;
        };
        if nas[1] == security_header::PLAIN_NAS_MESSAGE {
            return self
                .reject_idle_service_request(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    "not integrity protected",
                )
                .await;
        }
        let decoded = nas_security::nas_5gs_security_decode(&mut state.amf_ue, nas[1], nas);
        let mac_failed = std::mem::take(&mut state.amf_ue.mac_failed);
        let decoded_sr = match decoded {
            Ok(plain) if !mac_failed => plain,
            _ => {
                return self
                    .reject_idle_service_request(
                        association_id,
                        amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        "integrity check failed",
                    )
                    .await;
            }
        };
        // The Service Request's own octets (the security header stripped), and its
        // NAS message container deciphered under the context that just verified it:
        // TS 24.501 §4.4.6 ciphers the container's value part in an initial message.
        let _ = decoded_sr;
        let (enc_alg, knas_enc, ul_count, access_type) = (
            state.amf_ue.selected_enc_algorithm,
            state.amf_ue.knas_enc,
            state.amf_ue.ul_count,
            state.amf_ue.access_type,
        );
        let sr_ies = service_request_session_ies(plain, &|value: &mut Vec<u8>| {
            if enc_alg != 0 {
                nas_security::nas_encrypt(
                    enc_alg,
                    &knas_enc,
                    ul_count,
                    access_type,
                    nas_security::direction::UPLINK,
                    value,
                );
            }
        });

        // The UE is back: its record moves to the new NGAP IDs and leaves CM-IDLE.
        self.ue_auth_state.remove(old_id);
        state.ran_ue_ngap_id = ran_ue_ngap_id;
        // #648: the AmfUe's own id is the key its sessions and store entry live under;
        // it moves with them. Left behind, every SUPI-addressed Namf request after this
        // Service Request (the SMF's next paging N1N2MessageTransfer among them)
        // looked the session up under the old id and answered 404.
        state.amf_ue.id = amf_ue_ngap_id;
        state.association_id = association_id;
        state.reachability = None;
        state.cm_idle = false;
        state.amf_ue.nr_tai = crate::context::Tai5gs {
            plmn_id: initial_ue.plmn_id.clone(),
            tac: initial_ue.tac,
        };
        state.amf_ue.nr_cgi = crate::context::NrCgi {
            plmn_id: initial_ue.plmn_id.clone(),
            cell_id: initial_ue.nr_cell_identity,
        };

        // Answering a page stops T3513 and hands over what was waiting.
        let paging = {
            let g = &state.amf_ue.current_guti;
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            guard.paging_take_by_s_tmsi(g.amf_set_id, g.amf_pointer, g.tmsi)
        };
        let mut sessions = Vec::new();
        if let Some(p) = &paging {
            clear_session_paging(p);
            if p.pending_n2_release {
                // A paged release is sent after the ICS as its own Release Command.
            } else if let (Some(psi), Some(transfer)) = (p.pdu_session_id, p.pending_n2.clone()) {
                let s_nssai = {
                    let ctx = crate::context::amf_self();
                    let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
                    guard
                        .sess_find_by_psi(p.amf_ue_ngap_id, psi)
                        .map(|s| s.s_nssai)
                };
                match s_nssai {
                    Some(s_nssai) => sessions.push(crate::ngap_asn1::CxtReqSession {
                        pdu_session_id: psi,
                        s_nssai,
                        transfer,
                    }),
                    None => log::warn!(
                        "Paged PDU session {psi} of UE {old_id} no longer exists; its N2 SM information is dropped"
                    ),
                }
            }
        }

        // The UE's PDU sessions are keyed by its AMF-UE-NGAP-ID; move them to the
        // new one, or every later lookup (and this one) misses them (#518).
        self.rekey_ue_sessions(old_id, amf_ue_ngap_id);

        // TS 24.501 §5.6.1.4.1 / TS 23.502 §4.2.3.2 steps 4-12: release what the UE
        // no longer has, re-activate what it has uplink data for (#518).
        let held: Vec<(u8, Option<String>, crate::context::SNssai)> = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            guard
                .sess_list_for_ue(amf_ue_ngap_id)
                .into_iter()
                .map(|s| {
                    let r = self
                        .sm_context_refs
                        .get(&(amf_ue_ngap_id, s.psi))
                        .cloned()
                        .or(s.sm_context_ref.clone());
                    (s.psi, r, s.s_nssai)
                })
                .collect()
        };
        let already: Vec<u8> = sessions.iter().map(|s| s.pdu_session_id).collect();
        let mut plan = plan_service_request_sessions(
            &held.iter().map(|(psi, _, _)| *psi).collect::<Vec<_>>(),
            sr_ies,
            &already,
        );
        // #540 / TS 23.502 §4.2.3.3 step 6: a page for a PDU session whose N1N2
        // transfer brought no N2 SM transfer -- smfd's Downlink Data Report
        // paging names the session and the IE type only -- is re-activated like
        // an uplink-data session (§4.2.3.2 step 4, upCnxState ACTIVATING), so the
        // ICS carries it and the buffered downlink is delivered.
        if let Some(p) = &paging {
            if let (Some(psi), false) = (p.pdu_session_id, p.pending_n2_release) {
                if !already.contains(&psi)
                    && !plan.activate.contains(&psi)
                    && held.iter().any(|(h, _, _)| *h == psi)
                {
                    plan.activate.push(psi);
                }
            }
        }
        for psi in &plan.release {
            let (smf_host, smf_port) = self.smf_target_for(amf_ue_ngap_id, *psi);
            let sm_ref = held
                .iter()
                .find(|(p, _, _)| p == psi)
                .and_then(|(_, r, _)| r.clone());
            if let Some(r) = sm_ref {
                if let Err(e) =
                    crate::sbi_path::call_smf_release_sm_context(&smf_host, smf_port, &r).await
                {
                    log::warn!(
                        "UE {amf_ue_ngap_id}: SMF release of PSI {psi} (inactive at the UE) failed: {e}"
                    );
                }
            }
            self.sm_context_refs.remove(&(amf_ue_ngap_id, *psi));
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            if let Some(sess) = guard.sess_find_by_psi(amf_ue_ngap_id, *psi) {
                guard.sess_remove(sess.id);
            }
            log::info!("UE {amf_ue_ngap_id}: PSI {psi} released, the UE reports it inactive");
        }
        let mut reactivation_failed: u16 = 0;
        for psi in &plan.activate {
            let (smf_host, smf_port) = self.smf_target_for(amf_ue_ngap_id, *psi);
            let found = held.iter().find(|(p, _, _)| p == psi).cloned();
            // #754: no NG Reset DEACTIVATED for this session may reach the SMF after this
            // ACTIVATING.
            self.settle_ng_reset_deactivation(amf_ue_ngap_id, *psi)
                .await;
            let transfer = match &found {
                Some((_, Some(r), _)) => {
                    match crate::sbi_path::call_smf_activate_up_connection(&smf_host, smf_port, r)
                        .await
                    {
                        Ok(t) => Some(t),
                        Err(e) => {
                            log::warn!("UE {amf_ue_ngap_id}: PSI {psi} UP activation failed: {e}");
                            None
                        }
                    }
                }
                _ => None,
            };
            match (transfer, found) {
                (Some(transfer), Some((_, _, s_nssai))) => {
                    sessions.push(crate::ngap_asn1::CxtReqSession {
                        pdu_session_id: *psi,
                        s_nssai,
                        transfer,
                    })
                }
                _ => reactivation_failed |= 1 << psi,
            }
        }
        let remaining: u16 = held
            .iter()
            .map(|(p, _, _)| *p)
            .filter(|p| !plan.release.contains(p))
            .fold(0, |m, p| m | (1 << p));

        let kgnb = nextgcore_crypt::kdf::nextgcore_kdf_kgnb_and_kn3iwf(
            &state.amf_ue.kamf,
            state.amf_ue.ul_count,
            if state.amf_ue.access_type == 0 {
                ACCESS_TYPE_3GPP
            } else {
                state.amf_ue.access_type
            },
        );
        state.amf_ue.kgnb = kgnb;
        state.amf_ue.init_next_hop_chain();
        state.initial_context_setup_request_sent = true;
        state.initial_context_setup_response_received = false;
        // TS 24.501 §8.2.17: PDU session status when the UE sent one; the
        // re-activation result when it asked for re-activation (§5.6.1.4.1).
        let accept = gmm_build::build_service_accept_for_sessions(
            sr_ies.pdu_session_status.map(|_| remaining),
            sr_ies.uplink_data_status.map(|_| reactivation_failed),
        );
        let allowed_nssai = state.amf_ue.allowed_nssai.clone();
        let ue_security_capability = state.amf_ue.ue_security_capability.clone();
        let ue_ambr = (state.amf_ue.ue_ambr.downlink > 0 || state.amf_ue.ue_ambr.uplink > 0)
            .then_some((state.amf_ue.ue_ambr.downlink, state.amf_ue.ue_ambr.uplink));
        self.ue_auth_state.insert(amf_ue_ngap_id, state);

        let Some(protected) = self.protect_nas(amf_ue_ngap_id, &accept) else {
            return Ok(());
        };
        let ics = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            crate::ngap_asn1::build_initial_context_setup_request_with_sessions_asn1(
                &guard,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                &allowed_nssai,
                &ue_security_capability,
                &kgnb,
                Some(&protected),
                ue_ambr,
                &sessions,
            )
        };
        let Some(ics) = ics else {
            log::error!("Failed to build Initial Context Setup Request for the Service Request of UE {amf_ue_ngap_id}");
            return Ok(());
        };
        let (racs_id, racs_cap) = self.racs_ies_for(amf_ue_ngap_id);
        let ics = crate::racs::add_capability_ies(ics, racs_id.as_deref(), racs_cap.as_deref());
        self.send_to_association(association_id, &ics).await?;
        if let Some(p) = &paging {
            self.deliver_paged_after_service_request(
                association_id,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                p,
            )
            .await?;
        }
        log::info!(
            "Service Request from CM-IDLE: UE {old_id} -> {amf_ue_ngap_id}, Service Accept in \
             Initial Context Setup with {} PDU session(s){}",
            sessions.len(),
            if paging.is_some() {
                " (page answered, T3513 stopped)"
            } else {
                ""
            }
        );
        // The same CM-IDLE -> CM-CONNECTED reports `handle_service_request_nas`
        // fires, for the same reasons recorded there.
        if let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) {
            crate::namf_server::fire_connectivity_state_report(&state.amf_ue, true);
            crate::namf_server::fire_reachability_report(&state.amf_ue, true);
            crate::namf_server::fire_location_report(&state.amf_ue);
            crate::namf_server::fire_presence_in_aoi_report(&state.amf_ue);
        }
        crate::namf_server::fire_ues_in_area_report();
        Ok(())
    }

    /// What a page held that does not ride the Service Request's ICS (#518, TS
    /// 23.502 §4.2.3.3 step 5): an N1 message goes down in a DOWNLINK NAS TRANSPORT
    /// (5GSM payload, TS 24.501 §8.2.11), and a paged release is answered with its
    /// own PDU SESSION RESOURCE RELEASE COMMAND.
    async fn deliver_paged_after_service_request(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        paging: &crate::context::PagingContext,
    ) -> Result<()> {
        self.deliver_n1_n2(
            association_id,
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            paging.pdu_session_id,
            paging.pending_n2_release,
            paging.pending_n1.as_deref(),
            paging.pending_n1_container_type,
        )
        .await
    }

    /// Send an N1N2MessageTransfer's payload to a UE that has an NG context: a
    /// PDU SESSION RESOURCE RELEASE COMMAND for `psi` when `n2_release`, then the
    /// N1 in a protected DOWNLINK NAS TRANSPORT. Shared by the paged path (#518)
    /// and the CM-CONNECTED path (#666).
    #[allow(clippy::too_many_arguments)]
    async fn deliver_n1_n2(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        psi: Option<u8>,
        n2_release: bool,
        n1: Option<&[u8]>,
        n1_container_type: u8,
    ) -> Result<()> {
        if n2_release {
            if let Some(psi) = psi {
                match crate::ngap_asn1::build_pdu_session_resource_release_command_asn1(
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    &[psi],
                ) {
                    Some(cmd) => self.send_to_association(association_id, &cmd).await?,
                    None => log::error!("UE {amf_ue_ngap_id}: release of PSI {psi} did not encode"),
                }
            }
        }
        if let Some(n1) = n1 {
            let plain = gmm_build::build_dl_nas_transport(psi, n1_container_type, n1, None, None)
                .unwrap_or_default();
            match self.protect_nas(amf_ue_ngap_id, &plain) {
                Some(protected) => {
                    self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                        .await?;
                    log::info!("UE {amf_ue_ngap_id}: N1 message for PSI {psi:?} delivered");
                }
                None => log::warn!(
                    "UE {amf_ue_ngap_id}: N1 message for PSI {psi:?} not sent: no NAS \
                     security context"
                ),
            }
        }
        Ok(())
    }

    /// Record that `amf_ue_ngap_id` was allocated to (association, RAN UE NGAP ID)
    /// with no NAS context behind it (#758).
    fn remember_contextless_ue_id(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
    ) {
        self.contextless_ue_ids
            .retain(|c| c.amf_ue_ngap_id != amf_ue_ngap_id);
        if self.contextless_ue_ids.len() >= MAX_CONTEXTLESS_UE_IDS {
            self.contextless_ue_ids.pop_front();
        }
        self.contextless_ue_ids.push_back(ContextlessUeId {
            amf_ue_ngap_id,
            association_id,
            ran_ue_ngap_id,
        });
    }

    /// Forget the contextless allocations of the NG connections an NG Reset from
    /// `association_id` resets (#758): every one on the association for a whole
    /// reset; for a partial one, each that an item names by either ID.
    fn drop_contextless_ue_ids_for_reset(
        &mut self,
        association_id: u64,
        reset_type: &nextgcore_ngap::types::ResetType,
    ) {
        use nextgcore_ngap::types::ResetType;
        match reset_type {
            ResetType::NgInterface => self
                .contextless_ue_ids
                .retain(|c| c.association_id != association_id),
            ResetType::PartOfNgInterface(items) => self.contextless_ue_ids.retain(|c| {
                c.association_id != association_id
                    || !items.iter().any(|item| {
                        item.amf_ue_ngap_id == Some(c.amf_ue_ngap_id)
                            || item.ran_ue_ngap_id == Some(c.ran_ue_ngap_id)
                    })
            }),
        }
    }

    /// Whether `amf_ue_ngap_id` was allocated to exactly this connection with no
    /// NAS context (#758). A match is consumed.
    fn take_contextless_ue_id(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
    ) -> ContextlessLookup {
        let Some(pos) = self
            .contextless_ue_ids
            .iter()
            .position(|c| c.amf_ue_ngap_id == amf_ue_ngap_id)
        else {
            return ContextlessLookup::Unknown;
        };
        let c = self.contextless_ue_ids[pos];
        // TS 38.413 §10.6: an AP ID is local to its NG interface. On another
        // association the ID names no logical connection there at all, so it is an
        // unknown local ID, and saying "inconsistent" would tell that gNB the ID is
        // live elsewhere.
        if c.association_id != association_id {
            return ContextlessLookup::Unknown;
        }
        if c.ran_ue_ngap_id != ran_ue_ngap_id {
            return ContextlessLookup::Inconsistent;
        }
        self.contextless_ue_ids.remove(pos);
        ContextlessLookup::Matches
    }

    /// SERVICE REJECT #9 for a CM-IDLE Service Request the AMF cannot accept
    /// (TS 24.501 §5.6.1.5): the UE re-registers.
    async fn reject_idle_service_request(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        why: &str,
    ) -> Result<()> {
        log::warn!("Service Request in Initial UE Message rejected (#9): {why}");
        // #758: the ID is allocated to this connection with no NAS context behind it.
        self.remember_contextless_ue_id(association_id, amf_ue_ngap_id, ran_ue_ngap_id);
        let reject = gmm_build::build_service_reject(
            &AmfUe::default(),
            GmmCause::UeIdentityCannotBeDerivedByTheNetwork,
        );
        self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
            .await?;
        Ok(())
    }

    /// The connected-mode half of a Service Request's user-plane re-activation
    /// (TS 23.502 §4.2.3.2): every PSI in the Uplink data status that the AMF holds
    /// an SM context for is activated at its SMF, and the N2 SM information the SMF
    /// answers goes to the gNB in a PDU SESSION RESOURCE SETUP REQUEST.
    ///
    /// `accept` (the protected SERVICE ACCEPT) is carried in the first setup
    /// request that goes out; returns whether it was, so the caller sends it on its
    /// own otherwise.
    async fn activate_up_for_connected_service_request(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
        accept: &[u8],
    ) -> bool {
        let mut carried = false;
        // `nas` is the plain message: the Uplink NAS Transport path already
        // deciphered it, so a NAS message container needs no second pass.
        let ies = service_request_session_ies(nas, &|_value: &mut Vec<u8>| {});
        let held: Vec<(u8, Option<String>, crate::context::SNssai)> = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            guard
                .sess_list_for_ue(amf_ue_ngap_id)
                .into_iter()
                .map(|s| {
                    let r = self
                        .sm_context_refs
                        .get(&(amf_ue_ngap_id, s.psi))
                        .cloned()
                        .or(s.sm_context_ref.clone());
                    (s.psi, r, s.s_nssai)
                })
                .collect()
        };
        for (psi, sm_ref, s_nssai) in
            connected_sessions_to_activate(amf_ue_ngap_id, &held, ies.uplink_data_status)
        {
            let (smf_host, smf_port) = self.smf_target_for(amf_ue_ngap_id, psi);
            self.settle_ng_reset_deactivation(amf_ue_ngap_id, psi).await;
            let transfer = match crate::sbi_path::call_smf_activate_up_connection(
                &smf_host, smf_port, &sm_ref,
            )
            .await
            {
                Ok(t) => t,
                Err(e) => {
                    log::warn!("UE {amf_ue_ngap_id}: PSI {psi} UP activation failed: {e}");
                    continue;
                }
            };
            let Some(setup_req) = crate::ngap_asn1::build_pdu_session_resource_setup_request_asn1(
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                psi,
                s_nssai.sst,
                s_nssai.sd,
                (!carried).then_some(accept),
                &transfer,
            ) else {
                log::error!(
                    "UE {amf_ue_ngap_id}: PSI {psi} PDU Session Resource Setup did not encode"
                );
                continue;
            };
            match self.send_to_association(association_id, &setup_req).await {
                Ok(()) => {
                    carried = true;
                    log::info!(
                        "UE {amf_ue_ngap_id}: PSI {psi} user plane re-activated (connected-mode \
                         Service Request): PDU Session Resource Setup Request sent"
                    )
                }
                Err(e) => log::warn!("UE {amf_ue_ngap_id}: PSI {psi} setup request not sent: {e}"),
            }
        }
        carried
    }

    async fn handle_service_request_nas(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
    ) -> Result<()> {
        let service_type = service_request_service_type(nas).unwrap_or(0);
        log::info!("Service Request from UE {amf_ue_ngap_id}: service_type={service_type}");

        let has_context = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .map(|s| s.amf_ue.security_context_available && s.registered)
            .unwrap_or(false);

        if !has_context {
            // TS 24.501 Section 5.6.1.5: cause #9 forces re-registration
            let reject = gmm_build::build_service_reject(
                &AmfUe::default(),
                GmmCause::UeIdentityCannotBeDerivedByTheNetwork,
            );
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                .await?;
            return Ok(());
        }

        // PDU session status (IEI 0x50, TLV) if present
        self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            let mut pos = 4;
            state.amf_ue.pdu_session_status_present = false;
            while pos + 1 < nas.len() {
                if nas[pos] == 0x50 {
                    let len = nas[pos + 1] as usize;
                    if len >= 2 && pos + 2 + len <= nas.len() {
                        state.amf_ue.pdu_session_status_present = true;
                        state.amf_ue.pdu_session_status =
                            ((nas[pos + 2] as u16) << 8) | nas[pos + 3] as u16;
                    }
                    break;
                }
                pos += 1;
            }
        });

        let plain = {
            let state = self.ue_auth_state.get(amf_ue_ngap_id).expect("checked");
            gmm_build::build_service_accept(&state.amf_ue).unwrap_or_default()
        };
        let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) else {
            return Ok(());
        };

        // TS 23.502 §4.2.3.2 steps 4-12 for a UE that is already CM-CONNECTED: the
        // sessions in its Uplink data status get their user plane back --
        // Nsmf_PDUSession_UpdateSMContext (upCnxState ACTIVATING), then a PDU SESSION
        // RESOURCE SETUP REQUEST carrying the SMF's N2 SM information (#682).
        //
        // The Service Accept rides INSIDE that setup request (its NAS-PDU, step 12),
        // so the UE learns its service was accepted when the gNB has the bearer -- not
        // before. Sent ahead of the setup, the Accept let the UE release its held
        // uplink about 10 ms before the gNB had the session, and that packet was lost
        // (devtest1: the first ping after a gNB move, #684).
        let carried = self
            .activate_up_for_connected_service_request(
                association_id,
                amf_ue_ngap_id,
                ran_ue_ngap_id,
                nas,
                &protected,
            )
            .await;
        if !carried {
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                .await?;
        }
        log::info!(
            "Service Accept sent to UE {amf_ue_ngap_id} (protected{})",
            if carried {
                ", in the PDU Session Resource Setup Request"
            } else {
                ""
            }
        );

        // #74 criterion 5: CONNECTIVITY_STATE_REPORT, the CM-IDLE -> CM-CONNECTED half.
        // A Service Request is exactly that transition (TS 24.501 §5.6.1), which is the
        // "connection management state change" TS 29.518 §6.2 says the AMF reports, and
        // the Service Accept has now egressed so the connection really is up. Its
        // counterpart (CONNECTED -> IDLE on the N1 release) fires from
        // `start_reachability_supervision`.
        //
        // Distinct from a REACHABILITY_REPORT: reachability is whether the AMF can page
        // the UE, CM state is whether an N1 connection exists right now, and TS 29.518
        // gives them separate event types with separate report members (`reachability`
        // vs `cmInfoList`).
        //
        // Fired here rather than in `gmm_handler::handle_service_request` because that
        // function's only caller is in `mod tests` -- see the note on
        // `send_registration_accept`.
        //
        // #397: REACHABILITY_REPORT and LOCATION_REPORT fire from the same moment.
        //
        // `REACHABLE`: §6.2 (`29518-k00.txt:24022-24031`) reports "updated reachability
        // of a UE... when AMF becomes aware of a reachability change". A UE that has just
        // completed a Service Request is reachable by demonstration, not by inference --
        // it answered. That is also a genuine CHANGE: `start_reachability_supervision`
        // armed the mobile-reachable timer at the previous N1 release precisely because
        // the AMF could no longer reach it, and this is the transition back.
        //
        // LOCATION_REPORT: the UE may have moved while idle, and a Service Request is
        // where the AMF learns it. Deliberately fired at BOTH this site and
        // `send_registration_accept` -- §6.2's trigger is "when AMF becomes aware of a
        // location change of the UE", and the AMF becomes aware at each, so reporting
        // only one would silently drop the other.
        //
        // **#406 made this report HONEST.** Until then it was the sentence above with no
        // mechanism behind it: `handle_uplink_nas_transport` discarded the
        // `UserLocationInformation` the NGAP parser decodes as mandatory, so this site
        // re-reported the TAI stored at REGISTRATION and a UE that moved while idle was
        // reported at its old location. The refresh now happens in
        // `handle_uplink_nas_transport` BEFORE this dispatch, which is what makes the
        // `get` below observe the new value.
        //
        // Both used to fire from `gmm_handler::handle_service_request` (`:299-300`),
        // whose only caller is inside `mod tests` (#397 criterion 1). Moved rather than
        // given a production caller, for the reason recorded on
        // `send_registration_accept`.
        //
        // #400's PRESENCE_IN_AOI_REPORT and UES_IN_AREA_REPORT join them **as of #406**,
        // and this is the CEILING #400 stated at `handle_handover_notify` being lifted
        // rather than merely reworded. #400 declined this site for one stated reason: the
        // Service Request path could not learn a new location, so re-evaluating the
        // registration's TAI would report an unchanged verdict as news, which TS 29.518
        // §5.3.1's *"the AMF shall only report the UE(s) whose presence status has changed
        // compared to the previous notification sent by the AMF"* (`29518-k00.txt:4893-4895`)
        // forbids. That premise is now false: the TAI and the cell identity are both
        // refreshed from the message that carried them, so a verdict computed here is a
        // verdict about where the UE IS.
        //
        // And a Service Request is a moment presence genuinely can have changed: the UE was
        // in CM-IDLE, during which it may have moved across an area boundary without the
        // AMF hearing anything at all. Firing here is what makes an OUT->IN transition
        // observable for a UE that moved while idle — before #406 it was observable only
        // via a handover, i.e. only for a UE that moved while CONNECTED.
        //
        // Safe against double-reporting because the emitter applies §5.3.1's change rule
        // itself (`namf_server::fire_presence_in_aoi_report` ->
        // `event_subscription_record_presence`): a UE that did NOT cross a boundary sends
        // nothing from here. So the common case — a Service Request from the same cell the
        // UE registered in — is silent, which is the outcome the clause requires.
        //
        // Read from ONE `get`, so all five reports describe the same snapshot.
        if let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) {
            crate::namf_server::fire_connectivity_state_report(&state.amf_ue, true);
            crate::namf_server::fire_reachability_report(&state.amf_ue, true);
            crate::namf_server::fire_location_report(&state.amf_ue);
            crate::namf_server::fire_presence_in_aoi_report(&state.amf_ue);
        }
        // A UE returning from CM-IDLE may have moved into or out of a counted area while
        // the AMF could not see it, so the per-area totals can change even though the
        // served population did not. Takes no UE argument: the type is any-UE by
        // definition and its report carries no UE identity (Table 6.2.6.2.5-1 NOTE 1).
        crate::namf_server::fire_ues_in_area_report();

        // TS 33.501 §6.12.3: reallocate the 5G-GUTI after a service request. This is the
        // moment that matters for identity privacy -- the UE has just used the identity
        // it was paged with -- and NAS-based reallocation is the UE Configuration Update
        // procedure, which is why this is the live caller criterion 1 asks for.
        self.reallocate_guti_via_configuration_update(
            association_id,
            amf_ue_ngap_id,
            ran_ue_ngap_id,
        )
        .await?;
        Ok(())
    }

    /// Reallocate the 5G-GUTI with a UE Configuration Update, supervised by T3555
    /// (TS 24.501 §5.4.4, TS 33.501 §6.12.3).
    ///
    /// Off unless `AMF_GUTI_REALLOCATION` is set, and deliberately so: this adds an
    /// outbound NAS message to a procedure that previously ended at the Service Accept,
    /// and a UE that does not implement CONFIGURATION UPDATE COMMAND would leave T3555 to
    /// retransmit four times before aborting. #72 asks for exactly this shape ("each can
    /// ship behind an off-default gate until wired end-to-end"). A runtime switch rather
    /// than a cargo feature so both states stay inside `cargo test --workspace`.
    async fn reallocate_guti_via_configuration_update(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
    ) -> Result<()> {
        if !guti_reallocation_enabled() {
            return Ok(());
        }
        let Some(plain) = self.build_guti_reallocation_command(amf_ue_ngap_id) else {
            return Ok(());
        };
        let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) else {
            return Ok(());
        };
        let ngap_pdu = self
            .send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
            .await?;
        // Armed only once the command has been HANDED TO THE TRANSPORT: a timer
        // supervising a message that never left would abort a procedure that never
        // started. The `?` above is what enforces that ordering.
        self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3555, ngap_pdu);
        log::info!(
            "Configuration Update Command sent to UE {amf_ue_ngap_id}: 5G-GUTI reallocation, \
             T3555 armed"
        );
        Ok(())
    }

    /// #570: the UE's UE Radio Capability ID and capability, for the NGAP IEs.
    fn racs_ies_for(&self, amf_ue_ngap_id: u64) -> (Option<Vec<u8>>, Option<Vec<u8>>) {
        self.ue_auth_state
            .get(amf_ue_ngap_id)
            .map(|s| {
                (
                    s.amf_ue.ue_radio_capability_id.clone(),
                    Some(s.amf_ue.ue_radio_capability.clone()),
                )
            })
            .unwrap_or((None, None))
    }

    /// #570: UE RADIO CAPABILITY INFO INDICATION (TS 38.413 §8.14.1).
    ///
    /// The capability replaces the stored one (§8.14.1.2). For a UE that set the RACS
    /// bit and holds no usable ID, the UCMF assigns one keyed on the PEI's TAC
    /// (TS 23.501 §5.4.4.1a, TS 29.673 §5.2.2.3); a registered UE then gets it in a
    /// CONFIGURATION UPDATE COMMAND, an unregistered one at Registration Complete.
    async fn handle_ue_radio_capability_info_indication(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        let Some(ind) = crate::racs::decode_info_indication(data) else {
            if nextgcore_ngap_gen::decode(data).is_err() {
                return self
                    .report_transfer_syntax_error(
                        association_id,
                        "UE Radio Capability Info Indication",
                    )
                    .await;
            }
            log::warn!(
                "UE Radio Capability Info Indication from association {association_id} lacks a \
                 mandatory IE; ignored"
            );
            return Ok(());
        };
        let Some((want_id, tac)) = self.ue_auth_state.with_mut(ind.amf_ue_ngap_id, |s| {
            s.amf_ue.ue_radio_capability = ind.capability.clone();
            let usable = s
                .amf_ue
                .ue_radio_capability_id
                .as_deref()
                .is_some_and(|id| !crate::racs::is_retired(id));
            (
                s.amf_ue.racs_supported && !usable,
                s.amf_ue.pei.as_deref().and_then(crate::racs::tac_from_pei),
            )
        }) else {
            log::warn!(
                "UE Radio Capability Info Indication for unknown UE {}; ignored",
                ind.amf_ue_ngap_id
            );
            return Ok(());
        };
        log::info!(
            "UE Radio Capability Info Indication: stored {} octets for UE {}",
            ind.capability.len(),
            ind.amf_ue_ngap_id
        );
        if !want_id {
            return Ok(());
        }
        let Some(tac) = tac else {
            // TS 24.501 §5.4.4.1 c): the network may ask for the PEI. The AMF always
            // requests the IMEISV in the Security Mode Command, so a UE without one
            // here did not answer it; no ID is assigned rather than one keyed on
            // nothing.
            log::warn!(
                "UE {} supports RACS but has no PEI, so no TAC to assign an ID under",
                ind.amf_ue_ngap_id
            );
            return Ok(());
        };
        match crate::racs::ucmf_assign(&tac, &ind.capability).await {
            Ok(id) => {
                log::info!(
                    "UCMF assigned UE radio capability ID {:02x?} to UE {} (TAC {tac})",
                    id,
                    ind.amf_ue_ngap_id
                );
                self.ue_auth_state.with_mut(ind.amf_ue_ngap_id, |s| {
                    if s.amf_ue.ue_radio_capability_id.as_deref() != Some(id.as_slice()) {
                        s.amf_ue.ue_radio_capability_id = Some(id);
                        s.amf_ue.ue_radio_capability_id_known_to_ue = false;
                    }
                });
                self.send_racs_configuration_update(
                    association_id,
                    ind.amf_ue_ngap_id,
                    ind.ran_ue_ngap_id,
                )
                .await?;
            }
            Err(e) => log::warn!(
                "No UE radio capability ID for UE {}: {e}",
                ind.amf_ue_ngap_id
            ),
        }
        Ok(())
    }

    /// #570: deliver a pending UE radio capability ID (or its deletion indication) in
    /// a CONFIGURATION UPDATE COMMAND (TS 24.501 §5.4.4.2), acknowledgement requested
    /// so T3555 supervises it. Nothing to do for a UE that is not registered yet (the
    /// Registration Complete will call again), has nothing pending, or did not set the
    /// RACS bit.
    async fn send_racs_configuration_update(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
    ) -> Result<()> {
        let plain = self
            .ue_auth_state
            .with_mut(amf_ue_ngap_id, |s| {
                if !s.registered || !s.amf_ue.security_context_available {
                    return None;
                }
                // #746: `retx` is the UE's one NAS retransmission slot, so arming T3555
                // here would silently replace the procedure in flight: a Registration
                // Accept (T3550) would never be retransmitted, and a network-initiated
                // deregistration (T3522) would lose its retransmission and its
                // exhaustion teardown. TS 24.501 §5.4.4.6 has the network abort a UE
                // configuration update that collides with a de-registration, and the
                // registration procedure delivers RACS IEs itself. So the command waits:
                // nothing is consumed from the context, and the Registration Complete
                // and Configuration Update Complete handlers call again.
                if let Some(pending) = &s.retx {
                    log::info!(
                        "UE {amf_ue_ngap_id}: UE radio capability ID update deferred, \
                         {:?} is pending (TS 24.501 §5.4.4.6)",
                        pending.timer
                    );
                    return None;
                }
                let ies = crate::racs::nas_ies_for(
                    &mut s.amf_ue,
                    crate::racs::NasMessage::ConfigurationUpdateCommand,
                );
                if ies.is_empty() {
                    return None;
                }
                let param = crate::gmm_build::ConfigurationUpdateCommandParam {
                    acknowledgement_requested: true,
                    registration_requested: false,
                    guti: false,
                    ..Default::default()
                };
                let mut msg = gmm_build::build_configuration_update_command(&s.amf_ue, &param)?;
                msg.extend(ies);
                Some(msg)
            })
            .flatten();
        let Some(plain) = plain else {
            return Ok(());
        };
        let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) else {
            return Ok(());
        };
        let ngap_pdu = self
            .send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
            .await?;
        self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3555, ngap_pdu);
        log::info!(
            "Configuration Update Command sent to UE {amf_ue_ngap_id}: UE radio capability \
             ID, T3555 armed"
        );
        Ok(())
    }

    /// #570: UE RADIO CAPABILITY ID MAPPING (TS 38.413 §8.14.3): answer with the UE
    /// radio capability mapped to the ID, from the AMF's cache or a UCMF Resolve.
    ///
    /// §8.14.3.3 defines no unsuccessful outcome, so an ID nobody can resolve gets no
    /// answer: the NG-RAN node then retrieves the capability from the UE itself.
    async fn handle_ue_radio_capability_id_mapping(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        let Some(id) = crate::racs::decode_mapping_request(data) else {
            if nextgcore_ngap_gen::decode(data).is_err() {
                return self
                    .report_transfer_syntax_error(
                        association_id,
                        "UE Radio Capability ID Mapping Request",
                    )
                    .await;
            }
            log::warn!(
                "UE Radio Capability ID Mapping Request from association {association_id} \
                 carries no ID; ignored"
            );
            return Ok(());
        };
        // Answered at once from the cache.
        if let Some(cap) = crate::racs::cache_get(&id).filter(|_| !crate::racs::is_retired(&id)) {
            if let Some(pdu) = crate::racs::build_mapping_response(&id, &cap) {
                self.send_to_association(association_id, &pdu).await?;
                log::info!(
                    "UE Radio Capability ID Mapping Response sent to association \
                     {association_id}: {} octets for ID {id:02x?}",
                    cap.len()
                );
            }
            return Ok(());
        }
        // #747: an ID the UCMF has already said it has no entry for is not asked
        // about again — permanently for a PLMN-assigned ID the UCMF deleted,
        // and for the negative cache's TTL for a manufacturer-assigned one
        // (#925 review MAJOR 1).
        if crate::racs::is_known_deleted(&id) {
            log::info!(
                "UE radio capability ID {id:02x?} has no entry at the UCMF; no mapping \
                 response (TS 38.413 §8.14.3 defines no unsuccessful outcome)"
            );
            return Ok(());
        }
        // #925 review MINOR 2: release the slot of any lookup that never
        // reported, so an aborted or panicking job cannot hold one for ever.
        self.mapping_resolves
            .retain(|_, r| r.started.elapsed() < STALE_MAPPING_RESOLVE);
        // #925 review MINOR 3: one Resolve per ID. A second association asking
        // for an ID already being resolved joins its answer instead of starting
        // another lookup.
        if let Some(resolve) = self.mapping_resolves.get_mut(&id) {
            if !resolve.waiting.contains(&association_id) {
                resolve.waiting.push(association_id);
            }
            log::debug!(
                "UE radio capability ID {id:02x?} is already being resolved; association \
                 {association_id} waits for that answer"
            );
            return Ok(());
        }
        // #747: the Resolve runs off this task, which serves every gNB and must not
        // wait on the UCMF (up to the SBI timeout, plus NRF discovery). The number in
        // flight is capped, so a gNB flooding the procedure with random IDs gets the
        // excess unanswered, which TS 38.413 §8.14.3 allows: with no unsuccessful
        // outcome defined, the NG-RAN node is left to obtain the capability from the
        // UE as it would for a UE that presented no ID.
        if self.mapping_resolves.len() >= MAX_MAPPING_RESOLVES_IN_FLIGHT {
            log::warn!(
                "UE Radio Capability ID Mapping Request from association {association_id} \
                 not resolved: {MAX_MAPPING_RESOLVES_IN_FLIGHT} UCMF lookups already \
                 running; no mapping response"
            );
            return Ok(());
        }
        self.mapping_resolves.insert(
            id.clone(),
            MappingResolve {
                waiting: vec![association_id],
                started: Instant::now(),
            },
        );
        let lookup_id = id.clone();
        // #925 re-review MINOR C: the dictionary generation as of the decision to
        // ask, read here on the NGAP task rather than inside the job.
        let asked_at = crate::racs::creation_epoch();
        // The job ALWAYS reports, so the slot is released whether the UCMF
        // answered, refused or could not be reached.
        self.sbi_offload.spawn(async move {
            let capability = match crate::racs::ucmf_resolve_at(&lookup_id, asked_at).await {
                Ok(cap) => cap,
                Err(e) => {
                    log::warn!("UE radio capability ID {lookup_id:02x?} not resolved: {e}");
                    None
                }
            };
            Some(crate::sbi_offload::SbiOutcome::MappingResponse {
                id: lookup_id,
                capability,
            })
        });
        Ok(())
    }

    /// #747: send a UE Radio Capability ID Mapping Response an off-task UCMF
    /// lookup produced. An association that closed meanwhile fails the send,
    /// which is logged: the gNB that asked is gone.
    async fn send_mapping_response(&mut self, id: &[u8], capability: Option<Vec<u8>>) {
        // Releasing the slot here, and not in the job, is what makes the cap
        // leak-proof (#925 review MINOR 2).
        let Some(resolve) = self.mapping_resolves.remove(id) else {
            return;
        };
        let Some(pdu) = capability
            .as_deref()
            .and_then(|cap| crate::racs::build_mapping_response(id, cap))
        else {
            log::warn!(
                "UE radio capability ID {id:02x?} maps to no capability; no mapping response \
                 to {} association(s) (TS 38.413 §8.14.3 defines no unsuccessful outcome)",
                resolve.waiting.len()
            );
            return;
        };
        for association_id in resolve.waiting {
            match self.send_to_association(association_id, &pdu).await {
                Ok(()) => log::info!(
                    "UE Radio Capability ID Mapping Response sent to association \
                     {association_id} for ID {id:02x?}"
                ),
                Err(e) => log::warn!(
                    "UE Radio Capability ID Mapping Response for association \
                     {association_id} not sent: {e}"
                ),
            }
        }
    }

    /// Assign a fresh 5G-GUTI and build the CONFIGURATION UPDATE COMMAND that carries it.
    ///
    /// Split from the transmission so the message's CONTENT is testable without an SCTP
    /// association: what matters conformance-wise -- a new TMSI, the old one still
    /// current, and an acknowledgement request so a COMPLETE is owed -- is decided here.
    ///
    /// `None` when there is nothing to send: no context, not registered, or no security
    /// context (a UCU is integrity protected, so without one there is nothing to protect
    /// it with).
    fn build_guti_reallocation_command(&mut self, amf_ue_ngap_id: u64) -> Option<Vec<u8>> {
        // `with_mut`: `generate_new_guti` allocates the next 5G-TMSI onto the UE's
        // context, and that allocation must persist or the COMPLETE the UE returns
        // would be matched against a `next_guti` the AMF no longer holds -- the UE
        // would adopt an identity the network had forgotten. Await-free, so the
        // lock is held only for the build.
        self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            if !state.registered || !state.amf_ue.security_context_available {
                return None;
            }
            // A fresh 5G-TMSI, kept in next_guti until the UE acknowledges: the old GUTI
            // stays current meanwhile, so a UE that never answers is still addressable.
            // `generate_new_guti` sources the TMSI from the OS CSPRNG and touches only
            // the TMSI, so the PLMN and AMF identifiers of the current GUTI carry over
            // (TS 23.003 §2.10.1: the 5G-TMSI must not be predictable).
            state.amf_ue.next_guti = state.amf_ue.current_guti.clone();
            state.amf_ue.generate_new_guti();
            let param = crate::gmm_build::ConfigurationUpdateCommandParam {
                // Acknowledgement requested: without it there is no COMPLETE, so the
                // AMF could never know whether the UE adopted the new identity.
                acknowledgement_requested: true,
                registration_requested: false,
                guti: true,
                ..Default::default()
            };
            gmm_build::build_configuration_update_command(&state.amf_ue, &param)
        })?
    }

    /// Apply the TS 24.501 §4.4.4.3 integrity-check-failure exceptions.
    ///
    /// The rule is "discard, except" -- and the exceptions exist because the alternative
    /// is worse than processing a message whose MAC did not verify:
    ///
    /// - **REGISTRATION REQUEST**: re-run authentication. A UE whose security context has
    ///   diverged from the AMF's (a lost SMC, a restarted AMF, a rolled-over COUNT) can
    ///   only ever produce a failing MAC, so discarding leaves it unable to register at
    ///   all — it retries, fails the same check, and is stuck until it powers off. The
    ///   message is NOT trusted: nothing from it is applied, it triggers a fresh
    ///   authentication, and the UE must pass that before anything is accepted.
    /// - **SERVICE REQUEST**: answer SERVICE REJECT with 5GMM cause #9 ("UE identity
    ///   cannot be derived by the network"), which tells the UE to register again rather
    ///   than keep asking for service on a context the network cannot verify. Sent as a
    ///   PLAIN message: there is no usable security context to protect it with, which is
    ///   the whole reason we are here.
    /// - **anything else**: discarded, as before. A protected DEREGISTRATION REQUEST or
    ///   UL NAS TRANSPORT with a bad MAC is either corruption or an attacker, and acting
    ///   on it is what integrity protection exists to prevent.
    async fn handle_integrity_check_failure(
        &mut self,
        association_id: u64,
        ul_nas: &crate::ngap_asn1::UplinkNasTransportData,
        plain: &[u8],
        sec_hdr: u8,
    ) -> Result<()> {
        let amf_ue_ngap_id = ul_nas.amf_ue_ngap_id;
        let ran_ue_ngap_id = ul_nas.ran_ue_ngap_id;
        // The decoded plaintext is only used to learn WHICH message it is; nothing in it
        // is applied to the UE context.
        let msg_type = plain.get(2).copied().unwrap_or(0);
        let has_context = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .is_some_and(|s| s.amf_ue.security_context_available);

        match integrity_failure_action(msg_type, has_context) {
            IntegrityFailureAction::Reauthenticate => {
                log::warn!(
                    "MAC verification failed for a REGISTRATION REQUEST from UE \
                     {amf_ue_ngap_id} on an existing security context: re-authenticating \
                     (TS 24.501 §4.4.4.3) rather than discarding"
                );
                // integrity_protected = false: the request did NOT verify, so the
                // handler must treat its contents as cleartext and demand
                // authentication, exactly as it would for a first registration.
                self.handle_registration_request_nas(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    plain,
                    false,
                )
                .await
            }
            IntegrityFailureAction::ServiceReject => {
                log::warn!(
                    "MAC verification failed for a SERVICE REQUEST from UE \
                     {amf_ue_ngap_id}: SERVICE REJECT #9 (TS 24.501 §4.4.4.3)"
                );
                let reject = self.integrity_failure_service_reject(amf_ue_ngap_id);
                self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &reject)
                    .await?;
                Ok(())
            }
            IntegrityFailureAction::Discard => {
                log::warn!(
                    "NAS MAC verification failed for UE {amf_ue_ngap_id} \
                     (message type 0x{msg_type:02x}, security header 0x{sec_hdr:02x}), \
                     discarding: TS 24.501 §4.4.4.3 lists no exception for it"
                );
                Ok(())
            }
        }
    }

    /// The SERVICE REJECT the §4.4.4.3 exception sends: 5GMM cause #9, plain, because the
    /// security context that would have protected it is the one that just failed.
    fn integrity_failure_service_reject(&self, amf_ue_ngap_id: u64) -> Vec<u8> {
        // Owned rather than borrowed: the store hands out a CLONE, not a guard
        // (#341), so there is nothing left to borrow from once the lock is
        // released. `unwrap_or_default` replaces the previous local-plus-reference
        // dance.
        let amf_ue = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .map(|s| s.amf_ue)
            .unwrap_or_default();
        gmm_build::build_service_reject(&amf_ue, GmmCause::UeIdentityCannotBeDerivedByTheNetwork)
    }

    /// Handle UE-initiated Deregistration Request (TS 24.501 Section 5.5.2.2):
    /// release all PDU sessions at the SMF, purge the UDM registration, send
    /// Deregistration Accept (unless switch-off) and release the NG context
    async fn handle_deregistration_request_nas(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
    ) -> Result<()> {
        // De-registration type (low nibble of octet 4): bit4 (0x08) = switch off
        let dereg_type = nas.get(3).copied().unwrap_or(0);
        let switch_off = dereg_type & 0x08 != 0;
        log::info!("Deregistration Request from UE {amf_ue_ngap_id} (switch_off={switch_off})");

        // Release every PDU session at the SMF (TS 23.502 Section 4.2.2.3.2
        // step 5: Nsmf_PDUSession_ReleaseSMContext)
        self.release_all_pdu_sessions(amf_ue_ngap_id).await;

        // Purge the AMF registration at UDM
        if let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) {
            if let Some(supi) = state.amf_ue.supi.clone() {
                let (udm_host, udm_port) = crate::sbi_path::resolve_nf_endpoint_async(
                    crate::sbi_path::SbiServiceType::NudmUecm,
                )
                .await
                .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));
                if let Err(e) =
                    crate::sbi_path::call_udm_uecm_deregistration(&udm_host, udm_port, &supi).await
                {
                    log::warn!("[{supi}] UDM purge on deregistration failed: {e}");
                }
            }
        }

        // Deregistration Accept (not sent when the UE switched off,
        // TS 24.501 Section 5.5.2.2.2)
        if !switch_off {
            let plain = gmm_build::build_deregistration_accept(&AmfUe::default())
                .unwrap_or_else(|| vec![0x7E, 0x00, 0x46]);
            let pdu = self.protect_nas(amf_ue_ngap_id, &plain).unwrap_or(plain);
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &pdu)
                .await?;
            log::info!("Deregistration Accept sent to UE {amf_ue_ngap_id}");
        }

        self.finish_deregistration(association_id, amf_ue_ngap_id, ran_ue_ngap_id)
            .await
    }

    /// Common tail of both deregistration directions: terminate the PCF UE
    /// Policy Association (Wave-6 E7), drop the NAS state and release the NG
    /// UE context (Cause NAS deregister)
    async fn finish_deregistration(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
    ) -> Result<()> {
        self.deregistered_ue_cleanup(amf_ue_ngap_id);
        // Cause: NAS deregister (TS 38.413 Section 9.3.1.2, CauseNas value 2)
        self.release_ue(association_id, amf_ue_ngap_id, ran_ue_ngap_id, 2)
            .await
    }

    /// Terminate the UE's policy associations at the PCF, for a UE that is being
    /// deregistered.
    ///
    /// - AM Policy Association: AMF-initiated termination (TS 23.502 §4.16.3.2),
    ///   `Npcf_AMPolicyControl_Delete` (TS 29.507 §4.2.4). TS 23.502 §4.2.2.3.2 step 7
    ///   (UE-initiated) and §4.2.2.3.3 step 6 (network-initiated) require it on every
    ///   deregistration (#622).
    /// - UE Policy Association: `Npcf_UEPolicyControl_Delete` (TS 29.525 §4.2.4,
    ///   TS 23.502 §4.16.13.1), Wave-6 E7.
    ///
    /// Each delete runs on a background task: a PCF hiccup must never delay or fail
    /// the release that follows. Only an association that was actually created is
    /// deleted, so with `AMF_UE_POLICY_ASSOC=off` nothing extra is sent. Reads the
    /// association ids from `ue_auth_state`, so call it before the entry is removed.
    fn terminate_policy_associations(&self, amf_ue_ngap_id: u64) {
        let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) else {
            return;
        };
        if let Some(pol_asso_id) = state.policy_association_id {
            tokio::spawn(async move {
                let (pcf_host, pcf_port) = match crate::sbi_path::resolve_nf_endpoint_async(
                    crate::sbi_path::SbiServiceType::NpcfAmPolicyControl,
                )
                .await
                {
                    Ok(ep) => ep,
                    Err(e) => {
                        log::warn!(
                            "AM policy association {pol_asso_id} not deleted \
                             (PCF endpoint resolution failed): {e}"
                        );
                        return;
                    }
                };
                if let Err(e) =
                    crate::sbi_path::call_pcf_am_policy_delete(&pcf_host, pcf_port, &pol_asso_id)
                        .await
                {
                    log::warn!("Npcf_AMPolicyControl_Delete({pol_asso_id}) failed: {e}");
                }
            });
        }
        if let Some(pol_asso_id) = state.ue_policy_association_id {
            tokio::spawn(async move {
                let (pcf_host, pcf_port) = match crate::sbi_path::resolve_nf_endpoint_async(
                    crate::sbi_path::SbiServiceType::NpcfAmPolicyControl,
                )
                .await
                {
                    Ok(ep) => ep,
                    Err(e) => {
                        log::warn!(
                            "UE policy association {pol_asso_id} not deleted \
                             (PCF endpoint resolution failed): {e}"
                        );
                        return;
                    }
                };
                if let Err(e) =
                    crate::sbi_path::call_pcf_ue_policy_delete(&pcf_host, pcf_port, &pol_asso_id)
                        .await
                {
                    log::warn!("Npcf_UEPolicyControl_Delete({pol_asso_id}) failed: {e}");
                }
            });
        }
    }

    /// The per-UE teardown every deregistration shares, short of the N2 release:
    /// the AM and UE Policy Associations, the EPS bearer identities, the deregistration
    /// event reports, and the NAS state. Split out of [`Self::finish_deregistration`]
    /// for [`Self::local_deregistration`] (#602), which must not send an N2 release
    /// for a UE with no N2 connection.
    fn deregistered_ue_cleanup(&mut self, amf_ue_ngap_id: u64) {
        self.terminate_policy_associations(amf_ue_ngap_id);

        // #291: free the UE's EPS bearer identities. Done HERE, in the common tail of
        // both deregistration directions, and BEFORE `ue_auth_state` is dropped —
        // that is where the SUPI keying the stored `AmfUe` comes from.
        //
        // This is a backstop, not the primary mechanism: the SMF returns each
        // identity in a `releasedEbiList` when its PDU session is released. It is
        // needed because the stored `AmfUe` SURVIVES deregistration (nothing in
        // production removes one), so without it an identity whose release never
        // reached the AMF is leaked for the life of the process.
        if let Some(supi) = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .and_then(|s| s.amf_ue.supi.clone())
        {
            crate::namf_server::release_all_ebis_on_deregistration(&supi);
        }

        // #397: REGISTRATION_STATE_REPORT `DEREGISTERED`, and LOSS_OF_CONNECTIVITY for
        // the second trigger §6.2 names.
        //
        // Fired HERE, in the common tail, and not in either direction's handler: both
        // UE-initiated (`handle_deregistration_request_nas`) and network-initiated
        // deregistration converge on this function, so one call covers both and cannot
        // drift. It also fires for the UE that switched off -- no Deregistration Accept
        // is sent to such a UE (TS 24.501 §5.5.2.2.2), but it is just as deregistered,
        // and a consumer that heard nothing would still believe it registered.
        //
        // BEFORE `ue_auth_state.remove`, because that is where the SUPI and location the
        // reports carry live -- the same ordering constraint #291's EBI release above
        // records. An emitter after the remove would deliver a report with no identity.
        //
        // LOSS_OF_CONNECTIVITY: §6.2 (`29518-k00.txt:24089-24098`) names three triggers,
        // "when Mobile Reachable timer expires in the AMF..., when the UE detaches and
        // when AMF deregisters from UDM for an active UE". #398 wired the first;
        // deregistration is the other two, and both happen here -- the UDM purge runs in
        // `handle_deregistration_request_nas` just above. `DEREGISTERED` is the
        // `LossOfConnectivityReason` for exactly that
        // (`TS29518_Namf_EventExposure.yaml:1610`), distinct from the
        // `MAX_DETECTION_TIME_EXPIRED` #398 reports for the timer trigger -- so a
        // consumer can tell the two apart.
        //
        // REGISTRATION_STATE_REPORT used to fire `false` from
        // `gmm_handler::handle_deregistration_request` (`:368`), whose only caller is in
        // `mod tests` (#397 criterion 1).
        if let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) {
            crate::namf_server::fire_registration_state_report(&state.amf_ue, false);
            crate::namf_server::fire_loss_of_connectivity(&state.amf_ue, "DEREGISTERED");
        }

        self.ue_auth_state.remove(amf_ue_ngap_id);
    }

    /// LOCAL deregistration (#602): the old AMF's side of TS 23.502 §4.2.2.2.2 step
    /// 14d, for a Nudm_UECM_DeregistrationNotification with `UE_INITIAL_REGISTRATION`.
    ///
    /// A new AMF now serves the UE, so NO NAS message is sent: the UE belongs to the new
    /// AMF, and a DEREGISTRATION REQUEST that reached it would deregister it there. In
    /// order:
    /// 1. Nsmf_PDUSession_ReleaseSMContext for every PDU session (step 14d, "the SMF(s)
    ///    shall release the PDU Session on getting this notification").
    /// 2. In [`Self::deregistered_ue_cleanup`]: the AMF-initiated AM Policy
    ///    Association Termination (§4.16.3.2) and the UE Policy Association
    ///    Termination (§4.16.13.1).
    /// 3. A UE Context Release Command when the UE still has an N2 context here
    ///    (TS 38.413 §8.3.3; CauseNas "deregister"). None for a CM-IDLE UE: it has no
    ///    N2 connection to release.
    /// 4. The UE context itself: the NAS state, and the global RAN UE and AMF UE
    ///    entries, as the implicit deregistration removes them.
    ///
    /// No Nudm_UECM_Deregistration: the UDM already records the NEW AMF as serving,
    /// and that is what it notified us about.
    async fn local_deregistration(&mut self, amf_ue_ngap_id: u64) -> Result<()> {
        let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) else {
            return Err(anyhow::anyhow!("UE {amf_ue_ngap_id} not found"));
        };
        log::info!(
            "[{}] Local deregistration of UE {amf_ue_ngap_id}: a new AMF serves it \
             (UE_INITIAL_REGISTRATION, TS 23.502 §4.2.2.2.2 step 14d); no NAS is sent",
            state.amf_ue.supi.as_deref().unwrap_or("unknown")
        );

        self.release_all_pdu_sessions(amf_ue_ngap_id).await;

        self.deregistered_ue_cleanup(amf_ue_ngap_id);
        if state.cm_idle {
            self.forget_ue(amf_ue_ngap_id);
        } else if let Err(e) = self
            .release_ue(
                state.association_id,
                amf_ue_ngap_id,
                state.ran_ue_ngap_id,
                // Cause: NAS deregister (TS 38.413 Section 9.3.1.2, CauseNas value 2)
                2,
            )
            .await
        {
            // Best effort: the decision to drop the UE is already made and half
            // applied (`release_ue` forgot it before sending), so a lost gNB must not
            // leave the global RAN UE / AMF UE entries behind as well.
            log::warn!("UE Context Release Command for UE {amf_ue_ngap_id} not sent: {e}");
        }

        let handle = crate::context::amf_self();
        if let Ok(ctx) = handle.read() {
            let ran_ue = ctx.ran_ue_find_by_amf_ue_ngap_id(amf_ue_ngap_id);
            if let Some(ran_ue) = &ran_ue {
                ctx.ran_ue_remove(ran_ue.id);
            }
            // The AMF UE: the RAN UE's back-reference when there is one, else the UE's
            // own id -- for an NGAP-registered UE the two are the AMF UE NGAP ID.
            let amf_ue_id = ran_ue
                .map(|r| r.amf_ue_id)
                .filter(|id| *id != crate::context::NEXTGCORE_INVALID_POOL_ID)
                .unwrap_or(state.amf_ue.id);
            ctx.amf_ue_remove(amf_ue_id);
        }
        Ok(())
    }

    /// Network-initiated Deregistration Request (TS 24.501 Section 5.5.2.3).
    ///
    /// Sends a protected DEREGISTRATION REQUEST (0x47) and arms T3522.
    /// PDU sessions are released when the Deregistration Accept arrives (or
    /// on T3522 exhaustion, the implicit-deregistration abnormal action).
    pub async fn send_network_initiated_deregistration(
        &mut self,
        amf_ue_ngap_id: u64,
        reregistration_required: bool,
        gmm_cause: Option<GmmCause>,
    ) -> Result<()> {
        let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) else {
            return Err(anyhow::anyhow!("UE {amf_ue_ngap_id} not found"));
        };
        let association_id = state.association_id;
        let ran_ue_ngap_id = state.ran_ue_ngap_id;

        let reason = if reregistration_required {
            crate::gmm_build::DeregistrationReason::ReregistrationRequired
        } else {
            crate::gmm_build::DeregistrationReason::UeNotSwitchOff
        };
        let plain = gmm_build::build_deregistration_request(&AmfUe::default(), reason, gmm_cause)
            .unwrap_or_default();
        let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) else {
            return Err(anyhow::anyhow!(
                "no security context for UE {amf_ue_ngap_id}"
            ));
        };
        let ngap_pdu = self
            .send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
            .await?;
        self.arm_retx(amf_ue_ngap_id, NasProcTimer::T3522, ngap_pdu);
        log::info!("Network-initiated Deregistration Request sent to UE {amf_ue_ngap_id}");
        Ok(())
    }

    /// Handle UL NAS TRANSPORT (0x67, TS 24.501 Section 5.4.5): route N1 SM
    /// to the SMF; reply with cause #90 for container types without a
    /// forwarding target; 5GMM Status on protocol errors
    async fn handle_ul_nas_transport_nas(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
    ) -> Result<()> {
        if nas.len() < 6 {
            return Ok(());
        }
        let container_type = nas[3] & 0x0F;
        let container_len = ((nas[4] as usize) << 8) | (nas[5] as usize);
        if nas.len() < 6 + container_len {
            log::error!("UL NAS Transport container truncated");
            return Ok(());
        }
        let container = nas[6..6 + container_len].to_vec();

        // Optional IEs after the container: PDU session ID (IEI 0x12, TV)
        let mut psi: Option<u8> = None;
        let mut dnn_value: Option<String> = None;
        let mut pos = 6 + container_len;
        while pos < nas.len() {
            match nas[pos] {
                0x12 if pos + 1 < nas.len() => {
                    psi = Some(nas[pos + 1]);
                    pos += 2;
                }
                0x59 if pos + 1 < nas.len() => pos += 2, // Old PDU session ID (TV)
                0x22 if pos + 1 < nas.len() => {
                    // S-NSSAI (TLV)
                    pos += 2 + nas[pos + 1] as usize;
                }
                0x25 if pos + 1 < nas.len() => {
                    // DNN (TLV, TS 24.501 9.11.2.1A): length-prefixed labels.
                    // Capture it so the requested DNN (e.g. "xr") reaches the
                    // SMF instead of being forced to "internet" below.
                    let l = nas[pos + 1] as usize;
                    if pos + 2 + l <= nas.len() {
                        dnn_value = decode_dnn_labels(&nas[pos + 2..pos + 2 + l]);
                    }
                    pos += 2 + l;
                }
                b if b & 0x80 != 0 => pos += 1, // type-1 TV (e.g. request type 0x8-)
                _ => break,
            }
        }

        let transport = crate::gmm_handler::UlNasTransport {
            payload_container_type: container_type,
            payload_container: container.clone(),
            pdu_session_id: psi,
            ..Default::default()
        };

        // Parse/validate via the GMM handler, through `with_mut` because
        // `handle_ul_nas_transport` takes `&mut AmfUe` and records what it parsed
        // (the PDU session id and its request type) onto the context. Mutating a
        // clone and dropping it would leave the AMF routing a 5GSM message for a
        // session it has no record of. Await-free.
        let Some(action) = self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            let ran_ue = crate::context::RanUe::default();
            crate::gmm_handler::handle_ul_nas_transport(&mut state.amf_ue, &ran_ue, &transport)
        }) else {
            return Ok(());
        };

        match action {
            Ok(crate::gmm_handler::UlTransportAction::RouteToSmf { .. }) => {
                self.handle_5gsm_message(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    &container,
                    dnn_value.as_deref(),
                )
                .await?;
            }
            Ok(crate::gmm_handler::UlTransportAction::PayloadNotForwarded) => {
                // DL NAS TRANSPORT with the original payload + cause #90
                // (TS 24.501 Section 5.4.5.3.1)
                let plain = gmm_build::build_dl_nas_transport(
                    None,
                    container_type,
                    &container,
                    Some(GmmCause::PayloadWasNotForwarded),
                    None,
                )
                .unwrap_or_default();
                if let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) {
                    self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                        .await?;
                }
            }
            Ok(crate::gmm_handler::UlTransportAction::ForwardLppToLmf { lpp }) => {
                self.forward_ul_lpp_to_lmf(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    container_type,
                    lpp,
                )
                .await?;
            }
            Ok(crate::gmm_handler::UlTransportAction::ForwardUpdpToPcf { container }) => {
                self.forward_ul_updp_to_pcf(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    container_type,
                    container,
                )
                .await?;
            }
            Err(cause) => {
                // Protocol error: 5GMM STATUS (TS 24.501 Section 5.4.7)
                let plain = gmm_build::build_gmm_status(cause).unwrap_or_default();
                if let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) {
                    self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                        .await?;
                }
            }
        }
        Ok(())
    }

    /// Wave-6 A4 (TS 23.273 §6.11.2 uplink LPP leg): relay an uplink LPP N1
    /// message to the serving LMF via a Namf `N1MessageNotify` (TS 29.518
    /// §5.2.2.4) when the LMF registered an `n1MessageClass == "LPP"` notify
    /// callback for this UE via `N1N2MessageSubscribe` (Wave-6 A3). The LPP PDU
    /// is opaque to the AMF and forwarded **verbatim** (transparent relay).
    ///
    /// Fail-OPEN toward the UE: with NO registered LPP subscription the legacy
    /// abnormal action is preserved byte-for-byte — a Downlink NAS TRANSPORT
    /// echoing the payload with 5GMM cause #90 (TS 24.501 §5.4.5.3.1) — so the
    /// default matched-sim reg/PDU/ping path (UEs never send LPP) is unchanged.
    async fn forward_ul_lpp_to_lmf(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        container_type: u8,
        lpp: Vec<u8>,
    ) -> Result<()> {
        // Resolve the UE's ueContextId (SUPI) — the N1N2 subscription registry
        // key (the NGAP server's own per-UE state first, the shared AMF context
        // as fallback), mirroring the uplink NRPPa relay.
        let supi = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .and_then(|s| s.amf_ue.supi.clone())
            .or_else(|| {
                crate::context::amf_self()
                    .read()
                    .ok()
                    .and_then(|guard| guard.amf_ue_find_by_id(amf_ue_ngap_id))
                    .and_then(|ue| ue.supi.clone())
            });

        // A3 registry lookup (exact-class "LPP", fail-closed) + fallback LCS
        // correlation captured from the originating N1N2MessageTransfer.
        let (sub, fallback_corr) = {
            let ctx = crate::context::amf_self();
            let Ok(guard) = ctx.read() else {
                return Ok(());
            };
            match supi.as_deref() {
                Some(s) => (
                    guard.n1n2_subscription_find_n1(s, "LPP"),
                    guard.lcs_correlation_find(s),
                ),
                None => (None, None),
            }
        };

        if let Some(callback_uri) = sub.as_ref().and_then(|s| s.n1_notify_callback_uri.clone()) {
            let sub = sub.expect("callback_uri implies subscription");
            let lcs_correlation_id = sub
                .lcs_correlation_id
                .clone()
                .or_else(|| fallback_corr.map(|r| r.lcs_correlation_id));
            log::info!(
                "LCS: relaying uplink LPP N1 ({} B, amf_ue_ngap_id {amf_ue_ngap_id}) to LMF \
                 callback {callback_uri} (sub={})",
                lpp.len(),
                sub.subscription_id,
                callback_uri = nextgcore_sbi::log_redact::redact_last_segment(&callback_uri)
            );
            crate::namf_server::send_n1_message_notify(
                callback_uri,
                Some(sub.subscription_id),
                "LPP".to_string(),
                lcs_correlation_id,
                supi,
                lpp,
            );
            return Ok(());
        }

        // No LMF registered → legacy abnormal action, byte-identical to pre-A4:
        // DL NAS TRANSPORT echoing the payload with 5GMM cause #90.
        log::info!(
            "UL LPP positioning container ({} B, amf_ue_ngap_id {amf_ue_ngap_id}) — no LMF N1 \
             'LPP' subscription registered; replying 5GMM #90 (payload not forwarded)",
            lpp.len()
        );
        let plain = gmm_build::build_dl_nas_transport(
            None,
            container_type,
            &lpp,
            Some(GmmCause::PayloadWasNotForwarded),
            None,
        )
        .unwrap_or_default();
        if let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) {
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                .await?;
        }
        Ok(())
    }

    /// Wave-6 E6 (TS 29.525 §4.2.2.2 delivery-result loop): relay an uplink
    /// UE-policy N1 message (MANAGE UE POLICY COMPLETE / COMMAND REJECT, TS
    /// 24.501 D.2.1.3/D.2.1.4) to the PCF via a Namf `N1MessageNotify` (TS
    /// 29.518 §5.2.2.4) when the PCF registered an `n1MessageClass == "UPDP"`
    /// notify callback for this UE via `N1N2MessageSubscribe` (Wave-6 A3). The
    /// UE-policy container is opaque to the AMF and forwarded **verbatim**
    /// (transparent relay) — the PCF decodes the COMPLETE/REJECT.
    ///
    /// Fail-safe toward the UE and DEFAULT-SAFE: with NO registered "UPDP"
    /// subscription the legacy abnormal action is preserved byte-for-byte — a
    /// Downlink NAS TRANSPORT echoing the payload with 5GMM cause #90 (TS 24.501
    /// §5.4.5.3.1) — so on the default matched-sim path (no PCF subscription)
    /// the UL behaviour is unchanged. Exactly mirrors [`forward_ul_lpp_to_lmf`].
    async fn forward_ul_updp_to_pcf(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        container_type: u8,
        container: Vec<u8>,
    ) -> Result<()> {
        // Resolve the UE's ueContextId (SUPI) — the N1N2 subscription registry
        // key, mirroring the uplink LPP relay.
        let supi = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .and_then(|s| s.amf_ue.supi.clone())
            .or_else(|| {
                crate::context::amf_self()
                    .read()
                    .ok()
                    .and_then(|guard| guard.amf_ue_find_by_id(amf_ue_ngap_id))
                    .and_then(|ue| ue.supi.clone())
            });

        // A3 registry lookup (exact-class "UPDP", fail-closed): only a PCF that
        // registered a "UPDP" notify callback for this UE receives the uplink.
        let sub = {
            let ctx = crate::context::amf_self();
            let Ok(guard) = ctx.read() else {
                return Ok(());
            };
            match supi.as_deref() {
                Some(s) => guard.n1n2_subscription_find_n1(s, "UPDP"),
                None => None,
            }
        };

        if let Some(callback_uri) = sub.as_ref().and_then(|s| s.n1_notify_callback_uri.clone()) {
            let sub = sub.expect("callback_uri implies subscription");
            log::info!(
                "UE policy: relaying uplink UE-policy N1 ({} B, amf_ue_ngap_id {amf_ue_ngap_id}) \
                 to PCF callback {callback_uri} (sub={})",
                container.len(),
                sub.subscription_id,
                callback_uri = nextgcore_sbi::log_redact::redact_last_segment(&callback_uri)
            );
            crate::namf_server::send_n1_message_notify(
                callback_uri,
                Some(sub.subscription_id),
                "UPDP".to_string(),
                None, // no LCS correlation for UE-policy
                supi,
                container,
            );
            return Ok(());
        }

        // No PCF subscribed → legacy abnormal action, byte-identical to pre-E6:
        // DL NAS TRANSPORT echoing the payload with 5GMM cause #90.
        log::info!(
            "UL UE-policy container ({} B, amf_ue_ngap_id {amf_ue_ngap_id}) — no PCF N1 'UPDP' \
             subscription registered; replying 5GMM #90 (payload not forwarded)",
            container.len()
        );
        let plain = gmm_build::build_dl_nas_transport(
            None,
            container_type,
            &container,
            Some(GmmCause::PayloadWasNotForwarded),
            None,
        )
        .unwrap_or_default();
        if let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) {
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                .await?;
        }
        Ok(())
    }

    /// Handle a 5GSM PDU (from an UL NAS TRANSPORT N1 SM container, or a
    /// legacy raw 5GSM NAS PDU): SBI toward the SMF + N1/N2 distribution
    async fn handle_5gsm_message(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        sm_pdu: &[u8],
        dnn_override: Option<&str>,
    ) -> Result<()> {
        if sm_pdu.len() < 4 {
            return Ok(());
        }
        let psi = sm_pdu[1];
        let pti = sm_pdu[2];
        let sm_msg_type = sm_pdu[3];
        log::info!("5GSM message: PSI={psi}, PTI={pti}, msg_type=0x{sm_msg_type:02x}");

        let (smf_host, smf_port) = crate::sbi_path::resolve_nf_endpoint_async(
            crate::sbi_path::SbiServiceType::NsmfPdusession,
        )
        .await
        .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));
        // #669: a 5GSM message for an EXISTING session goes to the SMF holding its
        // context; only a new establishment is a fresh selection.
        let (smf_host, smf_port) = match self.sm_context_smfs.get(&(amf_ue_ngap_id, psi)) {
            Some(owner) if sm_msg_type != 0xC1 => owner.clone(),
            _ => (smf_host, smf_port),
        };

        match sm_msg_type {
            // PDU Session Establishment Request
            0xC1 => {
                log::info!("PDU Session Establishment Request from UE: PSI={psi}, PTI={pti}");
                // #877 m1: the re-selection window runs from the request's arrival,
                // so a first attempt that takes the connect timeout to fail does not
                // push the #90 past the UE's T3580.
                let arrived = std::time::Instant::now();

                // #796: a UE retransmission (T3580) of a request already waiting for
                // an SMF is not a new attempt. Sending it on the NGAP task would hold
                // all of N2 for the connect timeout of an unreachable SMF; the waiting
                // entry already re-selects off the task. Past the window it is
                // answered at once.
                if let Some(p) = self.pending_establishments.get_mut(&(amf_ue_ngap_id, psi)) {
                    if p.first_failure.elapsed() >= ESTABLISHMENT_RETRY_WINDOW {
                        self.pending_establishments.remove(&(amf_ue_ngap_id, psi));
                        return self
                            .answer_payload_not_forwarded(
                                association_id,
                                amf_ue_ngap_id,
                                ran_ue_ngap_id,
                                sm_pdu,
                                "within the re-selection window",
                            )
                            .await;
                    }
                    p.sm_pdu = sm_pdu.to_vec();
                    p.dnn_override = dnn_override.map(str::to_string);
                    log::info!(
                        "UE {amf_ue_ngap_id}: PDU session establishment PSI={psi} \
                         retransmitted while waiting for an SMF; the re-selection goes on"
                    );
                    return Ok(());
                }

                // S-NSSAI/DNN: from the UE's allowed slice when known
                let (sst, sd) = self
                    .ue_auth_state
                    .get(amf_ue_ngap_id)
                    .and_then(|s| s.amf_ue.allowed_nssai.first().map(|n| (n.sst, n.sd)))
                    .unwrap_or((1, None));
                // DNN from the UE's UL NAS Transport DNN IE (e.g. "xr" for an XR
                // session). Issue #204: when the UE omits the IE -- or on the
                // legacy raw-5GSM path, which carries no DNN -- the member is
                // OMITTED from SmContextCreateData rather than filled with the
                // literal "internet". `dnn` is optional in TS 29.502 §6.1.6.2.2,
                // and TS 23.501 §5.6.1 makes the SUBSCRIBED default the network's
                // answer; the SMF owns that decision because it is the NF that
                // retrieves SM subscription data (TS 23.501 §6.2.2). A literal
                // here meant every deployment whose subscribers do not all default
                // to a DNN named "internet" attached DNN-less sessions to the wrong
                // data network, with the wrong UPF, policy, charging and slice --
                // and silently, because the session established.
                let dnn = dnn_override;

                // RedCap indication: propagate the UE's Reduced-Capability
                // status (parsed at registration in gmm_handler) to the SMF so
                // it can apply a reduced session-AMBR (Rel-17, TS 38.101).
                let redcap_indication = self
                    .ue_auth_state
                    .get(amf_ue_ngap_id)
                    .map(|s| s.amf_ue.redcap_indication)
                    .unwrap_or(false);

                // #361: an EMERGENCY REGISTERED UE gets the emergency DNN and nothing else.
                //
                // TS 23.501 §5.16.4.9a: "the network shall reject any PDU Session
                // Establishment request for normal service from the UE on this Access Type",
                // and §5.16.4.9: "If the UE is Emergency Registered over a given access, it
                // shall not request a PDU Session to any other DNN over this access."
                //
                // Both halves are needed and only one existed. The UE-side half is the
                // "Emergency registered" bit in the Registration Accept, which #361 also adds;
                // this is the NETWORK half, which §5.16.4.9a puts a `shall` on precisely
                // because a UE may disregard its own. Before this the AMF only RECORDED
                // whether a session matched the emergency DNN (see the
                // `assign_emergency_pdu_session` block below) and forwarded every request
                // regardless -- so an emergency-registered UE could obtain a general-purpose
                // session, which for an UNAUTHENTICATED one means network access with no
                // subscription, no policy and no charging. That is the admission surface #361
                // names, and this is the fence §10.2.2 assumes is there.
                //
                // A DNN-LESS request is allowed through: TS 23.501 §5.16.4.2 has the network
                // apply its configured emergency DNN when an emergency-registered UE asks for a
                // session without naming one, which is the `dnn == None` case (#204). Same
                // predicate the recording block below uses, so the two cannot drift.
                //
                // 5GSM #29 "user authentication or authorization failed" (TS 24.501 §9.11.4.2,
                // wire value 0x1D): the UE is not authorized for this DNN in this registration.
                // Not #27 "missing or unknown DNN" -- the DNN may exist and be perfectly valid
                // for a normally registered UE, which is a different statement.
                if self.emergency.emergency_context(amf_ue_ngap_id).is_some() {
                    let emergency_dnn = self.emergency.emergency_dnn().to_string();
                    // `is_some_and(!=)` rather than `!is_none_or(==)`: a DNN-less request is
                    // NOT refused (§5.16.4.2 applies the configured emergency DNN), so the
                    // refusal condition is "named a DNN, and it was not the emergency one".
                    if dnn.is_some_and(|d| d != emergency_dnn) {
                        log::warn!(
                            "PDU session establishment REFUSED for emergency-registered UE \
                             {amf_ue_ngap_id}: PSI={psi} requested DNN '{}' but only the \
                             emergency DNN '{emergency_dnn}' is permitted over this access \
                             (TS 23.501 §5.16.4.9a); 5GSM #29",
                            dnn.unwrap_or("<none>")
                        );
                        let reject = vec![0x2E, psi, pti, 0xC3, 0x1D];
                        self.send_n1_sm_to_ue(
                            association_id,
                            amf_ue_ngap_id,
                            ran_ue_ngap_id,
                            psi,
                            &reject,
                        )
                        .await?;
                        return Ok(());
                    }
                }

                // Issue #73: convey the UE and serving-network identity on N11
                // (TS 29.502 6.1.6.2.2). Previously none of this was sent, so the
                // SMF fabricated `imsi-unknown` and every subscriber looked
                // identical to policy, charging and NSAC.
                // #980 review: this establishment's origination timestamp, taken
                // once here and kept with the request if it has to wait (#796), so
                // every retry of it carries the same value.
                let origination = nextgcore_sbi::datetime::now_origination_timestamp();
                let identity = {
                    let ctx = crate::context::amf_self();
                    let guard = ctx.read().ok();
                    // Bound first: the store returns an owned clone, and the
                    // builder borrows it (#341).
                    let ue = self.ue_auth_state.get(amf_ue_ngap_id);
                    crate::sbi_path::SmContextIdentity {
                        origination_timestamp: Some(origination.clone()),
                        ..build_sm_context_identity(
                            ue.as_ref(),
                            guard.as_ref().and_then(|c| c.served_guami.first()),
                        )
                    }
                };

                match crate::sbi_path::call_smf_create_sm_context(
                    &smf_host,
                    smf_port,
                    psi,
                    sst,
                    sd,
                    dnn,
                    sm_pdu,
                    redcap_indication,
                    &identity,
                )
                .await
                {
                    Ok(resp) => {
                        self.apply_sm_context_created(
                            association_id,
                            amf_ue_ngap_id,
                            ran_ue_ngap_id,
                            psi,
                            sst,
                            sd,
                            dnn,
                            sm_pdu,
                            resp,
                        )
                        .await?;
                    }
                    Err(e) if smf_unreachable(&e) => {
                        // #796: no SMF was reachable, e.g. the only one is
                        // restarting and released this session with 5GSM #39 on
                        // its way down. SMF selection is the AMF's job (TS 23.502
                        // §4.3.2.2.1): keep re-selecting for a bounded window, and
                        // only then tell the UE the message was not forwarded.
                        self.defer_establishment(
                            association_id,
                            amf_ue_ngap_id,
                            ran_ue_ngap_id,
                            sm_pdu,
                            dnn_override,
                            arrived,
                            &origination,
                            &e,
                        )
                        .await?;
                    }
                    Err(e) => {
                        // No local fabrication of sessions: PDU SESSION
                        // ESTABLISHMENT REJECT, 5GSM cause #26 insufficient
                        // resources (TS 24.501 Section 8.3.3)
                        log::warn!("SMF SM Context Create failed ({e}); rejecting PSI={psi}");
                        let reject = vec![0x2E, psi, pti, 0xC3, 0x1A];
                        self.send_n1_sm_to_ue(
                            association_id,
                            amf_ue_ngap_id,
                            ran_ue_ngap_id,
                            psi,
                            &reject,
                        )
                        .await?;
                    }
                }
            }
            // PDU Session Modification Request
            0xC9 => {
                log::info!("PDU Session Modification Request from UE: PSI={psi}, PTI={pti}");
                // SMF-chosen ref, not the PSI -- see sm_context_refs.
                let Some(sm_context_ref) =
                    self.sm_context_refs.get(&(amf_ue_ngap_id, psi)).cloned()
                else {
                    log::warn!(
                        "PDU Session Modification for UE {amf_ue_ngap_id} PSI {psi} with no \
                         stored SM context ref: dropping (no session to modify)"
                    );
                    return Ok(());
                };

                match crate::sbi_path::call_smf_update_sm_context_with_n1(
                    &smf_host,
                    smf_port,
                    &sm_context_ref,
                    sm_pdu,
                )
                .await
                {
                    Ok(resp) => {
                        // PDU Session Modification Command to UE (from SMF N1
                        // when provided)
                        let n1 = if resp.n1_sm_msg.is_empty() {
                            vec![0x2E, psi, pti, 0xCB]
                        } else {
                            resp.n1_sm_msg.clone()
                        };
                        self.send_n1_sm_to_ue(
                            association_id,
                            amf_ue_ngap_id,
                            ran_ue_ngap_id,
                            psi,
                            &n1,
                        )
                        .await?;

                        if !resp.n2_sm_info.is_empty() {
                            let modify_req = match crate::ngap_asn1::build_pdu_session_resource_modify_request_asn1(
                                amf_ue_ngap_id,
                                ran_ue_ngap_id,
                                psi,
                                None,
                                &resp.n2_sm_info,
                            ) {
                                Some(bytes) => bytes,
                                None => {
                                    log::error!("Failed to build PDU Session Resource Modify Request");
                                    return Ok(());
                                }
                            };
                            self.send_to_association(association_id, &modify_req)
                                .await?;
                            log::info!(
                                "PDU Session Resource Modify Request sent to gNB: PSI={psi}"
                            );
                        }
                    }
                    Err(e) => {
                        log::warn!("SMF modification failed ({e}), sending reject");
                        // PDU SESSION MODIFICATION REJECT, cause #26
                        let reject = vec![0x2E, psi, pti, 0xCC, 0x1A];
                        self.send_n1_sm_to_ue(
                            association_id,
                            amf_ue_ngap_id,
                            ran_ue_ngap_id,
                            psi,
                            &reject,
                        )
                        .await?;
                    }
                }
            }
            // PDU Session Modification Complete
            0xCD => {
                log::info!("PDU Session Modification Complete from UE: PSI={psi}");
            }
            // PDU Session Release Request
            0xD1 => {
                log::info!("PDU Session Release Request from UE: PSI={psi}, PTI={pti}");
                // SMF-chosen ref, not the PSI -- see sm_context_refs.
                let Some(sm_context_ref) =
                    self.sm_context_refs.get(&(amf_ue_ngap_id, psi)).cloned()
                else {
                    log::warn!(
                        "PDU Session Release for UE {amf_ue_ngap_id} PSI {psi} with no stored \
                         SM context ref: dropping (no session to release)"
                    );
                    return Ok(());
                };

                match crate::sbi_path::call_smf_release_sm_context(
                    &smf_host,
                    smf_port,
                    &sm_context_ref,
                )
                .await
                {
                    Ok(()) => log::info!("SMF SM Context Released: PSI={psi}"),
                    Err(e) => log::warn!("SMF release failed: {e}"),
                }
                // #756: the session is over at the AMF too. Forgotten even when the
                // SMF call failed: the UE is told the session is released below, so
                // nothing will address it again, and keeping the ref would leak it.
                self.forget_session(amf_ue_ngap_id, psi);

                // PDU Session Release Command (cause #36 regular deactivation)
                let release_cmd = vec![0x2E, psi, pti, 0xD3, 0x24];
                self.send_n1_sm_to_ue(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    psi,
                    &release_cmd,
                )
                .await?;

                let release_ngap =
                    match crate::ngap_asn1::build_pdu_session_resource_release_command_asn1(
                        amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        &[psi],
                    ) {
                        Some(bytes) => bytes,
                        None => {
                            log::error!("Failed to build PDU Session Resource Release Command");
                            return Ok(());
                        }
                    };
                self.send_to_association(association_id, &release_ngap)
                    .await?;
                log::info!("PDU Session Resource Release Command sent to gNB: PSI={psi}");
            }
            // PDU Session Release Complete (TS 24.501 Table 9.7.1: 0xD4; 0xD6 is 5GSM
            // STATUS). #582: relayed to the SMF (TS 23.502 §4.3.4.2 step 10), which
            // removes the SM context and notifies RELEASED -- the end of a release the
            // SMF started, e.g. for a session the NG-RAN reported released.
            0xD4 => {
                log::info!("PDU Session Release Complete from UE: PSI={psi}, PTI={pti}");
                match self.sm_context_refs.get(&(amf_ue_ngap_id, psi)).cloned() {
                    Some(sm_context_ref) => {
                        if let Err(e) = crate::sbi_path::call_smf_update_sm_context_n1_only(
                            &smf_host,
                            smf_port,
                            &sm_context_ref,
                            sm_pdu,
                        )
                        .await
                        {
                            log::warn!(
                                "PDU Session Release Complete for PSI={psi}: SMF update failed: {e}"
                            );
                        }
                    }
                    None => log::info!(
                        "PDU Session Release Complete for UE {amf_ue_ngap_id} PSI {psi}: no SM \
                         context left (released already)"
                    ),
                }
            }
            0xD6 => {
                log::info!("5GSM STATUS from UE: PSI={psi}");
            }
            other => {
                log::warn!("Unhandled 5GSM message type 0x{other:02x}");
            }
        }
        Ok(())
    }

    /// Send an N1 SM payload to the UE inside a protected DL NAS TRANSPORT
    /// (TS 24.501 Section 5.4.5.2). Falls back to the bare container only if
    /// no security context exists (pre-Rel-15 sim compatibility).
    async fn send_n1_sm_to_ue(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        psi: u8,
        n1_sm: &[u8],
    ) -> Result<()> {
        let plain = gmm_build::build_dl_nas_transport(
            Some(psi),
            payload_container_type::N1_SM_INFORMATION,
            n1_sm,
            None,
            None,
        )
        .unwrap_or_default();

        let pdu = match self.protect_nas(amf_ue_ngap_id, &plain) {
            Some(p) => p,
            None => {
                log::warn!(
                    "No NAS security context for UE {amf_ue_ngap_id}: sending bare N1 SM (legacy peer)"
                );
                n1_sm.to_vec()
            }
        };
        self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &pdu)
            .await?;
        Ok(())
    }

    /// Deliver LCS positioning downlinks the Namf SBI handler enqueued
    /// (TS 23.273). For each item the serving SCTP association + RAN-UE-NGAP-ID
    /// are resolved from this server's per-UE state; NRPPa is relayed to the gNB
    /// over N2 (UE-associated NRPPa transport), LPP to the UE over a
    /// security-protected N1 DL NAS Transport. Best effort: a UE that has since
    /// gone CM-IDLE, or a build/send failure, is logged and skipped — never
    /// propagated, so a positioning hiccup cannot break the NGAP pump.
    /// Drain the network-initiated deregistration queue (WSB-4) the
    /// Namf_Callback dereg-notify handler populated and send a protected
    /// DEREGISTRATION REQUEST + arm T3522 for each (TS 23.502 §4.2.2.3.3 /
    /// TS 24.501 §5.5.2.3). This is the (non-test) caller of
    /// [`Self::send_network_initiated_deregistration`].
    /// Drain the connected-UE N1N2 queue (#666) and send each item to the UE's
    /// serving gNB, in the shapes a paged transfer is delivered in after the
    /// Service Request. An item for a UE the NGAP task no longer knows is dropped
    /// with a warning: the SMF's T3591/T3592 retransmits, and an abandoned
    /// procedure is the SMF's to clean up.
    async fn process_connected_downlinks(&mut self) {
        let pending = {
            let ctx = crate::context::amf_self();
            let Ok(guard) = ctx.read() else {
                return;
            };
            guard.connected_downlink_drain()
        };
        for item in pending {
            let Some(state) = self.ue_auth_state.get(item.amf_ue_ngap_id) else {
                log::warn!(
                    "N1N2 transfer for UE {} (PSI {}) dropped: no NG context",
                    item.amf_ue_ngap_id,
                    item.pdu_session_id
                );
                continue;
            };
            let (association_id, ran_ue_ngap_id) = (state.association_id, state.ran_ue_ngap_id);
            if let Err(e) = self
                .deliver_n1_n2(
                    association_id,
                    item.amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    Some(item.pdu_session_id),
                    item.n2_release,
                    item.n1.as_deref(),
                    crate::gmm_handler::payload_container_type::N1_SM_INFORMATION,
                )
                .await
            {
                log::warn!(
                    "N1N2 transfer for UE {} (PSI {}) not sent: {e}",
                    item.amf_ue_ngap_id,
                    item.pdu_session_id
                );
            } else {
                log::info!(
                    "UE {}: N1N2 transfer for PSI {} delivered (release command: {}, N1: {})",
                    item.amf_ue_ngap_id,
                    item.pdu_session_id,
                    item.n2_release,
                    item.n1.is_some()
                );
            }
        }
    }

    /// A CreateSMContext answered (#796: extracted so an off-task re-selection
    /// attempt is applied by the same code as the first attempt): record the
    /// session, relay the N1 to the UE and, once the UE context is up at the gNB,
    /// send the PDU SESSION RESOURCE SETUP REQUEST.
    #[allow(clippy::too_many_arguments)]
    async fn apply_sm_context_created(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        psi: u8,
        sst: u8,
        sd: Option<u32>,
        dnn: Option<&str>,
        sm_pdu: &[u8],
        resp: crate::sbi_path::SmContextCreateResponse,
    ) -> Result<()> {
        // #796: an establishment that was waiting for an SMF is done.
        self.pending_establishments.remove(&(amf_ue_ngap_id, psi));
        log::info!(
            "SMF SM Context Created: ref={}, n1_len={}, n2_len={}",
            resp.sm_context_ref,
            resp.n1_sm_msg.len(),
            resp.n2_sm_info.len()
        );
        // Remember the SMF-chosen reference: every later
        // Nsmf_PDUSession_UpdateSMContext for this session must
        // use it verbatim (TS 29.502 §5.2.2.2.1). It is not the
        // PSI and must not be reconstructed from one.
        self.sm_context_refs
            .insert((amf_ue_ngap_id, psi), resp.sm_context_ref.clone());
        // #669: and WHICH SMF holds it.
        match resp.smf_authority.as_deref().and_then(split_authority) {
            Some(owner) => {
                self.sm_context_smfs.insert((amf_ue_ngap_id, psi), owner);
            }
            None => {
                self.sm_context_smfs.remove(&(amf_ue_ngap_id, psi));
            }
        }
        // #540: also the AmfSess the Namf N1N2MessageTransfer handler
        // and the Service Request's re-activation look the session up
        // in. Before this only `sm_context_refs` was written, so every
        // N1N2 transfer from the SMF -- the paging request included --
        // answered 404 and an idle UE could never be reached.
        #[cfg(test)]
        let forced_full = std::mem::take(&mut self.fail_next_session_record);
        #[cfg(not(test))]
        let forced_full = false;
        let recorded =
            !forced_full && record_amf_session(amf_ue_ngap_id, psi, &resp.sm_context_ref, sst, sd);
        if !recorded {
            // #756 review m1: a session the AMF cannot record is one it could never
            // page, modify, re-activate or release, and its refs would be swept within
            // 10 s, leaking it at the SMF and UPF. So it is not established: released
            // at the SMF, and the 5GSM message sent back to the UE as not forwarded
            // (TS 24.501 §5.4.5.2.5 a), §5.4.5.3.1 case e): 5GMM #90). The SMF's
            // Accept is not relayed.
            let (smf_host, smf_port) = self.smf_target_for(amf_ue_ngap_id, psi);
            let sm_ref = resp.sm_context_ref.clone();
            // Off the NGAP task, keyed on the session so it reaches the SMF before
            // any later CreateSMContext for the same PSI. Durable: the UE leaving
            // must not drop it, or the context leaks at the SMF.
            self.sbi_offload
                .spawn_keyed_durable((amf_ue_ngap_id, psi), move || async move {
                    if let Err(e) =
                        crate::sbi_path::call_smf_release_sm_context(&smf_host, smf_port, &sm_ref)
                            .await
                    {
                        log::warn!(
                            "UE {amf_ue_ngap_id}: SMF release of the unrecorded PDU session \
                             {psi} failed: {e}"
                        );
                    }
                    None
                });
            self.forget_session(amf_ue_ngap_id, psi);
            let plain = gmm_build::build_dl_nas_transport(
                Some(psi),
                crate::gmm_handler::payload_container_type::N1_SM_INFORMATION,
                sm_pdu,
                Some(GmmCause::PayloadWasNotForwarded),
                None,
            )
            .unwrap_or_default();
            if let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) {
                self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                    .await?;
            }
            return Ok(());
        }

        // #356: record the emergency PDU session against the UE's
        // emergency context. Before this `assign_emergency_pdu_session`
        // had no production caller, so `EmergencyContext.pdu_session_id`
        // was always `None` and nothing could tell WHICH session carried
        // the emergency call -- the one fact an operator needs to
        // prioritise or trace it.
        //
        // The condition is deliberately two-part. The UE must hold an
        // emergency context (the method returns `false` otherwise, so
        // this is what makes the record meaningful rather than merely
        // attempted), AND the session must be on the emergency DNN. A
        // DNN-less request counts: TS 23.501 §5.16.4.2 has the network
        // use the configured emergency DNN when an emergency-registered
        // UE asks for a session without naming one, which is exactly the
        // `dnn == None` case that reaches the SMF with the member
        // omitted (#204). An emergency-registered UE that explicitly asks
        // for some OTHER DNN is not establishing the emergency session
        // and must not be recorded as one.
        let emergency_dnn = self.emergency.emergency_dnn().to_string();
        let on_emergency_dnn = dnn.is_none_or(|d| d == emergency_dnn);
        if on_emergency_dnn
            && self
                .emergency
                .assign_emergency_pdu_session(amf_ue_ngap_id, psi)
        {
            log::warn!(
                "Emergency PDU session recorded for UE {amf_ue_ngap_id}: \
                 PSI={psi} on DNN '{}' (TS 23.501 §5.16.4.2)",
                dnn.unwrap_or(&emergency_dnn)
            );
        }

        // N1: PDU Session Establishment Accept via DL NAS
        // TRANSPORT (protected when a context exists)
        self.send_n1_sm_to_ue(
            association_id,
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            psi,
            &resp.n1_sm_msg,
        )
        .await?;
        // The N1 container the SMF produced is the 5GSM PDU Session
        // Establishment Accept; the AMF only relays it. Logged here
        // because the relay was previously silent, so the last
        // AMF-visible step of a successful session establishment left
        // no trace.
        if !resp.n1_sm_msg.is_empty() {
            log::info!(
                "PDU Session Establishment Accept sent to UE \
                 {amf_ue_ngap_id} (PSI={psi}, {} bytes)",
                resp.n1_sm_msg.len()
            );
        }

        // N2: PDU Session Resource Setup Request toward the gNB.
        // The UE context (AS-layer security) must be established
        // first — i.e. the gNB must have returned an Initial
        // Context Setup Response (TS 38.413 §8.3.1 precedes the
        // PDU session setup of TS 38.413 §8.2.1). Without it the
        // gNB has no KgNB/DRBs to attach the session to.
        let ics_done = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .map(|s| s.initial_context_setup_response_received)
            .unwrap_or(false);
        if !ics_done {
            log::warn!(
                "Deferring PDU Session Resource Setup for PSI={psi}: Initial \
                 Context Setup not yet confirmed for UE {amf_ue_ngap_id}"
            );
            return Ok(());
        }

        let setup_req = match crate::ngap_asn1::build_pdu_session_resource_setup_request_asn1(
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            psi,
            sst,
            sd,
            None,
            &resp.n2_sm_info,
        ) {
            Some(bytes) => bytes,
            None => {
                log::error!("Failed to build PDU Session Resource Setup Request");
                return Ok(());
            }
        };
        self.send_to_association(association_id, &setup_req).await?;
        log::info!("PDU Session Resource Setup Request sent to gNB: PSI={psi}");
        Ok(())
    }

    /// Keep a PDU Session Establishment Request whose CreateSMContext reached no
    /// SMF, for [`Self::process_pending_establishments`] to retry (#796). Once the
    /// window from its first failure has passed, or when too many are already
    /// waiting, the UE is answered instead: a DL NAS TRANSPORT carrying its 5GSM
    /// message back with 5GMM #90 "payload was not forwarded" (TS 24.501
    /// §5.4.5.2.5 a) 1), §5.4.5.3.1 case e): routing failure).
    #[allow(clippy::too_many_arguments)]
    async fn defer_establishment(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        sm_pdu: &[u8],
        dnn_override: Option<&str>,
        arrived: std::time::Instant,
        origination_timestamp: &str,
        error: &crate::sbi_path::SbiError,
    ) -> Result<()> {
        let psi = sm_pdu[1];
        let now = std::time::Instant::now();
        let key = (amf_ue_ngap_id, psi);
        // A UE retransmission of the same request keeps the original window, and
        // the original origination timestamp (#980 review).
        let (first_failure, generation, origination_timestamp) =
            self.pending_establishments.get(&key).map_or_else(
                || {
                    (
                        arrived,
                        ESTABLISHMENT_GENERATION.fetch_add(1, std::sync::atomic::Ordering::Relaxed),
                        origination_timestamp.to_string(),
                    )
                },
                |p| {
                    (
                        p.first_failure,
                        p.generation,
                        p.origination_timestamp.clone(),
                    )
                },
            );
        let full = !self.pending_establishments.contains_key(&key)
            && self.pending_establishments.len() >= MAX_PENDING_ESTABLISHMENTS;
        if full || now.duration_since(first_failure) >= ESTABLISHMENT_RETRY_WINDOW {
            self.pending_establishments.remove(&key);
            log::warn!("UE {amf_ue_ngap_id}: last CreateSMContext failure: {error}");
            return self
                .answer_payload_not_forwarded(
                    association_id,
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    sm_pdu,
                    if full {
                        "and the retry list is full"
                    } else {
                        "within the re-selection window"
                    },
                )
                .await;
        }
        log::warn!(
            "UE {amf_ue_ngap_id}: no SMF reachable for PDU session establishment PSI={psi} \
             ({error}); re-selecting for up to {}s (#796)",
            ESTABLISHMENT_RETRY_WINDOW
                .saturating_sub(now.duration_since(first_failure))
                .as_secs()
        );
        self.pending_establishments.insert(
            key,
            PendingEstablishment {
                association_id,
                ran_ue_ngap_id,
                sm_pdu: sm_pdu.to_vec(),
                dnn_override: dnn_override.map(str::to_string),
                first_failure,
                next_attempt: now + ESTABLISHMENT_RETRY_INTERVAL,
                in_flight: false,
                generation,
                origination_timestamp,
            },
        );
        Ok(())
    }

    /// The routing-failure answer (#796): a DL NAS TRANSPORT carrying the UE's own
    /// 5GSM message back, with 5GMM #90 "payload was not forwarded" (TS 24.501
    /// §5.4.5.2.5 a) 1), §5.4.5.3.1 case e)).
    async fn answer_payload_not_forwarded(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        sm_pdu: &[u8],
        why: &str,
    ) -> Result<()> {
        let psi = sm_pdu[1];
        log::warn!(
            "UE {amf_ue_ngap_id}: PDU session establishment PSI={psi} not forwarded: no SMF \
             reachable {why}; 5GMM #90 (TS 24.501 §5.4.5.3.1 e))"
        );
        let plain = gmm_build::build_dl_nas_transport(
            Some(psi),
            crate::gmm_handler::payload_container_type::N1_SM_INFORMATION,
            sm_pdu,
            Some(GmmCause::PayloadWasNotForwarded),
            None,
        )
        .unwrap_or_default();
        if let Some(protected) = self.protect_nas(amf_ue_ngap_id, &plain) {
            self.send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, &protected)
                .await?;
        }
        Ok(())
    }

    /// Supervise the waiting establishments (#796). Nothing here awaits an SBI
    /// request: each due attempt is spawned off the NGAP task
    /// ([`crate::sbi_offload`]) and its outcome is applied by
    /// [`Self::process_sbi_outcomes`]. So the window is wall clock: an entry whose
    /// window has passed is answered #90 here, at its end, even while an attempt
    /// to an unreachable SMF is still waiting for its connect timeout.
    ///
    /// A UE that went away, or went CM-IDLE (its 5GSM procedure does not survive
    /// the N1 release, and it re-requests on its own), is dropped without an
    /// answer.
    async fn process_pending_establishments(&mut self) {
        if self.pending_establishments.is_empty() {
            return;
        }
        let now = std::time::Instant::now();
        let keys: Vec<(u64, u8)> = self.pending_establishments.keys().copied().collect();
        for key in keys {
            let (amf_ue_ngap_id, psi) = key;
            let Some(p) = self.pending_establishments.get(&key).cloned() else {
                continue;
            };
            let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) else {
                self.pending_establishments.remove(&key);
                continue;
            };
            if state.is_cm_idle() {
                log::info!(
                    "UE {amf_ue_ngap_id}: went CM-IDLE while PDU session establishment \
                     PSI={psi} waited for an SMF; dropped (the UE re-requests)"
                );
                self.pending_establishments.remove(&key);
                // #877 re-review m1: an attempt still waiting for a permit is
                // cancelled, so it neither holds the PSI's key nor creates a
                // context nobody waits for. A started one finishes; a late
                // success is released (`apply_establishment_attempt`).
                self.sbi_offload.supersede_key(key);
                continue;
            }
            // The UE's current connection: it may have moved since.
            let (association_id, ran_ue_ngap_id) = (state.association_id, state.ran_ue_ngap_id);
            if now.duration_since(p.first_failure) >= ESTABLISHMENT_RETRY_WINDOW {
                self.pending_establishments.remove(&key);
                // #877 re-review m1, as for CM-IDLE above.
                self.sbi_offload.supersede_key(key);
                if let Err(e) = self
                    .answer_payload_not_forwarded(
                        association_id,
                        amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        &p.sm_pdu,
                        "within the re-selection window",
                    )
                    .await
                {
                    log::warn!("UE {amf_ue_ngap_id}: #90 for PSI={psi} not sent: {e}");
                }
                continue;
            }
            if p.in_flight || p.next_attempt > now {
                continue;
            }
            if let Some(w) = self.pending_establishments.get_mut(&key) {
                w.in_flight = true;
            }
            self.spawn_establishment_attempt(amf_ue_ngap_id, &p, &state);
        }
    }

    /// Start one off-task re-selection attempt (#796): SMF selection (NRF discovery
    /// on a cache miss) and CreateSMContext, bounded by what is left of the window.
    fn spawn_establishment_attempt(
        &mut self,
        amf_ue_ngap_id: u64,
        p: &PendingEstablishment,
        state: &UeNasContext,
    ) {
        let psi = p.sm_pdu[1];
        let (sst, sd) = state
            .amf_ue
            .allowed_nssai
            .first()
            .map_or((1, None), |n| (n.sst, n.sd));
        let redcap_indication = state.amf_ue.redcap_indication;
        let identity = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().ok();
            crate::sbi_path::SmContextIdentity {
                // The establishment's own stamp, not a new one: a retry is the
                // same request (#980 review).
                origination_timestamp: Some(p.origination_timestamp.clone()),
                ..build_sm_context_identity(
                    Some(state),
                    guard.as_ref().and_then(|c| c.served_guami.first()),
                )
            }
        };
        let sm_pdu = p.sm_pdu.clone();
        let dnn = p.dnn_override.clone();
        let generation = p.generation;
        log::info!("UE {amf_ue_ngap_id}: retrying PDU session establishment PSI={psi} (#796)");
        // Keyed on the session, so it is ordered with any other exchange for it
        // (the release of an abandoned context below), and `forget_ue` cancels it.
        // Not cut short at the window's end (#877 m4): the window is enforced by
        // the supervision, and a CreateSMContext that does complete late is
        // released rather than lost. The SBI client's own timeout bounds it.
        self.sbi_offload
            .spawn_keyed((amf_ue_ngap_id, psi), move || async move {
                let smf = crate::sbi_path::resolve_nf_endpoint_async(
                    crate::sbi_path::SbiServiceType::NsmfPdusession,
                )
                .await
                .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));
                let result = crate::sbi_path::call_smf_create_sm_context(
                    &smf.0,
                    smf.1,
                    psi,
                    sst,
                    sd,
                    dnn.as_deref(),
                    &sm_pdu,
                    redcap_indication,
                    &identity,
                )
                .await;
                Some(crate::sbi_offload::SbiOutcome::Establishment(
                    EstablishmentAttempt {
                        amf_ue_ngap_id,
                        psi,
                        generation,
                        sst,
                        sd,
                        dnn,
                        smf,
                        result,
                    },
                ))
            });
    }

    /// Apply every outcome the off-task SBI work produced, on the NGAP task.
    async fn process_sbi_outcomes(&mut self) {
        while let Some(outcome) = self.sbi_offload.try_recv() {
            match outcome {
                crate::sbi_offload::SbiOutcome::N2Handover(answer) => {
                    if let Err(e) = self.apply_n2_handover_answer(answer).await {
                        log::warn!("N2 handover SMF answer not applied: {e}");
                    }
                }
                crate::sbi_offload::SbiOutcome::Establishment(attempt) => {
                    if let Err(e) = self.apply_establishment_attempt(attempt).await {
                        log::warn!("Establishment retry outcome not applied: {e}");
                    }
                }
                crate::sbi_offload::SbiOutcome::MappingResponse { id, capability } => {
                    self.send_mapping_response(&id, capability).await
                }
            }
        }
    }

    /// One re-selection attempt came back (#796).
    async fn apply_establishment_attempt(&mut self, a: EstablishmentAttempt) -> Result<()> {
        let key = (a.amf_ue_ngap_id, a.psi);
        let waiting = self
            .pending_establishments
            .get(&key)
            .filter(|p| p.generation == a.generation)
            .cloned();
        let connection = self
            .ue_auth_state
            .get(a.amf_ue_ngap_id)
            .filter(|s| !s.is_cm_idle())
            .map(|s| (s.association_id, s.ran_ue_ngap_id));
        match (a.result, waiting, connection) {
            (Ok(resp), Some(p), Some((association_id, ran_ue_ngap_id))) => {
                self.apply_sm_context_created(
                    association_id,
                    a.amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    a.psi,
                    a.sst,
                    a.sd,
                    a.dnn.as_deref(),
                    &p.sm_pdu,
                    resp,
                )
                .await
            }
            (Ok(resp), _, _) => {
                // The UE was answered #90, went away or went idle meanwhile: nobody
                // will use this context, so it is released rather than leaked.
                log::info!(
                    "UE {}: SM context {} for PSI={} created after the establishment was \
                     abandoned; releasing it",
                    a.amf_ue_ngap_id,
                    resp.sm_context_ref,
                    a.psi
                );
                let (host, port) = resp
                    .smf_authority
                    .as_deref()
                    .and_then(split_authority)
                    .unwrap_or(a.smf);
                let sm_ref = resp.sm_context_ref;
                // Keyed on the session, so it reaches the SMF before any later
                // CreateSMContext for the same PSI.
                // Durable: a later supersede for this PSI, or the UE leaving, must
                // not drop it, or the context leaks at the SMF.
                self.sbi_offload
                    .spawn_keyed_durable(key, move || async move {
                        if let Err(e) =
                            crate::sbi_path::call_smf_release_sm_context(&host, port, &sm_ref).await
                        {
                            log::warn!("Release of abandoned SM context {sm_ref} failed: {e}");
                        }
                        None
                    });
                Ok(())
            }
            (Err(_), None, _) => Ok(()),
            (Err(_), Some(_), None) => {
                self.pending_establishments.remove(&key);
                Ok(())
            }
            (Err(e), Some(p), Some((association_id, ran_ue_ngap_id))) => {
                if smf_unreachable(&e) {
                    if let Some(w) = self.pending_establishments.get_mut(&key) {
                        w.in_flight = false;
                        w.next_attempt = std::time::Instant::now() + ESTABLISHMENT_RETRY_INTERVAL;
                    }
                    log::warn!(
                        "UE {}: establishment retry PSI={} reached no SMF ({e})",
                        a.amf_ue_ngap_id,
                        a.psi
                    );
                    return Ok(());
                }
                // An SMF answered and refused: as for a first attempt, 5GSM #26.
                self.pending_establishments.remove(&key);
                log::warn!(
                    "SMF SM Context Create failed ({e}); rejecting PSI={}",
                    a.psi
                );
                let pti = p.sm_pdu.get(2).copied().unwrap_or(0);
                let reject = vec![0x2E, a.psi, pti, 0xC3, 0x1A];
                self.send_n1_sm_to_ue(
                    association_id,
                    a.amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    a.psi,
                    &reject,
                )
                .await
            }
        }
    }

    async fn process_network_deregs(&mut self) {
        let ctx = crate::context::amf_self();
        let pending = {
            let Ok(guard) = ctx.read() else {
                return;
            };
            guard.network_dereg_drain()
        };
        for item in pending {
            if item.local {
                if let Err(e) = self.local_deregistration(item.amf_ue_ngap_id).await {
                    log::warn!(
                        "Local deregistration for UE {} failed: {e}",
                        item.amf_ue_ngap_id
                    );
                }
                continue;
            }
            let gmm_cause = item.gmm_cause.map(GmmCause::from);
            if let Err(e) = self
                .send_network_initiated_deregistration(
                    item.amf_ue_ngap_id,
                    item.reregistration_required,
                    gmm_cause,
                )
                .await
            {
                log::warn!(
                    "Network-initiated deregistration for UE {} failed: {e}",
                    item.amf_ue_ngap_id
                );
            }
        }
    }

    /// Drain the PWS N2 relay queue the Namf `non-ue-n2-messages/transfer`
    /// handler populated and forward each warning container to the NG-RAN nodes
    /// the consumer targeted (#396, TS 29.518 §5.2.2.4.1.3, TS 38.413 §8.12).
    /// This is the (non-test) caller of [`Self::pws_target_associations`].
    ///
    /// The container is sent **verbatim**: `pwsContainer` is a transparent
    /// `N2InfoContent` and §5.2.2.4.1.3 has the AMF *forward* it
    /// (`6g_docs/specs/29518-k00.txt:4152`). This pump decodes only far enough to
    /// log which PWS procedure it is relaying — it never re-encodes, because a
    /// decode/re-encode round trip through a partial model would drop any IE the
    /// CBCF sent that this build does not know about.
    async fn process_pws_n2_transfers(&mut self) {
        let ctx = crate::context::amf_self();
        let pending = {
            let Ok(guard) = ctx.read() else {
                return;
            };
            guard.pws_n2_drain()
        };
        for item in pending {
            let targets = self.pws_target_associations(&item).await;
            if targets.is_empty() {
                // Fail-loud rather than silently succeeding: a warning message
                // that reached no RAN node did not go out, and an operator must
                // be able to see that from the AMF's own logs. The SBI response
                // was already written by the time we get here (the 200 reports
                // that the AMF *initiated* the transfer, per §5.2.2.4.1.3 step
                // 2a), so this is the only place the fact can surface.
                log::warn!(
                    "PWS relay: warning message_identifier={:#06x} serial_number={:#06x} \
                     matched NO connected NG-RAN node (targets: {} gNB IDs, {} TAIs, rat={:?}); \
                     nothing was broadcast",
                    item.message_identifier,
                    item.serial_number,
                    item.target_gnb_ids.len(),
                    item.target_tais.len(),
                    item.rat_selector,
                );
                continue;
            }

            // data[1] is the procedure code (data[0] is the PDU-type CHOICE
            // index); logged so an operator can tell a WriteReplaceWarning (51)
            // relay from a PWSCancel (32) one without decoding the PDU.
            let procedure_code = item.ngap_pdu.get(1).copied().unwrap_or(0);
            let mut delivered = 0usize;
            for association_id in targets {
                match self
                    .send_to_association(association_id, &item.ngap_pdu)
                    .await
                {
                    Ok(()) => delivered += 1,
                    Err(e) => log::warn!("PWS relay to association {association_id} failed: {e}"),
                }
            }
            log::info!(
                "PWS relay: NGAP procedure {procedure_code} ({} B) forwarded to {delivered} \
                 NG-RAN node(s) (message_identifier={:#06x} serial_number={:#06x})",
                item.ngap_pdu.len(),
                item.message_identifier,
                item.serial_number,
            );
        }
    }

    /// Drain the non-UE-associated NRPPa relays (#807) and send each as a
    /// DOWNLINK NON UE ASSOCIATED NRPPA TRANSPORT (TS 38.413 §8.15.4) to the
    /// connected gNBs named in `globalRanNodeList`, with the LMF's nfId as the
    /// Routing ID. Resolved against the live sessions, like the PWS relay.
    pub(crate) async fn process_non_ue_nrppa_transfers(&mut self) {
        let pending = {
            let ctx = crate::context::amf_self();
            let Ok(guard) = ctx.read() else {
                return;
            };
            guard.non_ue_nrppa_drain()
        };
        for item in pending {
            let Some(pdu) = crate::positioning::build_nrppa_dl_non_ue_associated(
                &item.routing_id,
                &item.nrppa_pdu,
            ) else {
                log::warn!(
                    "Non-UE NRPPa relay: DOWNLINK NON UE ASSOCIATED NRPPA TRANSPORT encode failed"
                );
                continue;
            };
            let targets: Vec<(u32, u64)> = {
                let sessions = self.sessions.read().await;
                sessions
                    .values()
                    .filter(|s| item.target_gnb_ids.contains(&s.gnb.gnb_id))
                    .map(|s| (s.gnb.gnb_id, s.association_id))
                    .collect()
            };
            for gnb in &item.target_gnb_ids {
                if !targets.iter().any(|(g, _)| g == gnb) {
                    log::warn!(
                        "Non-UE NRPPa relay: gNB {gnb:#x} is not connected; the NRPPa PDU \
                         ({} B) was not delivered to it",
                        item.nrppa_pdu.len()
                    );
                }
            }
            for (gnb, association_id) in targets {
                match self.send_to_association(association_id, &pdu).await {
                    Ok(()) => log::info!(
                        "Non-UE NRPPa relay: {} B to gNB {gnb:#x} (association {association_id})",
                        item.nrppa_pdu.len()
                    ),
                    Err(e) => log::warn!("Non-UE NRPPa relay to gNB {gnb:#x} failed: {e}"),
                }
            }
        }
    }

    /// Resolve the SCTP associations a PWS transfer targets, applying the IE
    /// precedence of TS 29.518 §5.2.2.4.1.3 (`29518-k00.txt:4152-4159`):
    ///
    /// 1. `globalRanNodeList` present -> exactly those RAN nodes;
    /// 2. else `taiList` present -> nodes serving any listed TAI, filtered by
    ///    `ratSelector`;
    /// 3. else -> all attached nodes, filtered by `ratSelector`.
    ///
    /// Resolved HERE, against the live `sessions` map, and not in the SBI
    /// handler: `AmfContext::gnb_list` has no production writer, so resolving
    /// there would match nothing. Returns association IDs (not `&GnbSession`) so
    /// the read guard is dropped before the `&mut self` sends.
    async fn pws_target_associations(
        &self,
        item: &crate::context::PendingPwsN2Transfer,
    ) -> Vec<u64> {
        use crate::context::PwsRatSelector;

        let sessions = self.sessions.read().await;
        sessions
            .values()
            .filter(|session| {
                // The RAT filter applies to cases 2 and 3. It does NOT apply
                // when globalRanNodeList named the nodes explicitly: the spec
                // subordinates the filter to the absence of that IE ("subject to
                // the value of the ratSelector IE" appears only in the
                // globalRanNodeList-absent sentences), and the NOTE at
                // `29518-k00.txt:4160` says the list "only contains RAN nodes of
                // the same type" anyway.
                if !item.target_gnb_ids.is_empty() {
                    return item.target_gnb_ids.contains(&session.gnb.gnb_id);
                }

                if let Some(rat) = item.rat_selector {
                    let matches_rat = match rat {
                        PwsRatSelector::Nr => session.gnb.rat_type == crate::context::RatType::Nr,
                        PwsRatSelector::Eutra => {
                            session.gnb.rat_type == crate::context::RatType::Eutra
                        }
                    };
                    if !matches_rat {
                        return false;
                    }
                }

                if item.target_tais.is_empty() {
                    // Case 3: all attached nodes of the selected RAT.
                    return true;
                }

                // Case 2: the node serves at least one listed TAI. A gNB's
                // SupportedTAList carries a TAC plus the broadcast PLMNs for it
                // (TS 38.413 §9.3.3.8), so a TAI matches when both halves do.
                item.target_tais.iter().any(|(plmn, tac)| {
                    session.gnb.supported_ta_list.iter().any(|ta| {
                        ta.tac == *tac && ta.bplmn_list.iter().any(|bplmn| bplmn.plmn_id == *plmn)
                    })
                })
            })
            .map(|session| session.association_id)
            .collect()
    }

    /// Handle a WRITE-REPLACE WARNING RESPONSE (procedure 51) or PWS CANCEL
    /// RESPONSE (32) from an NG-RAN node and, if the consumer asked to be told,
    /// deliver it as a NonUeN2InfoNotify (#399, TS 29.518 §5.2.2.4.4.3 item 1).
    ///
    /// Three facts have to line up before anything is sent, and each failure is
    /// logged distinctly, because "nothing happened" is the failure mode that
    /// hides in a notification path:
    ///
    /// 1. the originating transfer set `sendRanResponse: true` — §5.2.2.4.4.3
    ///    conditions the response notification on the request having asked for it
    ///    ("If the Send-Write-Replace-Warning Indication IE was present ... then
    ///    the AMF may forward the Broadcast Completed Area List IE(s)",
    ///    `29518-k00.txt:4465-4468`), and the RESPONSE PDU carries no trace of
    ///    that ask, so it is matched by `(messageIdentifier, serialNumber)` —
    ///    the identity §6.1.6.4.3.3 itself uses (`:19073`);
    /// 2. a `PWS-BCAL` (or umbrella `PWS`) subscription exists, for the same
    ///    `nfId` when the transfer named one;
    /// 3. the association still maps to a known gNB — the responding node's
    ///    identity can ONLY come from there, because neither response carries a
    ///    Global RAN Node ID IE (`38413-j30.txt:15916-15939`, `:15968-15993`).
    ///
    /// Read from the live `sessions` map, never from `AmfContext::gnb_list`: that
    /// collection has no production writer, so anything keyed off it would match a
    /// permanently empty map and look correct while never firing.
    async fn handle_pws_response(
        &mut self,
        association_id: u64,
        procedure_code: Option<u16>,
        data: &[u8],
    ) -> Result<()> {
        // Decoded so the identifiers can be lifted into `pwsInfo` and so the
        // presence of the area list is known (it drives `bcEmptyAreaList`). The
        // PDU itself is still forwarded verbatim — this is a read, not a
        // re-encode. A response is a class-1 outcome: a "reject" IE or a
        // missing identifier is local error handling, a "notify" IE is reported
        // in an Error Indication (TS 38.413 §10.3.4.2).
        let resp = match crate::ngap_asn1::decode_pws_response_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Some(ei) =
                        crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                    {
                        self.send_to_association(association_id, &ei).await?;
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!(
                    "PWS response (procedure {procedure_code:?}) from association \
                     {association_id} rejected, dropped: {report:?}"
                );
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(
                        association_id,
                        &format!("PWS response (procedure {procedure_code:?})"),
                    )
                    .await;
            }
        };
        let (message_identifier, serial_number, has_area_list) = (
            resp.message_identifier,
            resp.serial_number,
            resp.has_area_list,
        );

        let (request, subscription) = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            let request = guard.pws_response_request_get(message_identifier, serial_number);
            // Fail-closed on (1): with no record the consumer either never asked
            // for the response or this is a warning the AMF did not relay, and
            // either way notifying would be inventing a recipient.
            let Some(request) = request else {
                log::info!(
                    "PWS response (procedure {procedure_code:?}) from association \
                     {association_id} for messageIdentifier={message_identifier:#06x} \
                     serialNumber={serial_number:#06x}: no sendRanResponse request recorded, \
                     nothing to notify (TS 29.518 §5.2.2.4.4.3)"
                );
                return Ok(());
            };
            let subscription =
                guard.non_ue_n2_subscription_find_by_class("PWS-BCAL", request.nf_id.as_deref());
            (request, subscription)
        };

        // Fail-closed on (2). This is also the condition the transfer's
        // `n2PwsSubMissInd: true` warned the consumer about, so reaching here means
        // the consumer was told and did not act.
        let Some(sub) = subscription else {
            log::warn!(
                "PWS response from association {association_id} \
                 (messageIdentifier={message_identifier:#06x}) has no PWS-BCAL/PWS \
                 subscription for nfId {:?}; dropped (the transfer's 200 already carried \
                 n2PwsSubMissInd:true)",
                request.nf_id
            );
            return Ok(());
        };

        // Fail-closed on (3), from the live session map.
        let Some((plmn, gnb_id, gnb_id_len)) =
            self.sessions
                .read()
                .await
                .get(&association_id)
                .map(|session| {
                    (
                        session.gnb.plmn_id.clone(),
                        session.gnb.gnb_id,
                        session.gnb.gnb_id_len,
                    )
                })
        else {
            log::warn!(
                "PWS response from association {association_id} has no session; cannot identify \
                 the responding NG-RAN node, dropped"
            );
            return Ok(());
        };
        let ran_node_id = crate::namf_server::global_ran_node_id_json(&plmn, gnb_id, gnb_id_len);

        log::info!(
            "PWS: notifying consumer of a procedure-{} response from gNB {gnb_id:#x} \
             (messageIdentifier={message_identifier:#06x} serialNumber={serial_number:#06x}, \
             area list {}, sub={})",
            procedure_code.unwrap_or(0),
            if has_area_list {
                "present"
            } else {
                "ABSENT -> bcEmptyAreaList"
            },
            sub.subscription_id,
        );
        crate::namf_server::send_non_ue_n2_info_notify(
            sub.n2_notify_callback_uri,
            sub.subscription_id,
            sub.n2_information_class,
            message_identifier,
            serial_number,
            ran_node_id,
            // "If the NG-RAN node(s) have responded WITHOUT the Broadcast
            // Completed Area List IE then the AMF SHALL include the NG-RAN node
            // ID(s) in "bcEmptyAreaList"" (`29518-k00.txt:4468-4471`) — a "shall",
            // unlike the aggregation "may" this path declines.
            !has_area_list,
            request.nf_id,
            sub.notif_correlation_id,
            data.to_vec(),
        );
        Ok(())
    }

    /// Handle a PWS RESTART INDICATION (procedure 34) or PWS FAILURE INDICATION
    /// (33) from an NG-RAN node and forward it to a subscribed consumer (#399,
    /// TS 29.518 §5.2.2.4.4.3 item 2).
    ///
    /// Unlike a response this is **unconditional** on any prior request:
    /// §5.2.2.4.4.3 item 2 (`29518-k00.txt:4490-4493`) is a "shall" — "The AMF
    /// shall forward the Restart Indication or Failure Indication to the NF Service
    /// Consumer" — with no originating transfer to correlate to (the NG-RAN raises
    /// these on its own, e.g. after losing PWS state). So the only gate is a
    /// subscription existing, because without one there is nowhere to send it.
    ///
    /// The class is `PWS-RF`, not `PWS-BCAL` (Table 6.1.6.4.3.3-3,
    /// `29518-k00.txt:19108-19118`), and the node identity comes from the PDU's own
    /// mandatory Global RAN Node ID IE (`38413-j30.txt:16031`) rather than from the
    /// association — that is what the node said about itself.
    async fn handle_pws_indication(
        &mut self,
        association_id: u64,
        procedure_code: Option<u16>,
        data: &[u8],
    ) -> Result<()> {
        // A class-2 procedure with no response: a "reject" IE or a missing Global
        // RAN Node ID terminates it with an Error Indication, a "notify" IE is
        // reported in one (TS 38.413 §10.3.4.2, §10.3.5).
        let ind = match crate::ngap_asn1::decode_pws_indication_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Some(ei) =
                        crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                    {
                        self.send_to_association(association_id, &ei).await?;
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!(
                    "PWS indication (procedure {procedure_code:?}) from association \
                     {association_id} rejected: {report:?}"
                );
                if let Some(ei) = crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                {
                    self.send_to_association(association_id, &ei).await?;
                }
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(
                        association_id,
                        &format!("PWS indication (procedure {procedure_code:?})"),
                    )
                    .await;
            }
        };
        if ind.restart {
            log::info!(
                "PWS RESTART INDICATION from association {association_id}: {} TAI(s), {} \
                 emergency area ID(s) available for reload (TS 38.413 §8.12.3)",
                ind.tai_count,
                ind.emergency_area_count,
            );
        } else {
            log::warn!(
                "PWS FAILURE INDICATION from association {association_id}: PWS operation \
                 failed for cells (TS 38.413 §8.12.4)"
            );
        }
        let global_ran_node_id = ind.global_ran_node_id;

        // No `nfId` filter: there is no originating transfer to have named one, so
        // any PWS-RF/PWS subscriber is a legitimate recipient of a node-raised
        // indication.
        let subscription = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            guard.non_ue_n2_subscription_find_by_class("PWS-RF", None)
        };
        let Some(sub) = subscription else {
            log::warn!(
                "PWS indication (procedure {procedure_code:?}) from association \
                 {association_id} has no PWS-RF/PWS subscription; dropped (no ErrorIndication \
                 sent -- the indication is a class-2 procedure the AMF never answers)"
            );
            return Ok(());
        };

        let ran_node_id = match &global_ran_node_id {
            nextgcore_ngap::types::GlobalRanNodeId::GlobalGnbId {
                plmn_identity,
                gnb_id,
                gnb_id_len,
            } => crate::namf_server::global_ran_node_id_json(
                &crate::ngap_asn1::decode_plmn_id(plmn_identity),
                *gnb_id,
                *gnb_id_len,
            ),
            nextgcore_ngap::types::GlobalRanNodeId::GlobalNgEnbId {
                plmn_identity,
                ng_enb_id,
            } => {
                // TS 29.571 `NgeNbId` is a PREFIXED string, not a bare hex value:
                // `^(MacroNGeNB-[A-Fa-f0-9]{5}|LMacroNGeNB-[A-Fa-f0-9]{6}|SMacroNGeNB-[A-Fa-f0-9]{5})$`
                // (`TS29571_CommonData.yaml:1458`). TS 38.413 §9.3.1.8's macro form
                // is 20 bits = 5 nibbles, which is the `MacroNGeNB-` arm.
                let plmn = crate::ngap_asn1::decode_plmn_id(plmn_identity);
                serde_json::json!({
                    "plmnId": { "mcc": plmn.mcc(), "mnc": plmn.mnc() },
                    "ngeNbId": format!("MacroNGeNB-{ng_enb_id:05X}"),
                })
            }
        };

        // A PWS indication carries no Message Identifier / Serial Number: its IE
        // tables (`38413-j30.txt:15995`, `:16064`) are the cell list and the Global
        // RAN Node ID. `PwsInformation` requires both as mandatory members
        // (`yaml:3298-3300`), so 0/0 is sent — the identifiers for "not about one
        // specific warning", which is exactly what a node-wide restart or failure
        // is. The consumer reads the class and the container, per
        // `29518-k00.txt:19119-19121`: "The Message Type shall be present and
        // encoded as the first N2 PWS Indication IE ... to enable the receiver to
        // decode the N2 PWS IEs" — and the Message Type is in the container.
        log::info!(
            "PWS: forwarding a procedure-{} indication to consumer (sub={}, class={})",
            procedure_code.unwrap_or(0),
            sub.subscription_id,
            sub.n2_information_class,
        );
        crate::namf_server::send_non_ue_n2_info_notify(
            sub.n2_notify_callback_uri,
            sub.subscription_id,
            sub.n2_information_class,
            0,
            0,
            ran_node_id,
            // `bcEmptyAreaList` is about a RESPONSE that omitted its area list
            // (§5.2.2.4.4.3 item 1). An indication has no area list to omit, so
            // setting it here would assert something the spec never scopes to
            // this event.
            false,
            None,
            sub.notif_correlation_id,
            data.to_vec(),
        );
        Ok(())
    }

    async fn process_positioning_downlinks(&mut self) {
        let ctx = crate::context::amf_self();
        let pending = {
            let Ok(guard) = ctx.read() else {
                return;
            };
            guard.positioning_dl_drain()
        };
        for item in pending {
            // Resolve the serving association + RAN-UE-NGAP-ID (Copy values, so
            // the immutable borrow is released before the &mut send calls).
            let Some((association_id, ran_ue_ngap_id)) = self
                .ue_auth_state
                .get(item.amf_ue_ngap_id)
                .map(|s| (s.association_id, s.ran_ue_ngap_id))
            else {
                log::warn!(
                    "LCS positioning DL for UE {} dropped: no live NGAP context",
                    item.amf_ue_ngap_id
                );
                continue;
            };
            match item.kind {
                crate::context::PositioningDlKind::NrppaToGnb {
                    routing_id,
                    nrppa_pdu,
                } => {
                    let Some(pdu) = crate::positioning::build_nrppa_dl_ue_associated(
                        item.amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        &routing_id,
                        &nrppa_pdu,
                    ) else {
                        log::warn!(
                            "LCS positioning DL NRPPa build failed for UE {}",
                            item.amf_ue_ngap_id
                        );
                        continue;
                    };
                    match self.send_to_association(association_id, &pdu).await {
                        Ok(()) => log::info!(
                            "LCS: delivered NRPPa DL transport ({} B) to gNB for UE {}",
                            pdu.len(),
                            item.amf_ue_ngap_id
                        ),
                        Err(e) => log::warn!("LCS positioning DL NRPPa send failed: {e}"),
                    }
                }
                crate::context::PositioningDlKind::LppToUe { lpp_pdu } => {
                    let Some(plain) = crate::positioning::build_lpp_dl_nas(&lpp_pdu) else {
                        log::warn!(
                            "LCS positioning DL LPP build failed for UE {}",
                            item.amf_ue_ngap_id
                        );
                        continue;
                    };
                    // Protect with the UE's NAS security context where available
                    // (registered UE); fall back to plain for a legacy peer.
                    let nas = self
                        .protect_nas(item.amf_ue_ngap_id, &plain)
                        .unwrap_or(plain);
                    match self
                        .send_nas_pdu(association_id, item.amf_ue_ngap_id, ran_ue_ngap_id, &nas)
                        .await
                    {
                        Ok(_) => log::info!(
                            "LCS: delivered LPP DL NAS Transport to UE {}",
                            item.amf_ue_ngap_id
                        ),
                        Err(e) => log::warn!("LCS positioning DL LPP send failed: {e}"),
                    }
                }
                // Wave-6 E5: UPDP (UE policy) downlink — DL NAS Transport with
                // payload container type "UE policy container" (0x05), same
                // protect + send flow as the LPP leg (TS 24.501 §5.4.5).
                crate::context::PositioningDlKind::UePolicyToUe { updp_pdu } => {
                    let Some(plain) = crate::gmm_build::build_ue_policy_dl_nas(&updp_pdu) else {
                        log::warn!(
                            "UE policy DL NAS build failed for UE {}",
                            item.amf_ue_ngap_id
                        );
                        continue;
                    };
                    let nas = self
                        .protect_nas(item.amf_ue_ngap_id, &plain)
                        .unwrap_or(plain);
                    match self
                        .send_nas_pdu(association_id, item.amf_ue_ngap_id, ran_ue_ngap_id, &nas)
                        .await
                    {
                        Ok(_) => log::info!(
                            "UE policy: delivered UE policy DL NAS Transport to UE {}",
                            item.amf_ue_ngap_id
                        ),
                        Err(e) => log::warn!("UE policy DL NAS send failed: {e}"),
                    }
                }
            }
        }
    }

    /// Handle an UplinkUEAssociatedNRPPaTransport (TS 38.413 Section 8.15.3,
    /// NGAP procedure 50): the gNB→AMF uplink leg of the LCS NRPPa relay
    /// (TS 23.273 Section 6.11).
    ///
    /// The NRPPa PDU is opaque to the AMF (transparent relay): it is forwarded
    /// **verbatim** to the LMF that registered an `n2InformationClass ==
    /// "NRPPa"` callback for this UE via Namf N1N2MessageSubscribe, as a
    /// multipart Namf N2InfoNotify POST (TS 29.518 Section 5.2.2.3.3). The
    /// notification's `lcsCorrelationId` comes from the subscription, falling
    /// back to the correlation captured from the originating
    /// N1N2MessageTransfer; the `nrppaInfo.nfId` is recovered from the NGAP
    /// RoutingID echo (our downlink seeds the RoutingID from the LMF's nfId).
    ///
    /// Fail-closed: with no registered consumer the PDU is dropped with a
    /// WARN and counted in [`UL_NRPPA_DROPPED_NO_CONSUMER`] — a relay with no
    /// consumer must not invent NGAP errors toward the gNB, so this path
    /// never sends an ErrorIndication (the pre-A1 `_` dispatch arm actively
    /// broke the procedure by replying AbstractSyntaxErrorReject).
    async fn handle_uplink_ue_associated_nrppa_transport(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        let ul = match crate::ngap_asn1::decode_uplink_nrppa_transport_asn1(data, true) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Some(ei) =
                        crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                    {
                        self.send_to_association(association_id, &ei).await?;
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!("Uplink UE-associated NRPPa transport from association {association_id} rejected: {report:?}");
                if let Some(ei) = crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                {
                    self.send_to_association(association_id, &ei).await?;
                }
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(
                        association_id,
                        "Uplink UE-associated NRPPa Transport",
                    )
                    .await;
            }
        };
        let Some(amf_ue_ngap_id) = ul.amf_ue_ngap_id else {
            return Ok(());
        };

        // Resolve the UE's ueContextId (SUPI) — the key of the N1N2
        // subscription registry (TS 29.518 Section 6.1.3.2.2): the NGAP
        // server's own per-UE state first, the shared AMF context as fallback.
        let supi = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .and_then(|s| s.amf_ue.supi.clone())
            .or_else(|| {
                crate::context::amf_self()
                    .read()
                    .ok()
                    .and_then(|guard| guard.amf_ue_find_by_id(amf_ue_ngap_id))
                    .and_then(|ue| ue.supi.clone())
            });

        // A3 registry lookup (exact-class, fail-closed) + fallback LCS
        // correlation captured from the originating N1N2MessageTransfer.
        let (sub, fallback_corr) = {
            let ctx = crate::context::amf_self();
            let Ok(guard) = ctx.read() else {
                return Ok(());
            };
            match supi.as_deref() {
                Some(s) => (
                    guard.n1n2_subscription_find_n2(s, "NRPPa"),
                    guard.lcs_correlation_find(s),
                ),
                None => (None, None),
            }
        };
        let Some(callback_uri) = sub.as_ref().and_then(|s| s.n2_notify_callback_uri.clone()) else {
            UL_NRPPA_DROPPED_NO_CONSUMER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            log::warn!(
                "Uplink UE-associated NRPPa (association {association_id}, \
                 amf_ue_ngap_id {amf_ue_ngap_id}, supi {supi:?}) dropped: no \
                 LMF N2 'NRPPa' subscription registered (no ErrorIndication \
                 sent — transparent relay, TS 23.273 Section 6.11)"
            );
            return Ok(());
        };
        let sub = sub.expect("callback_uri implies subscription");

        let lcs_correlation_id = sub
            .lcs_correlation_id
            .clone()
            .or_else(|| fallback_corr.map(|r| r.lcs_correlation_id));
        // The RoutingID is the opaque LMF identity echo (seeded from
        // nrppaInfo.nfId on the downlink leg); recover it as nfId when it is
        // printable, never fabricate one.
        let nf_id = String::from_utf8(ul.routing_id.clone())
            .ok()
            .filter(|s| !s.is_empty());

        log::info!(
            "LCS: relaying uplink UE-associated NRPPa ({} B, amf_ue_ngap_id \
             {amf_ue_ngap_id}) to LMF callback {callback_uri} (sub={})",
            ul.nrppa_pdu.len(),
            sub.subscription_id,
            callback_uri = nextgcore_sbi::log_redact::redact_last_segment(&callback_uri)
        );
        crate::namf_server::send_n2_info_notify(
            callback_uri,
            sub.subscription_id,
            lcs_correlation_id,
            nf_id,
            ul.nrppa_pdu,
        );
        Ok(())
    }

    /// Handle an UplinkNonUEAssociatedNRPPaTransport (TS 38.413 Section
    /// 8.15.5, NGAP procedure 47): the non-UE-associated uplink NRPPa leg
    /// (TRP information / assistance data, TS 23.273 Section 6.11).
    ///
    /// Same transparent-relay producer as the UE-associated arm but with no
    /// UE resolution — the procedure carries no UE identity, only the opaque
    /// RoutingID echo, so the consumer is resolved from the N1N2 subscription
    /// registry alone (any UE's `n2InformationClass == "NRPPa"` subscription;
    /// deterministic tie-break + WARN on ambiguity). Fail-closed drop with a
    /// WARN + [`UL_NRPPA_DROPPED_NO_CONSUMER`] when no LMF is registered;
    /// never an ErrorIndication.
    async fn handle_uplink_non_ue_associated_nrppa_transport(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        let ul = match crate::ngap_asn1::decode_uplink_nrppa_transport_asn1(data, false) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Some(ei) =
                        crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                    {
                        self.send_to_association(association_id, &ei).await?;
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!("Uplink non-UE-associated NRPPa transport from association {association_id} rejected: {report:?}");
                if let Some(ei) = crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                {
                    self.send_to_association(association_id, &ei).await?;
                }
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(
                        association_id,
                        "Uplink non-UE-associated NRPPa Transport",
                    )
                    .await;
            }
        };

        let nf_id = String::from_utf8(ul.routing_id.clone())
            .ok()
            .filter(|s| !s.is_empty());

        // #807, TS 29.518 §5.2.2.4.4.2: the answer goes to the LMF the Routing ID
        // names, through its non-UE NRPPa subscription, with the responding node's
        // identity. Only without one does the any-UE N1N2 fallback below apply.
        let non_ue = {
            let ctx = crate::context::amf_self();
            let Ok(guard) = ctx.read() else {
                return Ok(());
            };
            guard.non_ue_nrppa_subscription_find(nf_id.as_deref())
        };
        if let Some(sub) = non_ue {
            let ran_node_id = self.sessions.read().await.get(&association_id).map(|s| {
                crate::namf_server::global_ran_node_id_json(
                    &s.gnb.plmn_id,
                    s.gnb.gnb_id,
                    s.gnb.gnb_id_len,
                )
            });
            log::info!(
                "LCS: relaying uplink non-UE-associated NRPPa ({} B) to LMF {nf_id:?} via \
                 non-UE subscription {}",
                ul.nrppa_pdu.len(),
                sub.subscription_id
            );
            crate::namf_server::send_non_ue_nrppa_info_notify(
                sub.n2_notify_callback_uri,
                sub.subscription_id,
                nf_id,
                ran_node_id,
                ul.nrppa_pdu,
            );
            return Ok(());
        }

        let sub = {
            let ctx = crate::context::amf_self();
            let Ok(guard) = ctx.read() else {
                return Ok(());
            };
            guard.n1n2_subscription_find_any_n2("NRPPa")
        };
        let Some(callback_uri) = sub.as_ref().and_then(|s| s.n2_notify_callback_uri.clone()) else {
            UL_NRPPA_DROPPED_NO_CONSUMER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            log::warn!(
                "Uplink non-UE-associated NRPPa (association {association_id}) \
                 dropped: no LMF N2 'NRPPa' subscription registered (no \
                 ErrorIndication sent — transparent relay)"
            );
            return Ok(());
        };
        let sub = sub.expect("callback_uri implies subscription");

        log::info!(
            "LCS: relaying uplink non-UE-associated NRPPa ({} B) to LMF \
             callback {callback_uri} (sub={})",
            ul.nrppa_pdu.len(),
            sub.subscription_id,
            callback_uri = nextgcore_sbi::log_redact::redact_last_segment(&callback_uri)
        );
        crate::namf_server::send_n2_info_notify(
            callback_uri,
            sub.subscription_id,
            sub.lcs_correlation_id,
            nf_id,
            ul.nrppa_pdu,
        );
        Ok(())
    }

    /// Protect a plain inner NAS message with the UE's security context
    /// (integrity protected + ciphered). Returns None without a context.
    fn protect_nas(&mut self, amf_ue_ngap_id: u64, plain: &[u8]) -> Option<Vec<u8>> {
        // `with_mut`, NOT get-a-clone-and-mutate-it: `nas_5gs_security_encode`
        // INCREMENTS the downlink NAS COUNT, and that increment has to persist. A
        // mutation dropped with a clone would protect every downlink message with
        // the same COUNT, which TS 33.501 §6.4.3.1 forbids precisely because it
        // makes the keystream reusable. Nothing in the closure `.await`s, so the
        // write lock is held only across the encode itself.
        self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            if !state.amf_ue.security_context_available {
                return None;
            }
            nas_security::nas_5gs_security_encode(
                &mut state.amf_ue,
                plain,
                security_header::INTEGRITY_PROTECTED_AND_CIPHERED,
            )
        })?
    }

    /// Build a Downlink NAS Transport NGAP PDU and send it.
    /// Returns the NGAP PDU bytes for retransmission arming.
    async fn send_nas_pdu(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
    ) -> Result<Vec<u8>> {
        let pdu = crate::ngap_asn1::build_downlink_nas_transport_asn1(
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            nas,
        )
        .ok_or_else(|| anyhow::anyhow!("Failed to build Downlink NAS Transport"))?;
        self.send_to_association(association_id, &pdu).await?;
        Ok(pdu)
    }

    /// Arm a GMM procedure retransmission timer for a UE
    fn arm_retx(&mut self, amf_ue_ngap_id: u64, timer: NasProcTimer, ngap_pdu: Vec<u8>) {
        let (_max, duration) = timer.config(&self.timer_configs);
        #[cfg(feature = "ntn")]
        let duration = timer.ntn_compensated(
            &self.timer_configs,
            duration,
            self.ue_auth_state
                .get(amf_ue_ngap_id)
                .and_then(|s| s.amf_ue.ntn_timing_advance),
        );
        self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            state.retx = Some(NasRetx {
                timer,
                deadline: Instant::now() + duration,
                retries: 0,
                ngap_pdu,
            });
        });
    }

    /// The T3346 back-off to impose, or `None` when the AMF is not congested.
    ///
    /// Reads the registered-UE count from the global context rather than from
    /// `ue_auth_state`: the context is the authoritative registry, and a UE mid-
    /// registration is not yet load the way a registered one is.
    fn nas_congestion_backoff(&self) -> Option<u64> {
        let registered = crate::context::amf_self()
            .read()
            .map(|ctx| ctx.amf_ue_count())
            .unwrap_or(0);
        if crate::congestion::is_active(registered) {
            Some(crate::congestion::backoff_secs())
        } else {
            None
        }
    }

    /// Keep the NGAP overload signal in step with the NAS congestion posture
    /// (TS 38.413 §8.7.6/§8.7.7).
    ///
    /// Sent only on a TRANSITION, so a sustained overload does not re-broadcast Overload
    /// Start to every gNB on every poll. This also gives `send_overload_start` /
    /// `send_overload_stop` their first production caller: both were `pub async fn` with
    /// no callers at all, so the AMF could declare NAS congestion to a UE while telling
    /// the RAN nothing.
    async fn sync_ngap_overload(&mut self) -> Result<()> {
        let registered = crate::context::amf_self()
            .read()
            .map(|ctx| ctx.amf_ue_count())
            .unwrap_or(0);
        let congested = crate::congestion::is_active(registered);
        if congested == self.ngap_overload_declared {
            return Ok(());
        }
        self.ngap_overload_declared = congested;
        if congested {
            let reduce = crate::congestion::ngap_reduce_percent();
            log::warn!(
                "NAS congestion entered ({registered} registered UEs): broadcasting NGAP \
                 Overload Start, asking for a {reduce}% reduction"
            );
            self.send_overload_start(reduce).await
        } else {
            log::info!("NAS congestion cleared: broadcasting NGAP Overload Stop");
            self.send_overload_stop().await
        }
    }

    /// Handle a UE Context Release Complete from a gNB (TS 38.413 §8.3.3.2).
    ///
    /// Decoded with the generated codec (#417 stage 4), which applies the §10.3.4.2
    /// rules for a RESPONSE: a not-comprehended "ignore IE and notify sender" IE is
    /// reported in an Error Indication and the procedure goes on; one marked "reject"
    /// terminates the procedure unsuccessfully, handled locally -- the same fallback
    /// an undecodable Release Complete gets.
    async fn handle_ue_context_release_complete(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        use crate::ngap_asn1::UeContextReleaseCompleteDecode::{Complete, Failed, Undecodable};
        let (amf_ue_ngap_id, ran_ue_ngap_id) =
            match crate::ngap_asn1::decode_ue_context_release_complete_asn1(data) {
                Complete {
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    error_indication,
                } => {
                    // Best effort: the report must not stop the supervision below.
                    if let Some(report) = error_indication {
                        if let Err(e) = self
                            .send_criticality_error_indication(association_id, &report)
                            .await
                        {
                            log::warn!("Failed to send ErrorIndication: {e}");
                        }
                    }
                    (amf_ue_ngap_id, ran_ue_ngap_id)
                }
                Failed(diagnostics) => {
                    log::warn!(
                        "UE Context Release Complete carries not-comprehended IEs marked reject \
                     ({diagnostics:?}); the release is unsuccessfully terminated (TS 38.413 \
                     §10.3.4.2), handled locally"
                    );
                    (None, None)
                }
                // #999, TS 38.413 §10.2; then the same local handling as any
                // Release Complete that names no usable UE (#802).
                Undecodable => {
                    self.report_transfer_syntax_error(
                        association_id,
                        "UE Context Release Complete",
                    )
                    .await?;
                    (None, None)
                }
            };
        // #758: the released NG connection's contextless allocation goes with it, so
        // the gNB cannot later mint a context under the released ID.
        if let Some(id) = amf_ue_ngap_id {
            self.contextless_ue_ids
                .retain(|c| !(c.association_id == association_id && c.amf_ue_ngap_id == id));
        }
        // The N1 signalling connection is gone: a registered UE is now CM-IDLE, which
        // is what makes a later N1N2 transfer page it (#512). Marked whether or not
        // the mobile reachable timer below is enabled.
        //
        // #738: only when the released NG connection is the one SERVING the UE. After
        // an N2 handover `handle_handover_notify` has moved the UE to the target and
        // released the source with a successful-handover Release Command carrying the
        // same AMF UE NGAP ID; the source's Release Complete ends that old leg only
        // (TS 23.502 §4.9.1.3.3 step 14a, the release of the S-RAN's resources; TS 38.413
        // §8.3.3.2, the Complete ends THAT UE-associated logical NG-connection). Applying
        // it to the UE
        // marked a connected UE idle, deactivated its user plane and armed the mobile
        // reachable timer. The check and the idle marking share one store access, so
        // nothing can move the UE between them.
        if let Some(id) = amf_ue_ngap_id {
            let leg = self.ue_auth_state.with_mut(id, |s| {
                let serving = (s.association_id, s.ran_ue_ngap_id);
                // The RAN UE NGAP ID is mandatory but criticality ignore (§9.2.2.6):
                // when it was absent the association alone decides.
                if serving.0 != association_id || ran_ue_ngap_id.is_some_and(|ran| ran != serving.1)
                {
                    return Err(serving);
                }
                // Only the CONNECTED -> IDLE transition deactivates the user plane and
                // arms the timer: a duplicate Complete for a UE already idle must not
                // re-send DEACTIVATED or push the reachability deadline back.
                let went_idle = s.registered && !s.cm_idle;
                if s.registered {
                    s.cm_idle = true;
                }
                Ok((s.registered, went_idle))
            });
            let went_idle = match leg {
                Some(Err((serving_assoc, serving_ran))) => {
                    log::info!(
                        "UE Context Release Complete for UE {id} from association \
                         {association_id} (ran_ue_ngap_id={ran_ue_ngap_id:?}) ends a \
                         connection that no longer serves it (serving: association \
                         {serving_assoc}, ran_ue_ngap_id={serving_ran}); only that leg is \
                         released, the UE stays CM-CONNECTED"
                    );
                    return Ok(());
                }
                Some(Ok((true, false))) => {
                    log::debug!(
                        "Duplicate UE Context Release Complete for UE {id}: already CM-IDLE"
                    );
                    return Ok(());
                }
                Some(Ok((_, went_idle))) => went_idle,
                None => false,
            };
            // #540 / TS 23.502 §4.2.6 step 5: the AN release ends the user plane of
            // every PDU session the UE keeps, so the SMF has the UPF buffer
            // downlink data (and report it, which is what pages the UE) instead
            // of forwarding it to the released gNB F-TEID.
            if went_idle {
                self.deactivate_up_connections(id).await;
            }
        }
        // TS 24.501 §5.3.7: for a UE that is still REGISTERED this is the moment the
        // mobile reachable timer starts. A Complete that names no UE (undecodable, or
        // a not-comprehended reject IE handled locally, TS 38.413 §10.3.4.2) ended no
        // N1 connection this AMF can identify, so it arms nobody (#802 follow-up):
        // the association's other UEs are either CONNECTED, or idle since an earlier
        // release that already armed them, and re-arming those would extend their
        // supervision and send a false CM-CONNECTED -> CM-IDLE report each time.
        match amf_ue_ngap_id {
            Some(id) => self.start_reachability_supervision(id).await,
            None => log::warn!(
                "UE Context Release Complete on association {association_id} names no \
                 usable UE; no mobile reachable timer is started"
            ),
        }
        Ok(())
    }

    /// Nsmf_PDUSession_UpdateSMContext with `upCnxState: DEACTIVATED` for every
    /// PDU session of `amf_ue_ngap_id` (TS 23.502 §4.2.6 step 5, TS 29.502
    /// §5.2.2.3.2.2), once its AN release is complete (#540). Best effort: a
    /// failed deactivation is logged and the others still go.
    /// Run one of an NG Reset's SMF calls through the shared off-task SBI dispatch
    /// (#754). A DEACTIVATED is keyed by `(AMF UE NGAP ID, PSI)`: work for one session
    /// runs in order, a newer reset supersedes a queued older one, and a later activation
    /// settles it first (`settle_ng_reset_deactivation`). A release for an aborted
    /// de-registration is independent work: the UE is already forgotten.
    fn offload_ng_reset_smf_call(&mut self, call: NgResetSmfCall) {
        match call {
            NgResetSmfCall::Deactivate {
                amf_ue_ngap_id,
                psi,
                sm_ref,
                host,
                port,
            } => {
                let key = (amf_ue_ngap_id, psi);
                // A second reset before the first one's call ran: one is enough.
                self.sbi_offload.supersede_key(key);
                self.sbi_offload.spawn_keyed(key, move || async move {
                    match crate::sbi_path::call_smf_deactivate_up_connection(&host, port, &sm_ref)
                        .await
                    {
                        Ok(()) => log::info!(
                            "UE {amf_ue_ngap_id}: PSI {psi} user plane deactivated (NG Reset)"
                        ),
                        Err(e) => log::warn!(
                            "UE {amf_ue_ngap_id}: PSI {psi} user-plane deactivation after NG \
                             Reset failed: {e}"
                        ),
                    }
                    None
                });
            }
            NgResetSmfCall::Release {
                amf_ue_ngap_id,
                psi,
                sm_ref,
                host,
                port,
            } => self.sbi_offload.spawn(async move {
                match crate::sbi_path::call_smf_release_sm_context(&host, port, &sm_ref).await {
                    Ok(()) => log::info!(
                        "UE {amf_ue_ngap_id}: PSI {psi} released (de-registration aborted by \
                         NG Reset)"
                    ),
                    Err(e) => log::warn!(
                        "UE {amf_ue_ngap_id}: PSI {psi} release after NG Reset failed: {e}"
                    ),
                }
                None
            }),
        }
    }

    /// Before activating `(amf_ue_ngap_id, psi)` at the SMF: make sure an NG Reset's
    /// DEACTIVATED for it can no longer arrive afterwards (#754, review of #848). Queued
    /// work for the session is dropped; work already on the wire is waited for, bounded by
    /// the SBI client timeout and holding only this UE's procedure.
    async fn settle_ng_reset_deactivation(&mut self, amf_ue_ngap_id: u64, psi: u8) {
        let key = (amf_ue_ngap_id, psi);
        if self.sbi_offload.key_busy(key) {
            log::info!(
                "UE {amf_ue_ngap_id}: PSI {psi} re-activated while an NG Reset deactivation \
                 is pending; queued work is dropped and running work awaited first"
            );
            if !self
                .sbi_offload
                .settle_key(key, NG_RESET_SETTLE_MAX_WAIT)
                .await
            {
                // Still running: it stays ordered ahead of anything submitted for the key,
                // but an activation sent inline now could overtake it at the SMF.
                log::warn!(
                    "UE {amf_ue_ngap_id}: PSI {psi}: the NG Reset deactivation still runs after \
                     {NG_RESET_SETTLE_MAX_WAIT:?}; activating anyway"
                );
            }
        }
    }

    /// Every SM context of a UE as `(psi, smContextRef, SMF host, SMF port)`: the copy a
    /// task off the NGAP loop needs to address each session at the SMF that holds it.
    fn ue_sm_contexts(&self, amf_ue_ngap_id: u64) -> Vec<(u8, String, String, u16)> {
        self.sm_context_refs
            .iter()
            .filter(|((ue, _), _)| *ue == amf_ue_ngap_id)
            .map(|((_, psi), r)| {
                let (host, port) = self.smf_target_for(amf_ue_ngap_id, *psi);
                (*psi, r.clone(), host, port)
            })
            .collect()
    }

    async fn deactivate_up_connections(&mut self, amf_ue_ngap_id: u64) {
        let refs: Vec<(u8, String)> = self
            .sm_context_refs
            .iter()
            .filter(|((ue, _), _)| *ue == amf_ue_ngap_id)
            .map(|((_, psi), r)| (*psi, r.clone()))
            .collect();
        if refs.is_empty() {
            return;
        }
        for (psi, sm_ref) in refs {
            let (smf_host, smf_port) = self.smf_target_for(amf_ue_ngap_id, psi);
            match crate::sbi_path::call_smf_deactivate_up_connection(&smf_host, smf_port, &sm_ref)
                .await
            {
                Ok(()) => {
                    log::info!("UE {amf_ue_ngap_id}: PSI {psi} user plane deactivated (AN release)")
                }
                Err(e) => {
                    log::warn!("UE {amf_ue_ngap_id}: PSI {psi} user-plane deactivation failed: {e}")
                }
            }
        }
    }

    /// Start mobile-reachable supervision for a registered UE whose N1 connection was
    /// just released (TS 24.501 §5.3.7).
    async fn start_reachability_supervision(&mut self, amf_ue_ngap_id: u64) {
        let Some(config) = self.timer_configs.get(AmfTimerId::MobileReachable).cloned() else {
            return;
        };
        if !config.enabled {
            log::debug!("Mobile reachable timer disabled by configuration; not supervising");
            return;
        }
        let targets = [amf_ue_ngap_id];
        let deadline = Instant::now() + config.duration;
        for amf_ue_ngap_id in targets {
            // Await-free, so the arming happens under one lock acquisition: a
            // get-then-write-back would leave a window in which a release lands and
            // the timer is re-armed on a UE that no longer exists.
            let armed = self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
                if !state.registered {
                    // An unregistered UE has no context worth supervising; the
                    // release already disposed of it.
                    return false;
                }
                state.reachability = Some(Reachability {
                    phase: ReachabilityPhase::MobileReachable,
                    deadline,
                });
                true
            });
            if armed == Some(true) {
                log::info!(
                    "Mobile reachable timer started for UE {amf_ue_ngap_id} ({:?}) after N1 \
                     release (TS 24.501 §5.3.7)",
                    config.duration
                );
                // #74 criterion 5: CONNECTIVITY_STATE_REPORT for the
                // CM-CONNECTED -> CM-IDLE half. The N1 signalling connection is gone,
                // which is the "connection management state change" of TS 29.518 §6.2;
                // its counterpart (IDLE -> CONNECTED on a Service Request) fires from
                // `gmm_handler::handle_service_request`. Read from the record rather
                // than reconstructed, so the report carries the UE's real identities.
                if let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) {
                    crate::namf_server::fire_connectivity_state_report(&state.amf_ue, false);
                }
            }
        }
    }

    /// Advance the reachability timers: mobile reachable -> implicit deregistration ->
    /// implicit deregistration performed (TS 24.501 §5.3.7).
    ///
    /// Driven from the same poll as the retransmission timers, so there is one clock in
    /// this path rather than two that can disagree.
    async fn process_reachability_timers(&mut self) -> Result<()> {
        let now = Instant::now();
        let due: Vec<u64> = self
            .ue_auth_state
            .snapshot()
            .into_iter()
            .filter(|(_, s)| s.reachability.is_some_and(|r| r.deadline <= now))
            .map(|(id, _)| id)
            .collect();

        for amf_ue_ngap_id in due {
            let Some(reachability) = self
                .ue_auth_state
                .get(amf_ue_ngap_id)
                .and_then(|s| s.reachability)
            else {
                continue;
            };
            match reachability.phase {
                ReachabilityPhase::MobileReachable => {
                    // #74 criterion 5: LOSS_OF_CONNECTIVITY. TS 29.518 §6.2 names this
                    // trigger literally -- "Such condition is identified when Mobile
                    // Reachable timer expires in the AMF" -- and we are exactly there.
                    // Fired BEFORE the three branches below, because all three are
                    // reached by the SAME expiry: whether implicit deregistration is
                    // configured, disabled, or armed changes what the AMF does next, not
                    // whether the UE became unreachable. `MAX_DETECTION_TIME_EXPIRED` is
                    // the TS 29.518 `LossOfConnectivityReason` for a timer expiry
                    // (TS29518_Namf_EventExposure.yaml:1605-1614).
                    if let Some(state) = self.ue_auth_state.get(amf_ue_ngap_id) {
                        crate::namf_server::fire_loss_of_connectivity(
                            &state.amf_ue,
                            "MAX_DETECTION_TIME_EXPIRED",
                        );
                    }
                    let Some(config) = self
                        .timer_configs
                        .get(AmfTimerId::ImplicitDeregistration)
                        .cloned()
                    else {
                        // Every `reachability` write in this arm goes through
                        // `with_mut` so it PERSISTS. Mutating a clone and dropping
                        // it would leave the expired deadline in place, and this
                        // sweep would then fire on the same UE on every poll.
                        self.ue_auth_state
                            .with_mut(amf_ue_ngap_id, |s| s.reachability = None);
                        continue;
                    };
                    if !config.enabled {
                        // The operator asked for mobile-reachable supervision without
                        // implicit deregistration. Honoured literally: stop here rather
                        // than deregister, which is the thing they turned off.
                        log::info!(
                            "Mobile reachable timer expired for UE {amf_ue_ngap_id}; implicit \
                             deregistration is disabled, so the context is kept"
                        );
                        self.ue_auth_state
                            .with_mut(amf_ue_ngap_id, |s| s.reachability = None);
                        continue;
                    }
                    self.ue_auth_state.with_mut(amf_ue_ngap_id, |s| {
                        s.reachability = Some(Reachability {
                            phase: ReachabilityPhase::ImplicitDeregistration,
                            deadline: now + config.duration,
                        });
                    });
                    log::info!(
                        "Mobile reachable timer expired for UE {amf_ue_ngap_id}: implicit \
                         deregistration timer started ({:?})",
                        config.duration
                    );
                }
                ReachabilityPhase::ImplicitDeregistration => {
                    // TS 24.501 §5.3.7: implicitly deregister. No NAS message is sent --
                    // the UE is unreachable, which is why we are here.
                    log::warn!(
                        "Implicit deregistration timer expired for UE {amf_ue_ngap_id}: \
                         deregistering implicitly (TS 24.501 §5.3.7)"
                    );
                    // Cleared BEFORE the await: the release below yields, and a
                    // sweep that ran in between must not see this deadline still
                    // due and start a second implicit deregistration.
                    self.ue_auth_state
                        .with_mut(amf_ue_ngap_id, |s| s.reachability = None);
                    self.release_all_pdu_sessions(amf_ue_ngap_id).await;
                    // #622: an implicit deregistration is a deregistration, so the PCF's
                    // policy associations end with it (TS 23.502 §4.16.3.2). Before
                    // `forget_ue`, which drops the ids.
                    self.terminate_policy_associations(amf_ue_ngap_id);
                    // `forget_ue`, not a bare remove (#356): this path never reaches
                    // `release_ue` -- deliberately, since no NAS message can be sent to an
                    // unreachable UE -- so it is the third place an emergency context has
                    // to be freed.
                    self.forget_ue(amf_ue_ngap_id);
                    // The global context's RAN UE and AMF UE entries go too, or the
                    // implicit deregistration would free the NAS state and leave the NGAP
                    // one behind -- a UE that is deregistered and still occupies an id.
                    let handle = crate::context::amf_self();
                    let ids = handle
                        .read()
                        .ok()
                        .and_then(|ctx| ctx.ran_ue_find_by_amf_ue_ngap_id(amf_ue_ngap_id))
                        .map(|ran_ue| (ran_ue.id, ran_ue.amf_ue_id));
                    if let Some((ran_ue_id, amf_ue_id)) = ids {
                        if let Ok(ctx) = handle.read() {
                            ctx.ran_ue_remove(ran_ue_id);
                            ctx.amf_ue_remove(amf_ue_id);
                        }
                    }
                }
            }
        }
        Ok(())
    }

    /// Process GMM procedure timers: retransmit up to the configured maximum,
    /// then apply the per-timer abnormal action (TS 24.501 Sections 5.4.1.3.7,
    /// 5.4.3.7, 5.5.1.2.8, 5.5.2.3.6)
    async fn process_nas_timers(&mut self) -> Result<()> {
        let now = Instant::now();
        let due: Vec<u64> = self
            .ue_auth_state
            // The per-UE work in the loop sends NGAP PDUs and therefore `.await`s,
            // so the lock must be gone before it starts (#341).
            .snapshot()
            .into_iter()
            .filter(|(_, s)| s.retx.as_ref().is_some_and(|r| r.deadline <= now))
            .map(|(id, _)| id)
            .collect();

        for amf_ue_ngap_id in due {
            let Some(mut state) = self.ue_auth_state.remove(amf_ue_ngap_id) else {
                continue;
            };
            let Some(mut retx) = state.retx.take() else {
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                continue;
            };
            let (max_count, duration) = retx.timer.config(&self.timer_configs);
            #[cfg(feature = "ntn")]
            let duration = retx.timer.ntn_compensated(
                &self.timer_configs,
                duration,
                state.amf_ue.ntn_timing_advance,
            );

            if retx.retries < max_count {
                retx.retries += 1;
                retx.deadline = now + duration;
                log::info!(
                    "{:?} expired for UE {amf_ue_ngap_id}: retransmission {}/{max_count}",
                    retx.timer,
                    retx.retries
                );
                let association_id = state.association_id;
                let pdu = retx.ngap_pdu.clone();
                state.retx = Some(retx);
                self.ue_auth_state.insert(amf_ue_ngap_id, state);
                let _ = self.send_to_association(association_id, &pdu).await;
                continue;
            }

            // Maximum retransmissions reached: abnormal action
            log::warn!(
                "{:?} max retransmissions reached for UE {amf_ue_ngap_id}: aborting procedure",
                retx.timer
            );
            let association_id = state.association_id;
            let ran_ue_ngap_id = state.ran_ue_ngap_id;
            match retx.timer {
                NasProcTimer::T3550 => {
                    // Abort; the network considers the new GUTI valid
                    // (TS 24.501 Section 5.5.1.2.8 case c)
                    state.registered = true;
                    state.amf_ue.current_guti = state.amf_ue.next_guti.clone();
                    self.ue_auth_state.insert(amf_ue_ngap_id, state);
                }
                NasProcTimer::T3560 => {
                    // Abort authentication/SMC and release the N1 connection.
                    //
                    // No trailing `ue_auth_state.remove`: `release_ue` calls `forget_ue`
                    // as its first act, so the entry is already gone. The raw remove that
                    // used to sit here was redundant AND against `forget_ue`'s own
                    // instruction to be the only remover of a UE that is gone -- one
                    // funnel, or #356's emergency context leaks again the next time a path
                    // is added beside it.
                    self.ue_auth_state.insert(amf_ue_ngap_id, state);
                    self.release_ue(association_id, amf_ue_ngap_id, ran_ue_ngap_id, 1)
                        .await?;
                }
                NasProcTimer::T3570 => {
                    if state.pei_requested {
                        // PEI identification aborted: continue registration
                        state.pei_requested = false;
                        self.ue_auth_state.insert(amf_ue_ngap_id, state);
                        self.complete_registration(association_id, amf_ue_ngap_id, ran_ue_ngap_id)
                            .await?;
                    } else {
                        // SUCI identification aborted: release. `release_ue` -> `forget_ue`
                        // owns the removal; see the T3560 arm.
                        self.ue_auth_state.insert(amf_ue_ngap_id, state);
                        self.release_ue(association_id, amf_ue_ngap_id, ran_ue_ngap_id, 1)
                            .await?;
                    }
                }
                NasProcTimer::T3555 => {
                    // TS 24.501 §5.4.4.6 a): "on the fifth expiry of timer T3555, the
                    // procedure shall be aborted. In addition, if the CONFIGURATION
                    // UPDATE COMMAND message includes the 5G-GUTI IE, the network shall
                    // behave as described in case b)-1)" -- and b)-1) is: "the old and
                    // the new 5G-GUTI shall be considered as valid until the old 5G-GUTI
                    // can be considered as invalid by the AMF".
                    //
                    // So BOTH identities are kept: `current_guti` (the one the UE
                    // certainly has) and `next_guti` (the one it may already have
                    // adopted, since the COMPLETE may simply have been lost). Neither is
                    // overwritten.
                    //
                    // #352 fixes what stood here before: `next_guti = current_guti`,
                    // which discarded the reallocated identity, so a UE that HAD adopted
                    // it became unidentifiable -- the §5.4.4.6 b)-1) iii) recovery ("may
                    // use the identification procedure") was the only way back, on every
                    // aborted reallocation rather than only on a genuine mismatch.
                    //
                    // The window is closed by `resolve_registration_by_guti`, which
                    // accepts either identity on the next registration and commits
                    // whichever the UE presents, per b)-1) ii): "shall consider the new
                    // 5G-GUTI as valid if it is used by the UE".
                    //
                    // (#352's own body cites §5.4.4.3 for this rule. That clause is the
                    // UE's side of the procedure; the network-side rule is §5.4.4.6, and
                    // it is the one that supplies the collapse rule above.)
                    log::warn!(
                        "T3555 aborted for UE {amf_ue_ngap_id}: no Configuration Update \
                         Complete after four retransmissions. BOTH 5G-GUTIs stay valid \
                         (current 5G-TMSI=0x{:08x}, reallocated 5G-TMSI=0x{:08x}) until the \
                         UE presents one of them (TS 24.501 §5.4.4.6 a) -> b)-1))",
                        state.amf_ue.current_guti.tmsi,
                        state.amf_ue.next_guti.tmsi
                    );
                    self.ue_auth_state.insert(amf_ue_ngap_id, state);
                }
                NasProcTimer::T3522 => {
                    // Implicit deregistration (TS 24.501 Section 5.5.2.3.6).
                    //
                    // The raw remove that used to sit between these two calls was worse
                    // than the other two: it ran BEFORE `release_ue`, so `forget_ue` found
                    // nothing to remove and this path depended on `release_emergency`
                    // being reachable without the map entry. `release_ue` -> `forget_ue`
                    // owns the removal.
                    self.ue_auth_state.insert(amf_ue_ngap_id, state);
                    self.release_all_pdu_sessions(amf_ue_ngap_id).await;
                    // #622: the UE is deregistered locally, so its policy associations
                    // are terminated too. Before `release_ue`, which drops the ids.
                    self.terminate_policy_associations(amf_ue_ngap_id);
                    self.release_ue(association_id, amf_ue_ngap_id, ran_ue_ngap_id, 2)
                        .await?;
                }
            }
        }
        Ok(())
    }

    /// Release every PDU session of a UE at the SMF
    /// (Nsmf_PDUSession_ReleaseSMContext)
    async fn release_all_pdu_sessions(&mut self, amf_ue_ngap_id: u64) {
        let (smf_host, smf_port) = crate::sbi_path::resolve_nf_endpoint_async(
            crate::sbi_path::SbiServiceType::NsmfPdusession,
        )
        .await
        .unwrap_or_else(|_| ("127.0.0.1".to_string(), 7777));

        // Collect SM context refs from the global AMF context (copy out under
        // the lock, then call SBI without holding it)
        let sm_context_refs: Vec<(u8, String)> = {
            let mut refs = Vec::new();
            let ctx = crate::context::amf_self();
            if let Ok(context) = ctx.read() {
                let amf_ue_id = context
                    .ran_ue_find_by_amf_ue_ngap_id(amf_ue_ngap_id)
                    .map(|ran_ue| ran_ue.amf_ue_id)
                    .unwrap_or(amf_ue_ngap_id);
                for sess in context.sess_list_for_ue(amf_ue_id).iter() {
                    if let Some(ref r) = sess.sm_context_ref {
                        refs.push((sess.psi, r.clone()));
                    }
                }
            }
            refs
        };

        for (psi, sm_context_ref) in &sm_context_refs {
            // #669: each context is released at the SMF that holds it.
            let (smf_host, smf_port) = self
                .sm_context_smfs
                .get(&(amf_ue_ngap_id, *psi))
                .cloned()
                .unwrap_or_else(|| (smf_host.clone(), smf_port));
            match crate::sbi_path::call_smf_release_sm_context(&smf_host, smf_port, sm_context_ref)
                .await
            {
                Ok(()) => log::info!("SMF SM Context Released: PSI={psi}"),
                Err(e) => log::warn!("SMF release failed for PSI={psi}: {e}"),
            }
        }
    }

    /// Drop every per-UE state this task owns for a UE that has gone away.
    ///
    /// One place, because there are THREE paths that end a UE and they do not converge
    /// (#356): [`Self::release_ue`], the NG Reset handler, and the implicit
    /// deregistration the reachability timer performs. Each removed `ue_auth_state`
    /// directly and none touched `self.emergency`, so an emergency registration's
    /// context was created on the registration path and never freed --
    /// `active_count()`, the figure an operator watches during an emergency, counted
    /// every emergency this process had ever seen instead of the live ones, and a
    /// recycled AMF UE NGAP ID would have inherited the previous occupant's
    /// `authenticated` flag and assigned PDU session.
    ///
    /// Call this instead of `self.ue_auth_state.remove(..)` whenever the UE is GONE.
    /// Not on the paths that take the state out and put it back (the retransmission
    /// timers do this) and not on handover, where the UE has moved rather than left --
    /// `handle_handover_notify` documents why it must not use `release_ue` either.
    fn forget_ue(&mut self, amf_ue_ngap_id: u64) {
        self.ue_auth_state.remove(amf_ue_ngap_id);
        // #756: the UE's per-session state goes with it. AMF UE NGAP IDs are never
        // reused, so an entry left here is never overwritten. Before this, every
        // session the AMF ever served stayed in these maps (and in the context's
        // `sess_list`, capped at `max_num_of_sess`) for the life of the process.
        self.forget_ue_sessions(amf_ue_ngap_id);
        // #877 re-review M1: the UE's off-task SBI work is aborted, which frees
        // the permits it held for other UEs.
        self.sbi_offload.cancel_ue(amf_ue_ngap_id);
        // #796: nothing waits for an SMF on behalf of a UE that is gone.
        self.pending_establishments
            .retain(|(ue, _), _| *ue != amf_ue_ngap_id);
        // #742 review: a UE ended mid-handover (release, NG Reset, implicit
        // deregistration) takes its preparation state with it.
        self.forget_handover_preparation(amf_ue_ngap_id);
        // Logged at info, and only when there WAS one: the overwhelming majority of
        // releases are for ordinary UEs, and a line per release saying "no emergency
        // context" would bury the ones that matter. `active_count` is included because
        // the live figure is the operator-facing number and this is the only place it
        // decreases.
        if self.emergency.release_emergency(amf_ue_ngap_id) {
            log::info!(
                "Emergency context released for UE {amf_ue_ngap_id}: {} emergency \
                 registration(s) still active (TS 23.167)",
                self.emergency.active_count()
            );
        }
    }

    /// Drop everything this AMF holds about `amf_ue_ngap_id`'s PDU sessions (#756):
    /// the SM context refs and owning SMFs, any handover-in-flight per-session
    /// state, and the UE's entries in the context's `sess_list`. Callers release
    /// the sessions at the SMF first, where that is the procedure's job.
    fn forget_ue_sessions(&mut self, amf_ue_ngap_id: u64) {
        self.sm_context_refs
            .retain(|(ue, _), _| *ue != amf_ue_ngap_id);
        self.sm_context_smfs
            .retain(|(ue, _), _| *ue != amf_ue_ngap_id);
        self.handover_target_transfers
            .retain(|(ue, _), _| *ue != amf_ue_ngap_id);
        self.handover_target_assoc.remove(&amf_ue_ngap_id);
        let ctx = crate::context::amf_self();
        let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
        for sess in guard.sess_list_for_ue(amf_ue_ngap_id) {
            guard.sess_remove(sess.id);
        }
    }

    /// Drop one PDU session's state (#756): released at the SMF, so nothing will
    /// address it again.
    fn forget_session(&mut self, amf_ue_ngap_id: u64, psi: u8) {
        self.sm_context_refs.remove(&(amf_ue_ngap_id, psi));
        self.sm_context_smfs.remove(&(amf_ue_ngap_id, psi));
        self.handover_target_transfers
            .remove(&(amf_ue_ngap_id, psi));
        let ctx = crate::context::amf_self();
        let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
        if let Some(sess) = guard.sess_find_by_psi(amf_ue_ngap_id, psi) {
            guard.sess_remove(sess.id);
        }
    }

    /// Backstop sweep for per-session state whose end this task never sees (#756).
    /// For example, the SMF's SmContextStatusNotification RELEASED, which the SBI
    /// task handles by removing the `sess_list` entry. Drops any `sm_context_refs`
    /// / `sm_context_smfs` entry whose UE is gone or whose session the context no
    /// longer holds. Every write of those maps happens on this task, together with
    /// its `sess_list` write, so the sweep cannot interleave with one.
    fn sweep_orphaned_session_state(&mut self) -> usize {
        let held: std::collections::HashSet<(u64, u8)> = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            guard
                .sess_list_snapshot()
                .into_iter()
                .map(|s| (s.amf_ue_id, s.psi))
                .collect()
        };
        let live = |key: &(u64, u8), store: &crate::ue_store::UeStore<UeNasContext>| {
            held.contains(key) && store.contains(key.0)
        };
        let before = self.sm_context_refs.len() + self.sm_context_smfs.len();
        let store = std::sync::Arc::clone(&self.ue_auth_state);
        self.sm_context_refs.retain(|k, _| live(k, &store));
        self.sm_context_smfs.retain(|k, _| live(k, &store));
        before - (self.sm_context_refs.len() + self.sm_context_smfs.len())
    }

    /// Deliver a NAS PDU on a path whose OUTCOME does not depend on it arriving.
    ///
    /// `send_nas_pdu` maps any SCTP send failure to `Err`, and on a refusal path that
    /// error must not become the caller's: the AMF has already decided to end this UE, and
    /// a `?` here abandons the decision half-applied. Logged at warn rather than swallowed,
    /// because a reject the UE never received is a real diagnostic -- the UE will keep
    /// retrying a registration the AMF has refused.
    ///
    /// Use ONLY where the caller goes on to release the UE. Anywhere the procedure
    /// continues, a failed send genuinely is fatal and `?` is correct.
    async fn deliver_nas_best_effort(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas: &[u8],
        what: &str,
    ) {
        if let Err(e) = self
            .send_nas_pdu(association_id, amf_ue_ngap_id, ran_ue_ngap_id, nas)
            .await
        {
            log::warn!(
                "UE {amf_ue_ngap_id}: {what} could not be delivered ({e}); continuing to \
                 release the UE, which is the part that must happen (#359)"
            );
        }
    }
    /// Refuse a NAS procedure in flight: deliver `nas_reject`, then release the UE
    /// **whether or not the reject arrived**.
    ///
    /// NINETEEN sites used to write `send_nas_pdu(..).await?;` immediately followed by
    /// `release_ue(..).await?;`, so a failed reject send returned early and the release
    /// never ran (#359). The window is narrow -- the association has to fail between the
    /// decision to refuse and the reject being written -- but it is exactly the moment when
    /// the gNB link is already unhealthy, i.e. when the two failures correlate.
    ///
    /// What was lost is not just the release command. `start_authentication` TAKES the UE's
    /// NAS state out of `ue_auth_state` and its AUSF-failure arm never put it back, so the
    /// early return left the `AmfUe` context gone with no release at all: the RAN kept a UE
    /// the AMF had forgotten, every later NAS message from it hit an empty map and was
    /// dropped by a `return Ok(())` guard, no T3560 was armed to recover it, and #356's
    /// emergency context was orphaned because all three release sites need the UE to still
    /// be in the map or to be named by a reset.
    ///
    /// A release command that cannot be delivered is still the right bookkeeping:
    /// [`Self::release_ue`] calls [`Self::forget_ue`] as its FIRST act, so the AMF stops
    /// holding a UE it can no longer reach either way. This is the one funnel for that
    /// decision, so no individual arm can regress to the `?` form.
    async fn reject_and_release(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas_reject: &[u8],
        nas_cause: u8,
    ) -> Result<()> {
        self.deliver_nas_best_effort(
            association_id,
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            nas_reject,
            "the NAS reject",
        )
        .await;
        self.release_ue(association_id, amf_ue_ngap_id, ran_ue_ngap_id, nas_cause)
            .await
    }

    /// Send a UEContextReleaseCommand with a NAS cause and drop the UE's
    /// NAS state (0 = normal-release, 1 = authentication-failure,
    /// 2 = deregister)
    async fn release_ue(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: u64,
        ran_ue_ngap_id: u32,
        nas_cause: u8,
    ) -> Result<()> {
        self.forget_ue(amf_ue_ngap_id);
        if let Some(cmd) = crate::ngap_asn1::build_ue_context_release_command_asn1(
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            ngap_handler::cause_group::NAS,
            nas_cause as i64,
        ) {
            self.send_to_association(association_id, &cmd).await?;
            log::info!(
                "UE Context Release Command sent (UE {amf_ue_ngap_id}, NAS cause {nas_cause})"
            );
        }
        Ok(())
    }

    // ========================================================================
    // Error Indication (TS 38.413 Section 8.7.5)
    // ========================================================================

    /// Send an NGAP ErrorIndication to a gNB (TS 38.413 Section 8.7.5).
    ///
    /// Emitted when the AMF receives an undecodable PDU, a PDU for an
    /// unimplemented/unexpected procedure, or a UE-associated message it cannot
    /// process. The AMF-UE-NGAP-ID / RAN-UE-NGAP-ID are included when known so
    /// the gNB can correlate the indication to a UE association.
    async fn send_error_indication(
        &mut self,
        association_id: u64,
        amf_ue_ngap_id: Option<u64>,
        ran_ue_ngap_id: Option<u32>,
        cause: ngap_gen::Cause,
    ) -> Result<()> {
        match crate::ngap_asn1::build_error_indication_generated(
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            cause,
        ) {
            Some(bytes) => {
                self.send_to_association(association_id, &bytes).await?;
                log::info!(
                    "ErrorIndication sent to association {association_id} \
                     (amf_ue_ngap_id={amf_ue_ngap_id:?}, ran_ue_ngap_id={ran_ue_ngap_id:?})"
                );
            }
            None => log::error!("Failed to build ErrorIndication"),
        }
        Ok(())
    }

    /// TS 38.413 §10.2: *"If a Transfer Syntax Error occurs, the receiver should initiate
    /// Error Indication procedure with appropriate cause value for the Transfer Syntax
    /// protocol error."* The message could not be decoded, so the Error Indication names
    /// no UE (#999). Never used for an Error Indication itself, which is not answered.
    async fn report_transfer_syntax_error(
        &mut self,
        association_id: u64,
        what: &str,
    ) -> Result<()> {
        log::warn!(
            "{what} from association {association_id} could not be decoded; sending Error \
             Indication (transfer-syntax-error, TS 38.413 §10.2)"
        );
        // Best effort: a report that cannot be sent is logged, and the handler goes on
        // with whatever local handling it does for an unusable message.
        if let Err(e) = self
            .send_error_indication(
                association_id,
                None,
                None,
                ngap_gen::Cause::Protocol(ngap_gen::CauseProtocol(
                    ngap_gen::CauseProtocol::TRANSFER_SYNTAX_ERROR,
                )),
            )
            .await
        {
            log::warn!("Failed to send ErrorIndication to association {association_id}: {e}");
        }
        Ok(())
    }

    /// Send an Error Indication reporting not-comprehended or missing IEs of a received
    /// message (TS 38.413 §10.3.4.2, §10.3.5), encoded by the generated codec.
    async fn send_criticality_error_indication(
        &mut self,
        association_id: u64,
        report: &crate::ngap_asn1::CriticalityErrorIndication,
    ) -> Result<()> {
        match crate::ngap_asn1::build_criticality_error_indication_asn1(report) {
            Some(bytes) => {
                self.send_to_association(association_id, &bytes).await?;
                log::info!(
                    "ErrorIndication sent to association {association_id} for procedure {} \
                     (cause protocol {}, IEs {:?})",
                    report.procedure.procedure_code,
                    report.cause_protocol,
                    report.diagnostics
                );
            }
            None => log::error!("Failed to build criticality ErrorIndication"),
        }
        Ok(())
    }

    /// Handle an inbound ErrorIndication from a gNB (TS 38.413 Section 8.7.5).
    /// The AMF never replies; it logs the reported cause/diagnostics for the
    /// affected UE association so operators can trace the protocol error. An
    /// error in the indication itself gets local handling only -- here, a log
    /// line -- never an Error Indication back (§10.6).
    async fn handle_error_indication(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        let Some(ei) = crate::ngap_asn1::decode_error_indication_asn1(data) else {
            log::error!("Failed to decode ErrorIndication from association {association_id}");
            return Ok(());
        };
        if ei.cause.is_none() && ei.criticality_diagnostics.is_none() {
            // §8.7.5.2: "shall contain at least either the Cause IE or the
            // Criticality Diagnostics IE".
            log::warn!(
                "ErrorIndication from association {association_id} carries neither a Cause \
                 nor Criticality Diagnostics"
            );
        }
        log::warn!(
            "ErrorIndication from association {association_id}: \
             amf_ue_ngap_id={:?}, ran_ue_ngap_id={:?}, cause={:?}, criticality_diagnostics={:?}",
            ei.amf_ue_ngap_id,
            ei.ran_ue_ngap_id,
            ei.cause,
            ei.criticality_diagnostics
        );
        Ok(())
    }

    // ========================================================================
    // AMF-initiated Overload Start / Stop (TS 38.413 Sections 8.7.6/8.7.7)
    // ========================================================================

    /// Broadcast an AMF-initiated Overload Start to every connected gNB
    /// (TS 38.413 Section 8.7.6). `reduce_percent` is the requested traffic
    /// reduction (OverloadResponse = Overload Action, here the percentage
    /// variant `OverloadStartNSSAIList`-less form via OverloadResponse).
    pub async fn send_overload_start(&mut self, reduce_percent: u8) -> Result<()> {
        let bytes = match crate::ngap_asn1::build_overload_start_asn1(reduce_percent) {
            Some(b) => b,
            None => {
                log::error!("Failed to build OverloadStart");
                return Ok(());
            }
        };
        let assoc_ids: Vec<u64> = self.sessions.read().await.keys().copied().collect();
        for assoc_id in assoc_ids {
            self.send_to_association(assoc_id, &bytes).await?;
        }
        log::info!("OverloadStart broadcast (reduce {reduce_percent}%)");
        Ok(())
    }

    /// Broadcast an AMF-initiated Overload Stop to every connected gNB
    /// (TS 38.413 Section 8.7.7).
    pub async fn send_overload_stop(&mut self) -> Result<()> {
        let bytes = match crate::ngap_asn1::build_overload_stop_asn1() {
            Some(b) => b,
            None => {
                log::error!("Failed to build OverloadStop");
                return Ok(());
            }
        };
        let assoc_ids: Vec<u64> = self.sessions.read().await.keys().copied().collect();
        for assoc_id in assoc_ids {
            self.send_to_association(assoc_id, &bytes).await?;
        }
        log::info!("OverloadStop broadcast");
        Ok(())
    }

    // ========================================================================
    // N2 Handover (TS 38.413 Section 8.4) and Xn Path Switch (Section 8.4.4)
    // ========================================================================

    /// Drop everything an N2 handover preparation of `amf_ue_ngap_id` left behind: the
    /// target the HandoverRequest went to, the relay target and every per-session target
    /// transfer (#742).
    ///
    /// Called whenever a preparation ends without a HandoverNotify (Cancel, Failure, a
    /// refusal), before a new one starts, and from `forget_ue` (release, NG Reset,
    /// implicit deregistration). Leaving the transfers was not a leak only: the next
    /// handover's Notify relays EVERY stored transfer of the UE to the SMF as
    /// HANDOVER_COMPLETE, so a session the new target did not admit was switched to the
    /// DL tunnel of a target the UE never reached.
    fn forget_handover_preparation(&mut self, amf_ue_ngap_id: u64) {
        self.handover_pending_target.remove(&amf_ue_ngap_id);
        self.handover_prepared_psis.remove(&amf_ue_ngap_id);
        self.ho_preparations.remove(&amf_ue_ngap_id);
        self.ho_commands.remove(&amf_ue_ngap_id);
        self.handover_dropped_psis.remove(&amf_ue_ngap_id);
        self.handover_listed_psis.remove(&amf_ue_ngap_id);
        self.handover_target_release_psis.remove(&amf_ue_ngap_id);
        self.handover_cancelled_psis.remove(&amf_ue_ngap_id);
        self.handover_target_assoc.remove(&amf_ue_ngap_id);
        self.handover_target_transfers
            .retain(|(ue, _psi), _| *ue != amf_ue_ngap_id);
    }

    /// Send the source NG-RAN Release Commands whose step 6a timer has expired (#806).
    async fn process_pending_source_releases(&mut self) {
        if self.pending_source_releases.is_empty() {
            return;
        }
        let now = Instant::now();
        let (due, waiting): (Vec<_>, Vec<_>) = std::mem::take(&mut self.pending_source_releases)
            .into_iter()
            .partition(|p| p.deadline <= now);
        self.pending_source_releases = waiting;
        for p in due {
            // A UE that came back to the old source within the hold (ping-pong) may be
            // served there again under the same RAN UE NGAP ID: that connection is the
            // serving one now, and releasing it would cut the UE off.
            let serving = self
                .ue_auth_state
                .get(p.amf_ue_ngap_id)
                .map(|s| (s.association_id, s.ran_ue_ngap_id));
            if serving == Some((p.association_id, p.ran_ue_ngap_id)) {
                log::info!(
                    "UE {}: the deferred source release on association {} (ran_ue_ngap_id={}) \
                     is skipped: the UE is served on that connection again",
                    p.amf_ue_ngap_id,
                    p.association_id,
                    p.ran_ue_ngap_id
                );
                continue;
            }
            let Some(cmd) = crate::ngap_asn1::build_ue_context_release_command_asn1(
                p.amf_ue_ngap_id,
                p.ran_ue_ngap_id,
                ngap_handler::cause_group::RADIO_NETWORK,
                nextgcore_ngap::types::CauseRadioNetwork::SuccessfulHandover as i64,
            ) else {
                continue;
            };
            match self.send_to_association(p.association_id, &cmd).await {
                Ok(()) => log::info!(
                    "UE Context Release Command sent to SOURCE association {} for UE {} \
                     (source ran_ue_ngap_id={}, successful-handover) after the step 6a timer",
                    p.association_id,
                    p.amf_ue_ngap_id,
                    p.ran_ue_ngap_id
                ),
                Err(e) => log::warn!(
                    "Could not release the SOURCE context for UE {} on association {}: {e}",
                    p.amf_ue_ngap_id,
                    p.association_id
                ),
            }
        }
    }

    /// Handle a HandoverRequired from the source gNB (TS 38.413 Section 8.4.1).
    ///
    /// For an intra-AMF / Xn-less N2 handover the AMF would forward the
    /// SourceToTarget container to the target gNB in a HandoverRequest. Reaching
    /// the target requires resolving its NG association from the TargetID, which
    /// is cross-gNB state. When the target cannot be resolved on this AMF the
    /// preparation is rejected with HandoverPreparationFailure carrying the
    /// spec cause (TS 38.413 Section 9.2.3.6), rather than being dropped.
    async fn handle_handover_required(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        // #417: the GENERATED codec, applying TS 38.413 §10.3.4.2 / §10.3.5.
        let required = match crate::ngap_asn1::decode_handover_required_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                // "Ignore IE and notify sender": the preparation goes on, and the
                // not-comprehended IEs are reported in an Error Indication.
                if let Some(report) = error_indication {
                    self.send_criticality_error_indication(association_id, &report)
                        .await?;
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!(
                    "HandoverRequired from association {association_id} rejected: {report:?}"
                );
                // Class 1 with an unsuccessful outcome: answer with HANDOVER
                // PREPARATION FAILURE naming the IEs, when the UE can be named.
                if let (Some(amf_ue_ngap_id), Some(ran_ue_ngap_id)) =
                    (report.amf_ue_ngap_id, report.ran_ue_ngap_id)
                {
                    let failure = nextgcore_ngap::types::HandoverPreparationFailure {
                        amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        cause: nextgcore_ngap::types::Cause::Protocol(
                            nextgcore_ngap::types::CauseProtocol::AbstractSyntaxErrorReject,
                        ),
                        criticality_diagnostics: Some(crate::ngap_asn1::hand_written_diagnostics(
                            &report,
                        )),
                    };
                    if let Some(bytes) =
                        crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure)
                    {
                        self.send_to_association(association_id, &bytes).await?;
                    }
                } else {
                    self.send_criticality_error_indication(association_id, &report)
                        .await?;
                }
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                // #744: a well-formed HANDOVER REQUIRED for a handover type or target this
                // AMF cannot represent is a preparation it cannot carry out, not a
                // transfer-syntax error: answer HANDOVER PREPARATION FAILURE with
                // ho-target-not-allowed, so the source stops waiting for TNGRELOCprep
                // (TS 38.413 §8.4.1.3) and the cause names the real reason.
                if let Some((amf_ue_ngap_id, ran_ue_ngap_id)) =
                    crate::ngap_asn1::handover_required_unsupported_target(data)
                {
                    log::warn!(
                        "HandoverRequired from association {association_id} for UE \
                         {amf_ue_ngap_id} asks for a handover type or target this AMF \
                         cannot represent; HandoverPreparationFailure ho-target-not-allowed"
                    );
                    // #844 review: as the other refusals do, no relay target or session
                    // transfer of an earlier preparation outlives this one, so a later
                    // Uplink RAN Status Transfer cannot follow it to a gNB the UE is not
                    // moving to; a preparation still in progress is cancelled.
                    self.supersede_handover_in_progress(amf_ue_ngap_id).await;
                    self.forget_handover_preparation(amf_ue_ngap_id);
                    let failure = nextgcore_ngap::types::HandoverPreparationFailure {
                        amf_ue_ngap_id,
                        ran_ue_ngap_id,
                        cause: nextgcore_ngap::types::Cause::RadioNetwork(
                            nextgcore_ngap::types::CauseRadioNetwork::HoTargetNotAllowed,
                        ),
                        criticality_diagnostics: None,
                    };
                    if let Some(bytes) =
                        crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure)
                    {
                        self.send_to_association(association_id, &bytes).await?;
                    }
                    return Ok(());
                }
                self.send_error_indication(
                    association_id,
                    None,
                    None,
                    ngap_gen::Cause::Protocol(ngap_gen::CauseProtocol(
                        ngap_gen::CauseProtocol::TRANSFER_SYNTAX_ERROR,
                    )),
                )
                .await?;
                return Ok(());
            }
        };
        log::info!(
            "HandoverRequired (amf_ue_ngap_id={}, ran_ue_ngap_id={}, type={:?})",
            required.amf_ue_ngap_id,
            required.ran_ue_ngap_id,
            required.handover_type
        );

        // Inter-system handover (TS 38.413 §9.3.1.22 HandoverType): decide on the
        // TYPE before looking for a target gNB, because for anything but intra-5GS
        // there is no gNB to look for (#116).
        //
        // #116's criterion 7 describes an unconditional `handover_type != 0` reject in
        // `ngap_handler`. That reject no longer exists -- re-verified at `bf57ddd`, the
        // only survivor is the `HO_TARGET_NOT_ALLOWED` constant -- and its absence left
        // something WORSE than an honest refusal: the type was logged and then passed
        // straight through into the `HandoverRequest` below. So a `fivegs-to-eps`
        // preparation was resolved against connected gNBs and either failed with
        // `UnknownTargetId` (a cause that misdescribes the reason: the target is an
        // MME, not an unknown gNB) or, if some gNB's id happened to match, was
        // forwarded to a gNB as a 5GS→EPS handover the AMF cannot carry out.
        //
        // Declined honestly instead, with local cleanup. `ho-target-not-allowed` is
        // the accurate cause: the target system is not one this AMF may hand over to.
        // Nothing is torn down for the UE -- it stays registered and served on 5GS, which
        // is the graceful degradation #116 asks for rather than a hard failure.
        //
        // #408 made the `fivegs-to-eps` arm CONDITIONAL: when the N26 leg is up, a socket is
        // bound and a target MME is configured, the preparation is DRIVEN (below) instead of
        // refused. `eps-to-5gs` stays refused unconditionally --
        // `inter_system_handover_refusal_with` carries why.
        if let Some((cause, target_system)) = inter_system_handover_refusal(required.handover_type)
        {
            log::warn!(
                "HandoverRequired with HandoverType={:?} ({target_system}): declining with \
                 ho-target-not-allowed. A Forward Relocation cannot be driven for this \
                 preparation -- the N26 switch, a bound N26 socket and a configured target MME \
                 are all required (see n26_path::is_forward_relocation_drivable), and an \
                 eps-to-5gs HandoverRequired from a gNB names a procedure whose source is the \
                 E-UTRAN and so cannot legitimately arrive here. Refusing beats forwarding a \
                 preparation that will fail. The UE keeps its 5GS registration and PDU \
                 sessions; nothing is released.",
                required.handover_type
            );
            let failure = nextgcore_ngap::types::HandoverPreparationFailure {
                amf_ue_ngap_id: required.amf_ue_ngap_id,
                ran_ue_ngap_id: required.ran_ue_ngap_id,
                cause: nextgcore_ngap::types::Cause::RadioNetwork(cause),
                criticality_diagnostics: None,
            };
            // Local cleanup, the same state HandoverCancel drops: a relay target and
            // any per-session transfers left from an earlier preparation for this UE.
            // Dropped BEFORE the failure is sent, so a failed send cannot leave a
            // stale relay target that a later Uplink RAN Status Transfer would follow
            // to a gNB this UE is not moving to.
            self.forget_handover_preparation(required.amf_ue_ngap_id);
            if let Some(bytes) = crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure)
            {
                self.send_to_association(association_id, &bytes).await?;
            }
            return Ok(());
        }

        // #408: a `fivegs-to-eps` preparation that got past the refusal is one a Forward
        // Relocation CAN be driven for, so it is routed over N26 rather than resolved against
        // connected gNBs. It must return here: the target of this handover is an eNB, and
        // falling through to `find_association_for_target` below would search the gNB table
        // for it and answer `unknown-target-id` -- the exact mis-cause #116 existed to fix.
        if required.handover_type == nextgcore_ngap::types::HandoverType::FivegsToEps {
            self.drive_forward_relocation(association_id, &required)
                .await?;
            return Ok(());
        }

        // Locate the target gNB association from the TargetID's Global RAN Node
        // ID. Without a matching connected gNB the AMF cannot allocate handover
        // resources (inter-AMF / N2 relocation needs Namf_Communication, which
        // is out of scope here).
        let target_assoc = self.find_association_for_target(&required.target_id).await;

        if target_assoc.is_none() {
            log::warn!(
                "HandoverRequired: target gNB not reachable on this AMF; \
                 rejecting with HandoverPreparationFailure"
            );
            let failure = nextgcore_ngap::types::HandoverPreparationFailure {
                amf_ue_ngap_id: required.amf_ue_ngap_id,
                ran_ue_ngap_id: required.ran_ue_ngap_id,
                cause: nextgcore_ngap::types::Cause::RadioNetwork(
                    nextgcore_ngap::types::CauseRadioNetwork::UnknownTargetId,
                ),
                criticality_diagnostics: None,
            };
            if let Some(bytes) = crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure)
            {
                self.send_to_association(association_id, &bytes).await?;
            }
            return Ok(());
        }

        // Intra-AMF path: forward a HandoverRequest to the target gNB built from
        // the source UE context. Cross-gNB UE-context relocation (new
        // RAN-UE-NGAP-ID allocation at the target, T304 supervision, the
        // HandoverRequestAcknowledge->HandoverCommand stitching) is tracked as
        // future work; we emit the HandoverRequest with the source container so
        // the target can begin admission.
        let target_assoc = target_assoc.expect("checked is_some");
        // Mutable: advancing the {NH, NCC} chain for the target gNB mutates the
        // stored pair (TS 33.501 Section 6.9.2.3.3).
        let Some(_state) = self.ue_auth_state.get(required.amf_ue_ngap_id) else {
            log::warn!(
                "HandoverRequired for unknown UE {}; rejecting",
                required.amf_ue_ngap_id
            );
            let failure = nextgcore_ngap::types::HandoverPreparationFailure {
                amf_ue_ngap_id: required.amf_ue_ngap_id,
                ran_ue_ngap_id: required.ran_ue_ngap_id,
                cause: nextgcore_ngap::types::Cause::RadioNetwork(
                    nextgcore_ngap::types::CauseRadioNetwork::UnknownLocalUeNgapId,
                ),
                criticality_diagnostics: None,
            };
            if let Some(bytes) = crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure)
            {
                self.send_to_association(association_id, &bytes).await?;
            }
            return Ok(());
        };

        // #964, TS 23.502 §4.9.1.3.2 steps 3-7: the target's Handover Request Transfer is
        // the SMF's, not the source's Handover Required Transfer (a different structure,
        // TS 38.413 §9.3.4.12 vs §9.3.4.1, which the target cannot decode). Each session
        // goes to its SMF with hoState PREPARING off the NGAP task; the HANDOVER REQUEST
        // follows when every SMF has answered (`send_handover_request`).
        self.start_handover_preparation(association_id, target_assoc, required)
            .await
    }

    /// Drive a 5GS→EPS handover preparation over N26 (#408, TS 23.502 §4.11.1.2.1 steps 2-3).
    ///
    /// Reached only when [`crate::n26_path::forward_relocation_drivable`] answered `true`, i.e.
    /// the switch is on, a socket is bound and a target MME is configured — so this is the
    /// "routes when it can" half of #408 criterion 4, and `inter_system_handover_refusal` above
    /// is the "refuses when it cannot" half.
    ///
    /// A failure here answers `HandoverPreparationFailure` rather than leaving the source gNB
    /// to time out T304, and the cause is still `ho-target-not-allowed`: the honest statement is
    /// that this AMF could not reach the target system, and blaming the RAN with
    /// `unknown-target-id` would send an operator to the wrong place.
    async fn drive_forward_relocation(
        &mut self,
        association_id: u64,
        required: &nextgcore_ngap::types::HandoverRequired,
    ) -> Result<()> {
        // The AMF's own UE id. `ue_auth_state` is the NGAP layer's view; `amf_ue.id` is the
        // store key `n26_path` needs to find the sessions and the security context.
        let ue_id = self
            .ue_auth_state
            .get(required.amf_ue_ngap_id)
            .map(|s| s.amf_ue.id);
        let Some(ue_id) = ue_id else {
            log::warn!(
                "HandoverRequired (fivegs-to-eps) for unknown UE {}; refusing the preparation \
                 rather than sending a Forward Relocation Request for a context this AMF does \
                 not hold",
                required.amf_ue_ngap_id
            );
            self.refuse_inter_system_preparation(
                association_id,
                required,
                nextgcore_ngap::types::CauseRadioNetwork::UnknownLocalUeNgapId,
            )
            .await?;
            return Ok(());
        };

        let target_identification = Self::eps_target_identification(&required.target_id);
        let target_identification = match target_identification {
            Ok(body) => body,
            Err(why) => {
                log::warn!(
                    "HandoverRequired (fivegs-to-eps) for UE {}: {why}; answering Handover \
                     Preparation Failure (ho-target-not-allowed) rather than sending the MME a \
                     Target Identification for an eNB the gNB did not name",
                    required.amf_ue_ngap_id
                );
                self.refuse_inter_system_preparation(
                    association_id,
                    required,
                    nextgcore_ngap::types::CauseRadioNetwork::HoTargetNotAllowed,
                )
                .await?;
                return Ok(());
            }
        };

        // #408 criterion 6, at the site where the input exists. The gNB's own Direct Forwarding
        // Path Availability is now PARSED (it used to fall into `handle_unknown_ie`), and it is
        // reported here precisely so the refusal to use it is SPECIFIC rather than silent.
        match required.direct_forwarding_path_availability {
            Some(_) => log::warn!(
                "HandoverRequired (fivegs-to-eps) for UE {}: the source gNB reports \
                 direct-path-available, and this AMF is NOT using it. Direct forwarding needs \
                 the forwarding endpoints relayed to the gNB in a HandoverCommandTransfer's \
                 dLForwardingUP-TNLInformation (TS 38.413 §9.3.4.10, ASN.1 at \
                 38413-j30.txt:48917), and this tree has no encoder for that structure -- the \
                 intra-5GS path relays the TARGET gNB's own transfer verbatim, and \
                 inter-system there is no target gNB to have produced one. So the Direct \
                 Forwarding Indication stays CLEAR in the Forward Relocation Request and \
                 downlink data in flight for these bearers is discarded rather than forwarded. \
                 Claiming forwarding this AMF cannot relay would be worse: the MME would \
                 establish indirect tunnels through a Serving GW and hold them until its own \
                 timer expired while the gNB forwarded into nothing.",
                required.amf_ue_ngap_id
            ),
            None => log::info!(
                "HandoverRequired (fivegs-to-eps) for UE {}: the source gNB reports NO direct \
                 forwarding path (the Direct Forwarding Path Availability IE is absent, and \
                 its single enumerated value means presence = available -- TS 23.502 \
                 §4.11.1.2.1 step 1). Indirect forwarding is not requested either: TS 23.502 \
                 §4.11.1.2.1 step 10b has the UPF allocate the forwarding tunnel via an \
                 Nsmf_PDUSession_UpdateSMContext carrying data-forwarding information, and \
                 this SMF's update handler implements only the hoState machine. Downlink data \
                 in flight for these bearers is discarded rather than forwarded.",
                required.amf_ue_ngap_id
            ),
        }

        match crate::n26_path::send_forward_relocation_request(
            required.amf_ue_ngap_id,
            ue_id,
            &required.source_to_target_container,
            &target_identification,
        )
        .await
        {
            Ok(seq) => {
                log::info!(
                    "HandoverRequired (fivegs-to-eps) for UE {}: Forward Relocation Request \
                     sent over N26 (seq={seq}). The HandoverCommand to the source gNB follows \
                     when the target MME answers (TS 23.502 §4.11.1.2.1 steps 3-11).",
                    required.amf_ue_ngap_id
                );
                Ok(())
            }
            Err(why) => {
                log::warn!(
                    "HandoverRequired (fivegs-to-eps) for UE {}: no Forward Relocation Request \
                     was sent ({why}). The preparation is REFUSED so the source gNB stops \
                     waiting, rather than left to time out its own T304 -- and the UE keeps \
                     its 5GS registration and PDU sessions.",
                    required.amf_ue_ngap_id
                );
                self.refuse_inter_system_preparation(
                    association_id,
                    required,
                    nextgcore_ngap::types::CauseRadioNetwork::HoTargetNotAllowed,
                )
                .await
            }
        }
    }

    /// The TS 29.274 §8.51 Target Identification body for a `fivegs-to-eps` HandoverRequired's
    /// TargetID, or why there is none (#741).
    fn eps_target_identification(
        target_id: &nextgcore_ngap::types::TargetId,
    ) -> std::result::Result<bytes::Bytes, String> {
        // The Target Identification the MME needs, built from the TargetID the gNB chose --
        // relayed, not invented, because a target this AMF picked would route the preparation
        // to an eNB the gNB did not select. TS 29.274 §8.51: a macro id is Target Type 1
        // (Figure 8.51-2), a short or long macro id Target Type 4 (Figure 8.51-4), each with
        // the selected EPS TAC (#741).
        match target_id {
            nextgcore_ngap::types::TargetId::TargetGlobalNgEnbId {
                plmn_identity,
                ng_enb_id,
                selected_eps_tai,
            } => crate::n26_build::encode_enb_target_identification(
                plmn_identity,
                *ng_enb_id,
                selected_eps_tai.tac,
            ),
            // TS 38.413 §9.3.1.25: an NG-RAN target is a gNB or ng-eNB in 5GS, which an EPS
            // handover cannot reach; the E-UTRAN alternative is the one that names an eNB and
            // an EPS TAI. Building a Target Identification from a gNB id would ask the MME for
            // an eNB that does not exist.
            nextgcore_ngap::types::TargetId::TargetRanNodeId { .. } => Err(
                "a fivegs-to-eps HandoverRequired names an NG-RAN node, not an E-UTRAN eNB"
                    .to_string(),
            ),
        }
    }

    /// Answer a `HandoverPreparationFailure` for an inter-system preparation, with cleanup.
    ///
    /// Factored out of the two sites that need it so the local cleanup cannot drift between
    /// them: the relay target and any per-session transfers left from an earlier preparation are
    /// dropped BEFORE the failure is sent, so a failed send cannot leave a stale relay target
    /// that a later Uplink RAN Status Transfer would follow to a gNB this UE is not moving to.
    async fn refuse_inter_system_preparation(
        &mut self,
        association_id: u64,
        required: &nextgcore_ngap::types::HandoverRequired,
        cause: nextgcore_ngap::types::CauseRadioNetwork,
    ) -> Result<()> {
        let failure = nextgcore_ngap::types::HandoverPreparationFailure {
            amf_ue_ngap_id: required.amf_ue_ngap_id,
            ran_ue_ngap_id: required.ran_ue_ngap_id,
            cause: nextgcore_ngap::types::Cause::RadioNetwork(cause),
            criticality_diagnostics: None,
        };
        self.supersede_handover_in_progress(required.amf_ue_ngap_id)
            .await;
        self.forget_handover_preparation(required.amf_ue_ngap_id);
        if let Some(bytes) = crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure) {
            self.send_to_association(association_id, &bytes).await?;
        }
        Ok(())
    }

    /// Start an intra-5GS N2 preparation at the SMFs (#964, TS 23.502 §4.9.1.3.2 step
    /// 3): one `hoState: PREPARING` per listed PDU session that has an SM context, keyed
    /// per (UE, PSI) off the NGAP task, with the source's Handover Required Transfer and
    /// the target's `targetId`. A session with no SM context cannot be handed over and is
    /// left out; with none left, the source gets a HANDOVER PREPARATION FAILURE now.
    async fn start_handover_preparation(
        &mut self,
        source_assoc: u64,
        target_assoc: u64,
        required: nextgcore_ngap::types::HandoverRequired,
    ) -> Result<()> {
        let ue = required.amf_ue_ngap_id;
        self.supersede_handover_in_progress(ue).await;
        // #742: a new preparation starts from nothing. An earlier one that ended without
        // a Notify must not contribute a session transfer the new target never admitted.
        self.forget_handover_preparation(ue);
        self.ho_generation += 1;
        let generation = self.ho_generation;
        let target_id = handover_target_id_json(&required.target_id);
        let mut awaiting = HashSet::new();
        for item in &required.pdu_session_list {
            let psi = item.pdu_session_id;
            let Some(sm_ref) = self.sm_context_refs.get(&(ue, psi)).cloned() else {
                log::warn!(
                    "HandoverRequired for UE {ue}: PSI {psi} has no SM context; it is not \
                     handed over"
                );
                continue;
            };
            if !awaiting.insert(psi) {
                continue;
            }
            let (host, port) = self.smf_target_for(ue, psi);
            let transfer = item.transfer.clone();
            let target_id = target_id.clone();
            self.sbi_offload.spawn_keyed((ue, psi), move || async move {
                let result = crate::sbi_path::call_smf_n2_handover(
                    &host,
                    port,
                    &sm_ref,
                    "PREPARING",
                    Some(("HANDOVER_REQUIRED", &transfer)),
                    target_id.as_ref(),
                    None,
                )
                .await
                .and_then(|answer| match answer {
                    Some((t, n2)) if t == "PDU_RES_SETUP_REQ" => Ok(n2),
                    other => Err(format!(
                        "no Handover Request Transfer in the PREPARING answer ({:?})",
                        other.map(|(t, _)| t)
                    )),
                });
                Some(crate::sbi_offload::SbiOutcome::N2Handover(
                    N2HandoverAnswer {
                        amf_ue_ngap_id: ue,
                        psi,
                        generation,
                        step: N2HandoverStep::Preparing,
                        result,
                    },
                ))
            });
        }
        if awaiting.is_empty() {
            log::warn!(
                "HandoverRequired for UE {ue}: no listed PDU session can be handed over; \
                 HANDOVER PREPARATION FAILURE"
            );
            return self
                .fail_handover_preparation(source_assoc, &required)
                .await;
        }
        self.ho_preparations.insert(
            ue,
            HoPreparation {
                generation,
                deadline: Instant::now() + self.ho_preparation_wait,
                source_assoc,
                target_assoc,
                required,
                awaiting,
                ready: Vec::new(),
            },
        );
        Ok(())
    }

    /// A new HandoverRequired from the source supersedes a preparation still in progress
    /// for the UE (#964 review; #844 review for the refusals): the source has abandoned it,
    /// so its target releases what it prepared and its SMFs are told CANCELLED, keyed
    /// ahead of anything the new request starts.
    async fn supersede_handover_in_progress(&mut self, ue: u64) {
        if self.ho_preparations.contains_key(&ue)
            || self.ho_commands.contains_key(&ue)
            || self.handover_pending_target.contains_key(&ue)
        {
            log::info!(
                "HandoverRequired for UE {ue} supersedes the preparation in progress; it is \
                 cancelled"
            );
            self.release_cancelled_handover_target(ue, "HO_CANCEL")
                .await;
        }
    }

    /// HANDOVER PREPARATION FAILURE for an intra-5GS preparation this AMF could not carry
    /// to the target (#964): cause ho-failure-in-target-5GC-ngran-node-or-target-system.
    async fn fail_handover_preparation(
        &mut self,
        source_assoc: u64,
        required: &nextgcore_ngap::types::HandoverRequired,
    ) -> Result<()> {
        self.forget_handover_preparation(required.amf_ue_ngap_id);
        let failure = nextgcore_ngap::types::HandoverPreparationFailure {
            amf_ue_ngap_id: required.amf_ue_ngap_id,
            ran_ue_ngap_id: required.ran_ue_ngap_id,
            cause: nextgcore_ngap::types::Cause::RadioNetwork(
                nextgcore_ngap::types::CauseRadioNetwork::HoFailureInTarget5gcNgranNodeOrTargetSystem,
            ),
            criticality_diagnostics: None,
        };
        if let Some(bytes) = crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure) {
            self.send_to_association(source_assoc, &bytes).await?;
        }
        Ok(())
    }

    /// One SMF answered an N2 handover step for one session (#964). A stale answer, for a
    /// preparation since cancelled or superseded, is dropped.
    async fn apply_n2_handover_answer(&mut self, answer: N2HandoverAnswer) -> Result<()> {
        let ue = answer.amf_ue_ngap_id;
        match answer.step {
            N2HandoverStep::Preparing => {
                let Some(prep) = self
                    .ho_preparations
                    .get_mut(&ue)
                    .filter(|p| p.generation == answer.generation)
                else {
                    return Ok(());
                };
                if !prep.awaiting.remove(&answer.psi) {
                    return Ok(());
                }
                match answer.result {
                    Ok(transfer) => prep.ready.push((answer.psi, transfer)),
                    Err(e) => {
                        log::warn!(
                            "HandoverRequired for UE {ue}: PSI {} not handed over: {e}",
                            answer.psi
                        );
                        // #964 review: the SMF may have processed the PREPARING before
                        // its answer was lost; CANCELLED leaves it no preparation.
                        self.cancel_sessions_at_smfs(ue, &[answer.psi], "HO_FAILURE");
                    }
                }
                if self
                    .ho_preparations
                    .get(&ue)
                    .is_some_and(|p| p.awaiting.is_empty())
                {
                    let prep = self.ho_preparations.remove(&ue).expect("present");
                    if prep.ready.is_empty() {
                        return self
                            .fail_handover_preparation(prep.source_assoc, &prep.required)
                            .await;
                    }
                    return self.send_handover_request(prep).await;
                }
            }
            N2HandoverStep::Prepared | N2HandoverStep::AllocationFailed => {
                let Some(cmd) = self
                    .ho_commands
                    .get_mut(&ue)
                    .filter(|c| c.generation == answer.generation)
                else {
                    return Ok(());
                };
                if !cmd.awaiting.remove(&answer.psi) {
                    return Ok(());
                }
                match (answer.step, answer.result) {
                    (N2HandoverStep::AllocationFailed, Ok(transfer)) => {
                        cmd.released.push((answer.psi, transfer))
                    }
                    (_, Ok(transfer)) => cmd.ready.push((answer.psi, transfer)),
                    (step, Err(e)) => {
                        log::warn!(
                            "HandoverRequestAcknowledge for UE {ue}: PSI {} ({step:?}): {e}",
                            answer.psi
                        );
                        self.cancel_sessions_at_smfs(ue, &[answer.psi], "HO_FAILURE");
                    }
                }
                if self
                    .ho_commands
                    .get(&ue)
                    .is_some_and(|c| c.awaiting.is_empty())
                {
                    let cmd = self.ho_commands.remove(&ue).expect("present");
                    return self.send_handover_command(ue, cmd).await;
                }
            }
        }
        Ok(())
    }

    /// Start the PREPARED step at the SMFs for a target's Acknowledge (#964).
    async fn start_handover_command(
        &mut self,
        target_assoc: u64,
        source_assoc: u64,
        ack: nextgcore_ngap::types::HandoverRequestAcknowledge,
    ) -> Result<()> {
        let ue = ack.amf_ue_ngap_id;
        self.ho_generation += 1;
        let generation = self.ho_generation;
        let mut awaiting = HashSet::new();
        for item in &ack.admitted_list {
            let psi = item.pdu_session_id;
            let Some(sm_ref) = self.sm_context_refs.get(&(ue, psi)).cloned() else {
                continue;
            };
            if !awaiting.insert(psi) {
                continue;
            }
            let (host, port) = self.smf_target_for(ue, psi);
            let transfer = item.transfer.clone();
            self.sbi_offload.spawn_keyed((ue, psi), move || async move {
                let result = crate::sbi_path::call_smf_n2_handover(
                    &host,
                    port,
                    &sm_ref,
                    "PREPARED",
                    Some(("HANDOVER_REQ_ACK", &transfer)),
                    None,
                    None,
                )
                .await
                .and_then(|answer| match answer {
                    Some((t, n2)) if t == "HANDOVER_CMD" => Ok(n2),
                    other => Err(format!(
                        "no Handover Command Transfer in the PREPARED answer ({:?})",
                        other.map(|(t, _)| t)
                    )),
                });
                Some(crate::sbi_offload::SbiOutcome::N2Handover(
                    N2HandoverAnswer {
                        amf_ue_ngap_id: ue,
                        psi,
                        generation,
                        step: N2HandoverStep::Prepared,
                        result,
                    },
                ))
            });
        }
        // The sessions the target could not admit (TS 29.502 §5.2.2.3.4.2): each SMF gets
        // the target's Handover Resource Allocation Unsuccessful Transfer and answers with
        // the Handover Preparation Unsuccessful Transfer the HANDOVER COMMAND's release
        // list carries; the session stays on the source until the UE moves.
        for failed in ack.failed_list.iter().flatten() {
            let psi = failed.pdu_session_id;
            let Some(sm_ref) = self.sm_context_refs.get(&(ue, psi)).cloned() else {
                continue;
            };
            if !awaiting.insert(psi) {
                continue;
            }
            let (host, port) = self.smf_target_for(ue, psi);
            let transfer = failed.transfer.clone();
            self.sbi_offload.spawn_keyed((ue, psi), move || async move {
                let result = crate::sbi_path::call_smf_n2_handover(
                    &host,
                    port,
                    &sm_ref,
                    "PREPARED",
                    Some(("HANDOVER_RES_ALLOC_FAIL", &transfer)),
                    None,
                    None,
                )
                .await
                .and_then(|answer| match answer {
                    Some((t, n2)) if t == "HANDOVER_PREP_FAIL" => Ok(n2),
                    other => Err(format!(
                        "no Handover Preparation Unsuccessful Transfer in the answer ({:?})",
                        other.map(|(t, _)| t)
                    )),
                });
                Some(crate::sbi_offload::SbiOutcome::N2Handover(
                    N2HandoverAnswer {
                        amf_ue_ngap_id: ue,
                        psi,
                        generation,
                        step: N2HandoverStep::AllocationFailed,
                        result,
                    },
                ))
            });
        }
        let pending = HoCommandPending {
            generation,
            deadline: Instant::now() + self.ho_command_wait,
            source_assoc,
            target_assoc,
            target_ran: ack.ran_ue_ngap_id,
            target_to_source_container: ack.target_to_source_container.clone(),
            admitted: ack
                .admitted_list
                .iter()
                .map(|a| (a.pdu_session_id, a.transfer.clone()))
                .collect(),
            awaiting,
            ready: Vec::new(),
            offered: self
                .handover_listed_psis
                .get(&ue)
                .cloned()
                .unwrap_or_default(),
            released: Vec::new(),
        };
        if pending.awaiting.is_empty() {
            return self.send_handover_command(ue, pending).await;
        }
        self.ho_commands.insert(ue, pending);
        Ok(())
    }

    /// The HANDOVER COMMAND to the source, carrying each session's Handover Command
    /// Transfer from its SMF (#964, TS 23.502 §4.9.1.3.2 step 12). With no session left,
    /// the handover cannot go ahead: the source gets a HANDOVER PREPARATION FAILURE, the
    /// target releases what it admitted and the SMFs are told CANCELLED.
    async fn send_handover_command(&mut self, ue: u64, mut cmd: HoCommandPending) -> Result<()> {
        cmd.ready.sort_by_key(|(psi, _)| *psi);
        let Some(state) = self.ue_auth_state.get(ue) else {
            log::warn!("HandoverRequestAcknowledge for UE {ue}: the UE went away");
            return Ok(());
        };
        let ran_ue_ngap_id = state.ran_ue_ngap_id;
        if cmd.ready.is_empty() {
            log::warn!(
                "HandoverRequestAcknowledge for UE {ue}: no admitted session has a Handover \
                 Command Transfer; the handover is failed"
            );
            // The target admitted the UE under this pair, so it is released under it.
            self.handover_target_assoc
                .insert(ue, (cmd.target_assoc, cmd.target_ran));
            self.release_cancelled_handover_target(ue, "HO_FAILURE")
                .await;
            self.forget_handover_preparation(ue);
            let failure = nextgcore_ngap::types::HandoverPreparationFailure {
                amf_ue_ngap_id: ue,
                ran_ue_ngap_id,
                cause: nextgcore_ngap::types::Cause::RadioNetwork(
                    nextgcore_ngap::types::CauseRadioNetwork::HoFailureInTarget5gcNgranNodeOrTargetSystem,
                ),
                criticality_diagnostics: None,
            };
            if let Some(b) = crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure) {
                self.send_to_association(cmd.source_assoc, &b).await?;
            }
            return Ok(());
        }
        // TS 38.413 §9.2.3.2, TS 23.502 §4.9.1.3.2 step 12: every session the source
        // offered that is not handed over goes in the PDU Session Resource to Release
        // List, with its SMF's Handover Preparation Unsuccessful Transfer, or this AMF's
        // own when the SMF gave none. They are deactivated at the SMF once the UE has
        // moved (`complete_handover_at_smfs`).
        let mut offered = cmd.offered.clone();
        offered.extend(cmd.released.iter().map(|(psi, _)| *psi));
        offered.sort_unstable();
        offered.dedup();
        let dropped: Vec<(u8, Vec<u8>)> = offered
            .into_iter()
            .filter(|psi| !cmd.ready.iter().any(|(p, _)| p == psi))
            .filter_map(|psi| {
                cmd.released
                    .iter()
                    .find(|(p, _)| *p == psi)
                    .map(|(_, t)| t.clone())
                    .or_else(|| {
                        crate::ngap_asn1::handover_preparation_unsuccessful_transfer(
                            nextgcore_ngap::types::Cause::RadioNetwork(
                                nextgcore_ngap::types::CauseRadioNetwork::HoFailureInTarget5gcNgranNodeOrTargetSystem,
                            ),
                        )
                    })
                    .map(|t| (psi, t))
            })
            .collect();
        let command = nextgcore_ngap::types::HandoverCommand {
            amf_ue_ngap_id: ue,
            ran_ue_ngap_id,
            handover_type: nextgcore_ngap::types::HandoverType::Intra5gs,
            nas_security_parameters_from_ngran: None,
            pdu_session_list: cmd
                .ready
                .iter()
                .map(
                    |(psi, transfer)| nextgcore_ngap::types::PduSessionResourceHandoverItem {
                        pdu_session_id: *psi,
                        transfer: transfer.clone(),
                    },
                )
                .collect(),
            release_list: (!dropped.is_empty()).then(|| {
                dropped
                    .iter()
                    .map(
                        |(psi, transfer)| nextgcore_ngap::types::PduSessionResourceReleaseItem {
                            pdu_session_id: *psi,
                            transfer: transfer.clone(),
                        },
                    )
                    .collect()
            }),
            target_to_source_container: cmd.target_to_source_container.clone(),
        };
        let source_assoc = cmd.source_assoc;
        match crate::ngap_asn1::build_handover_command_generated(&command).ok_or(()) {
            Ok(bytes) => {
                if let Err(e) = self.send_to_association(source_assoc, &bytes).await {
                    // The source never learns the handover was prepared, so it will not
                    // execute it: the target releases what it admitted and the SMFs are
                    // told the handover failed, rather than both holding a preparation
                    // until their own timers.
                    log::warn!(
                        "HandoverCommand for UE {ue} could not be sent to the source \
                         association {source_assoc} ({e}); the handover is abandoned: the \
                         target association {} releases its prepared context and the SMFs \
                         are told CANCELLED (HO_FAILURE)",
                        cmd.target_assoc
                    );
                    self.handover_target_assoc
                        .insert(ue, (cmd.target_assoc, cmd.target_ran));
                    self.release_cancelled_handover_target(ue, "HO_FAILURE")
                        .await;
                    self.forget_handover_preparation(ue);
                    return Ok(());
                }
                log::info!(
                    "HandoverCommand sent to source association {source_assoc} for UE {ue} \
                     ({} session(s))",
                    cmd.ready.len()
                );
                // Remember where the UE is going. The source gNB may now send an
                // UPLINK RAN STATUS TRANSFER (TS 38.413 §8.4.6) that has to reach
                // this target, and only this point in the procedure knows which
                // association admitted the UE.
                //
                // Recorded only on the success path: if the HandoverCommand never
                // reached the source, the source will not send a status transfer,
                // and a stale target entry would misroute the next handover's.
                //
                // With the RAN UE NGAP ID the TARGET allocated (#740): the relayed
                // status must name the UE as the target knows it.
                self.handover_target_assoc
                    .insert(ue, (cmd.target_assoc, cmd.target_ran));
                // #70 / #964: the sessions the HandoverCommand hands over, completed at
                // the SMF once the UE has actually arrived (Notify).
                for (psi, transfer) in &cmd.admitted {
                    if cmd.ready.iter().any(|(p, _)| p == psi) {
                        self.handover_target_transfers
                            .insert((ue, *psi), transfer.clone());
                    }
                }
                self.handover_dropped_psis
                    .insert(ue, dropped.iter().map(|(psi, _)| *psi).collect());
                // #964 review: a session the target admitted but this handover does not
                // carry (its PREPARED failed or was not answered in time) holds resources
                // at the target; they are released once the UE is there.
                let admitted_not_handed: Vec<u8> = cmd
                    .admitted
                    .iter()
                    .map(|(psi, _)| *psi)
                    .filter(|psi| !cmd.ready.iter().any(|(p, _)| p == psi))
                    .collect();
                if !admitted_not_handed.is_empty() {
                    self.handover_target_release_psis
                        .insert(ue, admitted_not_handed);
                }
            }
            Err(()) => log::error!("Failed to build HandoverCommand"),
        }
        Ok(())
    }

    /// Release what a cancelled intra-5GS handover prepared (#804): a UE Context Release
    /// Command to the target, cause handover-cancelled -- under the id pair its
    /// Acknowledge established, or the AMF UE NGAP ID alone before one (UE-NGAP-IDs) --
    /// and `hoState: CANCELLED` with `smf_cause` to each session's SMF: `HO_CANCEL` for
    /// the source's Handover Cancel, `HO_FAILURE` for a handover this AMF could not carry
    /// out (TS 29.502 §5.2.2.3.4.4).
    async fn release_cancelled_handover_target(
        &mut self,
        amf_ue_ngap_id: u64,
        smf_cause: &'static str,
    ) {
        let target = match (
            self.handover_target_assoc.get(&amf_ue_ngap_id).copied(),
            self.handover_pending_target.get(&amf_ue_ngap_id).copied(),
            self.ho_commands
                .get(&amf_ue_ngap_id)
                .map(|c| (c.target_assoc, c.target_ran)),
        ) {
            (Some((assoc, ran)), _, _) | (None, _, Some((assoc, ran))) => Some((assoc, Some(ran))),
            (None, Some(assoc), None) => Some((assoc, None)),
            (None, None, None) => None,
        };
        if let Some((assoc, ran)) = target {
            match crate::ngap_asn1::build_ue_context_release_command_ids_asn1(
                amf_ue_ngap_id,
                ran,
                ngap_handler::cause_group::RADIO_NETWORK,
                nextgcore_ngap::types::CauseRadioNetwork::HandoverCancelled as i64,
            ) {
                Some(cmd) => match self.send_to_association(assoc, &cmd).await {
                    Ok(()) => log::info!(
                        "Handover of UE {amf_ue_ngap_id} cancelled: UE Context Release \
                         Command (handover-cancelled) to the target association {assoc} \
                         (target RAN UE NGAP ID {ran:?})"
                    ),
                    Err(e) => log::warn!(
                        "Handover of UE {amf_ue_ngap_id} cancelled: the target association \
                         {assoc} could not be told to release its prepared context: {e}"
                    ),
                },
                None => log::error!("Failed to build the target's UE Context Release Command"),
            }
        }
        self.cancel_handover_at_smfs(amf_ue_ngap_id, smf_cause);
    }

    /// `hoState: CANCELLED` with `cause` (TS 29.502 §5.2.2.3.4.4) to the SMF of every
    /// session of the UE's current intra-5GS preparation (#804, #964), keyed per (UE,
    /// PSI) off the NGAP task, so it reaches the SMF after any step still running for
    /// the session and before the next one.
    fn cancel_handover_at_smfs(&mut self, amf_ue_ngap_id: u64, cause: &'static str) {
        let mut psis: Vec<u8> = self
            .handover_prepared_psis
            .get(&amf_ue_ngap_id)
            .cloned()
            .unwrap_or_default();
        if let Some(prep) = self.ho_preparations.get(&amf_ue_ngap_id) {
            psis.extend(prep.awaiting.iter().copied());
            psis.extend(prep.ready.iter().map(|(psi, _)| *psi));
        }
        psis.sort_unstable();
        psis.dedup();
        self.cancel_sessions_at_smfs(amf_ue_ngap_id, &psis, cause);
    }

    /// `hoState: CANCELLED` with `cause` to the SMF of each of `psis`, keyed per (UE, PSI)
    /// so it runs after whatever step is still in flight for the session (#964).
    fn cancel_sessions_at_smfs(&mut self, amf_ue_ngap_id: u64, psis: &[u8], cause: &'static str) {
        for &psi in psis {
            if !self
                .handover_cancelled_psis
                .entry(amf_ue_ngap_id)
                .or_default()
                .insert(psi)
            {
                continue;
            }
            let Some(sm_ref) = self.sm_context_refs.get(&(amf_ue_ngap_id, psi)).cloned() else {
                continue;
            };
            let (host, port) = self.smf_target_for(amf_ue_ngap_id, psi);
            self.sbi_offload
                .spawn_keyed((amf_ue_ngap_id, psi), move || async move {
                    match crate::sbi_path::call_smf_n2_handover(
                        &host,
                        port,
                        &sm_ref,
                        "CANCELLED",
                        None,
                        None,
                        Some(cause),
                    )
                    .await
                    {
                        Ok(_) => log::info!(
                            "UE {amf_ue_ngap_id}: PSI {psi} handover CANCELLED ({cause}) at \
                             the SMF"
                        ),
                        Err(e) => log::warn!(
                            "UE {amf_ue_ngap_id}: PSI {psi} CANCELLED not delivered: {e}"
                        ),
                    }
                    None
                });
        }
    }

    /// The SMF side of a completed intra-5GS handover (#964): `hoState: COMPLETED` for
    /// each handed-over session (TS 29.502 §5.2.2.3.4.3), and `upCnxState: DEACTIVATED`
    /// for each session the HANDOVER COMMAND released instead (TS 23.502 §4.9.1.3.2 step
    /// 10: the SMF deactivates the user plane of a session the target did not accept once
    /// the handover is done; the source NG-RAN, which held it, has been released).
    /// Each call is keyed per (UE, PSI) off the NGAP task. Returns how many COMPLETED
    /// calls were queued.
    fn complete_handover_at_smfs(&mut self, ue: u64, handed_over: &[u8]) -> usize {
        let dropped = self.handover_dropped_psis.remove(&ue).unwrap_or_default();
        let mut queued = 0usize;
        for &psi in handed_over {
            let Some(sm_ref) = self.sm_context_refs.get(&(ue, psi)).cloned() else {
                log::warn!("HandoverNotify for UE {ue}: PSI {psi} has no SM context");
                continue;
            };
            let (host, port) = self.smf_target_for(ue, psi);
            self.sbi_offload.spawn_keyed((ue, psi), move || async move {
                let complete = || {
                    crate::sbi_path::call_smf_n2_handover(
                        &host,
                        port,
                        &sm_ref,
                        "COMPLETED",
                        None,
                        None,
                        None,
                    )
                };
                // #964 review: the source has been released, so a COMPLETED that does not
                // land leaves the downlink pointed at nothing; it is tried once more.
                let mut outcome = complete().await;
                if let Err(e) = &outcome {
                    log::warn!(
                        "UE {ue}: PSI {psi} COMPLETED failed ({e}); retrying once in \
                         {HANDOVER_COMPLETED_RETRY:?}"
                    );
                    tokio::time::sleep(HANDOVER_COMPLETED_RETRY).await;
                    outcome = complete().await;
                }
                match outcome {
                    Ok(_) => log::info!(
                        "UE {ue}: PSI {psi} handover COMPLETED at the SMF; the downlink is on \
                         the target"
                    ),
                    Err(e) => log::warn!(
                        "UE {ue}: PSI {psi} COMPLETED not delivered ({e}); the SMF still \
                         points the downlink at the source"
                    ),
                }
                None
            });
            queued += 1;
        }
        for psi in dropped {
            let Some(sm_ref) = self.sm_context_refs.get(&(ue, psi)).cloned() else {
                continue;
            };
            let (host, port) = self.smf_target_for(ue, psi);
            self.sbi_offload.spawn_keyed((ue, psi), move || async move {
                match crate::sbi_path::call_smf_deactivate_up_connection(&host, port, &sm_ref).await
                {
                    Ok(_) => log::info!(
                        "UE {ue}: PSI {psi}, not handed over, has its user plane deactivated"
                    ),
                    Err(e) => log::warn!(
                        "UE {ue}: PSI {psi}, not handed over, could not be deactivated: {e}"
                    ),
                }
                None
            });
        }
        queued
    }

    /// TS 23.502 §4.9.1.3.2 step 8 (#964 review): "At expiry of the maximum wait time or
    /// when all Nsmf_PDUSession_UpdateSMContext Response messages are received, AMF
    /// continues with the N2 Handover procedure". A preparation or an Acknowledge whose
    /// wait has expired goes on with the sessions that answered; each session still
    /// waiting is not handed over and its SMF is told CANCELLED (HO_FAILURE), keyed after
    /// the step it has not answered. Its late answer is ignored.
    async fn process_handover_deadlines(&mut self) {
        let now = Instant::now();
        let expired: Vec<u64> = self
            .ho_preparations
            .iter()
            .filter(|(_, p)| p.deadline <= now)
            .map(|(ue, _)| *ue)
            .collect();
        for ue in expired {
            let Some(prep) = self.ho_preparations.remove(&ue) else {
                continue;
            };
            let mut late: Vec<u8> = prep.awaiting.iter().copied().collect();
            late.sort_unstable();
            log::warn!(
                "HandoverRequired for UE {ue}: no PREPARING answer within {:?} for PSIs \
                 {late:?}; continuing with PSIs {:?}",
                self.ho_preparation_wait,
                prep.ready.iter().map(|(psi, _)| *psi).collect::<Vec<_>>()
            );
            self.cancel_sessions_at_smfs(ue, &late, "HO_FAILURE");
            let result = if prep.ready.is_empty() {
                self.fail_handover_preparation(prep.source_assoc, &prep.required)
                    .await
            } else {
                self.send_handover_request(prep).await
            };
            if let Err(e) = result {
                log::warn!("HandoverRequired for UE {ue}: continuing after the wait: {e}");
            }
        }
        let expired: Vec<u64> = self
            .ho_commands
            .iter()
            .filter(|(_, c)| c.deadline <= now)
            .map(|(ue, _)| *ue)
            .collect();
        for ue in expired {
            let Some(mut cmd) = self.ho_commands.remove(&ue) else {
                continue;
            };
            let mut late: Vec<u8> = cmd.awaiting.drain().collect();
            late.sort_unstable();
            log::warn!(
                "HandoverRequestAcknowledge for UE {ue}: no PREPARED answer within {:?} for \
                 PSIs {late:?}; commanding the source with PSIs {:?}",
                self.ho_command_wait,
                cmd.ready.iter().map(|(psi, _)| *psi).collect::<Vec<_>>()
            );
            self.cancel_sessions_at_smfs(ue, &late, "HO_FAILURE");
            if let Err(e) = self.send_handover_command(ue, cmd).await {
                log::warn!("HandoverRequestAcknowledge for UE {ue}: after the wait: {e}");
            }
        }
    }

    /// The HANDOVER REQUEST to the target, carrying each session's Handover Request
    /// Transfer from its SMF (#964, TS 23.502 §4.9.1.3.2 step 7).
    async fn send_handover_request(&mut self, prep: HoPreparation) -> Result<()> {
        let HoPreparation {
            source_assoc: association_id,
            target_assoc,
            required,
            mut ready,
            ..
        } = prep;
        ready.sort_by_key(|(psi, _)| *psi);
        let Some(state) = self.ue_auth_state.get(required.amf_ue_ngap_id) else {
            log::warn!(
                "HandoverRequired for UE {}: the UE went away during the preparation",
                required.amf_ue_ngap_id
            );
            return Ok(());
        };
        let (guami_plmn, amf_region, amf_set, amf_pointer) = {
            let ctx_arc = crate::context::amf_self();
            // Read THROUGH the poison: this replaced a `tokio::sync::RwLock`,
            // which cannot poison, so bailing here would be a new failure mode
            // rather than a preserved one (#363).
            let ctx = ctx_arc.read().unwrap_or_else(|e| e.into_inner());
            match ctx.served_guami.first() {
                Some(g) => (
                    g.plmn_id.clone(),
                    g.amf_id.region,
                    g.amf_id.set,
                    g.amf_id.pointer,
                ),
                None => (state.amf_ue.nr_tai.plmn_id.clone(), 2u8, 1u16, 0u8),
            }
        };

        // Advance the forward-security chain for the target gNB (TS 33.501
        // Section 6.9.2.3.3). This MUST NOT copy the stored pair: the target
        // needs an NH the source gNB has never held, which is the whole point
        // of the chain. Shared with the Xn path so the two cannot diverge.
        // Through `with_mut`, because `advance_next_hop` is not a read:
        // it re-derives NH from KAMF and increments the NH Chaining Count
        // (TS 33.501 §6.9.2.3.3). Losing that with a dropped clone would hand the
        // target gNB an NH the AMF does not believe it issued and reuse the same
        // NCC on the next handover, which is exactly the key separation the
        // vertical derivation exists to provide. `expect` is sound: the UE was
        // resolved above and this is the single-threaded NGAP receive loop.
        let (ho_ncc, ho_nh) = self
            .ue_auth_state
            .with_mut(required.amf_ue_ngap_id, |s| s.amf_ue.advance_next_hop())
            .expect("the UE was resolved at the top of this handler");

        // #743: each PDU session goes to the target with ITS OWN S-NSSAI (TS 38.413
        // §9.2.3.4, PDU Session Resource Setup Request Item (HO)), from the session
        // record written at establishment (`record_amf_session`). It used to be the UE's
        // FIRST allowed S-NSSAI for every session, so a UE with sessions on two slices
        // handed the second one over under the wrong slice. The first allowed S-NSSAI
        // stays the fallback for a session the AMF has no record of. One context read,
        // released before anything else touches the context.
        let session_slices: HashMap<u8, crate::context::SNssai> = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            required
                .pdu_session_list
                .iter()
                .filter_map(|p| {
                    let sess = guard.sess_find_by_psi(required.amf_ue_ngap_id, p.pdu_session_id);
                    if sess.is_none() {
                        log::warn!(
                            "HandoverRequired for UE {}: no session record for PSI {}; its \
                             S-NSSAI falls back to the first allowed one",
                            required.amf_ue_ngap_id,
                            p.pdu_session_id
                        );
                    }
                    // SST 0 is no slice: TS 23.501 §5.15.2.2 standardises SST values from
                    // 1, and 0 is what a record whose writer had no S-NSSAI holds
                    // (`SNssai::default()`). It falls back like a missing record rather
                    // than going to the target as a slice it cannot admit.
                    sess.filter(|sess| sess.s_nssai.sst != 0)
                        .map(|sess| (p.pdu_session_id, sess.s_nssai))
                })
                .collect()
        };

        let ho_request = nextgcore_ngap::types::HandoverRequest {
            amf_ue_ngap_id: required.amf_ue_ngap_id,
            handover_type: required.handover_type,
            cause: required.cause,
            ue_ambr: nextgcore_ngap::types::UeAmbrInfo {
                dl: state.amf_ue.ue_ambr.downlink.max(1),
                ul: state.amf_ue.ue_ambr.uplink.max(1),
            },
            ue_security_capabilities: ue_caps_to_ngap_for_ue(&state.amf_ue),
            security_context: nextgcore_ngap::types::SecurityContext {
                next_hop_chaining_count: ho_ncc,
                next_hop: ho_nh,
            },
            pdu_session_list: ready
                .iter()
                .map(
                    |(psi, transfer)| nextgcore_ngap::types::PduSessionResourceSetupItemHoReq {
                        pdu_session_id: *psi,
                        s_nssai: session_slices
                            .get(psi)
                            .or_else(|| state.amf_ue.allowed_nssai.first())
                            .map(|s| nextgcore_ngap::types::SNssai {
                                sst: s.sst,
                                sd: s.sd.map(|sd| sd.to_be_bytes()[1..4].try_into().unwrap()),
                            })
                            .unwrap_or(nextgcore_ngap::types::SNssai { sst: 1, sd: None }),
                        transfer: transfer.clone(),
                    },
                )
                .collect(),
            allowed_nssai: state
                .amf_ue
                .allowed_nssai
                .iter()
                .map(|s| nextgcore_ngap::types::SNssai {
                    sst: s.sst,
                    sd: s.sd.map(|sd| sd.to_be_bytes()[1..4].try_into().unwrap()),
                })
                .collect(),
            source_to_target_container: required.source_to_target_container.clone(),
            guami: nextgcore_ngap::types::Guami {
                plmn_identity: plmn_id_to_ngap_bytes(&guami_plmn),
                amf_region_id: amf_region,
                amf_set_id: amf_set,
                amf_pointer,
            },
        };

        // #417: the GENERATED codec.
        let (racs_id, _) = self.racs_ies_for(required.amf_ue_ngap_id);
        match crate::ngap_asn1::build_handover_request_generated(&ho_request).ok_or(()) {
            Ok(bytes) => {
                // #570: the UE Radio Capability ID, when the UE has one (TS 38.413 §9.2.3.4).
                let bytes = crate::racs::add_capability_ies(bytes, racs_id.as_deref(), None);
                self.handover_prepared_psis.insert(
                    required.amf_ue_ngap_id,
                    ready.iter().map(|(psi, _)| *psi).collect(),
                );
                if let Err(e) = self.send_to_association(target_assoc, &bytes).await {
                    // The target never saw the request: the SMFs that prepared are told
                    // the handover failed, and the source gets its answer now rather than
                    // waiting out TNGRELOCprep.
                    log::warn!(
                        "HandoverRequest for UE {} could not be sent to the target \
                         association {target_assoc} ({e}); the preparation fails: the SMFs \
                         are told CANCELLED (HO_FAILURE) and the source association \
                         {association_id} gets a HANDOVER PREPARATION FAILURE",
                        required.amf_ue_ngap_id
                    );
                    self.cancel_handover_at_smfs(required.amf_ue_ngap_id, "HO_FAILURE");
                    return self
                        .fail_handover_preparation(association_id, &required)
                        .await;
                }
                self.handover_pending_target
                    .insert(required.amf_ue_ngap_id, target_assoc);
                self.handover_listed_psis.insert(
                    required.amf_ue_ngap_id,
                    required
                        .pdu_session_list
                        .iter()
                        .map(|item| item.pdu_session_id)
                        .collect(),
                );
                log::info!(
                    "HandoverRequest forwarded to target association {target_assoc} \
                     for UE {}",
                    required.amf_ue_ngap_id
                );
            }
            Err(()) => {
                log::error!("Failed to build HandoverRequest");
                let failure = nextgcore_ngap::types::HandoverPreparationFailure {
                    amf_ue_ngap_id: required.amf_ue_ngap_id,
                    ran_ue_ngap_id: required.ran_ue_ngap_id,
                    cause: nextgcore_ngap::types::Cause::Protocol(
                        nextgcore_ngap::types::CauseProtocol::Unspecified,
                    ),
                    criticality_diagnostics: None,
                };
                if let Some(b) = crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure)
                {
                    self.send_to_association(association_id, &b).await?;
                }
            }
        }
        Ok(())
    }

    /// Handle a HandoverRequestAcknowledge from the target gNB
    /// (TS 38.413 Section 8.4.2). The AMF stitches the TargetToSource container
    /// into a HandoverCommand back to the source gNB.
    async fn handle_handover_request_acknowledge(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        // #417: the GENERATED codec, TS 38.413 §10.3.4.2 for a response.
        let ack = match crate::ngap_asn1::decode_handover_request_acknowledge_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Some(ei) =
                        crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                    {
                        self.send_to_association(association_id, &ei).await?;
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                // A response: local error handling only (§10.3.4.2).
                log::warn!(
                    "HandoverRequestAcknowledge from association {association_id} \
                     not comprehended: {report:?}"
                );
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(association_id, "Handover Request Acknowledge")
                    .await
            }
        };
        log::info!(
            "HandoverRequestAcknowledge from association {association_id} \
             (amf_ue_ngap_id={}, admitted {} sessions)",
            ack.amf_ue_ngap_id,
            ack.admitted_list.len()
        );

        // #418: an EPS→5GS handover's acknowledge is answered to the MME over N26 (step 14),
        // not to a source gNB -- there is none; the UE is arriving from E-UTRAN.
        if self.eps_ho_in_flight.contains_key(&ack.amf_ue_ngap_id) {
            self.complete_eps_to_5gs_preparation(association_id, &ack)
                .await;
            return Ok(());
        }

        // #742 review: only the target the CURRENT preparation's HandoverRequest went to
        // may answer it. A late Acknowledge from a target whose preparation was cancelled
        // or superseded would otherwise send the source a HandoverCommand for a handover
        // it abandoned and restore that target's session transfers, which the next
        // Notify relays as HANDOVER_COMPLETE.
        if self.handover_pending_target.get(&ack.amf_ue_ngap_id) != Some(&association_id) {
            log::warn!(
                "HandoverRequestAcknowledge for UE {} from association {association_id}, \
                 which is not the target of its current preparation ({:?}); ignored",
                ack.amf_ue_ngap_id,
                self.handover_pending_target.get(&ack.amf_ue_ngap_id)
            );
            return Ok(());
        }

        // Resolve the source gNB association for this UE. The source is the gNB
        // that issued the original HandoverRequired (its NG association is the
        // one currently holding the UE auth state).
        let source_assoc = self
            .ue_auth_state
            .get(ack.amf_ue_ngap_id)
            .map(|s| s.association_id);
        let Some(source_assoc) = source_assoc else {
            log::warn!(
                "HandoverRequestAcknowledge for unknown UE {}; cannot send HandoverCommand",
                ack.amf_ue_ngap_id
            );
            return Ok(());
        };
        // #964, TS 23.502 §4.9.1.3.2 steps 9-11: each admitted session's Handover Request
        // Acknowledge Transfer goes to its SMF with hoState PREPARED; the SMF answers with
        // the Handover Command Transfer the source needs (a different structure, TS 38.413
        // §9.3.4.10 vs §9.3.4.11). A session the target refused is reported with its
        // Handover Resource Allocation Unsuccessful Transfer. The HANDOVER COMMAND follows
        // when every PREPARED is answered (`send_handover_command`).
        self.start_handover_command(association_id, source_assoc, ack)
            .await?;
        Ok(())
    }

    /// Handle an UPLINK RAN STATUS TRANSFER from the source gNB (TS 38.413
    /// §8.4.7) by relaying it to the target as a DOWNLINK RAN STATUS TRANSFER
    /// (§8.4.8).
    ///
    /// This is the PDCP SN/HFN status the target needs to resume the DRBs without
    /// losing or duplicating packets. It used to be accepted and dropped (and
    /// before that, answered with an ErrorIndication), so lossless handover was
    /// not lossless: every mobility event lost the in-flight user-plane data the
    /// container exists to preserve.
    ///
    /// The transparent container is relayed **byte-for-byte**; the AMF has no
    /// business interpreting it (see `RanStatusTransfer::container`).
    /// Returns the association the status was relayed to, or `None` when there
    /// was nothing to relay it to. The return value **is** the routing decision,
    /// which is what makes this testable: the relay itself goes out over SCTP and
    /// a test with no live association cannot observe the bytes.
    async fn handle_uplink_ran_status_transfer(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<Option<u64>> {
        // #417: the GENERATED codec, TS 38.413 §10.3.4.2 for a Class 2
        // message with no response.
        let transfer = match crate::ngap_asn1::decode_uplink_ran_status_transfer_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    self.send_criticality_error_indication(association_id, &report)
                        .await?;
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                self.send_criticality_error_indication(association_id, &report)
                    .await?;
                return Ok(None);
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                self.report_transfer_syntax_error(association_id, "Uplink RAN Status Transfer")
                    .await?;
                return Ok(None);
            }
        };

        let Some(&(target_assoc, target_ran_ue_ngap_id)) =
            self.handover_target_assoc.get(&transfer.amf_ue_ngap_id)
        else {
            // No handover in flight for this UE. Log and drop: the AMF must not
            // invent an NGAP error toward the gNB for a procedure that needs no
            // response, which is the same rule the uplink NRPPa relay follows.
            log::warn!(
                "UPLINK RAN STATUS TRANSFER for UE {} with no handover in flight; \
                 nothing to relay it to",
                transfer.amf_ue_ngap_id
            );
            return Ok(None);
        };

        if target_assoc == association_id {
            log::warn!(
                "UPLINK RAN STATUS TRANSFER for UE {} arrived from the association \
                 recorded as its handover target ({target_assoc}); not relaying it back \
                 to its own sender",
                transfer.amf_ue_ngap_id
            );
            return Ok(None);
        }

        // #740: the target names the UE by the RAN UE NGAP ID IT allocated, returned in
        // the HandoverRequestAcknowledge (TS 38.413 §8.4.2.2, §9.2.3.5); the source's
        // id is meaningless there. Relaying it unchanged made the target see an
        // inconsistent UE NGAP ID pair (§10.6) or, worse, address another UE's PDCP
        // state. The AMF UE NGAP ID is the same on both legs.
        let transfer = crate::ngap_asn1::RanStatusRelay {
            ran_ue_ngap_id: target_ran_ue_ngap_id,
            ..transfer
        };
        match crate::ngap_asn1::build_downlink_ran_status_transfer_generated(&transfer).ok_or(()) {
            Ok(bytes) => {
                // A failed send to the TARGET is not a reason to abort handling of
                // the SOURCE's association, so it is logged rather than propagated.
                // The handover will fall back to lossy resumption, which is the
                // pre-existing behaviour, instead of tearing down an NG interface
                // that is working.
                if let Err(e) = self.send_to_association(target_assoc, &bytes).await {
                    log::error!(
                        "Failed to deliver the relayed RAN status for UE {} to \
                         handover target {target_assoc}: {e}",
                        transfer.amf_ue_ngap_id
                    );
                } else {
                    log::info!(
                        "Relayed RAN status ({} DRBs) for UE {} from association \
                         {association_id} to handover target {target_assoc}",
                        transfer
                            .container
                            .dr_bs_subject_to_status_transfer_list
                            .0
                            .len(),
                        transfer.amf_ue_ngap_id
                    );
                }
            }
            Err(()) => return Ok(None),
        }
        Ok(Some(target_assoc))
    }

    /// Handle a HandoverFailure from the target gNB (TS 38.413 Section 8.4.2).
    /// Resource allocation failed at the target; relay a
    /// HandoverPreparationFailure to the source gNB so it aborts T304.
    async fn handle_handover_failure(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        // #417: the GENERATED codec, TS 38.413 §10.3.4.2 for a response.
        let failure = match crate::ngap_asn1::decode_handover_failure_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Some(ei) =
                        crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                    {
                        self.send_to_association(association_id, &ei).await?;
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                // A response: local error handling only (§10.3.4.2).
                log::warn!("HandoverFailure from association {association_id} not comprehended: {report:?}");
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                return self
                    .report_transfer_syntax_error(association_id, "Handover Failure")
                    .await
            }
        };
        log::warn!(
            "HandoverFailure from association {association_id} (amf_ue_ngap_id={}, cause={:?})",
            failure.amf_ue_ngap_id,
            failure.cause
        );
        // #418: the target gNB refused an EPS→5GS handover. TS 23.502 §4.11.1.2.2.2 step 14:
        // "In the case of Handover Failure in step 10, the target AMF provides to the MME the
        // failure related information".
        if let Some(in_flight) = self.eps_ho_in_flight.remove(&failure.amf_ue_ngap_id) {
            self.abandon_eps_to_5gs_handover(
                failure.amf_ue_ngap_id,
                in_flight,
                "the target gNB answered HandoverFailure",
            )
            .await;
            return Ok(());
        }
        // #742 review: a Failure from a target that is not the current preparation's
        // (a late answer to a cancelled or superseded one) must not abort the current one.
        if self.handover_pending_target.get(&failure.amf_ue_ngap_id) != Some(&association_id) {
            log::warn!(
                "HandoverFailure for UE {} from association {association_id}, which is not \
                 the target of its current preparation; ignored",
                failure.amf_ue_ngap_id
            );
            return Ok(());
        }
        // The target refused the UE, so there is no longer anywhere to relay a RAN
        // status transfer to. Dropped first and unconditionally: a stale entry
        // would misroute the NEXT handover's status transfer for this UE to a gNB
        // that already rejected it, and that must not hinge on whether the
        // preparation failure reached the source. The per-session transfers go with
        // it (#742).
        // #964, TS 29.502 §5.2.2.3.4.2: the target refused, so each session's SMF is told
        // the handover is CANCELLED with cause HO_FAILURE.
        self.cancel_handover_at_smfs(failure.amf_ue_ngap_id, "HO_FAILURE");
        self.forget_handover_preparation(failure.amf_ue_ngap_id);
        let source = self
            .ue_auth_state
            .get(failure.amf_ue_ngap_id)
            .map(|s| (s.association_id, s.ran_ue_ngap_id));
        if let Some((source_assoc, ran_ue_ngap_id)) = source {
            let prep_failure = nextgcore_ngap::types::HandoverPreparationFailure {
                amf_ue_ngap_id: failure.amf_ue_ngap_id,
                ran_ue_ngap_id,
                cause: failure.cause,
                criticality_diagnostics: None,
            };
            if let Some(bytes) =
                crate::ngap_asn1::build_handover_preparation_failure_asn1(&prep_failure)
            {
                self.send_to_association(source_assoc, &bytes).await?;
            }
        }
        Ok(())
    }

    /// Handle a HandoverNotify from the target gNB (TS 38.413 Section 8.4.3):
    /// the UE has successfully arrived. The AMF updates the UE's serving cell
    /// location and (in a full deployment) releases the source-side resources.
    async fn handle_handover_notify(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<HandoverCompletion> {
        // #417: the GENERATED codec, TS 38.413 §10.3.4.2 for a procedure with no
        // response. `user_location_info` is `None` when the ULI -- criticality
        // ignore -- is absent or not NR; the serving location then stays as it was.
        let notify = match crate::ngap_asn1::decode_handover_notify_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message: (amf_ue_ngap_id, ran_ue_ngap_id, user_location_info),
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Some(ei) =
                        crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                    {
                        self.send_to_association(association_id, &ei).await?;
                    }
                }
                HandoverNotifyDecoded {
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    user_location_info,
                }
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!("HandoverNotify from association {association_id} rejected: {report:?}");
                if let Some(ei) = crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                {
                    self.send_to_association(association_id, &ei).await?;
                }
                return Ok(HandoverCompletion::default());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                self.report_transfer_syntax_error(association_id, "Handover Notify")
                    .await?;
                return Ok(HandoverCompletion::default());
            }
        };
        log::info!(
            "HandoverNotify from association {association_id} (amf_ue_ngap_id={}, ran_ue_ngap_id={})",
            notify.amf_ue_ngap_id,
            notify.ran_ue_ngap_id
        );
        // #803 / #739: a Notify is accepted only from the target this AMF prepared, under
        // the RAN UE NGAP ID that target allocated in its Acknowledge (TS 38.413 §8.4.3,
        // §10.6). For an EPS->5GS handover that is the UE's recorded target; otherwise the
        // Acknowledge's (association, RAN UE NGAP ID). Anything else -- no handover in
        // flight, a stale or duplicate Notify, another gNB -- would move the UE's serving
        // connection to the sender and release the real one, so it is dropped with an
        // Error Indication and changes nothing.
        let expected = if self.eps_ho_in_flight.contains_key(&notify.amf_ue_ngap_id) {
            self.ue_auth_state
                .get(notify.amf_ue_ngap_id)
                .map(|s| (s.association_id, s.ran_ue_ngap_id))
        } else {
            self.handover_target_assoc
                .get(&notify.amf_ue_ngap_id)
                .copied()
        };
        if expected != Some((association_id, notify.ran_ue_ngap_id)) {
            let cause = if expected.is_some_and(|(assoc, _)| assoc == association_id) {
                ngap_gen::CauseRadioNetwork::INCONSISTENT_REMOTE_UE_NGAP_ID
            } else {
                ngap_gen::CauseRadioNetwork::UNKNOWN_LOCAL_UE_NGAP_ID
            };
            log::warn!(
                "HandoverNotify for UE {} from association {association_id} (RAN UE NGAP ID \
                 {}) is not from the prepared target ({expected:?}); dropped, Error Indication",
                notify.amf_ue_ngap_id,
                notify.ran_ue_ngap_id
            );
            self.send_error_indication(
                association_id,
                Some(notify.amf_ue_ngap_id),
                Some(notify.ran_ue_ngap_id),
                ngap_gen::Cause::RadioNetwork(ngap_gen::CauseRadioNetwork(cause)),
            )
            .await?;
            return Ok(HandoverCompletion::default());
        }
        // #70: the SOURCE identity, captured BEFORE the serving association is moved to
        // the target below. After that move it is unrecoverable, and it is exactly what the
        // UEContextReleaseCommand has to be addressed to — TS 38.413 §8.4.3 has the AMF
        // release the source NG-RAN UE context once the UE has arrived, and before #70
        // nothing did, so every N2 handover leaked a source RAN context.
        //
        // #803: compared as the (association, RAN UE NGAP ID) PAIR. An intra-gNB N2
        // handover keeps the association and changes the RAN UE NGAP ID, and its source
        // context needs releasing just the same; comparing associations alone left it to
        // the gNB's own TNGRELOCoverall.
        let source = self
            .ue_auth_state
            .get(notify.amf_ue_ngap_id)
            .map(|s| (s.association_id, s.ran_ue_ngap_id))
            .filter(|pair| *pair != (association_id, notify.ran_ue_ngap_id));

        let updated = self.ue_auth_state.with_mut(notify.amf_ue_ngap_id, |state| {
            // Move the serving association/RAN-UE-NGAP-ID and location to the
            // target now that the UE has arrived (TS 23.502 Section 4.9.1.3).
            state.association_id = association_id;
            state.ran_ue_ngap_id = notify.ran_ue_ngap_id;
            // #738 review: the UE has ARRIVED on the target, so it is CM-CONNECTED
            // whatever happened to the source leg meanwhile. A source Release Complete
            // that came BEFORE this Notify (a source-raised release mid-execution) was
            // the serving leg at the time and idled the UE and armed the mobile
            // reachable timer; left in place, a connected UE would be paged and later
            // implicitly deregistered.
            state.cm_idle = false;
            state.reachability = None;
            // #406: was this same unpacking written out inline. Shared with the Uplink NAS
            // Transport and PathSwitchRequest sites now, so the three cannot reassemble the
            // big-endian TAC differently. Behaviour here is unchanged — this was the one
            // site that already did it correctly, and it is the reference the other two
            // were measured against.
            if let Some(location) = &notify.user_location_info {
                apply_user_location(&mut state.amf_ue, location);
            }
            log::info!(
                "UE {} relocated to target gNB (association {association_id})",
                notify.amf_ue_ngap_id
            );
        });
        // `with_mut` answers `None` when there was no such UE, so the
        // unknown-UE branch reads off its return value rather than a second
        // lookup -- one lock acquisition, and no window in which the UE could be
        // released between the update and the check.
        if updated.is_none() {
            log::warn!(
                "HandoverNotify for unknown UE {}; ignoring",
                notify.amf_ue_ngap_id
            );
        }

        // #400: PRESENCE_IN_AOI_REPORT — **the transition site**.
        //
        // TS 29.518 §6.2 names the trigger as a transition, not a state: the consumer
        // receives *"the current present state of a UE in a specific Area of Interest
        // (AOI), and notification when a specified UE enters or leaves the specified
        // area"* (`29518-k00.txt:23968-23978`). A handover is where this AMF observes a UE
        // moving while CONNECTED; **#406 added the other half**, the UE that moved while
        // CM-IDLE, which `handle_service_request_nas` now reports (see the note there).
        // Until #406 this site was the only one, because the Service Request path could not
        // learn a new location at all.
        //
        // Fired AFTER the `with_mut` above, deliberately: that closure is what writes the
        // TARGET's TAI and cell identity, so evaluating before it would compare the
        // subscribed areas against where the UE USED to be and report the transition
        // backwards.
        //
        // The emitter applies §5.3.1's change rule (*"In subsequent notifications, the
        // AMF shall only report the UE(s) whose presence status has changed compared to
        // the previous notification sent by the AMF"*, `:4895-4897`), so a relocation
        // WITHIN one area sends nothing. Without that gate this site would notify on
        // every handover regardless of whether presence changed, which is the
        // "plausible-but-wrong moment" #400 was filed to avoid.
        //
        // #400's CEILING HERE — *"the SERVICE REQUEST path does NOT fire these, because
        // `parse_uplink_nas_transport_asn1` discards the `UserLocationInformation`"* — was
        // LIFTED by #406 rather than reworded. That parser now keeps the IE and
        // `handle_uplink_nas_transport` writes both `nr_tai` and `nr_cgi` from it, so the
        // Service Request is a real location-learning moment and fires these two as well.
        // The reasoning for firing there is at that site.
        //
        // Nor is this still `nr_cgi`'s only production writer. #406 gave it four: this
        // site, `handle_uplink_nas_transport`, `handle_path_switch_request` (the Xn
        // handover, which produces no HandoverNotify at all and was silently discarding a
        // mandatory location) and `handle_initial_ue_message` (which parsed the cell
        // identity and logged it). `namf_server::ue_ncgi_is_known` still guards a DEFAULT
        // cell id, but the reason is now "never learned" in general rather than "no
        // handover yet".
        if let Some(state) = self.ue_auth_state.get(notify.amf_ue_ngap_id) {
            crate::namf_server::fire_presence_in_aoi_report(&state.amf_ue);
        }
        // A relocation can move a UE into or out of a counted area, so the per-area
        // totals change even though the served population did not.
        crate::namf_server::fire_ues_in_area_report();

        // #418: an EPS→5GS handover completes toward the MME, not a source gNB
        // (TS 23.502 §4.11.1.2.2.3): the SMFs are told the handover completed and the source
        // MME gets the Forward Relocation Complete Notification. There is no source NG-RAN
        // context to release -- the source was an eNB, released by the MME.
        if let Some(in_flight) = self.eps_ho_in_flight.remove(&notify.amf_ue_ngap_id) {
            let sessions_relayed = self
                .finish_eps_to_5gs_handover(notify.amf_ue_ngap_id, in_flight)
                .await;
            return Ok(HandoverCompletion {
                sessions_relayed,
                source_context: None,
                source_release_sent: false,
                source_release_deferred: false,
            });
        }

        // #70 / #964: switch the core-side DL path to the target (TS 23.502 §4.9.1.3.3
        // steps 6-12, TS 29.502 §5.2.2.3.4.3): `hoState: COMPLETED` to the SMF of each
        // handed-over session. The SMF learned the target's DL tunnel at PREPARED, so
        // COMPLETED carries no N2 SM information. Done HERE and not at the Acknowledge
        // because until the UE has arrived the source is still serving it. Keyed per
        // (UE, PSI), so it reaches the SMF after that session's PREPARED.
        let ue = notify.amf_ue_ngap_id;
        let mut handed_over: Vec<u8> = self
            .handover_target_transfers
            .keys()
            .filter(|(u, _)| *u == ue)
            .map(|(_, psi)| *psi)
            .collect();
        handed_over.sort_unstable();
        if handed_over.is_empty() {
            log::warn!(
                "HandoverNotify for UE {ue}: no session was handed over, so no SMF is told \
                 the handover completed"
            );
        }
        let sessions_relayed = self.complete_handover_at_smfs(ue, &handed_over);
        self.handover_target_transfers.retain(|(u, _), _| *u != ue);
        if let Some(psis) = self.handover_target_release_psis.remove(&ue) {
            match crate::ngap_asn1::build_pdu_session_resource_release_command_asn1(
                ue,
                notify.ran_ue_ngap_id,
                &psis,
            ) {
                Some(cmd) => match self.send_to_association(association_id, &cmd).await {
                    Ok(()) => log::info!(
                        "HandoverNotify for UE {ue}: PDU Session Resource Release Command \
                         to the target for PSIs {psis:?}, admitted there but not handed over"
                    ),
                    Err(e) => log::warn!(
                        "HandoverNotify for UE {ue}: the target could not be told to \
                         release PSIs {psis:?}: {e}"
                    ),
                },
                None => log::error!("Failed to build the PDU Session Resource Release Command"),
            }
        }

        // #70: release the SOURCE NG-RAN UE context (TS 38.413 §8.4.3).
        //
        // NOT via `release_ue`, which removes `ue_auth_state` — the UE has not gone away,
        // it has MOVED, and dropping its context here would deregister a UE that is
        // registered and served by the target. Only the source gNB's copy is released.
        let mut source_release_sent = false;
        // #806, TS 23.502 §4.9.1.3.3: at the Handover Notify "a timer ... is started to
        // supervise when resources in S-RAN shall be release[d]" (step 6a), and step 14a
        // releases the source "after the timer in step 6a expires" -- so the source is
        // kept, for in-flight forwarding, for the hold after THIS Notify. 0 releases now.
        let hold_until = (!self.handover_source_hold.is_zero())
            .then(|| Instant::now() + self.handover_source_hold);
        let mut source_release_deferred = false;
        if let (Some((source_assoc, source_ran_ue_id)), Some(deadline)) = (source, hold_until) {
            self.pending_source_releases.push(PendingSourceRelease {
                deadline,
                amf_ue_ngap_id: notify.amf_ue_ngap_id,
                association_id: source_assoc,
                ran_ue_ngap_id: source_ran_ue_id,
            });
            source_release_deferred = true;
            log::info!(
                "UE {}: source release on association {source_assoc} deferred {:?} to the \
                 step 6a timer (TS 23.502 §4.9.1.3.3 step 14a)",
                notify.amf_ue_ngap_id,
                deadline.saturating_duration_since(Instant::now())
            );
        } else if let Some((source_assoc, source_ran_ue_id)) = source {
            if let Some(cmd) = crate::ngap_asn1::build_ue_context_release_command_asn1(
                notify.amf_ue_ngap_id,
                source_ran_ue_id,
                ngap_handler::cause_group::RADIO_NETWORK,
                nextgcore_ngap::types::CauseRadioNetwork::SuccessfulHandover as i64,
            ) {
                // A failed send must not abort the procedure: the UE has already arrived
                // and the core path is switched, so returning an error here would leave the
                // handover half-reported. The source context leak is logged instead.
                match self.send_to_association(source_assoc, &cmd).await {
                    Ok(()) => {
                        source_release_sent = true;
                        log::info!(
                            "UE Context Release Command sent to SOURCE association \
                             {source_assoc} for UE {} (source \
                             ran_ue_ngap_id={source_ran_ue_id}, cause successful-handover)",
                            notify.amf_ue_ngap_id
                        );
                    }
                    Err(e) => log::warn!(
                        "Could not release the SOURCE context for UE {} on association \
                         {source_assoc}: {e}",
                        notify.amf_ue_ngap_id
                    ),
                }
            }
        } else {
            log::debug!(
                "HandoverNotify for UE {} arrived on the association already serving it; \
                 no source context to release",
                notify.amf_ue_ngap_id
            );
        }

        // Handover complete: `ue_auth_state` now names the target itself, so the
        // separate target record has served its purpose. Leaving it would keep the
        // relay pointing at the (now serving) gNB after the procedure ended.
        self.handover_target_assoc.remove(&notify.amf_ue_ngap_id);
        self.handover_pending_target.remove(&notify.amf_ue_ngap_id);
        Ok(HandoverCompletion {
            sessions_relayed,
            source_context: source,
            source_release_sent,
            source_release_deferred,
        })
    }
}

/// What a HandoverNotify actually completed (#70).
///
/// Returned rather than logged for the same reason
/// `handle_uplink_ran_status_transfer` returns its relay target: the two things this
/// handler now does — telling the SMF the target DL tunnel and releasing the source NG-RAN
/// context — are both outbound sends, and a test that asserted on log lines would pass for
/// a handler that logged without sending. TS 38.413 §8.4.3 and TS 23.502 §4.9.1.3.3 step 12
/// require both, so both are reported.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct HandoverCompletion {
    /// PDU sessions whose target DL tunnel the SMF accepted. For an EPS→5GS handover
    /// (#945), the PDU sessions whose SMF was sent COMPLETED: that update runs off the
    /// NGAP task after the Forward Relocation Complete Notification, and is not awaited.
    pub sessions_relayed: usize,
    /// `(association, source RAN-UE-NGAP-ID)` the release command was ADDRESSED to.
    ///
    /// `None` when the notify arrived on the association already serving the UE — an
    /// intra-gNB case with no separate source context to release.
    ///
    /// Separate from [`Self::source_release_sent`] on purpose: which source to release is a
    /// DECISION made from state that the relocation immediately overwrites, and whether the
    /// datagram left is a property of the SCTP association. A test can drive the first
    /// without a live gNB; only an E2E can drive the second, and collapsing them into one
    /// field would make the decision untestable.
    pub source_context: Option<(u64, u32)>,
    /// Whether the release command actually reached the source association.
    pub source_release_sent: bool,
    /// Whether the release was deferred to the step 6a timer (#806); it is then sent by
    /// the poll loop when that timer expires.
    pub source_release_deferred: bool,
}

/// A source NG-RAN UE context waiting for the step 6a timer before its Release Command
/// (#806, TS 23.502 §4.9.1.3.3 step 14a).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PendingSourceRelease {
    deadline: Instant,
    amf_ue_ngap_id: u64,
    association_id: u64,
    ran_ue_ngap_id: u32,
}

/// Default of the step 6a timer (#806): long enough for in-flight downlink to drain over
/// the forwarding path, short against the gNB's own TNGRELOCoverall.
const DEFAULT_HANDOVER_SOURCE_HOLD: Duration = Duration::from_secs(2);

/// `AMF_HANDOVER_SOURCE_HOLD_MS`, else [`DEFAULT_HANDOVER_SOURCE_HOLD`]. A test that
/// wants the release at the Notify sets `NgapServer::handover_source_hold` itself.
fn handover_source_hold_from_env() -> Duration {
    match std::env::var("AMF_HANDOVER_SOURCE_HOLD_MS") {
        Ok(v) => v
            .trim()
            .parse::<u64>()
            .map(Duration::from_millis)
            .unwrap_or_else(|_| {
                log::warn!(
                    "AMF_HANDOVER_SOURCE_HOLD_MS={v:?} is not a number of milliseconds; using \
                 {DEFAULT_HANDOVER_SOURCE_HOLD:?}"
                );
                DEFAULT_HANDOVER_SOURCE_HOLD
            }),
        Err(_) => DEFAULT_HANDOVER_SOURCE_HOLD,
    }
}

/// An EPS→5GS handover between the HandoverRequest and its completion (#418).
pub(crate) struct EpsHoInFlight {
    /// The N26 server step 14's response and the Complete Notification leave from.
    server: Arc<crate::n26_path::N26Server>,
    /// The Forward Relocation Request's sequence number, echoed by the response.
    seq: u32,
    /// The MME's N26 address and control-plane TEID.
    mme_peer: SocketAddr,
    mme_teid: u32,
    /// The PDN connections prepared at their SMFs.
    sessions: Vec<crate::n26_path::EpsHoSession>,
    /// The Forward Relocation Request has been answered (accepted) and the target gNB's
    /// RAN UE NGAP ID learned from its acknowledge (#592).
    answered: bool,
}

/// What a Relocation Cancel Request did (#592), returned for assertion.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EpsHandoverCancel {
    /// The preparation was released.
    Released {
        /// The arriving UE's AMF UE NGAP ID.
        amf_ue_ngap_id: u64,
        /// The UE Context Release Command and the target association it went to.
        release: Option<(u64, Vec<u8>)>,
        /// SM contexts the SMFs were told are CANCELLED.
        sessions_cancelled: usize,
    },
    /// No preparation matched; answered "IMSI/IMEI not known".
    Unknown,
}

/// Where an EPS→5GS HandoverRequest went, or why it did not (#418).
///
/// The decision is returned so it can be asserted without a connected gNB; the send
/// itself is a property of the SCTP association.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EpsHandoverStart {
    /// The HandoverRequest was built for the target association.
    Requested {
        /// The AMF UE NGAP ID allocated for the arriving UE.
        amf_ue_ngap_id: u64,
        /// The target gNB's association.
        target_association: u64,
    },
    /// Refused to the MME with this cause.
    Refused {
        /// GTPv2-C cause.
        cause: u8,
    },
}

/// The connected gNB a Forward Relocation Request's Target Identification names (#418).
///
/// Matched on the **whole** Global gNB ID — PLMN, gNB ID and its bit length — because a gNB
/// ID is only unique within its PLMN and at its own length: TS 38.413 §9.3.1.6 makes the
/// length part of the identity, and two gNBs with IDs 0x01 at 22 and at 32 bits are
/// different nodes.
pub(crate) fn eps_handover_target_association(
    sessions: &HashMap<u64, GnbSession>,
    target: &crate::n26_eps_to_5gs::TargetGnb,
) -> Option<u64> {
    let plmn = crate::ngap_asn1::decode_plmn_id(&target.plmn_bcd);
    sessions
        .iter()
        .find(|(_, s)| {
            s.gnb.gnb_id_presence
                && s.gnb.gnb_id == target.gnb_id
                && s.gnb.gnb_id_len == target.gnb_id_len
                && s.gnb.plmn_id == plmn
        })
        .map(|(assoc, _)| *assoc)
}

/// Seed the arriving UE's context from an EPS→5GS preparation (#418).
///
/// The mapped 5G security context of TS 33.501 §8.4.2 step 3, field by field: K_AMF' and
/// its NAS keys, the ngKSI (value from the eKSI, type **mapped**, §8.6.2), 5G NAS COUNTs of
/// 0 with the downlink advanced once for the NAS Container, the selected 5G algorithms, the
/// UE's security capabilities, and the stored `{NCC = 1, NH}` pair of step 4. Plus the
/// identities the MME sent and the location the target gNB serves, so the UE is addressable
/// and resolvable by SUPI before it registers.
pub(crate) fn seed_eps_to_5gs_ue(ue: &mut AmfUe, prep: &crate::n26_path::EpsToFivegsPreparation) {
    let m = &prep.mapped;
    ue.supi = prep.supi.clone();
    ue.pei = prep.pei.clone();
    ue.kamf = m.kamf;
    ue.knas_int = m.knas_int;
    ue.knas_enc = m.knas_enc;
    ue.ul_count = 0;
    ue.dl_count = m.dl_count;
    ue.selected_int_algorithm = m.nia;
    ue.selected_enc_algorithm = m.nea;
    ue.nas.amf_ksi = m.ngksi;
    // TSC = 1: "mapped security context" (TS 24.501 §9.11.3.32), §8.6.2.
    ue.nas.amf_tsc = 1;
    ue.security_context_available = true;
    ue.ue_security_capability = crate::context::UeSecurityCapability {
        ea: m.ue_5g_caps.0,
        ia: m.ue_5g_caps.1,
        eea: m.ue_eps_caps.0,
        eia: m.ue_eps_caps.1,
    };
    ue.ue_network_capability = crate::context::UeNetworkCapability {
        eea: m.ue_eps_caps.0,
        eia: m.ue_eps_caps.1,
    };
    ue.nhcc = crate::n26_eps_to_5gs::STORED_NCC_AFTER_HANDOVER_REQUEST;
    ue.nh = m.stored_nh;
    ue.nr_tai = crate::context::Tai5gs {
        plmn_id: crate::ngap_asn1::decode_plmn_id(&prep.target.plmn_bcd),
        tac: prep.target.tac,
    };
    // Step 7: "The AMF stores also the allocated EBI(s) associated to the PDU Session ID."
    ue.assigned_ebis = prep
        .sessions
        .iter()
        .flat_map(|sess| {
            let psi = sess.created.pdu_session_id;
            let with_arp: Vec<crate::context::AssignedEbi> = sess
                .created
                .allocated_ebi_arps
                .iter()
                .map(|(ebi, arp)| crate::context::AssignedEbi {
                    ebi: *ebi,
                    pdu_session_id: psi,
                    arp: arp.clone(),
                })
                .collect();
            if !with_arp.is_empty() {
                return with_arp;
            }
            // This tree's SMF answers with `ebiQfiMapping` and no ARP. The EBI is still the
            // SMF's allocation and is stored; the ARP is the lowest priority, non-pre-empting
            // one, which claims nothing the SMF did not grant.
            sess.created
                .allocated_ebis
                .iter()
                .map(|ebi| crate::context::AssignedEbi {
                    ebi: *ebi,
                    pdu_session_id: psi,
                    arp: crate::context::EbiArp {
                        priority_level: 15,
                        preempt_cap: "NOT_PREEMPT".to_string(),
                        preempt_vuln: "NOT_PREEMPTABLE".to_string(),
                    },
                })
                .collect()
        })
        .collect();
    let ue_ambr = crate::n26_eps_to_5gs::ue_ambr_bps(
        &prep
            .sessions
            .iter()
            .filter_map(|s| s.apn_ambr_kbps)
            .collect::<Vec<_>>(),
        prep.security.subscribed_ue_ambr_kbps,
    );
    if let Some((dl, ul)) = ue_ambr {
        ue.ue_ambr = crate::context::Bitrate {
            downlink: dl,
            uplink: ul,
        };
    }
}

impl NgapServer {
    /// Send the HandoverRequest for each EPS→5GS handover the N26 leg prepared (#418).
    async fn process_fivegs_to_eps_answers(&mut self) {
        for answer in crate::n26_path::drain_fivegs_to_eps_answers() {
            if let Some((association_id, pdu)) = self.fivegs_to_eps_answer_pdu(&answer) {
                if let Err(e) = self.send_to_association(association_id, &pdu).await {
                    log::warn!(
                        "5GS→EPS: the answer for UE {} could not be sent to association \
                         {association_id}: {e}",
                        answer.amf_ue_ngap_id
                    );
                }
            }
        }
    }

    /// TS 23.502 §4.11.1.2.1 step 11 (#476): the PDU the source gNB gets for a 5GS→EPS
    /// preparation the target MME answered, and the association it goes to.
    ///
    /// Accepted → HANDOVER COMMAND (TS 38.413 §9.2.3.2) with the target eNB's container and
    /// the NAS Security Parameters from NG-RAN TS 33.501 §8.3.2 step 7 requires. Refused →
    /// HANDOVER PREPARATION FAILURE, `ho-failure-in-target-5GC-ngran-node-or-target-system`
    /// (§9.3.1.2): the target system said no, which is that cause's meaning. `None` when the
    /// UE is no longer known to this AMF — there is no source to answer.
    pub(crate) fn fivegs_to_eps_answer_pdu(
        &mut self,
        answer: &crate::n26_path::FivegsToEpsAnswer,
    ) -> Option<(u64, Vec<u8>)> {
        let Some((ran_ue_ngap_id, association_id)) = self
            .ue_auth_state
            .get(answer.amf_ue_ngap_id)
            .map(|state| (state.ran_ue_ngap_id, state.association_id))
        else {
            log::warn!(
                "5GS→EPS: the target MME answered for UE {}, which this AMF no longer holds; \
                 nothing is sent",
                answer.amf_ue_ngap_id
            );
            return None;
        };
        // The relay target and any per-session transfers of the preparation are done with
        // either way.
        self.forget_handover_preparation(answer.amf_ue_ngap_id);
        match inter_system_handover_command(&answer.outcome) {
            Some(command) => {
                let pdu = crate::ngap_asn1::build_fivegs_to_eps_handover_command_asn1(
                    answer.amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    command.nas_count_lsb,
                    &command.target_to_source_container,
                )?;
                log::info!(
                    "5GS→EPS: HandoverCommand to the source gNB (association {association_id}) \
                     for UE {}: {}-octet target-to-source container, NAS Security Parameters \
                     from NG-RAN = DL COUNT LSB {:#04x}; bearers {:?} move WITHOUT data \
                     forwarding (none was requested)",
                    answer.amf_ue_ngap_id,
                    command.target_to_source_container.len(),
                    command.nas_count_lsb,
                    command.bearers_without_forwarding
                );
                Some((association_id, pdu))
            }
            None => {
                let failure = nextgcore_ngap::types::HandoverPreparationFailure {
                    amf_ue_ngap_id: answer.amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    cause: nextgcore_ngap::types::Cause::RadioNetwork(
                        nextgcore_ngap::types::CauseRadioNetwork::HoFailureInTarget5gcNgranNodeOrTargetSystem,
                    ),
                    criticality_diagnostics: None,
                };
                let pdu = crate::ngap_asn1::build_handover_preparation_failure_asn1(&failure)?;
                log::warn!(
                    "5GS→EPS: the target refused UE {}'s relocation ({:?}); \
                     HandoverPreparationFailure to the source gNB (association \
                     {association_id}), the UE stays on 5GS",
                    answer.amf_ue_ngap_id,
                    answer.outcome
                );
                Some((association_id, pdu))
            }
        }
    }

    async fn process_eps_to_5gs_cancels(&mut self) {
        for cancel in crate::n26_path::drain_eps_to_5gs_cancels() {
            let _ = self.cancel_eps_to_5gs_handover(cancel).await;
        }
    }

    /// TS 23.502 §4.11.1.2.3 steps 3-5 with this AMF as target (#592): the source MME
    /// cancelled an EPS→5GS handover.
    ///
    /// - step 3: UE CONTEXT RELEASE COMMAND (handover-cancelled) to the target gNB, by AMF
    ///   UE NGAP ID alone if the gNB has not acknowledged yet;
    /// - the Forward Relocation Request, if still unanswered, is refused, so the MME's
    ///   transaction closes rather than retransmitting into a new preparation;
    /// - step 4b: each SMF is told `hoState` CANCELLED (`HO_CANCEL`);
    /// - the UE context, its sessions and the mapped security context are deleted;
    /// - step 5: Relocation Cancel Response, "Request accepted".
    ///
    /// A cancel naming no preparation is answered "IMSI/IMEI not known" (§7.3.17).
    pub(crate) async fn cancel_eps_to_5gs_handover(
        &mut self,
        cancel: crate::n26_path::EpsToFivegsCancel,
    ) -> EpsHandoverCancel {
        let found = self.eps_ho_in_flight.keys().copied().find(|id| {
            let by_supi = cancel.supi.is_some()
                && self
                    .ue_auth_state
                    .get(*id)
                    .is_some_and(|s| s.amf_ue.supi == cancel.supi);
            let by_teid = cancel.amf_teid != 0 && *id as u32 == cancel.amf_teid;
            by_supi || by_teid
        });
        let Some(amf_ue_ngap_id) = found else {
            log::warn!(
                "EPS→5GS: Relocation Cancel Request (seq={}) from MME {} names no preparation \
                 here ({:?}, TEID {:#x}); answering 'IMSI/IMEI not known'",
                cancel.seq,
                cancel.mme_peer,
                cancel.supi,
                cancel.amf_teid
            );
            cancel
                .server
                .send_to_mme(
                    cancel.mme_peer,
                    &crate::n26_eps_to_5gs::build_relocation_cancel_response(
                        cancel.seq,
                        0,
                        crate::n26_path::CAUSE_IMSI_IMEI_NOT_KNOWN,
                    ),
                )
                .await;
            return EpsHandoverCancel::Unknown;
        };
        let Some(in_flight) = self.eps_ho_in_flight.remove(&amf_ue_ngap_id) else {
            return EpsHandoverCancel::Unknown;
        };

        // Step 3.
        let release = self.ue_auth_state.get(amf_ue_ngap_id).and_then(|state| {
            let ran = in_flight.answered.then_some(state.ran_ue_ngap_id);
            crate::ngap_asn1::build_ue_context_release_command_ids_asn1(
                amf_ue_ngap_id,
                ran,
                0, // RadioNetwork
                5, // handover-cancelled (TS 38.413 §9.3.1.2)
            )
            .map(|pdu| (state.association_id, pdu))
        });
        if let Some((association_id, pdu)) = &release {
            if let Err(e) = self.send_to_association(*association_id, pdu).await {
                log::warn!(
                    "EPS→5GS: the UE Context Release Command for cancelled UE {amf_ue_ngap_id} \
                     could not be sent to association {association_id}: {e}"
                );
            }
        }
        if !in_flight.answered {
            in_flight
                .server
                .send_to_mme(
                    in_flight.mme_peer,
                    &crate::n26_eps_to_5gs::build_forward_relocation_response_refusal(
                        in_flight.seq,
                        in_flight.mme_teid,
                        crate::n26_eps_to_5gs::CAUSE_RELOCATION_FAILURE,
                    ),
                )
                .await;
        }
        // Step 4b.
        for sess in &in_flight.sessions {
            if let Err(e) = crate::sbi_path::call_smf_cancel_sm_context_handover(
                &sess.smf.0,
                sess.smf.1,
                &sess.created.sm_context_ref,
            )
            .await
            {
                log::warn!(
                    "EPS→5GS: SMF {}:{} did not confirm the cancel of SM context {}: {e}",
                    sess.smf.0,
                    sess.smf.1,
                    sess.created.sm_context_ref
                );
            }
            self.sm_context_refs
                .remove(&(amf_ue_ngap_id, sess.created.pdu_session_id));
        }
        self.ue_auth_state.remove(amf_ue_ngap_id);
        {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            for sess in guard.sess_list_for_ue(amf_ue_ngap_id) {
                guard.sess_remove(sess.id);
            }
        }
        // Step 5.
        in_flight
            .server
            .send_to_mme(
                in_flight.mme_peer,
                &crate::n26_eps_to_5gs::build_relocation_cancel_response(
                    cancel.seq,
                    in_flight.mme_teid,
                    crate::n26_eps_to_5gs::CAUSE_REQUEST_ACCEPTED,
                ),
            )
            .await;
        log::info!(
            "EPS→5GS: the MME cancelled UE {amf_ue_ngap_id}'s handover; target gNB released, \
             {} SM context(s) cancelled, Relocation Cancel Response sent",
            in_flight.sessions.len()
        );
        EpsHandoverCancel::Released {
            amf_ue_ngap_id,
            release,
            sessions_cancelled: in_flight.sessions.len(),
        }
    }

    async fn process_eps_to_5gs_preparations(&mut self) {
        for prep in crate::n26_path::drain_eps_to_5gs_preparations() {
            let _ = self.start_eps_to_5gs_handover(prep).await;
        }
    }

    /// TS 23.502 §4.11.1.2.2.2 step 9: the HandoverRequest to the target gNB (#418).
    ///
    /// Allocates the AMF UE NGAP ID, seeds the UE context with the mapped 5G security
    /// context and the prepared sessions, and sends the HandoverRequest. Every failure
    /// answers the MME with `Relocation failure` and tells each SMF the preparation is
    /// CANCELLED, so neither is left holding state for a handover that will not happen.
    pub(crate) async fn start_eps_to_5gs_handover(
        &mut self,
        prep: crate::n26_path::EpsToFivegsPreparation,
    ) -> EpsHandoverStart {
        let seq = prep.seq;
        let (amf_ue_ngap_id, target_assoc, bytes) =
            match self.prepare_eps_to_5gs_handover_request(prep).await {
                Ok(prepared) => prepared,
                Err(refused) => return refused,
            };
        match self.send_to_association(target_assoc, &bytes).await {
            Ok(()) => {
                log::info!(
                    "EPS→5GS (seq={seq}): HandoverRequest sent to target gNB association \
                     {target_assoc} for UE {amf_ue_ngap_id} (NCC 0 with the temporary K_gNB, \
                     NSCI and NASC included -- TS 33.501 §8.4.2 step 4)"
                );
                EpsHandoverStart::Requested {
                    amf_ue_ngap_id,
                    target_association: target_assoc,
                }
            }
            Err(e) => {
                log::warn!(
                    "EPS→5GS (seq={seq}): the HandoverRequest could not be sent to association \
                     {target_assoc}: {e}; refusing the relocation"
                );
                match self.eps_ho_in_flight.remove(&amf_ue_ngap_id) {
                    Some(in_flight) => {
                        self.abandon_eps_to_5gs_handover(amf_ue_ngap_id, in_flight, "send failed")
                            .await
                    }
                    None => EpsHandoverStart::Refused {
                        cause: crate::n26_eps_to_5gs::CAUSE_RELOCATION_FAILURE,
                    },
                }
            }
        }
    }

    /// Everything step 9 decides before the send: the target association, the AMF UE NGAP
    /// ID, the seeded UE context, the recorded sessions and the HandoverRequest bytes (#418).
    ///
    /// Split from the send so the decision is assertable without a connected gNB. On `Ok`
    /// the UE, its sessions and the in-flight record are installed; on `Err` the MME has
    /// already been refused and the SMFs told CANCELLED.
    pub(crate) async fn prepare_eps_to_5gs_handover_request(
        &mut self,
        prep: crate::n26_path::EpsToFivegsPreparation,
    ) -> std::result::Result<(u64, u64, Vec<u8>), EpsHandoverStart> {
        let target_assoc = {
            let sessions = self.sessions.read().await;
            eps_handover_target_association(&sessions, &prep.target)
        };
        let amf_ue_ngap_id = crate::context::amf_self()
            .read()
            .unwrap_or_else(|e| e.into_inner())
            .next_amf_ue_ngap_id();
        let in_flight = EpsHoInFlight {
            server: Arc::clone(&prep.server),
            seq: prep.seq,
            mme_peer: prep.mme_peer,
            mme_teid: prep.mme_teid,
            sessions: prep.sessions.clone(),
            answered: false,
        };
        let Some(target_assoc) = target_assoc else {
            log::warn!(
                "EPS→5GS (seq={}): target gNB {:#x}/{} bits is not connected to this AMF; \
                 refusing the relocation",
                prep.seq,
                prep.target.gnb_id,
                prep.target.gnb_id_len
            );
            return Err(self
                .abandon_eps_to_5gs_handover(amf_ue_ngap_id, in_flight, "no such target gNB")
                .await);
        };

        let mut state = UeNasContext::new(
            amf_ue_ngap_id,
            0,
            target_assoc,
            crate::context::nas_security_canary(),
        );
        seed_eps_to_5gs_ue(&mut state.amf_ue, &prep);
        let default_nssai = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            guard
                .plmn_support
                .first()
                .and_then(|p| p.s_nssai.first().cloned())
        };
        let sessions: Vec<crate::ngap_asn1::HandoverRequestSession> = prep
            .sessions
            .iter()
            .filter_map(|sess| {
                let s_nssai = sess
                    .created
                    .s_nssai
                    .map(|(sst, sd)| crate::context::SNssai { sst, sd })
                    .or_else(|| default_nssai.clone())?;
                Some(crate::ngap_asn1::HandoverRequestSession {
                    pdu_session_id: sess.created.pdu_session_id,
                    s_nssai,
                    transfer: sess.created.n2_sm_info.clone(),
                })
            })
            .collect();
        let mut allowed_nssai: Vec<crate::context::SNssai> = Vec::new();
        for sess in &sessions {
            if !allowed_nssai
                .iter()
                .any(|s| s.sst == sess.s_nssai.sst && s.sd == sess.s_nssai.sd)
            {
                allowed_nssai.push(sess.s_nssai.clone());
            }
        }
        state.amf_ue.allowed_nssai = allowed_nssai.clone();
        let ue_ambr = (state.amf_ue.ue_ambr.downlink, state.amf_ue.ue_ambr.uplink);
        if sessions.is_empty() || ue_ambr == (0, 0) {
            log::warn!(
                "EPS→5GS (seq={}): the HandoverRequest cannot carry its mandatory IEs (no \
                 S-NSSAI for any session, or no UE-AMBR from the MME); refusing the relocation",
                prep.seq
            );
            return Err(self
                .abandon_eps_to_5gs_handover(
                    amf_ue_ngap_id,
                    in_flight,
                    "unbuildable HandoverRequest",
                )
                .await);
        }

        let request = crate::ngap_asn1::EpsToFivegsHandoverRequest {
            amf_ue_ngap_id,
            ue_ambr_bps: ue_ambr,
            ue_security_capability: state.amf_ue.ue_security_capability.clone(),
            next_hop: prep.mapped.temporary_kgnb,
            nas_container: prep.mapped.nas_container.to_vec(),
            sessions,
            allowed_nssai,
            source_to_target_container: prep.source_to_target_container.clone(),
        };
        let bytes = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            crate::ngap_asn1::build_eps_to_5gs_handover_request_asn1(&guard, &request)
        };
        let Some(bytes) = bytes else {
            return Err(self
                .abandon_eps_to_5gs_handover(
                    amf_ue_ngap_id,
                    in_flight,
                    "HandoverRequest encode failed",
                )
                .await);
        };

        // The UE and its sessions exist from here on: the target gNB may answer at once.
        // Each session is recorded under the S-NSSAI its HandoverRequest item carried,
        // the default one included when the SMF named none (#743 follow-up), so a later
        // N2 handover hands it over under the same slice.
        for sess in &prep.sessions {
            self.sm_context_refs.insert(
                (amf_ue_ngap_id, sess.created.pdu_session_id),
                sess.created.sm_context_ref.clone(),
            );
            let used = request
                .sessions
                .iter()
                .find(|s| s.pdu_session_id == sess.created.pdu_session_id)
                .map(|s| s.s_nssai.clone());
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            if let Some(mut amf_sess) = guard.sess_add(amf_ue_ngap_id, sess.created.pdu_session_id)
            {
                amf_sess.sm_context_ref = Some(sess.created.sm_context_ref.clone());
                if let Some(s_nssai) = used {
                    amf_sess.s_nssai = s_nssai;
                }
                guard.sess_update(&amf_sess);
            }
        }
        self.ue_auth_state.insert(amf_ue_ngap_id, state);
        self.eps_ho_in_flight.insert(amf_ue_ngap_id, in_flight);

        Ok((amf_ue_ngap_id, target_assoc, bytes))
    }

    /// Steps 10-14: the target gNB admitted the UE; tell each SMF (step 11) and answer the
    /// MME with the Forward Relocation Response (step 14), #418.
    ///
    /// Returns the EBIs the response reported as set up, for assertion.
    pub(crate) async fn complete_eps_to_5gs_preparation(
        &mut self,
        association_id: u64,
        ack: &nextgcore_ngap::types::HandoverRequestAcknowledge,
    ) -> Vec<u8> {
        let Some(in_flight) = self.eps_ho_in_flight.get(&ack.amf_ue_ngap_id) else {
            return Vec::new();
        };
        let server = Arc::clone(&in_flight.server);
        let (seq, mme_peer, mme_teid) = (in_flight.seq, in_flight.mme_peer, in_flight.mme_teid);
        let sessions = in_flight.sessions.clone();
        // The gNB's RAN UE NGAP ID is learned here, which is what makes the UE addressable
        // at the target.
        let _ = self.ue_auth_state.with_mut(ack.amf_ue_ngap_id, |state| {
            state.ran_ue_ngap_id = ack.ran_ue_ngap_id;
            state.association_id = association_id;
        });

        let mut bearers = Vec::new();
        // #946: the sessions that do not move, each with why. Their SMFs are told CANCELLED
        // and the AMF forgets them once the relocation is known to go ahead, so execution
        // never sends them COMPLETED and the AMF holds no session the MME did not hand over.
        let mut not_moved: Vec<(&crate::n26_path::EpsHoSession, &str)> = Vec::new();
        for sess in &sessions {
            let psi = sess.created.pdu_session_id;
            let (host, port) = (&sess.smf.0, sess.smf.1);
            match ack.admitted_list.iter().find(|a| a.pdu_session_id == psi) {
                Some(admitted) => {
                    // Step 11: the N2 SM response, the target's
                    // HandoverRequestAcknowledgeTransfer, relayed opaquely.
                    match crate::sbi_path::call_smf_update_sm_context_ho_state(
                        host,
                        port,
                        &sess.created.sm_context_ref,
                        "PREPARED",
                        Some(("HANDOVER_REQ_ACK", &admitted.transfer)),
                    )
                    .await
                    {
                        Ok(elements) => {
                            let from_smf: Vec<_> = elements
                                .iter()
                                .filter_map(|e| {
                                    crate::n26_eps_to_5gs::bearer_context_from_container(e)
                                })
                                .collect();
                            if from_smf.is_empty() {
                                // #946, TS 23.502 §4.11.1.2.2.2 step 12: the EPS Bearer
                                // Setup list "is generated based on the list of accepted
                                // QFI(s)". It is the SMF's statement of which bearers moved,
                                // so an answer without one (or with none usable) confirmed
                                // no bearer. Reporting the allocated EBIs instead told the
                                // MME to hand over bearers the SMF never accepted.
                                log::warn!(
                                    "EPS→5GS (seq={seq}): SMF {host}:{port} answered PREPARED for \
                                     PDU session {psi} with no EPS Bearer Setup List; none of its \
                                     bearers is reported as set up"
                                );
                                not_moved.push((sess, "no EPS bearer confirmed by the SMF"));
                            } else {
                                bearers.extend(from_smf);
                            }
                        }
                        Err(e) => {
                            log::warn!(
                                "EPS→5GS (seq={seq}): SMF {host}:{port} did not take PDU \
                                 session {psi}'s target tunnel ({e}); its bearers are NOT \
                                 reported as set up"
                            );
                            not_moved.push((sess, "the SMF did not take the target tunnel"));
                        }
                    }
                }
                None => {
                    log::warn!(
                        "EPS→5GS (seq={seq}): the target gNB did not admit PDU session {psi}; \
                         its SMF is told the handover is CANCELLED for it"
                    );
                    not_moved.push((sess, "not admitted by the target gNB"));
                }
            }
        }

        let ebis: Vec<u8> = bearers.iter().filter_map(|b| b.ebi().ok()).collect();
        let amf_fteid = server.local_fteid(ack.amf_ue_ngap_id as u32);
        let (Some(amf_fteid), false) = (amf_fteid, bearers.is_empty()) else {
            log::warn!(
                "EPS→5GS (seq={seq}): no bearer could be moved, or this AMF has no IPv4 N26 \
                 F-TEID to give; refusing the relocation"
            );
            // The abandon cancels every session at its SMF, the unmoved ones included.
            if let Some(in_flight) = self.eps_ho_in_flight.remove(&ack.amf_ue_ngap_id) {
                self.abandon_eps_to_5gs_handover(ack.amf_ue_ngap_id, in_flight, "nothing moved")
                    .await;
            }
            return Vec::new();
        };
        let unmoved: Vec<(crate::n26_path::EpsHoSession, String)> = not_moved
            .into_iter()
            .map(|(sess, why)| (sess.clone(), why.to_string()))
            .collect();
        for (sess, why) in unmoved {
            self.drop_unmoved_eps_session(ack.amf_ue_ngap_id, &sess, &why);
        }
        let response = crate::n26_eps_to_5gs::build_eps_to_5gs_forward_relocation_response(
            seq,
            mme_teid,
            &amf_fteid,
            &bearers,
            &ack.target_to_source_container,
        );
        server.send_to_mme(mme_peer, &response).await;
        if let Some(in_flight) = self.eps_ho_in_flight.get_mut(&ack.amf_ue_ngap_id) {
            in_flight.answered = true;
        }
        log::info!(
            "EPS→5GS (seq={seq}): Forward Relocation Response ACCEPTED to MME {mme_peer} for UE \
             {}: bearers {ebis:?} set up, target-to-source container {} octets \
             (TS 23.502 §4.11.1.2.2.2 step 14)",
            ack.amf_ue_ngap_id,
            ack.target_to_source_container.len()
        );
        ebis
    }

    /// A PDU session an EPS→5GS relocation goes ahead without (#946): not admitted by the
    /// target gNB, refused by its SMF, or with no EPS bearer the SMF confirmed. Its SMF is
    /// told CANCELLED (TS 29.502 §5.2.2.3.4.4), off the NGAP task and durably, since nothing
    /// else will release that preparation. The AMF forgets the session: execution sends
    /// COMPLETED only to the sessions that moved, and the AMF keeps no session, SM context
    /// or EBI the MME was not told was set up.
    fn drop_unmoved_eps_session(
        &mut self,
        amf_ue_ngap_id: u64,
        sess: &crate::n26_path::EpsHoSession,
        why: &str,
    ) {
        let psi = sess.created.pdu_session_id;
        let (host, port, sm_ref) = (
            sess.smf.0.clone(),
            sess.smf.1,
            sess.created.sm_context_ref.clone(),
        );
        self.sbi_offload
            .spawn_keyed_durable((amf_ue_ngap_id, psi), move || async move {
                if let Err(e) = crate::sbi_path::call_smf_update_sm_context_ho_state(
                    &host,
                    port,
                    &sm_ref,
                    "CANCELLED",
                    None,
                )
                .await
                {
                    log::warn!(
                        "EPS→5GS: SMF {host}:{port} did not confirm the cancel of SM context \
                         {sm_ref}: {e}"
                    );
                }
                None
            });
        if let Some(in_flight) = self.eps_ho_in_flight.get_mut(&amf_ue_ngap_id) {
            in_flight
                .sessions
                .retain(|s| s.created.pdu_session_id != psi);
        }
        self.sm_context_refs.remove(&(amf_ue_ngap_id, psi));
        let _ = self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            state
                .amf_ue
                .assigned_ebis
                .retain(|e| e.pdu_session_id != psi);
        });
        {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            for amf_sess in guard.sess_list_for_ue(amf_ue_ngap_id) {
                if amf_sess.psi == psi {
                    guard.sess_remove(amf_sess.id);
                }
            }
        }
        log::info!(
            "EPS→5GS: PDU session {psi} of UE {amf_ue_ngap_id} does not move ({why}); its SMF \
             is told CANCELLED and the AMF forgets it"
        );
    }

    /// The execution phase's AMF half (TS 23.502 §4.11.1.2.2.3): the UE arrived.
    ///
    /// Each SMF is told the handover COMPLETED (step 7, *"Handover Complete indication for
    /// PDU Session ID"*), and the source MME gets the Forward Relocation Complete
    /// Notification (step 5) that lets it release the source side. Returns how many SMFs
    /// accepted.
    async fn finish_eps_to_5gs_handover(
        &mut self,
        amf_ue_ngap_id: u64,
        in_flight: EpsHoInFlight,
    ) -> usize {
        // #945: TS 23.502 §4.11.1.2.2.3 step 5, the Forward Relocation Complete
        // Notification, comes BEFORE step 7, Nsmf_PDUSession_UpdateSMContext (Handover
        // Complete). The MME needs it to release the source eNB and start its step-14
        // indirect-forwarding timer, so it must not wait on any SMF: one slow or dead
        // SMF+PGW-C used to delay it by up to the SBI timeout per PDN connection, while a
        // failed COMPLETED still got an FRCN at the end.
        let seq = in_flight.server.alloc_sequence().await;
        let notification = crate::n26_eps_to_5gs::build_forward_relocation_complete_notification(
            seq,
            in_flight.mme_teid,
        );
        in_flight
            .server
            .send_to_mme(in_flight.mme_peer, &notification)
            .await;
        // Step 7, off the NGAP task and concurrently across sessions. Keyed per (UE, PSI),
        // so a later exchange for the same session (a release, an activation) reaches the
        // SMF after this one. Nothing waits on the answer: a refusal is logged.
        for sess in &in_flight.sessions {
            let (smf, sm_ref, psi) = (
                sess.smf.clone(),
                sess.created.sm_context_ref.clone(),
                sess.created.pdu_session_id,
            );
            self.sbi_offload
                .spawn_keyed((amf_ue_ngap_id, psi), move || async move {
                    if let Err(e) = crate::sbi_path::call_smf_update_sm_context_ho_state(
                        &smf.0,
                        smf.1,
                        &sm_ref,
                        "COMPLETED",
                        None,
                    )
                    .await
                    {
                        log::warn!(
                            "EPS→5GS: SMF did not accept COMPLETED for PDU session {psi} of \
                             UE {amf_ue_ngap_id}: {e}"
                        );
                    }
                    None
                });
        }
        let told = in_flight.sessions.len();
        log::info!(
            "EPS→5GS: UE {amf_ue_ngap_id} arrived on 5GS; Forward Relocation Complete \
             Notification sent to MME {} (seq={seq}); COMPLETED sent to {told} SMF(s)",
            in_flight.mme_peer
        );
        told
    }

    /// End an EPS→5GS handover that will not complete: refuse to the MME, cancel at each
    /// SMF, and forget the UE (#418). TS 33.501 §8.4.2: *"If the handover is not completed
    /// successfully, the new mapped 5G security context cannot be used in the future. In
    /// this case, the AMF shall delete the new mapped 5G security context."*
    async fn abandon_eps_to_5gs_handover(
        &mut self,
        amf_ue_ngap_id: u64,
        in_flight: EpsHoInFlight,
        why: &str,
    ) -> EpsHandoverStart {
        let cause = crate::n26_eps_to_5gs::CAUSE_RELOCATION_FAILURE;
        let refusal = crate::n26_eps_to_5gs::build_forward_relocation_response_refusal(
            in_flight.seq,
            in_flight.mme_teid,
            cause,
        );
        in_flight
            .server
            .send_to_mme(in_flight.mme_peer, &refusal)
            .await;
        for sess in &in_flight.sessions {
            let _ = crate::sbi_path::call_smf_update_sm_context_ho_state(
                &sess.smf.0,
                sess.smf.1,
                &sess.created.sm_context_ref,
                "CANCELLED",
                None,
            )
            .await;
            self.sm_context_refs
                .remove(&(amf_ue_ngap_id, sess.created.pdu_session_id));
        }
        // The mapped security context is deleted with the UE.
        self.ue_auth_state.remove(amf_ue_ngap_id);
        {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            for sess in guard.sess_list_for_ue(amf_ue_ngap_id) {
                guard.sess_remove(sess.id);
            }
        }
        log::warn!(
            "EPS→5GS (seq={}): relocation REFUSED to MME {} with 'Relocation failure' ({why}); \
             {} SMF preparation(s) cancelled and the mapped 5G security context deleted",
            in_flight.seq,
            in_flight.mme_peer,
            in_flight.sessions.len()
        );
        EpsHandoverStart::Refused { cause }
    }
}

/// In-process strict-peer harness for the EPS→5GS handover (#475).
///
/// Not gated behind `#[cfg(test)]` for the reason `crate::test_support` is not: a peer
/// crate (smfd) drives this AMF's REAL N26 → NGAP path against its own REAL handlers as a
/// dev-dependency, and `cfg(test)` items are invisible across crates. Each method is a thin
/// door onto the production method of the same purpose — nothing here re-implements the AMF.
impl NgapServer {
    /// Register a target gNB association, as NG Setup would have, so a Target
    /// Identification naming it resolves.
    pub async fn harness_add_target_gnb(
        &self,
        association_id: u64,
        gnb_id: u32,
        gnb_id_len: u8,
        plmn: PlmnId,
    ) {
        let mut session = GnbSession::new(
            association_id,
            association_id,
            "127.0.0.1:38412".parse().expect("literal address"),
        );
        session.gnb.gnb_id = gnb_id;
        session.gnb.gnb_id_len = gnb_id_len;
        session.gnb.gnb_id_presence = true;
        session.gnb.plmn_id = plmn;
        self.sessions.write().await.insert(association_id, session);
    }

    /// TS 23.502 §4.11.1.2.2.2 steps 8-9: turn a drained N26 preparation into the NGAP
    /// HANDOVER REQUEST for the target. Returns `(AMF UE NGAP ID, target association, PDU)`.
    pub async fn harness_prepare_eps_to_5gs(
        &mut self,
        prep: crate::n26_path::EpsToFivegsPreparation,
    ) -> Result<(u64, u64, Vec<u8>)> {
        self.prepare_eps_to_5gs_handover_request(prep)
            .await
            .map_err(|refused| anyhow::anyhow!("EPS→5GS preparation refused: {refused:?}"))
    }

    /// Step 7's stored EBIs for the arriving UE: `(EBI, PDU session ID, ARP)`.
    pub fn harness_assigned_ebis(
        &self,
        amf_ue_ngap_id: u64,
    ) -> Vec<(u8, u8, crate::context::EbiArp)> {
        self.ue_auth_state
            .get(amf_ue_ngap_id)
            .map(|ue| {
                ue.amf_ue
                    .assigned_ebis
                    .iter()
                    .map(|e| (e.ebi, e.pdu_session_id, e.arp.clone()))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Steps 10-14: deliver the target's HANDOVER REQUEST ACKNOWLEDGE.
    pub async fn harness_handover_request_acknowledge(
        &mut self,
        association_id: u64,
        pdu: &[u8],
    ) -> Result<()> {
        self.handle_handover_request_acknowledge(association_id, pdu)
            .await
    }

    /// Execution: deliver the target's HANDOVER NOTIFY.
    pub async fn harness_handover_notify(
        &mut self,
        association_id: u64,
        pdu: &[u8],
    ) -> Result<HandoverCompletion> {
        self.handle_handover_notify(association_id, pdu).await
    }
}

impl NgapServer {
    /// Handle a HandoverCancel from the source gNB (TS 38.413 Section 8.4.5).
    /// The AMF acknowledges with a HandoverCancelAcknowledge.
    async fn handle_handover_cancel(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        // #417: the GENERATED codec, TS 38.413 §10.3.4.2: Handover Cancel has a
        // response and no unsuccessful outcome, so "notify" IEs go in the
        // Acknowledge and "reject" ones (or missing UE IDs) end it with an
        // Error Indication.
        let (cancel, notify) = match crate::ngap_asn1::decode_handover_cancel_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => (
                message,
                error_indication.map(|r| r.diagnostics).unwrap_or_default(),
            ),
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!("HandoverCancel from association {association_id} rejected: {report:?}");
                if let Some(ei) = crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                {
                    self.send_to_association(association_id, &ei).await?;
                }
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                self.send_error_indication(
                    association_id,
                    None,
                    None,
                    ngap_gen::Cause::Protocol(ngap_gen::CauseProtocol(
                        ngap_gen::CauseProtocol::TRANSFER_SYNTAX_ERROR,
                    )),
                )
                .await?;
                return Ok(());
            }
        };
        log::info!(
            "HandoverCancel from association {association_id} (amf_ue_ngap_id={}, cause={:?})",
            cancel.amf_ue_ngap_id,
            cancel.cause
        );
        // #804, TS 23.502 §4.9.1.4 steps 2-3 (and §4.11.1.2.3 steps 3, 4b): the target
        // releases what it reserved for the handover, and the SMF is told the handover is
        // cancelled. Before, the target kept its prepared UE context until its own timer
        // and the SMF never heard.
        self.release_cancelled_handover_target(cancel.amf_ue_ngap_id, "HO_CANCEL")
            .await;
        // The source abandoned the handover; nothing further will be relayed.
        // Dropped BEFORE the acknowledgement is sent, so a failed ack cannot leave
        // a stale relay target behind. The per-session transfers go with it (#742).
        self.forget_handover_preparation(cancel.amf_ue_ngap_id);
        match crate::ngap_asn1::build_handover_cancel_acknowledge_asn1(
            cancel.amf_ue_ngap_id,
            cancel.ran_ue_ngap_id,
            &notify,
        ) {
            Some(bytes) => {
                self.send_to_association(association_id, &bytes).await?;
                log::info!(
                    "HandoverCancelAcknowledge sent for UE {}",
                    cancel.amf_ue_ngap_id
                );
            }
            None => log::error!("Failed to build HandoverCancelAcknowledge"),
        }
        Ok(())
    }

    /// Handle a PathSwitchRequest from the target gNB after an Xn handover
    /// (TS 38.413 Section 8.4.4). The AMF updates the UE's RAN-UE-NGAP-ID and
    /// serving association, derives a fresh NH (TS 33.501 Section 6.9.2.3.3),
    /// and replies with PathSwitchRequestAcknowledge; on any inconsistency it
    /// replies with PathSwitchRequestFailure (TS 38.413 Section 9.2.3.12).
    async fn handle_path_switch_request(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        // #417: the GENERATED codec, TS 38.413 §10.3.4.2 / §10.3.5 for a Class 1
        // initiating message.
        let (req, notify) = match crate::ngap_asn1::decode_path_switch_request_asn1(data) {
            crate::ngap_asn1::PathSwitchRequestDecode::Proceed { request, notify } => {
                (request, notify)
            }
            crate::ngap_asn1::PathSwitchRequestDecode::Reject { sessions, report } => {
                log::warn!(
                    "PathSwitchRequest from association {association_id} rejected: {report:?}"
                );
                let failure = match (report.amf_ue_ngap_id, report.ran_ue_ngap_id) {
                    (Some(amf), Some(ran)) => path_switch_failure(
                        amf,
                        ran,
                        &sessions,
                        nextgcore_ngap::types::Cause::Protocol(
                            nextgcore_ngap::types::CauseProtocol::AbstractSyntaxErrorReject,
                        ),
                        &report.diagnostics,
                    ),
                    _ => None,
                };
                match failure {
                    Some(bytes) => self.send_to_association(association_id, &bytes).await?,
                    // No UE ids or no sessions: the Failure cannot be built.
                    None => {
                        self.send_criticality_error_indication(association_id, &report)
                            .await?
                    }
                }
                return Ok(());
            }
            crate::ngap_asn1::PathSwitchRequestDecode::Undecodable => {
                self.send_error_indication(
                    association_id,
                    None,
                    None,
                    ngap_gen::Cause::Protocol(ngap_gen::CauseProtocol(
                        ngap_gen::CauseProtocol::TRANSFER_SYNTAX_ERROR,
                    )),
                )
                .await?;
                return Ok(());
            }
        };
        let amf_ue_ngap_id = req.source_amf_ue_ngap_id;
        let requested: Vec<u8> = req
            .pdu_session_list
            .iter()
            .map(|p| p.pdu_session_id)
            .collect();
        log::info!(
            "PathSwitchRequest (amf_ue_ngap_id={amf_ue_ngap_id}, new ran_ue_ngap_id={})",
            req.ran_ue_ngap_id
        );

        // #745, TS 38.413 §8.4.4.4: the same PDU Session ID more than once in the
        // To Be Switched DL List is answered with PATH SWITCH REQUEST FAILURE, the AMF
        // generating the Path Switch Request Unsuccessful Transfer itself. Checked before
        // ANY state change: no NH/NCC advance, no relocation, no N11 call. Each session
        // is listed once in the Released List, cause multiple-PDU-session-ID-instances.
        // Checked before the unknown-UE check below, so a duplicated list for an unknown
        // UE is answered with this cause: §8.4.4.4 does not order the two abnormal
        // conditions, and either answer releases every named session.
        let mut distinct = requested.clone();
        distinct.sort_unstable();
        distinct.dedup();
        if distinct.len() != requested.len() {
            log::warn!(
                "PathSwitchRequest for UE {amf_ue_ngap_id} lists a PDU Session ID more than \
                 once ({requested:?}); failing it (TS 38.413 §8.4.4.4)"
            );
            if let Some(bytes) = path_switch_failure(
                amf_ue_ngap_id,
                req.ran_ue_ngap_id,
                &distinct,
                nextgcore_ngap::types::Cause::RadioNetwork(
                    nextgcore_ngap::types::CauseRadioNetwork::MultiplePduSessionIdInstances,
                ),
                &[],
            ) {
                self.send_to_association(association_id, &bytes).await?;
            }
            return Ok(());
        }

        // Unknown UE → PathSwitchRequestFailure releasing every session it named,
        // cause unknown-local-UE-NGAP-ID (the list is mandatory, §9.2.3.10).
        if !self.ue_auth_state.contains(amf_ue_ngap_id) {
            log::warn!("PathSwitchRequest for unknown UE {amf_ue_ngap_id}; failing");
            if let Some(bytes) = path_switch_failure(
                amf_ue_ngap_id,
                req.ran_ue_ngap_id,
                &requested,
                nextgcore_ngap::types::Cause::RadioNetwork(
                    nextgcore_ngap::types::CauseRadioNetwork::UnknownLocalUeNgapId,
                ),
                &[],
            ) {
                self.send_to_association(association_id, &bytes).await?;
            }
            return Ok(());
        }

        // Derive a fresh NH from KAMF (vertical key derivation) and increment
        // the NHCC (TS 33.501 Section 6.9.2.3.3 / 6.9.4.1).
        // `with_mut`, because everything this block does to `state` must PERSIST:
        // it advances the NH key chain and it moves the UE's serving association
        // to the target gNB. A dropped clone would leave the AMF believing the UE
        // is still on the source association -- so every later downlink NAS would
        // be sent to the gNB the UE just left -- and would reuse the NCC on the
        // next switch. Await-free; the relays below happen after it returns.
        let (ncc, inbound, allowed_nssai, ue_caps) = self
            .ue_auth_state
            .with_mut(amf_ue_ngap_id, |state| {
                // Shared with the N2 path (see AmfUe::advance_next_hop) so the two
                // cannot derive keys differently. The chain is seeded from KgNB at
                // AS-context establishment, so this no longer chains from zeros.
                let (_ncc, _nh) = state.amf_ue.advance_next_hop();
                // Move the UE's serving RAN association and RAN-UE-NGAP-ID to the
                // target gNB; this is the N3 tunnel/RAN identity update.
                state.ran_ue_ngap_id = req.ran_ue_ngap_id;
                state.association_id = association_id;

                // #406, the SECOND instance of the discarded-location class: move the
                // stored location to the TARGET cell as well as the target association.
                //
                // `UserLocationInformation` is MANDATORY on PATH SWITCH REQUEST
                // (TS 38.413 §9.2.3.8, `38413-j30.txt:13741-13742`), and TS 23.502
                // §4.9.1.2.2 step 1b says what it is for: the target NG-RAN *"sends an N2
                // Path Switch Request message to an AMF to inform that the UE has moved to
                // a new Target cell"* (`23502-k20.txt:17848-17858`). Before this the
                // handler bound `req` and never read `req.user_location_info` at all.
                //
                // This is the arm that matters most after the filed one: an Xn handover
                // produces NO `HandoverNotify`, so this message is the AMF's ONLY
                // notification that the UE relocated. Without it a UE that moved by Xn —
                // the common case, since Xn is preferred wherever the interface exists —
                // left the stored location untouched, and `nr_cgi`'s single writer was
                // reachable only via the LESS common handover type.
                //
                // Inside the same `with_mut` as the association move, deliberately: the two
                // describe one event, and a reader must not have to wonder whether the
                // location and the serving gNB can disagree.
                // Criticality ignore: a request without it keeps the stored location.
                if let Some(uli) = &req.user_location_info {
                    apply_user_location(&mut state.amf_ue, uli);
                }

                // #70: the inbound request transfers, kept so each can be relayed to the SMF
                // AFTER this borrow ends. The switched list is built from the SMF's ANSWERS
                // below, not from these — echoing the gNB's own PathSwitchRequestTransfer back
                // as the acknowledge is the defect #70 names, and it tells the target gNB to
                // send uplink traffic to itself (TS 38.413 §9.3.4.8 vs §9.3.4.9).
                let inbound: Vec<(u8, Vec<u8>)> = req
                    .pdu_session_list
                    .iter()
                    .map(|p| (p.pdu_session_id, p.transfer.clone()))
                    .collect();

                let allowed_nssai = state
                    .amf_ue
                    .allowed_nssai
                    .iter()
                    .map(|s| nextgcore_ngap::types::SNssai {
                        sst: s.sst,
                        sd: s.sd.map(|sd| sd.to_be_bytes()[1..4].try_into().unwrap()),
                    })
                    .collect::<Vec<_>>();

                (
                    state.amf_ue.nhcc,
                    inbound,
                    allowed_nssai,
                    ue_caps_to_ngap_for_ue(&state.amf_ue),
                )
            })
            .expect("the UE was resolved above");

        // #70: Nsmf_PDUSession_UpdateSMContext per switched PDU session
        // (TS 29.502 §5.2.2.3.3). The SMF switches the UPF's DL path to the target and
        // answers with the PathSwitchRequestAcknowledgeTransfer this acknowledge owes the
        // gNB. Done after the state borrow ends because it awaits.
        //
        // A session the SMF does not acknowledge is left OUT of the switched list rather
        // than acknowledged with a fabricated transfer: TS 38.413 §9.3.4.9 makes the
        // acknowledge the core's statement about the uplink path, and inventing one would
        // point the target gNB at a tunnel no UPF serves. A gNB that finds a session
        // missing from the switched list releases it, which is the honest outcome.
        let switched_list = self.switched_list_from_smf(amf_ue_ngap_id, &inbound).await;

        let nh = self
            .ue_auth_state
            .get(amf_ue_ngap_id)
            .expect("checked")
            .amf_ue
            .nh;

        let allowed_for_ack = if allowed_nssai.is_empty() {
            vec![nextgcore_ngap::types::SNssai { sst: 1, sd: None }]
        } else {
            allowed_nssai
        };

        // A session the SMF did not switch is RELEASED (§8.4.4.2: "PDU Session
        // Resource Released List"), not silently dropped.
        let not_switched: Vec<u8> = requested
            .iter()
            .copied()
            .filter(|psi| !switched_list.iter().any(|s| s.pdu_session_id == *psi))
            .collect();
        let unswitched_cause =
            nextgcore_ngap::types::Cause::Misc(nextgcore_ngap::types::CauseMisc::Unspecified);
        let ack_bytes = (!switched_list.is_empty())
            .then(|| {
                let ack = nextgcore_ngap::types::PathSwitchRequestAcknowledge {
                    amf_ue_ngap_id,
                    ran_ue_ngap_id: req.ran_ue_ngap_id,
                    ue_security_capabilities: Some(ue_caps),
                    security_context: nextgcore_ngap::types::SecurityContext {
                        next_hop_chaining_count: ncc,
                        next_hop: nh,
                    },
                    switched_list,
                    released_list: released_items(&not_switched, unswitched_cause),
                    allowed_nssai: allowed_for_ack,
                };
                crate::ngap_asn1::build_path_switch_request_acknowledge_generated(&ack, &notify)
            })
            .flatten();
        let (racs_id, _) = self.racs_ies_for(amf_ue_ngap_id);
        match ack_bytes {
            Some(bytes) => {
                // #570: the UE Radio Capability ID, when the UE has one (TS 38.413 §9.2.3.9).
                let bytes = crate::racs::add_capability_ies(bytes, racs_id.as_deref(), None);
                self.send_to_association(association_id, &bytes).await?;
                log::info!(
                    "PathSwitchRequestAcknowledge sent for UE {amf_ue_ngap_id} \
                     (new ran_ue_ngap_id={}, NCC={ncc}, {} released)",
                    req.ran_ue_ngap_id,
                    not_switched.len()
                );
            }
            None => {
                // Nothing switched (or the acknowledge did not encode): §8.4.4.3,
                // PATH SWITCH REQUEST FAILURE releasing every requested session.
                log::warn!(
                    "PathSwitchRequest for UE {amf_ue_ngap_id}: no session switched; failing"
                );
                if let Some(b) = path_switch_failure(
                    amf_ue_ngap_id,
                    req.ran_ue_ngap_id,
                    &requested,
                    unswitched_cause,
                    &notify,
                ) {
                    self.send_to_association(association_id, &b).await?;
                }
            }
        }
        Ok(())
    }

    /// Resolve the SCTP association of the gNB named by a handover TargetID by
    /// matching its Global RAN Node ID against connected gNB contexts.
    async fn find_association_for_target(
        &self,
        target_id: &nextgcore_ngap::types::TargetId,
    ) -> Option<u64> {
        let target_gnb_id = match target_id {
            nextgcore_ngap::types::TargetId::TargetRanNodeId {
                global_ran_node_id, ..
            } => match global_ran_node_id {
                nextgcore_ngap::types::GlobalRanNodeId::GlobalGnbId { gnb_id, .. } => {
                    Some(*gnb_id as u64)
                }
                _ => None,
            },
            nextgcore_ngap::types::TargetId::TargetGlobalNgEnbId { .. } => None,
        }?;
        let sessions = self.sessions.read().await;
        sessions
            .iter()
            .find(|(_, s)| s.gnb.gnb_id as u64 == target_gnb_id)
            .map(|(assoc, _)| *assoc)
    }

    /// Handle Initial Context Setup Response from the gNB (TS 38.413 §8.3.1.2).
    ///
    /// The gNB has set up AS-layer security and delivered the piggybacked
    /// Registration Accept to the UE. The AMF marks the UE context as
    /// established and transitions the GMM FSM out of InitialContextSetup; the
    /// NAS-layer Registration Complete then drives the move to Registered. The
    /// ICS-based retransmission timer is cleared since the gNB has the NAS PDU.
    ///
    /// Decoded with the generated codec (#417 stage 7), which applies the §10.3.4.2
    /// rules for a RESPONSE: a not-comprehended "ignore IE and notify sender" IE is
    /// reported in an Error Indication and the procedure goes on; one marked
    /// "reject" terminates it unsuccessfully, handled locally -- the UE stays in
    /// InitialContextSetup and T3550 retransmits the request, as it did for an
    /// undecodable Response. Both IDs are criticality ignore (§10.3.5): without the
    /// AMF UE NGAP ID there is no UE to update, without the RAN one nothing is lost.
    async fn handle_initial_context_setup_response(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        use crate::ngap_asn1::InitialContextSetupOutcomeDecode::{Decoded, Failed, Undecodable};
        let ics_setup_sessions: Vec<(u8, Vec<u8>)>;
        let (amf_ue_ngap_id, ran_ue_ngap_id) =
            match crate::ngap_asn1::decode_initial_context_setup_response_asn1(data) {
                Decoded {
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    error_indication,
                    setup_sessions,
                    ..
                } => {
                    ics_setup_sessions = setup_sessions;
                    // Best effort: the report must not stop the procedure.
                    if let Some(report) = error_indication {
                        if let Err(e) = self
                            .send_criticality_error_indication(association_id, &report)
                            .await
                        {
                            log::warn!("Failed to send ErrorIndication: {e}");
                        }
                    }
                    let Some(amf_ue_ngap_id) = amf_ue_ngap_id else {
                        log::warn!(
                            "Initial Context Setup Response without an AMF UE NGAP ID \
                             (association {association_id}); no UE to update"
                        );
                        return Ok(());
                    };
                    (amf_ue_ngap_id, ran_ue_ngap_id)
                }
                Failed(diagnostics) => {
                    log::warn!(
                        "Initial Context Setup Response carries not-comprehended IEs marked \
                         reject ({diagnostics:?}); the procedure is unsuccessfully terminated \
                         (TS 38.413 §10.3.4.2), handled locally"
                    );
                    return Ok(());
                }
                Undecodable => {
                    return self
                        .report_transfer_syntax_error(
                            association_id,
                            "Initial Context Setup Response",
                        )
                        .await
                }
            };
        log::info!(
            "Initial Context Setup Response: amf_ue_ngap_id={amf_ue_ngap_id}, \
             ran_ue_ngap_id={ran_ue_ngap_id:?} (association {association_id})"
        );
        // #540: each set-up session's Setup Response Transfer carries the gNB's
        // downlink tunnel; the SMF must have it to move the UPF's downlink FAR off
        // BUFF (TS 23.502 §4.2.3.2 steps 12-14). Before this an ICS that carried
        // sessions -- a Service Request's re-activation -- left the UPF buffering.
        for (psi, transfer) in &ics_setup_sessions {
            self.relay_n2_sm_to_smf(
                amf_ue_ngap_id,
                *psi,
                "PDU_RES_SETUP_RSP",
                transfer,
                "InitialContextSetupResponse",
            )
            .await;
        }

        let updated = self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            state.initial_context_setup_response_received = true;
            // The gNB has the Registration Accept; stop retransmitting the ICS
            // request. T3550 logic that waits for Registration Complete is reset
            // here — Registration Complete arrives on the uplink NAS path.
            state.retx = None;
            // Leave InitialContextSetup; Registration Complete moves the FSM to
            // Registered (TS 24.501 §5.5.1.2.4).
            state.gmm_fsm.transition_to_registered();
            log::info!("UE {amf_ue_ngap_id} context established (AS-layer security up)");
        });
        if updated.is_none() {
            log::warn!("Initial Context Setup Response for unknown UE {amf_ue_ngap_id}; ignoring");
        }
        Ok(())
    }

    /// Handle Initial Context Setup Failure from the gNB (TS 38.413 §8.3.1.3).
    ///
    /// The gNB could not establish AS-layer security. The registration cannot
    /// complete, so the AMF releases the UE context.
    ///
    /// Decoded with the generated codec (#417 stage 7) under the §10.3.4.2 response
    /// rules, as the Response is. Both IDs are criticality ignore (§10.3.5): without
    /// the AMF UE NGAP ID there is no UE to release; without the RAN one the
    /// Release Command takes the RAN UE NGAP ID the AMF stored for that UE.
    async fn handle_initial_context_setup_failure(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        use crate::ngap_asn1::InitialContextSetupOutcomeDecode::{Decoded, Failed, Undecodable};
        let (amf_ue_ngap_id, ran_ue_ngap_id, cause) =
            match crate::ngap_asn1::decode_initial_context_setup_failure_asn1(data) {
                Decoded {
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    cause,
                    error_indication,
                    ..
                } => {
                    // Best effort: the report must not stop the release.
                    if let Some(report) = error_indication {
                        if let Err(e) = self
                            .send_criticality_error_indication(association_id, &report)
                            .await
                        {
                            log::warn!("Failed to send ErrorIndication: {e}");
                        }
                    }
                    let Some(amf_ue_ngap_id) = amf_ue_ngap_id else {
                        log::warn!(
                            "Initial Context Setup Failure without an AMF UE NGAP ID \
                             (association {association_id}); no UE to release"
                        );
                        return Ok(());
                    };
                    let stored = self
                        .ue_auth_state
                        .with_mut(amf_ue_ngap_id, |state| state.ran_ue_ngap_id);
                    let Some(ran_ue_ngap_id) = ran_ue_ngap_id.or(stored) else {
                        log::warn!(
                            "Initial Context Setup Failure for unknown UE {amf_ue_ngap_id} \
                             without a RAN UE NGAP ID; nothing to release"
                        );
                        return Ok(());
                    };
                    (amf_ue_ngap_id, ran_ue_ngap_id, cause)
                }
                Failed(diagnostics) => {
                    log::warn!(
                        "Initial Context Setup Failure carries not-comprehended IEs marked \
                         reject ({diagnostics:?}); the procedure is unsuccessfully terminated \
                         (TS 38.413 §10.3.4.2), handled locally"
                    );
                    return Ok(());
                }
                Undecodable => {
                    return self
                        .report_transfer_syntax_error(
                            association_id,
                            "Initial Context Setup Failure",
                        )
                        .await
                }
            };
        log::warn!(
            "Initial Context Setup Failure: amf_ue_ngap_id={amf_ue_ngap_id}, \
             ran_ue_ngap_id={ran_ue_ngap_id}, cause={cause:?} (association {association_id}); \
             releasing UE"
        );

        // Drop any pending ICS retransmission, then release the NG context.
        self.ue_auth_state.with_mut(amf_ue_ngap_id, |state| {
            state.retx = None;
            state.gmm_fsm.transition_to_exception();
        });
        // NAS cause #22 "congestion" is not appropriate; use #9 (UE identity
        // cannot be derived) so the UE re-registers (TS 24.501 Annex).
        self.release_ue(
            association_id,
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            GmmCause::UeIdentityCannotBeDerivedByTheNetwork as u8,
        )
        .await
    }

    /// Handle PDU Session Resource Setup Response from gNB
    ///
    /// Extracts gNB TEID from the response and forwards it to SMF via SM Context Update.
    /// The SMF then sends PFCP Session Modification to the UPF to activate the DL FAR.
    /// The SMF's SBI host/port, from the environment (same lookup every N11 call
    /// site in this file uses).
    /// The SMF holding UE `amf_ue_ngap_id`'s PSI `psi` SM context (#669), falling
    /// back to [`Self::smf_sbi_target`] for a context created before this was
    /// recorded.
    fn smf_target_for(&self, amf_ue_ngap_id: u64, psi: u8) -> (String, u16) {
        self.sm_context_smfs
            .get(&(amf_ue_ngap_id, psi))
            .cloned()
            .unwrap_or_else(Self::smf_sbi_target)
    }

    fn smf_sbi_target() -> (String, u16) {
        let host = std::env::var("SMF_SBI_ADDR").unwrap_or_else(|_| "127.0.0.1".to_string());
        let port: u16 = std::env::var("SMF_SBI_PORT")
            .ok()
            .and_then(|p| p.parse().ok())
            .unwrap_or(7777);
        (host, port)
    }

    /// Relay one per-PDU-session N2 SM container to the SMF via
    /// Nsmf_PDUSession_UpdateSMContext (TS 23.502 §4.3.2.2.1).
    ///
    /// `context` names the NGAP procedure for the log line, so a failure says
    /// which relay dropped rather than just "update failed".
    ///
    /// Returns whether the relay was attempted and accepted, so callers can count
    /// what actually reached the SMF instead of assuming.
    /// Build a PathSwitchRequestAcknowledge's switched list from the SMF's ANSWERS (#70).
    ///
    /// One `Nsmf_PDUSession_UpdateSMContext` per switched session (TS 29.502 §5.2.2.3.3);
    /// the SMF switches the UPF's DL path to the target and returns the
    /// `PathSwitchRequestAcknowledgeTransfer` the gNB is owed.
    ///
    /// A session the SMF does not acknowledge is left OUT rather than acknowledged with the
    /// gNB's own request transfer. That echo is the defect #70 names: TS 38.413 §9.3.4.8 and
    /// §9.3.4.9 are different messages in opposite directions — the request carries the
    /// target's DL tunnel, the acknowledge the core's UL tunnel — so echoing one for the
    /// other tells the target gNB to send uplink traffic to itself. A gNB that finds a
    /// session missing from the switched list releases it, which is the honest outcome when
    /// the core cannot confirm the switch.
    ///
    /// Extracted from `handle_path_switch_request` so the no-echo property is testable: the
    /// acknowledge is built and immediately sent, and a harness with no live gNB association
    /// cannot inspect what went into it.
    async fn switched_list_from_smf(
        &self,
        amf_ue_ngap_id: u64,
        inbound: &[(u8, Vec<u8>)],
    ) -> Vec<nextgcore_ngap::types::PduSessionResourceSwitchedItem> {
        let mut switched_list = Vec::with_capacity(inbound.len());
        for (pdu_session_id, request_transfer) in inbound {
            match self
                .relay_n2_sm_to_smf_for_answer(
                    amf_ue_ngap_id,
                    *pdu_session_id,
                    "PATH_SWITCH_REQ",
                    request_transfer,
                    "PathSwitchRequest",
                )
                .await
            {
                Some(ack_transfer) => {
                    switched_list.push(nextgcore_ngap::types::PduSessionResourceSwitchedItem {
                        pdu_session_id: *pdu_session_id,
                        transfer: ack_transfer,
                    });
                }
                None => log::warn!(
                    "PathSwitchRequest: PSI {pdu_session_id} of UE {amf_ue_ngap_id} is NOT \
                     in the switched list -- the SMF supplied no acknowledge transfer, and \
                     echoing the gNB's own request transfer would point it at its own tunnel"
                ),
            }
        }
        switched_list
    }

    /// Relay an N2 SM container to the SMF and return the container it answers with
    /// (#70, TS 29.502 §5.2.2.3.3).
    ///
    /// The mobility twin of [`Self::relay_n2_sm_to_smf`], which discards the response. On
    /// a path switch the response is the point: it carries the
    /// `PathSwitchRequestAcknowledgeTransfer` the target gNB is owed, and without it the
    /// AMF has nothing conformant to put in the acknowledge — which is why the pre-#70
    /// code echoed the gNB's own request transfer back instead.
    ///
    /// `None` means the relay failed or the SMF answered with no N2 SM part, and the caller
    /// must decide what to do about it rather than substituting something.
    async fn relay_n2_sm_to_smf_for_answer(
        &self,
        amf_ue_ngap_id: u64,
        pdu_session_id: u8,
        n2_sm_info_type: &str,
        transfer: &[u8],
        context: &str,
    ) -> Option<Vec<u8>> {
        let sm_context_ref = self
            .sm_context_refs
            .get(&(amf_ue_ngap_id, pdu_session_id))
            .cloned()?;
        let (host, port) = self.smf_target_for(amf_ue_ngap_id, pdu_session_id);
        match crate::sbi_path::call_smf_update_sm_context_n2(
            &host,
            port,
            &sm_context_ref,
            n2_sm_info_type,
            transfer,
        )
        .await
        {
            Ok(resp) if !resp.n2_sm_info.is_empty() => {
                log::info!(
                    "{context}: SMF ref={sm_context_ref} answered with {} N2 SM bytes for \
                     UE {amf_ue_ngap_id} PSI {pdu_session_id}",
                    resp.n2_sm_info.len()
                );
                Some(resp.n2_sm_info)
            }
            Ok(_) => {
                log::warn!(
                    "{context}: SMF ref={sm_context_ref} accepted the update but returned \
                     no N2 SM information for UE {amf_ue_ngap_id} PSI {pdu_session_id}"
                );
                None
            }
            Err(e) => {
                log::warn!(
                    "{context}: SMF update failed for UE {amf_ue_ngap_id} PSI \
                     {pdu_session_id} (ref={sm_context_ref}): {e}"
                );
                None
            }
        }
    }

    /// Relay an N2 SM container with `n2_sm_info_type` and return the SMF's
    /// answer as `(n2SmInfoType, n2SmInfo)`; `None` when there is no SM context
    /// or the SMF call fails. Unlike [`Self::relay_n2_sm_to_smf_for_answer`], the
    /// answer's type comes back too, because a Modify Indication's answer is
    /// either a Confirm Transfer or an Unsuccessful Transfer (#525).
    async fn relay_n2_sm_to_smf_with_answer(
        &self,
        amf_ue_ngap_id: u64,
        pdu_session_id: u8,
        n2_sm_info_type: &str,
        transfer: &[u8],
        context: &str,
    ) -> Option<(Option<String>, Vec<u8>)> {
        let Some(sm_context_ref) = self
            .sm_context_refs
            .get(&(amf_ue_ngap_id, pdu_session_id))
            .cloned()
        else {
            log::error!(
                "{context}: no SM context ref stored for UE {amf_ue_ngap_id} PSI \
                 {pdu_session_id}"
            );
            return None;
        };
        let (host, port) = self.smf_target_for(amf_ue_ngap_id, pdu_session_id);
        match crate::sbi_path::call_smf_update_sm_context_n2(
            &host,
            port,
            &sm_context_ref,
            n2_sm_info_type,
            transfer,
        )
        .await
        {
            Ok(resp) => Some((resp.n2_sm_info_type, resp.n2_sm_info)),
            Err(e) => {
                log::warn!(
                    "{context}: SMF update ({n2_sm_info_type}) for UE {amf_ue_ngap_id} PSI \
                     {pdu_session_id} (ref={sm_context_ref}) failed: {e}"
                );
                None
            }
        }
    }

    async fn relay_n2_sm_to_smf(
        &self,
        amf_ue_ngap_id: u64,
        pdu_session_id: u8,
        n2_sm_info_type: &str,
        transfer: &[u8],
        context: &str,
    ) -> bool {
        // Always the SMF-chosen reference from the Create response, never
        // format!("{pdu_session_id}"). The PSI is 1 for the first session of every
        // UE while the SMF's ref is a monotonic index, so a fabricated ref sends
        // every update to session "1".
        let Some(sm_context_ref) = self
            .sm_context_refs
            .get(&(amf_ue_ngap_id, pdu_session_id))
            .cloned()
        else {
            log::error!(
                "{context}: no SM context ref stored for UE {amf_ue_ngap_id} PSI \
                 {pdu_session_id}; cannot relay the N2 SM container to the SMF"
            );
            return false;
        };

        let (host, port) = self.smf_target_for(amf_ue_ngap_id, pdu_session_id);
        // The container is forwarded opaquely: the AMF never re-encodes N2 SM
        // information (TS 23.502).
        // Each container with its own n2SmInfoType (TS 29.502 §6.1.6.3.12, #525).
        match crate::sbi_path::call_smf_update_sm_context_n2(
            &host,
            port,
            &sm_context_ref,
            n2_sm_info_type,
            transfer,
        )
        .await
        {
            Ok(_) => {
                log::info!(
                    "{context}: relayed {} N2 SM bytes for UE {amf_ue_ngap_id} PSI \
                     {pdu_session_id} to SMF ref={sm_context_ref}",
                    transfer.len()
                );
                true
            }
            Err(e) => {
                log::warn!(
                    "{context}: failed to relay the N2 SM container for UE \
                     {amf_ue_ngap_id} PSI {pdu_session_id} (ref={sm_context_ref}): {e}"
                );
                false
            }
        }
    }

    /// Handle a PDU SESSION RESOURCE SETUP RESPONSE (TS 38.413 §8.2.1).
    ///
    /// Decoded with the generated codec (#417 stage 6), which applies the
    /// §10.3.4.2 rules for a RESPONSE: a not-comprehended "ignore IE and notify
    /// sender" IE is reported in an Error Indication and the transfers are
    /// relayed all the same; one marked "reject" terminates the procedure
    /// unsuccessfully, handled locally by relaying nothing -- what an
    /// undecodable response already got.
    async fn handle_pdu_session_resource_setup_response(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        use crate::ngap_asn1::PduSessionResourceSetupResponseDecode::{
            Decoded, Failed, Undecodable,
        };
        log::info!(
            "PDU Session Resource Setup Response from association {} ({} bytes)",
            association_id,
            data.len()
        );

        let (amf_ue_ngap_id, ran_ue_ngap_id, setup, failed) =
            match crate::ngap_asn1::decode_pdu_session_resource_setup_response_asn1(data) {
                Decoded {
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    setup,
                    failed,
                    error_indication,
                } => {
                    // Best effort: the report must not stop the relay below.
                    if let Some(report) = error_indication {
                        if let Err(e) = self
                            .send_criticality_error_indication(association_id, &report)
                            .await
                        {
                            log::warn!("Failed to send ErrorIndication: {e}");
                        }
                    }
                    (amf_ue_ngap_id, ran_ue_ngap_id, setup, failed)
                }
                Failed(diagnostics) => {
                    log::warn!(
                        "PDU Session Resource Setup Response from association \
                         {association_id} carries not-comprehended IEs marked reject \
                         ({diagnostics:?}); the procedure is unsuccessfully terminated \
                         (TS 38.413 §10.3.4.2), handled locally"
                    );
                    return Ok(());
                }
                Undecodable => {
                    return self
                        .report_transfer_syntax_error(
                            association_id,
                            "PDU Session Resource Setup Response",
                        )
                        .await;
                }
            };
        // The AMF UE NGAP ID has criticality ignore, so its absence is ignored
        // (§10.3.5) -- but it is what names the UE whose SM contexts the
        // transfers belong to, so without it there is nothing to relay them to.
        let Some(amf_ue_ngap_id) = amf_ue_ngap_id else {
            log::warn!(
                "PDU Session Resource Setup Response from association {association_id} \
                 names no AMF UE NGAP ID; {} set-up and {} failed transfers cannot be \
                 relayed",
                setup.len(),
                failed.len()
            );
            return Ok(());
        };

        log::info!(
            "Decoded Setup Response: amf_ue_ngap_id={amf_ue_ngap_id}, \
             ran_ue_ngap_id={ran_ue_ngap_id:?}, setup={}, failed={}",
            setup.len(),
            failed.len()
        );

        // TS 38.413 §8.2.1 / TS 23.502 §4.3.2.2.1: EVERY successfully-set-up
        // session's N2 SM Response Transfer is relayed to the SMF, each against
        // its own SM context.
        //
        // This loop used to collapse into a single `gnb_endpoint` variable that
        // each iteration overwrote, so only the LAST session in the list was ever
        // forwarded. A UE with concurrent eMBB and IMS/VoNR sessions — the common
        // multi-session case — had exactly one session's downlink TEID installed
        // and the rest left half-open: the gNB believed they were up, the UPF had
        // no downlink FAR for them.
        let mut relayed = 0usize;
        for item in &setup {
            // Decode the transfer only to log the endpoint; the bytes relayed to
            // the SMF are the ones received (TS 23.502: opaque to the AMF). A
            // transfer this build cannot parse is still relayed, because the SMF
            // is its actual consumer and the AMF's parse is only for observability.
            match ngap_asn1::parse_n2_sm_setup_response_transfer(&item.transfer) {
                Some(endpoint) => log::info!(
                    "Setup Response PSI={}: gNB TEID=0x{:08x}, addr={:?}, QFIs={:?}",
                    item.pdu_session_id,
                    endpoint.teid,
                    endpoint.address,
                    endpoint.qfis
                ),
                None => log::warn!(
                    "Could not parse the setup-response transfer for PSI={} ({} bytes); \
                     relaying it to the SMF unchanged anyway",
                    item.pdu_session_id,
                    item.transfer.len()
                ),
            }

            if self
                .relay_n2_sm_to_smf(
                    amf_ue_ngap_id,
                    item.pdu_session_id,
                    "PDU_RES_SETUP_RSP",
                    &item.transfer,
                    "PDUSessionResourceSetupResponse",
                )
                .await
            {
                relayed += 1;
            }
        }

        // The failed-to-setup list was never inspected. Its per-session
        // Unsuccessful Transfer carries the gNB's cause, and the SMF needs it to
        // release the session it thinks it just established — otherwise the
        // session leaks at the SMF and UPF until some other event clears it.
        for item in &failed {
            log::warn!(
                "gNB failed to set up PSI={} ({} bytes of unsuccessful transfer); \
                 relaying the failure to the SMF",
                item.pdu_session_id,
                item.transfer.len()
            );
            self.relay_n2_sm_to_smf(
                amf_ue_ngap_id,
                item.pdu_session_id,
                "PDU_RES_SETUP_FAIL",
                &item.transfer,
                "PDUSessionResourceSetupResponse (failed-to-setup)",
            )
            .await;
        }

        if setup.is_empty() && failed.is_empty() {
            log::warn!(
                "PDU Session Resource Setup Response for UE {} carries neither a \
                 setup nor a failed list",
                amf_ue_ngap_id
            );
        } else {
            log::info!(
                "PDU Session Resource Setup Response: relayed {relayed}/{} successful \
                 and {} failed sessions to the SMF",
                setup.len(),
                failed.len()
            );
        }

        Ok(())
    }

    /// Handle a PDU SESSION RESOURCE MODIFY RESPONSE (TS 38.413 §8.2.2).
    ///
    /// Each modified session carries an N2 SM Modify Response Transfer the SMF
    /// must see to complete the modification, and each failed one a Modify
    /// Unsuccessful Transfer; each is relayed with its own n2SmInfoType
    /// (`PDU_RES_MOD_RSP` / `PDU_RES_MOD_FAIL`, #525) -- both used to reach the
    /// SMF labelled `PDU_RES_SETUP_RSP`.
    ///
    /// Decoded with the generated codec (#417), which applies the §10.3.4.2 rules
    /// for a RESPONSE: "ignore IE and notify sender" is reported in an Error
    /// Indication and the transfers are relayed all the same; "reject"
    /// terminates the procedure unsuccessfully, handled locally.
    async fn handle_pdu_session_resource_modify_response(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        use crate::ngap_asn1::PduSessionResourceModifyResponseDecode::{
            Decoded, Failed, Undecodable,
        };
        let (amf_ue_ngap_id, modified, failed) =
            match crate::ngap_asn1::decode_pdu_session_resource_modify_response_asn1(data) {
                Decoded {
                    amf_ue_ngap_id,
                    modified,
                    failed,
                    error_indication,
                    ..
                } => {
                    if let Some(report) = error_indication {
                        if let Err(e) = self
                            .send_criticality_error_indication(association_id, &report)
                            .await
                        {
                            log::warn!("Failed to send ErrorIndication: {e}");
                        }
                    }
                    (amf_ue_ngap_id, modified, failed)
                }
                Failed(diagnostics) => {
                    log::warn!(
                        "PDU Session Resource Modify Response from association \
                         {association_id} carries not-comprehended IEs marked reject \
                         ({diagnostics:?}); the procedure is unsuccessfully terminated \
                         (TS 38.413 §10.3.4.2), handled locally"
                    );
                    return Ok(());
                }
                Undecodable => {
                    return self
                        .report_transfer_syntax_error(
                            association_id,
                            "PDU Session Resource Modify Response",
                        )
                        .await;
                }
            };
        // Criticality ignore, so its absence is ignored (§10.3.5) -- but it names
        // the UE whose SM contexts the transfers belong to.
        let Some(amf_ue_ngap_id) = amf_ue_ngap_id else {
            log::warn!(
                "PDU Session Resource Modify Response from association {association_id} \
                 names no AMF UE NGAP ID; {} transfers cannot be relayed",
                modified.len() + failed.len()
            );
            return Ok(());
        };

        log::info!(
            "PDU Session Resource Modify Response from association {association_id}: \
             UE {amf_ue_ngap_id}, modified={}, failed={}",
            modified.len(),
            failed.len()
        );

        for item in &modified {
            self.relay_n2_sm_to_smf(
                amf_ue_ngap_id,
                item.pdu_session_id,
                "PDU_RES_MOD_RSP",
                &item.transfer,
                "PDUSessionResourceModifyResponse",
            )
            .await;
        }
        for item in &failed {
            log::warn!(
                "gNB failed to modify PSI={}; relaying the failure to the SMF",
                item.pdu_session_id
            );
            self.relay_n2_sm_to_smf(
                amf_ue_ngap_id,
                item.pdu_session_id,
                "PDU_RES_MOD_FAIL",
                &item.transfer,
                "PDUSessionResourceModifyResponse (failed-to-modify)",
            )
            .await;
        }
        Ok(())
    }

    /// Handle a PDU SESSION RESOURCE RELEASE RESPONSE (TS 38.413 §8.2.3).
    ///
    /// The per-session Release Response Transfer carries the gNB's final
    /// Secondary RAT usage / release confirmation. It used to be dropped with
    /// "session cleanup already done" — which assumed the AMF's own bookkeeping
    /// was the whole story and left the SMF without the gNB's confirmation.
    ///
    /// Decoded with the generated codec (#417 stage 5), which applies the §10.3.4.2
    /// rules for a RESPONSE: a not-comprehended "ignore IE and notify sender" IE is
    /// reported in an Error Indication and the transfers are relayed all the same;
    /// one marked "reject" terminates the procedure unsuccessfully, handled locally
    /// by relaying nothing -- what an undecodable response already got.
    async fn handle_pdu_session_resource_release_response(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        use crate::ngap_asn1::PduSessionResourceReleaseResponseDecode::{
            Failed, Released, Undecodable,
        };
        let (amf_ue_ngap_id, released) =
            match crate::ngap_asn1::decode_pdu_session_resource_release_response_asn1(data) {
                Released {
                    amf_ue_ngap_id,
                    released,
                    error_indication,
                    ..
                } => {
                    // Best effort: the report must not stop the relay below.
                    if let Some(report) = error_indication {
                        if let Err(e) = self
                            .send_criticality_error_indication(association_id, &report)
                            .await
                        {
                            log::warn!("Failed to send ErrorIndication: {e}");
                        }
                    }
                    (amf_ue_ngap_id, released)
                }
                Failed(diagnostics) => {
                    log::warn!(
                        "PDU Session Resource Release Response from association \
                         {association_id} carries not-comprehended IEs marked reject \
                         ({diagnostics:?}); the procedure is unsuccessfully terminated \
                         (TS 38.413 §10.3.4.2), handled locally"
                    );
                    return Ok(());
                }
                Undecodable => {
                    return self
                        .report_transfer_syntax_error(
                            association_id,
                            "PDU Session Resource Release Response",
                        )
                        .await;
                }
            };
        // The AMF UE NGAP ID has criticality ignore, so its absence is ignored
        // (§10.3.5) -- but it is what names the UE whose SM contexts the
        // transfers belong to, so without it there is nothing to relay them to.
        let Some(amf_ue_ngap_id) = amf_ue_ngap_id else {
            log::warn!(
                "PDU Session Resource Release Response from association {association_id} \
                 names no AMF UE NGAP ID; {} released transfers cannot be relayed",
                released.len()
            );
            return Ok(());
        };

        log::info!(
            "PDU Session Resource Release Response from association {association_id}: \
             UE {amf_ue_ngap_id}, released={}",
            released.len()
        );

        for item in &released {
            // An empty transfer is tolerated here: nothing in it to relay, so
            // relaying nothing is correct rather than an error to report.
            if item.transfer.is_empty() {
                log::debug!(
                    "Released PSI={} carries no Release Response Transfer; nothing \
                     to relay",
                    item.pdu_session_id
                );
                continue;
            }
            self.relay_n2_sm_to_smf(
                amf_ue_ngap_id,
                item.pdu_session_id,
                "PDU_RES_REL_RSP",
                &item.transfer,
                "PDUSessionResourceReleaseResponse",
            )
            .await;
        }
        Ok(())
    }

    /// Handle a PDU SESSION RESOURCE MODIFY INDICATION (TS 38.413 §8.2.4).
    ///
    /// A gNB-initiated modification (TS 23.502 §4.3.3.2, AN-initiated). Class 1:
    /// the AMF must answer with a PDU SESSION RESOURCE MODIFY CONFIRM. Each
    /// session's Modify Indication Transfer goes to the SMF as `PDU_RES_MOD_IND`,
    /// and the SMF's answer -- a Modify Confirm Transfer (`PDU_RES_MOD_CFM`) or a
    /// Modify Indication Unsuccessful Transfer (`PDU_RES_MOD_IND_FAIL`) -- goes
    /// back in the Confirm's modified or failed list. Before #525 the indication
    /// was relayed labelled `PDU_RES_SETUP_RSP` and never answered at all.
    ///
    /// Decoded with the generated codec (#417) under §10.3.4.2: "notify" IEs are
    /// reported in the Confirm's Criticality Diagnostics; "reject", or a missing
    /// mandatory IE, stops the procedure with an Error Indication (there is no
    /// unsuccessful outcome).
    async fn handle_pdu_session_resource_modify_indication(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        match self.modify_indication_answer(data).await {
            ModifyIndicationAnswer::Confirm(bytes) => {
                self.send_to_association(association_id, &bytes).await?;
                log::info!(
                    "PDU Session Resource Modify Confirm sent to association {association_id}"
                );
                Ok(())
            }
            ModifyIndicationAnswer::ErrorIndication(report) => {
                self.send_criticality_error_indication(association_id, &report)
                    .await
            }
            ModifyIndicationAnswer::TransferSyntaxError => {
                self.report_transfer_syntax_error(
                    association_id,
                    "PDU Session Resource Modify Indication",
                )
                .await
            }
            ModifyIndicationAnswer::Nothing => Ok(()),
        }
    }

    /// The answer to a PDU Session Resource Modify Indication: relay each
    /// session to the SMF and build the Modify Confirm from what it says. Split
    /// from the handler so the Confirm's content is testable without a gNB to
    /// send it to.
    async fn modify_indication_answer(&mut self, data: &[u8]) -> ModifyIndicationAnswer {
        use crate::ngap_asn1::PduSessionResourceModifyIndicationDecode::{
            Proceed, Reject, Undecodable,
        };
        let (amf_ue_ngap_id, ran_ue_ngap_id, sessions, notify) =
            match crate::ngap_asn1::decode_pdu_session_resource_modify_indication_asn1(data) {
                Proceed {
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    sessions,
                    notify,
                } => (amf_ue_ngap_id, ran_ue_ngap_id, sessions, notify),
                Reject(report) => return ModifyIndicationAnswer::ErrorIndication(report),
                Undecodable => return ModifyIndicationAnswer::TransferSyntaxError,
            };

        log::info!(
            "PDU Session Resource Modify Indication: UE {amf_ue_ngap_id}, {} sessions",
            sessions.len()
        );

        let mut confirmed = Vec::new();
        let mut failed = Vec::new();
        for item in &sessions {
            match self
                .relay_n2_sm_to_smf_with_answer(
                    amf_ue_ngap_id,
                    item.pdu_session_id,
                    "PDU_RES_MOD_IND",
                    &item.transfer,
                    "PDUSessionResourceModifyIndication",
                )
                .await
            {
                Some((Some(t), n2)) if t == "PDU_RES_MOD_CFM" && !n2.is_empty() => {
                    confirmed.push(crate::ngap_asn1::ModifyPduSession {
                        pdu_session_id: item.pdu_session_id,
                        transfer: n2,
                    });
                }
                Some((Some(t), n2)) if t == "PDU_RES_MOD_IND_FAIL" && !n2.is_empty() => {
                    failed.push(crate::ngap_asn1::ModifyPduSession {
                        pdu_session_id: item.pdu_session_id,
                        transfer: n2,
                    });
                }
                other => {
                    // No usable answer (no SM context, SMF unreachable or refusing,
                    // or no transfer): the gNB is told this session's modification
                    // failed rather than left without an entry for it.
                    log::warn!(
                        "PDUSessionResourceModifyIndication: no Modify Confirm Transfer \
                         from the SMF for UE {amf_ue_ngap_id} PSI {} ({:?}); reporting it \
                         failed",
                        item.pdu_session_id,
                        other.as_ref().map(|(t, n2)| (t.clone(), n2.len()))
                    );
                    if let Some(transfer) =
                        crate::ngap_asn1::modify_indication_unsuccessful_transfer(
                            nextgcore_ngap::types::Cause::Misc(
                                nextgcore_ngap::types::CauseMisc::Unspecified,
                            ),
                        )
                    {
                        failed.push(crate::ngap_asn1::ModifyPduSession {
                            pdu_session_id: item.pdu_session_id,
                            transfer,
                        });
                    }
                }
            }
        }

        match crate::ngap_asn1::build_pdu_session_resource_modify_confirm_asn1(
            amf_ue_ngap_id,
            ran_ue_ngap_id,
            &confirmed,
            &failed,
            &notify,
        ) {
            Some(bytes) => {
                log::info!(
                    "PDU Session Resource Modify Confirm for UE {amf_ue_ngap_id}: \
                     confirmed={}, failed={}",
                    confirmed.len(),
                    failed.len()
                );
                ModifyIndicationAnswer::Confirm(bytes)
            }
            None => {
                log::error!("Failed to build PDU Session Resource Modify Confirm");
                ModifyIndicationAnswer::Nothing
            }
        }
    }

    /// Handle a PDU SESSION RESOURCE NOTIFY (TS 38.413 §8.2.5).
    ///
    /// The gNB reports that a session's QoS flows are no longer (or are again)
    /// fulfilled, or that a session was released on its side. Both lists carry N2
    /// SM containers the SMF acts on.
    async fn handle_pdu_session_resource_notify(
        &mut self,
        association_id: u64,
        data: &[u8],
    ) -> Result<()> {
        // A class-2 procedure with no response (TS 38.413 §10.3.4.2, §10.3.5).
        let notify = match crate::ngap_asn1::decode_pdu_session_resource_notify_asn1(data) {
            crate::ngap_asn1::NasTransportDecode::Proceed {
                message,
                error_indication,
            } => {
                if let Some(report) = error_indication {
                    if let Some(ei) =
                        crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                    {
                        self.send_to_association(association_id, &ei).await?;
                    }
                }
                message
            }
            crate::ngap_asn1::NasTransportDecode::Reject(report) => {
                log::warn!(
                    "PDU Session Resource Notify from association {association_id} rejected: {report:?}"
                );
                if let Some(ei) = crate::ngap_asn1::build_criticality_error_indication_asn1(&report)
                {
                    self.send_to_association(association_id, &ei).await?;
                }
                return Ok(());
            }
            crate::ngap_asn1::NasTransportDecode::Undecodable => {
                // #752: TS 38.413 §10.2.
                log::warn!(
                    "Failed to decode PDU Session Resource Notify from association \
                     {association_id}; sending Error Indication (transfer-syntax-error)"
                );
                self.send_error_indication(
                    association_id,
                    None,
                    None,
                    ngap_gen::Cause::Protocol(ngap_gen::CauseProtocol(
                        ngap_gen::CauseProtocol::TRANSFER_SYNTAX_ERROR,
                    )),
                )
                .await?;
                return Ok(());
            }
        };

        log::info!(
            "PDU Session Resource Notify from association {association_id}: UE {}, \
             notify={}, released={}",
            notify.amf_ue_ngap_id,
            notify.notify_list.len(),
            notify.released_list.len()
        );

        for item in &notify.notify_list {
            self.relay_n2_sm_to_smf(
                notify.amf_ue_ngap_id,
                item.pdu_session_id,
                "PDU_RES_NTY",
                &item.transfer,
                "PDUSessionResourceNotify",
            )
            .await;
        }
        for item in &notify.released_list {
            // #582, TS 23.502 §4.3.4.2 step 1d -> 3a -> 4: when the SMF releases the
            // session the NG-RAN reported released, its answer carries the PDU Session
            // Release Command and no N2 resource release (the NG-RAN's resources are
            // already gone), so the AMF "transmits the NAS message ... to the UE".
            let Some(sm_context_ref) = self
                .sm_context_refs
                .get(&(notify.amf_ue_ngap_id, item.pdu_session_id))
                .cloned()
            else {
                log::error!(
                    "PDUSessionResourceNotify (released): no SM context ref stored for UE {} \
                     PSI {}",
                    notify.amf_ue_ngap_id,
                    item.pdu_session_id
                );
                continue;
            };
            let (host, port) = self.smf_target_for(notify.amf_ue_ngap_id, item.pdu_session_id);
            match crate::sbi_path::call_smf_update_sm_context_n2(
                &host,
                port,
                &sm_context_ref,
                "PDU_RES_NTY_REL",
                &item.transfer,
            )
            .await
            {
                Ok(resp) if !resp.n1_sm_msg.is_empty() => {
                    log::info!(
                        "PDUSessionResourceNotify (released): SMF ref={sm_context_ref} \
                         releases UE {} PSI {}; relaying its {}-byte N1 SM to the UE",
                        notify.amf_ue_ngap_id,
                        item.pdu_session_id,
                        resp.n1_sm_msg.len()
                    );
                    self.send_n1_sm_to_ue(
                        association_id,
                        notify.amf_ue_ngap_id,
                        notify.ran_ue_ngap_id,
                        item.pdu_session_id,
                        &resp.n1_sm_msg,
                    )
                    .await?;
                }
                Ok(_) => log::info!(
                    "PDUSessionResourceNotify (released): relayed to SMF ref={sm_context_ref} \
                     for UE {} PSI {}",
                    notify.amf_ue_ngap_id,
                    item.pdu_session_id
                ),
                Err(e) => log::warn!(
                    "PDUSessionResourceNotify (released): SMF update for UE {} PSI {} \
                     (ref={sm_context_ref}) failed: {e}",
                    notify.amf_ue_ngap_id,
                    item.pdu_session_id
                ),
            }
        }
        Ok(())
    }

    /// Handle an NG-RAN outcome for an MBS procedure (TS 23.247, TS 38.413 §9.2.9).
    ///
    /// All MBS procedures the AMF drives are AMF->NG-RAN initiating messages, so
    /// what arrives on the association is the gNB's Successful (`0x20`) or
    /// Unsuccessful (`0x40`) outcome. This updates the per-gNB session state in
    /// [`crate::ngap_mcast::NgapMcastContext`] so the MB-SMF can later be told
    /// what the RAN did.
    ///
    /// The session is located by `MBS-SessionID` (IE 299), which every MBS
    /// message carries, rather than by association: one gNB can hold several MBS
    /// sessions, so the association alone does not identify one.
    ///
    /// No ErrorIndication is emitted for an unparseable outcome. The procedure is
    /// one the AMF *does* implement, so the TS 38.413 §10.3 cause that the `_`
    /// fallthrough would attach (`abstract-syntax-error-reject`) would be a lie;
    /// the honest response to a malformed outcome of a known procedure is to log
    /// it and leave the session in its current state, which a later timeout or a
    /// re-drive resolves.
    async fn handle_mbs_outcome(
        &mut self,
        association_id: u64,
        procedure_code: Option<u16>,
        data: &[u8],
    ) -> Result<()> {
        let outcome = match data.first() {
            Some(0x20) => MbsOutcome::Successful,
            Some(0x40) => MbsOutcome::Unsuccessful,
            // An INITIATING MBS message from a gNB. Only
            // BroadcastSessionReleaseRequired (75) is gNB-initiated in TS 38.413,
            // and it is not in this arm, so this is a peer error.
            _ => {
                log::warn!(
                    "MBS procedure {procedure_code:?} arrived as an initiating message from \
                     association {association_id}; the AMF is the initiator for 68/71/72/73/74"
                );
                return Ok(());
            }
        };

        let Some(mbs_session_id) = crate::ngap_asn1::extract_mbs_session_id(data) else {
            log::warn!(
                "MBS outcome for procedure {procedure_code:?} from association \
                 {association_id} carries no decodable MBS-SessionID (IE 299); \
                 session state left unchanged"
            );
            return Ok(());
        };

        let gnb_id = self.gnb_id_for_association(association_id).await;
        let mcast = crate::context::amf_mcast();

        let Some(session) = mcast.session_find_by_tmgi(&mbs_session_id) else {
            log::warn!(
                "MBS outcome for an unknown session (tmgi_svc={:#x}) from association \
                 {association_id}; the AMF holds no such MBS session",
                mbs_session_id.service_id_u32()
            );
            return Ok(());
        };
        let session_id = session.mbs_session_id;
        let success = matches!(outcome, MbsOutcome::Successful);

        match procedure_code {
            Some(71) => {
                // The gNB's UL TEID would arrive in the activation response's
                // transfer. It is NOT read here: multicast transport is
                // established by the Distribution Setup procedures (69/70), which
                // this AMF does not yet drive, so there is nowhere for a TEID to
                // be used. Recording one would be a value with no consumer.
                let all = mcast.session_activation_response(session_id, gnb_id, None, success);
                log::info!(
                    "MBS activation outcome: session={session_id} gnb={gnb_id} \
                     success={success} all_responded={all}"
                );
            }
            Some(72) => {
                let all = mcast.session_deactivation_response(session_id, gnb_id);
                log::info!(
                    "MBS deactivation outcome: session={session_id} gnb={gnb_id} \
                     all_inactive={all}"
                );
            }
            // 68 (BroadcastSessionSetup), 73 (MulticastSessionUpdate) and 74
            // (MulticastGroupPaging) have no state transition to record yet:
            // broadcast sessions are not modelled in NgapMcastContext, update has
            // no AMF-side driver, and paging is fire-and-forget with criticality
            // ignore. Logged so the outcome is visible rather than silently
            // dropped, and deliberately not invented into a state change.
            other => {
                log::info!(
                    "MBS outcome for procedure {other:?} from association {association_id} \
                     (session={session_id} gnb={gnb_id} success={success}) accepted; \
                     no AMF state transition is defined for it yet"
                );
            }
        }

        Ok(())
    }

    /// The gNB id this association belongs to, or 0 when the association has no
    /// completed NG Setup.
    async fn gnb_id_for_association(&self, association_id: u64) -> u32 {
        self.sessions
            .read()
            .await
            .get(&association_id)
            .map(|g| g.id as u32)
            .unwrap_or(0)
    }

    /// Handle UE Context Release Request from gNB
    ///
    /// Releases all PDU sessions at SMF and sends UEContextReleaseCommand back.
    async fn handle_ue_context_release(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        log::info!(
            "UE Context Release Request from association {} ({} bytes)",
            association_id,
            data.len()
        );

        // #417 stage 4: decoded with the generated codec, which applies TS 38.413
        // §10.3.4.2/§10.3.5 for a procedure with no response message. A request the AMF
        // must reject is terminated with an Error Indication and nothing is released;
        // "ignore IE and notify sender" IEs are reported in one and the release goes on.
        use crate::ngap_asn1::UeContextReleaseRequestDecode::{Proceed, Reject, Undecodable};
        let (amf_ue_ngap_id, ran_ue_ngap_id, cause) =
            match crate::ngap_asn1::decode_ue_context_release_request_asn1(data) {
                Proceed {
                    amf_ue_ngap_id,
                    ran_ue_ngap_id,
                    cause,
                    error_indication,
                } => {
                    // Best effort: the report must not stop the release it reports on.
                    if let Some(report) = error_indication {
                        if let Err(e) = self
                            .send_criticality_error_indication(association_id, &report)
                            .await
                        {
                            log::warn!("Failed to send ErrorIndication: {e}");
                        }
                    }
                    (Some(amf_ue_ngap_id), Some(ran_ue_ngap_id), cause)
                }
                Reject(report) => {
                    log::warn!(
                        "UE Context Release Request rejected (TS 38.413 §10.3.4.2/§10.3.5): \
                         {:?}",
                        report.diagnostics
                    );
                    return self
                        .send_criticality_error_indication(association_id, &report)
                        .await;
                }
                // Nothing identifies a UE to release (#999, TS 38.413 §10.2).
                Undecodable => {
                    return self
                        .report_transfer_syntax_error(association_id, "UE Context Release Request")
                        .await
                }
            };

        log::info!(
            "UE Context Release: AMF UE NGAP ID={amf_ue_ngap_id:?}, RAN UE NGAP ID={ran_ue_ngap_id:?}"
        );

        // #397: COMMUNICATION_FAILURE_REPORT. This is the AMF becoming aware of a RAN
        // failure "based on connection release", identifying the "RAN/NAS release code"
        // -- TS 23.502 table 4.15.3.1-1 (`23502-k20.txt:28570-28577`) names the AMF as
        // the detecting NF and this as the mechanism, and TS 29.518 §6.2 implements that
        // table row as this event type (`29518-k00.txt:5126-5131`).
        //
        // Fired BEFORE the PDU-session teardown below, because the Cause the gNB sent is
        // what the report carries and the teardown is the consequence, not the event.
        //
        // The Cause is the release code the RAN actually sent, decoded off the wire, so
        // there is no placeholder here. (#397's own text says "Neither release code is
        // plumbed anywhere the event could read it"; the ran one was, one call away.) It
        // is mandatory with criticality ignore, so a request without one is still
        // released (TS 38.413 §10.3.5) -- with no release code to report.
        if let (Some(ngap_id), Some((group, value))) = (amf_ue_ngap_id, cause) {
            if is_communication_failure_cause(group, value) {
                if let Some(state) = self.ue_auth_state.get(ngap_id) {
                    crate::namf_server::fire_communication_failure(&state.amf_ue, group, value);
                }
            } else {
                log::debug!(
                    "UE Context Release Request cause group={group} value={value} is an expected \
                     release, so no COMMUNICATION_FAILURE_REPORT (TS 23.502 table 4.15.3.1-1 \
                     defines the event as an UNEXPECTED termination)"
                );
            }
        }

        // Release all PDU sessions at SMF
        let smf_host = std::env::var("SMF_SBI_ADDR").unwrap_or_else(|_| "127.0.0.1".to_string());
        let smf_port: u16 = std::env::var("SMF_SBI_PORT")
            .ok()
            .and_then(|p| p.parse().ok())
            .unwrap_or(7777);

        // Look up active sessions for this UE via AMF UE NGAP ID -> RanUe -> amf_ue_id -> sessions
        // Collect session refs under the read lock, then release lock before async SMF calls
        let sm_context_refs: Vec<(u8, String)> = {
            let mut refs = Vec::new();
            if let Some(ngap_id) = amf_ue_ngap_id {
                let ctx = crate::context::amf_self();
                let context = ctx.read();
                if let Ok(context) = context {
                    let amf_ue_id = context
                        .ran_ue_find_by_amf_ue_ngap_id(ngap_id)
                        .map(|ran_ue| ran_ue.amf_ue_id)
                        .unwrap_or(ngap_id);

                    for sess in context.sess_list_for_ue(amf_ue_id).iter() {
                        if let Some(ref r) = sess.sm_context_ref {
                            refs.push((sess.psi, r.clone()));
                        }
                    }
                }
            }
            refs
        };

        if sm_context_refs.is_empty() {
            log::debug!("No PDU sessions to release for UE context release");
        }
        // #540 / TS 23.502 §4.2.6: an AN release keeps a REGISTERED UE's PDU
        // sessions -- only their user plane is deactivated, at Release Complete
        // (`deactivate_up_connections`), so downlink data is buffered and pages
        // the UE. Releasing them here left nothing for paging or the Service
        // Request to bring back. An unregistered UE has no use for them.
        let keeps_sessions = amf_ue_ngap_id
            .and_then(|id| self.ue_auth_state.get(id))
            .is_some_and(|s| s.registered);
        let sm_context_refs = if keeps_sessions {
            if !sm_context_refs.is_empty() {
                log::info!(
                    "AN release of a registered UE: keeping {} PDU session(s), their user \
                     plane is deactivated at Release Complete (TS 23.502 §4.2.6)",
                    sm_context_refs.len()
                );
            }
            Vec::new()
        } else {
            sm_context_refs
        };
        for (psi, sm_context_ref) in &sm_context_refs {
            log::info!("Releasing SMF SM Context: PSI={psi}, ref={sm_context_ref}");
            match crate::sbi_path::call_smf_release_sm_context(&smf_host, smf_port, sm_context_ref)
                .await
            {
                Ok(()) => log::info!("SMF SM Context Released: PSI={psi}"),
                Err(e) => log::warn!("SMF release failed for PSI={psi}: {e}"),
            }
        }

        // Build and send UEContextReleaseCommand (Cause: NAS normal-release)
        if let (Some(amf_id), Some(ran_id)) = (amf_ue_ngap_id, ran_ue_ngap_id) {
            let release_cmd = crate::ngap_asn1::build_ue_context_release_command_asn1(
                amf_id,
                ran_id,
                ngap_handler::cause_group::NAS,
                0, // CauseNas normal-release
            );
            if let Some(cmd) = release_cmd {
                self.send_to_association(association_id, &cmd).await?;
                log::info!("UE Context Release Command sent to gNB");
            }
        }

        Ok(())
    }

    /// Send Paging to all connected gNBs in the UE's tracking area
    ///
    /// This is called when the AMF needs to page a UE in CM-IDLE state,
    /// e.g., when downlink data notification is received from SMF.
    /// The associations of the gNBs serving at least one of these TAIs: a TAI
    /// matches a gNB's SupportedTAList entry when both its TAC and one of that
    /// entry's broadcast PLMNs match (TS 38.413 §9.3.3.8). Paging goes only to
    /// these (TS 38.413 §8.5.1, TS 23.502 §4.2.3.3 step 4b).
    async fn paging_target_associations(&self, tais: &[(crate::context::PlmnId, u32)]) -> Vec<u64> {
        self.sessions
            .read()
            .await
            .values()
            .filter(|session| {
                tais.iter().any(|(plmn, tac)| {
                    session.gnb.supported_ta_list.iter().any(|ta| {
                        ta.tac == *tac && ta.bplmn_list.iter().any(|b| b.plmn_id == *plmn)
                    })
                })
            })
            .map(|session| session.association_id)
            .collect()
    }

    /// Send the NGAP PAGING for one paging context to every gNB serving the
    /// UE's registration area. Returns how many associations it went out on.
    pub async fn send_paging(&mut self, paging: &crate::context::PagingContext) -> Result<usize> {
        let tais = paging.paging_tais();
        // The PAGING's TAI List for Paging names the registration area. This AMF
        // assigns a one-TAI registration area (`gmm_build`), so it is that TAI.
        let (plmn_id, tac) = tais
            .first()
            .cloned()
            .unwrap_or((paging.plmn_id.clone(), paging.tac));
        let Some(paging_bytes) = crate::ngap_asn1::build_paging_asn1(
            paging.amf_set_id,
            paging.amf_pointer,
            paging.tmsi,
            &plmn_id,
            tac,
        ) else {
            log::error!("Failed to build Paging message");
            return Err(anyhow::anyhow!("Failed to build Paging message"));
        };

        let targets = self.paging_target_associations(&tais).await;
        let mut sent = 0usize;
        for assoc_id in &targets {
            match self.send_to_association(*assoc_id, &paging_bytes).await {
                Ok(()) => sent += 1,
                Err(e) => log::warn!("Failed to send Paging to association {assoc_id}: {e}"),
            }
        }
        log::info!(
            "Paging sent to {sent}/{} gNB(s) serving the registration area: \
             5G-S-TMSI=({}, {}, 0x{:08x}), attempt {}",
            targets.len(),
            paging.amf_set_id,
            paging.amf_pointer,
            paging.tmsi,
            u32::from(paging.retransmit_count) + 1
        );
        Ok(sent)
    }

    /// The paging pump (#512): transmit due PAGINGs and abandon expired ones.
    ///
    /// TS 24.501 §5.6.2.2.1 starts T3513 when paging starts; §5.6.2.2.2 has the
    /// network retransmit on T3513 expiry and restart it, a bounded number of
    /// times. On the last expiry, TS 23.502 §4.2.3.3 step 4c: the AMF tells the
    /// requester with Namf_Communication_N1N2TransferFailureNotification, cause
    /// UE_NOT_RESPONDING (TS 29.518 Table 6.1.6.3.x / §6.1.6.2.8).
    async fn process_paging(&mut self) {
        self.process_paging_with(paging_t3513()).await;
    }

    /// [`Self::process_paging`] with T3513 supplied, so a test can run the whole
    /// retransmission ladder without sleeping.
    async fn process_paging_with(&mut self, t3513: Duration) {
        let due = {
            let ctx = crate::context::amf_self();
            let guard = ctx.read().unwrap_or_else(|e| e.into_inner());
            guard.paging_take_due(t3513)
        };
        for paging in &due.send {
            if let Err(e) = self.send_paging(paging).await {
                log::warn!("Paging for UE {} not sent: {e}", paging.amf_ue_ngap_id);
            }
        }
        for paging in due.expired {
            self.paging_abandoned(&paging);
        }
    }

    /// Final T3513 expiry: notify the requester and clear the session's paging
    /// state, so a later transfer is not refused as "paging ongoing".
    fn paging_abandoned(&self, paging: &crate::context::PagingContext) {
        if let Some(uri) = &paging.failure_notify_uri {
            crate::namf_server::send_n1n2_failure_notification(
                uri.clone(),
                "UE_NOT_RESPONDING",
                paging.n1n2_msg_data_uri.clone(),
            );
        }
        clear_session_paging(paging);
        log::warn!(
            "Paging abandoned for UE {}: no response after {} attempt(s){}",
            paging.amf_ue_ngap_id,
            u32::from(paging.retransmit_count) + 1,
            if paging.failure_notify_uri.is_some() {
                ", requester notified (UE_NOT_RESPONDING)"
            } else {
                ""
            }
        );
    }

    /// Send message to a gNB by association ID
    /// NOTE: This method requires &mut self to access the SCTP server
    async fn send_to_association(&mut self, association_id: u64, data: &[u8]) -> Result<()> {
        log::debug!(
            "Sending {} bytes to association {}",
            data.len(),
            association_id
        );

        #[cfg(test)]
        if self.fail_next_sends > 0 {
            self.fail_next_sends -= 1;
            return Err(anyhow::anyhow!("SCTP send error: injected by a test"));
        }
        let stream_id = self.ngap_stream_for(association_id, data);
        #[cfg(test)]
        if let Some(sent) = self.sent_ngap.as_mut() {
            sent.push((association_id, stream_id, data.to_vec()));
            return Ok(());
        }

        self.transport
            .send(association_id, stream_id, data)
            .await
            .map_err(|e| anyhow::anyhow!("SCTP send error: {e}"))
    }

    /// The SCTP stream an NGAP PDU goes out on (TS 38.412 §7, #813).
    ///
    /// §7 reserves one stream pair for the sole use of non-UE-associated signalling and
    /// at least one pair for UE-associated signalling, and "for a single UE-associated
    /// signalling ... one SCTP stream" that "should not be changed". So:
    ///
    /// - a non-UE-associated PDU (NG Setup, NG Reset, RAN / AMF Configuration Update,
    ///   Paging, PWS, Overload, an Error Indication without UE ids, ...) goes on stream 0;
    /// - a UE-associated one goes on stream `1 + key % (n - 1)`, where `n` is the
    ///   association's negotiated outbound stream count and `key` is the UE's AMF UE
    ///   NGAP ID (its RAN UE NGAP ID when the PDU carries no AMF one). The AMF UE NGAP ID
    ///   is fixed for the UE on the association, so its stream is too.
    ///
    /// With fewer than two negotiated streams the peer left no second pair, and stream 0
    /// is the only valid identifier.
    fn ngap_stream_for(&mut self, association_id: u64, pdu: &[u8]) -> u16 {
        let Some(ue) = crate::ngap_asn1::ue_association_key(pdu) else {
            return 0;
        };
        let Some(outbound) = self.outbound_streams_of(association_id) else {
            return 0;
        };
        let key = match ue {
            crate::ngap_asn1::UeAssociation::Amf(id) => id,
            // Only the RAN UE NGAP ID (e.g. an Error Indication): resolve the UE it names
            // on THIS association, so its PDUs stay on the one stream §7 asks for. With
            // two streams there is only stream 1, so the lookup is skipped.
            crate::ngap_asn1::UeAssociation::Ran(ran) if outbound > 2 => self
                .ue_auth_state
                .snapshot()
                .into_iter()
                .find(|(_, s)| s.association_id == association_id && s.ran_ue_ngap_id == ran)
                .map(|(amf_ue_ngap_id, _)| amf_ue_ngap_id)
                .unwrap_or(u64::from(ran)),
            crate::ngap_asn1::UeAssociation::Ran(ran) => u64::from(ran),
        };
        ue_associated_stream(key, outbound)
    }

    /// The negotiated outbound stream count of `association_id`, asked of the transport
    /// once per association and cached (#813, review of #870): the kernel backend answers
    /// with a `getsockopt`, which must not run per PDU, and an association whose count is
    /// unknown is warned about once, not at signalling rate. The entry goes when the
    /// association closes. `None` sends everything on stream 0.
    fn outbound_streams_of(&mut self, association_id: u64) -> Option<u16> {
        #[cfg(test)]
        if self.sent_ngap.is_some() {
            return Some(self.test_outbound_streams);
        }
        if let Some(cached) = self.outbound_streams.get(&association_id) {
            return *cached;
        }
        let count = self.transport.outbound_streams(association_id);
        if count.is_none() {
            log::warn!(
                "association {association_id}: negotiated outbound stream count unknown; \
                 its UE-associated NGAP goes on stream 0"
            );
        }
        self.outbound_streams.insert(association_id, count);
        count
    }

    /// Send message to a gNB by ID
    pub async fn send_by_id(&mut self, gnb_id: u64, data: &[u8]) -> Result<()> {
        // Find the association ID for this gNB ID, then drop the read lock
        // before calling send_to_association (which needs &mut self).
        let assoc_id = {
            let sessions = self.sessions.read().await;
            sessions
                .iter()
                .find(|(_, session)| session.id == gnb_id)
                .map(|(assoc_id, _)| *assoc_id)
        };

        match assoc_id {
            Some(assoc_id) => {
                log::debug!("Sending {} bytes to gNB {}", data.len(), gnb_id);
                self.send_to_association(assoc_id, data).await
            }
            None => Err(anyhow::anyhow!("gNB {gnb_id} not found")),
        }
    }

    /// Close a gNB session
    pub async fn close_session(&self, association_id: u64) -> Result<()> {
        if let Some(session) = self.sessions.write().await.remove(&association_id) {
            log::info!(
                "Closed gNB session {} (association {})",
                session.id,
                association_id
            );
            self.assoc_to_addr.write().await.remove(&association_id);
        }
        Ok(())
    }
}

// ============================================================================
// NAS parsing / helper functions (TS 24.501)
// ============================================================================

/// This AMF's `nfInstanceId`, the one it registers with the NRF and the UDM.
///
/// #753: this used to be a SECOND random UUID per process, so it could not be
/// pinned (`NEXTGCORE_AMF_INSTANCE_ID` did not reach it). After every restart the
/// UDM therefore saw a "new AMF" and sent the restarted AMF a
/// UE_INITIAL_REGISTRATION dereg-notify for each re-registering UE.
fn amf_instance_id() -> String {
    nextgcore_sbi::nf_instance_id::nf_instance_id(nextgcore_sbi::types::NfType::Amf).to_string()
}

/// Nudm_UECM_Registration (amf-3gpp-access) for `amf_ue` under this AMF's
/// `nfInstanceId` (#753), with a fresh `deregCallbackUri` token.
///
/// The token is recorded on the UE only once the UDM has ACCEPTED the
/// registration. After a failed PUT the UDM still holds the previous registration
/// and its URI, and a genuine notification about it must still act. During the
/// PUT the UE is out of the store (`complete_registration` holds it), so a
/// notification the PUT provokes for an older registration gets 404 anyway.
/// Afterwards it names an older token and is ignored.
async fn register_with_udm_uecm(
    amf_ue: &mut AmfUe,
    udm_host: &str,
    udm_port: u16,
    supi: &str,
    guami_mcc: &str,
    guami_mnc: &str,
    amf_id_hex: &str,
) -> crate::sbi_path::SbiResult<()> {
    let dereg_token = crate::sbi_path::new_dereg_callback_token();
    crate::sbi_path::call_udm_uecm_registration(
        udm_host,
        udm_port,
        supi,
        &amf_instance_id(),
        &dereg_token,
        guami_mcc,
        guami_mnc,
        amf_id_hex,
    )
    .await?;
    amf_ue.uecm_dereg_token = Some(dereg_token);
    Ok(())
}

/// [`amf_instance_id`], for the UECM wire test in `sbi_path`.
#[cfg(test)]
pub(crate) fn amf_instance_id_for_tests() -> String {
    amf_instance_id()
}

/// Parsed Registration Request (TS 24.501 Section 8.2.6)
#[derive(Debug, Clone, Default)]
struct ParsedRegistrationRequest {
    registration_type: u8,
    tsc: u8,
    ksi: u8,
    identity_type: u8,
    suci: Option<String>,
    guti: Option<Guti5gs>,
    plmn: Option<PlmnId>,
    sec_cap: Option<UeSecurityCapability>,
    requested_nssai: Vec<SNssai>,
    /// SNPN NID (Rel-17, TS 23.501 §5.30) included by the UE, if any.
    snpn_nid: Option<String>,
    /// MINT disaster-roaming indication (Rel-18, TS 23.761 §4.2). Set when the
    /// UE requests disaster-roaming / minimization-of-service-interruption
    /// handling for this (e.g. secondary multi-SUPI) registration.
    disaster_roaming: bool,
    /// UAV indication (Rel-18, TS 23.256). `Some(caa_id)` when the UE
    /// registered as an aerial UE; the AMF then creates a UAV flight
    /// authorization (geofence) context. The string is the UAV CAA-level ID
    /// (may be empty when only the aerial-UE capability is signalled).
    uav_indication: Option<String>,
    /// RedCap (Reduced Capability) indication (Rel-17, TS 38.101). Set when the
    /// UE signals a reduced-capability device (NAS IEI 0xA9) so the AMF caps
    /// UE-AMBR and forwards the indication to the SMF for a reduced session-AMBR.
    redcap_indication: bool,
    /// Presence bitmask of the optional IEs surfaced by
    /// `parse_registration_request_pdu`, used by the §4.4.6 cleartext-IE gate
    /// (`validate_initial_registration_cleartext`). See the `reg_present` bit
    /// constants.
    presencemask: u64,
    /// Whether a NAS message container IE (0x71) was present. Per TS 24.501
    /// §4.4.6 it must not appear in an unprotected initial NAS message.
    nas_message_container_present: bool,
    /// Payload container type from the half-octet IEI `8-` (TS 24.501 §9.11.3.40).
    payload_container_type: Option<u8>,
    /// Whether the UE claimed S1 mode (EPC NAS) support in its 5GMM capability IE
    /// (IEI 0x10, TS 24.501 §9.11.3.1 octet 3 bit 1).
    ///
    /// #116: the IE was walked past by the default TLV arm, so `s1_mode` was
    /// write-never and the AMF could not obey §5.5.1.2.4 — which makes signalling
    /// `IWK N26` conditional on exactly this bit.
    s1_mode: bool,
    /// RACS (#570): the 5GMM capability IE's RACS bit (octet 4 bit 8,
    /// TS 24.501 §9.11.3.1).
    racs_supported: bool,
    /// RACS (#570): the UE radio capability ID IE's value octets (IEI 0x67,
    /// TS 24.501 §9.11.3.68), a non-cleartext IE (§4.4.6).
    ue_radio_capability_id: Option<Vec<u8>>,
    /// EPS NAS message container contents (IEI 0x70, TLV-E, TS 24.501 §9.11.3.24).
    ///
    /// #116: previously skipped. Per §5.5.1.2.2 a UE arriving from EPS puts an
    /// ATTACH REQUEST (or TRACKING AREA UPDATE REQUEST) here, and its PRESENCE is how
    /// the AMF knows the 5GS mobile identity holds a 5G-GUTI **mapped** from a
    /// 4G-GUTI rather than a native one — see [`Self::guti_is_mapped_from_eps`].
    eps_nas_message_container: Option<Vec<u8>>,
    /// Additional GUTI IE (IEI 0x77, TLV-E) decoded as a 5G-GUTI.
    ///
    /// Per §5.5.1.2.2 a UE that maps a 4G-GUTI into the 5GS mobile identity IE puts
    /// its valid NATIVE 5G-GUTI here, if it holds one. So on the EPS→5GS path this is
    /// the identity that may be treated as native, and the one in the mobile identity
    /// IE is not.
    additional_guti: Option<Guti5gs>,
    /// Payload container contents from IEI 0x7B (§9.11.3.39).
    ///
    /// #91: §5.5.1.2.2 lets a UE carry a "UE policy container" here holding a UE
    /// STATE INDICATION with the UPSIs it already has installed. The bytes were
    /// SKIPPED before -- the arm that handles 0x7B advanced past them and kept
    /// nothing -- so the PCF could never learn the UE's installed set and could only
    /// push a full policy.
    payload_container: Option<Vec<u8>>,
}

impl ParsedRegistrationRequest {
    /// The payload container's contents when it is a UE policy container.
    ///
    /// Gated on the TYPE, because a container of some other type is not one:
    /// forwarding an SMS container to the PCF's UPDP decoder would be worse than
    /// dropping it. `PAYLOAD_CONTAINER_TYPE_UE_POLICY` is `6` (§9.11.3.40).
    fn ue_policy_container(&self) -> Option<&[u8]> {
        const PAYLOAD_CONTAINER_TYPE_UE_POLICY: u8 = 6;
        match (self.payload_container_type, self.payload_container.as_ref()) {
            (Some(PAYLOAD_CONTAINER_TYPE_UE_POLICY), Some(bytes)) => Some(bytes),
            _ => None,
        }
    }

    /// Is the 5GS mobile identity a 5G-GUTI **mapped from a 4G-GUTI** (TS 23.003
    /// §2.10.2.2.2) rather than a native one?
    ///
    /// There is no separate identity TYPE for it — §9.11.3.4 has one `5G-GUTI` value
    /// and a mapped GUTI is structurally identical to a native one, which is exactly
    /// why storing it as native was silent. The discriminator is the **EPS NAS message
    /// container**: §5.5.1.2.2 requires a UE that maps its 4G-GUTI to include an
    /// ATTACH REQUEST in that IE, and §5.5.1.3.4 case c.2 reads the same way round
    /// ("has included the 5G-GUTI mapped from the 4G-GUTI in the 5GS mobile identity
    /// IE and not included an Additional GUTI IE").
    ///
    /// Gated on the identity actually being a GUTI: a UE registering with a SUCI can
    /// also carry an EPS NAS message container, and calling that a mapped GUTI would
    /// be a second wrong answer.
    fn guti_is_mapped_from_eps(&self) -> bool {
        self.eps_nas_message_container.is_some()
            && self.identity_type == mobile_identity_type::GUTI
            && self.guti.is_some()
    }
}

/// Presence bits set in `ParsedRegistrationRequest::presencemask` for the
/// TS 24.501 §4.4.6 cleartext-IE gate. Mirrors the (dead-code) gmm_handler
/// logic but operates on the live `ParsedRegistrationRequest`. Cleartext IEs
/// (permitted in an unprotected initial NAS message) are folded into
/// `REGISTRATION_CLEARTEXT_PRESENT`; any bit OUTSIDE that mask is a
/// non-cleartext IE whose presence in an unprotected initial Registration
/// Request is a §4.4.6 violation (5GMM #95). Rel-17/18 capability indications
/// (SNPN NID / RedCap / MINT / UAV) are intentionally NOT assigned a bit so
/// they never trip the gate.
mod reg_present {
    /// UE security capability (IEI 0x2E) — cleartext.
    pub const UE_SECURITY_CAPABILITY: u64 = 1 << 0;
    /// Additional GUTI (IEI 0x77, TLV-E) — cleartext.
    pub const ADDITIONAL_GUTI: u64 = 1 << 1;
    /// Requested NSSAI (IEI 0x2F) — NOT cleartext.
    pub const REQUESTED_NSSAI: u64 = 1 << 2;
    /// Last visited registered TAI (IEI 0x52) — NOT cleartext.
    pub const LAST_VISITED_TAI: u64 = 1 << 3;
}

/// IEs permitted in an unprotected initial NAS message per TS 24.501 §4.4.6.
const REGISTRATION_CLEARTEXT_PRESENT: u64 =
    reg_present::UE_SECURITY_CAPABILITY | reg_present::ADDITIONAL_GUTI;

/// Enforce the TS 24.501 §4.4.6 / TS 33.501 §6.4.6 cleartext-IE rule on a
/// Registration Request before it influences UE context state.
///
/// When the message is integrity-protected — the full request replayed inside
/// Security Mode Complete, or a mobility/periodic update sent over an existing
/// NAS security context — every IE is permitted and this returns `None`.
///
/// When the message is an unprotected initial NAS message (no security context
/// yet), only the §4.4.6 cleartext IEs are allowed: a non-cleartext IE (e.g.
/// Requested NSSAI), or a NAS message container, present in the clear is a
/// conformance violation and returns `Some(SemanticallyIncorrectMessage)`
/// (5GMM #95). The full Requested NSSAI etc. must instead be taken from the
/// integrity-protected replay inside Security Mode Complete.
fn validate_initial_registration_cleartext(
    req: &ParsedRegistrationRequest,
    integrity_protected: bool,
) -> Option<GmmCause> {
    if integrity_protected {
        return None;
    }
    // Non-cleartext IE present in an unprotected initial NAS message.
    if (req.presencemask & !REGISTRATION_CLEARTEXT_PRESENT) != 0 {
        log::error!(
            "Non-cleartext IE in unprotected initial Registration Request \
             (presencemask={:#x}); rejecting (5GMM #95)",
            req.presencemask
        );
        return Some(GmmCause::SemanticallyIncorrectMessage);
    }
    // A NAS message container cannot be trusted before a security context exists.
    if req.nas_message_container_present {
        log::error!(
            "NAS message container in unprotected initial Registration Request; \
             rejecting (5GMM #95)"
        );
        return Some(GmmCause::SemanticallyIncorrectMessage);
    }
    None
}

/// Assemble the UE and serving-network identity the AMF conveys on N11
/// (TS 29.502 §6.1.6.2.2 `SmContextCreateData`) from the UE's NAS context and the
/// AMF's own served GUAMI.
///
/// Every member is `Option`: an identity the AMF does not hold is OMITTED by
/// `build_create_sm_context_request` rather than placeheld, because a wrong
/// identity is worse than an absent one (issue #73).
///
/// Extracted from the inline block at the CreateSMContext call site so that this
/// mapping is reachable from a test. It is the half of the identity path that was
/// unguarded: a test that hands `build_create_sm_context_request` an identity it
/// built itself proves the SERIALISER emits what it is given, and would keep
/// passing if this function returned `None` for every member.
fn build_sm_context_identity(
    state: Option<&UeNasContext>,
    served_guami: Option<&crate::context::Guami>,
) -> crate::sbi_path::SmContextIdentity {
    // The serving PLMN: prefer the TAI the UE is actually in, then the AMF's own
    // served GUAMI. Never a literal.
    let serving_plmn = state
        .map(|s| &s.amf_ue.nr_tai.plmn_id)
        .map(|p| (p.mcc(), p.mnc()))
        .or_else(|| served_guami.map(|g| (g.plmn_id.mcc(), g.plmn_id.mnc())));
    let guami = served_guami.map(|g| {
        serde_json::json!({
            "plmnId": { "mcc": g.plmn_id.mcc(), "mnc": g.plmn_id.mnc() },
            "amfId": format!(
                "{:02x}{:03x}{:02x}",
                g.amf_id.region, g.amf_id.set, g.amf_id.pointer
            ),
        })
    });
    // TS 29.571 UserLocation: the serving NR TAI.
    let ue_location = state.map(|s| &s.amf_ue.nr_tai).map(|tai| {
        serde_json::json!({
            "nrLocation": {
                "tai": {
                    "plmnId": {
                        "mcc": tai.plmn_id.mcc(),
                        "mnc": tai.plmn_id.mnc(),
                    },
                    "tac": format!("{:06x}", tai.tac),
                }
            }
        })
    });
    crate::sbi_path::SmContextIdentity {
        supi: state.and_then(|s| s.amf_ue.supi.clone()),
        pei: state.and_then(|s| s.amf_ue.pei.clone()),
        guami,
        serving_plmn,
        serving_nf_id: None,
        ue_location,
        // Issue #205: the UE's EXTERNAL identity, stored on the UE context from
        // the `gpsis` array of the `am-data` the AMF retrieves at registration.
        gpsi: state.and_then(|s| s.amf_ue.gpsi.clone()),
        // Set by the establishment that sends it (#980 review).
        origination_timestamp: None,
    }
}

/// amfd-06: choose the authorized Allowed-NSSAI for a Registration Accept
/// (TS 23.502 §4.2.2.2.3, TS 24.501 §9.11.3.37).
///
/// Authorization is network-authoritative only: the UDM `subscribed` slice set
/// is used when present, otherwise the AMF's configured `plmn_default` slice
/// support. The UE's Requested NSSAI is deliberately NOT a parameter — it is the
/// UE's *ask*, never an authorization, and must never be echoed back as the
/// Allowed NSSAI. An empty return value means no S-NSSAI is authorized; the
/// caller MUST then reject the registration with 5GMM cause #62 (No network
/// slices available) rather than send a Registration Accept.
fn select_allowed_nssai(subscribed: &[SNssai], plmn_default: &[SNssai]) -> Vec<SNssai> {
    if !subscribed.is_empty() {
        subscribed.to_vec()
    } else {
        plmn_default.to_vec()
    }
}

/// amfd-05: build a NAS Authentication Request that relays an AUSF EAP-Request
/// to the UE (EAP-AKA', TS 33.501 §6.1.3.1; TS 24.501 §5.4.1.2.4 / §9.11.2.2).
///
/// The AMF is a transparent EAP passthrough: it copies the `eap_payload` bytes
/// returned by the AUSF (`Nausf_UEAuthentication`, TS 29.509 §6.1.3) verbatim
/// into the EAP message IE (IEI 0x78, type 6 TLV-E) of an Authentication Request,
/// alongside the ngKSI and ABBA. No RAND/AUTN are present (those belong to the
/// 5G-AKA path). Encoded via nextgcore-nas so the wire image is conformant.
///
/// This is the additive, self-contained core of amfd-05. Driving the EAP
/// round-trips needs the AUSF `eap-session` SBI plumbing in `sbi_path.rs`
/// (out of this change's scope) — see the module status note.
///
/// FLAGGED: not yet called by the live authentication path. The branch that
/// selects EAP-AKA' (on AUSF `authType == "EAP_AKA_PRIME"`) and loops
/// `eapPayload` to/from the AUSF `eap-session` lives in `sbi_path.rs`, which is
/// out of scope for this amfd-only change; wiring is E2E-deferred.
#[allow(dead_code)]
fn build_eap_authentication_request(tsc: u8, ksi: u8, abba: &[u8], eap_payload: &[u8]) -> Vec<u8> {
    use nextgcore_nas::common::types::{Abba, EapMessage, KeySetIdentifier};
    use nextgcore_nas::fiveg::message::{
        build_5gmm_message, AuthenticationRequest, FiveGmmMessage,
    };

    let msg = FiveGmmMessage::AuthenticationRequest(AuthenticationRequest {
        ngksi: KeySetIdentifier::new(tsc, ksi),
        abba: Abba::new(abba.to_vec()),
        rand: None,
        autn: None,
        eap_message: Some(EapMessage::new(eap_payload.to_vec())),
    });
    build_5gmm_message(&msg).to_vec()
}

/// amfd-05: extract the EAP-Response payload from a UE Authentication Response
/// so the AMF can relay it back to the AUSF unchanged (transparent passthrough).
///
/// The plain NAS message is `EPD | SHT | msg-type | ...IEs`; the EAP message IE
/// (IEI 0x78, TS 24.501 §9.11.2.2) carries a 2-octet length followed by the EAP
/// packet. Returns the raw EAP packet, or `None` when no EAP message IE is
/// present (e.g. a 5G-AKA Authentication Response carrying RES* under IEI 0x2D).
///
/// FLAGGED: paired with [`build_eap_authentication_request`]; not yet called by
/// the live path (the relay loop to the AUSF lives in `sbi_path.rs`).
#[allow(dead_code)]
fn parse_eap_message_from_authentication_response(nas: &[u8]) -> Option<Vec<u8>> {
    // Skip EPD, SHT, message-type.
    let mut pos = 3;
    while pos < nas.len() {
        if nas[pos] == 0x78 {
            // IEI(1) + length(2) + EAP packet.
            let len = ((*nas.get(pos + 1)? as usize) << 8) | (*nas.get(pos + 2)? as usize);
            let start = pos + 3;
            let end = start.checked_add(len)?;
            if end <= nas.len() {
                return Some(nas[start..end].to_vec());
            }
            return None;
        }
        pos += 1;
    }
    None
}

/// SNPN allowed-NID list for this AMF (Rel-17, TS 23.501 §5.30).
///
/// Read from `AMF_SNPN_ALLOWED_NIDS` as a comma-separated list of 11-hex-char
/// NIDs. Empty/unset means no NID restriction (accept any SNPN NID), matching
/// `AmfUe::validate_nid`'s empty-list semantics. Sourcing from an env var keeps
/// the SNPN gate modular and consistent with the AMF's other runtime config.
/// Decode a DNN IE value (TS 24.501 9.11.2.1A / TS 23.003): a sequence of
/// labels each prefixed by a 1-byte length, joined with '.'. Returns None for
/// an empty/malformed value so the caller falls back to the default DNN.
fn decode_dnn_labels(bytes: &[u8]) -> Option<String> {
    let mut labels = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        let len = bytes[i] as usize;
        if len == 0 || i + 1 + len > bytes.len() {
            break;
        }
        labels.push(String::from_utf8_lossy(&bytes[i + 1..i + 1 + len]).to_string());
        i += 1 + len;
    }
    if labels.is_empty() {
        None
    } else {
        Some(labels.join("."))
    }
}

fn snpn_allowed_nids() -> Vec<String> {
    std::env::var("AMF_SNPN_ALLOWED_NIDS")
        .ok()
        .map(|v| {
            v.split(',')
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect()
        })
        .unwrap_or_default()
}

/// Decode the 44-bit packed SNPN NID (TS 23.003 §12.7) carried in the
/// Registration Request NID IE back to its canonical 11-uppercase-hex-digit
/// string. The wire form is 6 octets: assignment-mode nibble first, then the
/// 10-digit NID value MSB-first; the trailing nibble of the 6th octet is spare.
/// Must mirror the sim encoder (`nextgsim-nas` `encode_nid_44bit`). Returns
/// `None` if fewer than 6 octets are present.
fn decode_nid_44bit(octets: &[u8]) -> Option<String> {
    if octets.len() < 6 {
        return None;
    }
    let mut s = String::with_capacity(11);
    for &b in &octets[..5] {
        s.push(char::from_digit((b >> 4) as u32, 16)?.to_ascii_uppercase());
        s.push(char::from_digit((b & 0x0F) as u32, 16)?.to_ascii_uppercase());
    }
    s.push(char::from_digit((octets[5] >> 4) as u32, 16)?.to_ascii_uppercase());
    Some(s)
}

/// Parse a Service-level-AA container's contents (TS 24.501 §9.11.2.10) and
/// return the CAA-level UAV ID from the Service-level device ID parameter
/// (param-IEI 0x10, type-4, UTF-8). Mirrors the sim encoder
/// (`nextgsim-nas` `encode_service_level_aa_container`). Unknown type-4
/// parameters are skipped per the spec's "ignore unknown IEI" rule.
fn decode_service_level_aa_container(bytes: &[u8]) -> Option<String> {
    let mut i = 0;
    while i + 2 <= bytes.len() {
        let ptype = bytes[i];
        let plen = bytes[i + 1] as usize;
        let start = i + 2;
        if start + plen > bytes.len() {
            break;
        }
        if ptype == 0x10 {
            return std::str::from_utf8(&bytes[start..start + plen])
                .ok()
                .map(|s| s.to_string());
        }
        i = start + plen;
    }
    None
}

/// UAV geofence configuration for this AMF (Rel-18, TS 23.256).
///
/// Returns `(min_lat, max_lat, min_lon, max_lon, min_alt, max_alt)` read from
/// `AMF_UAV_GEOFENCE` as six comma-separated decimals. Defaults to a permissive
/// area capped at 120 m altitude (the common regulatory ceiling) when unset, so
/// a UAV reporting above 120 m or outside the area triggers a geofence deny.
/// Sourcing from an env var keeps the UAV gate modular and consistent with the
/// AMF's other runtime config (e.g. `AMF_SNPN_ALLOWED_NIDS`).
fn uav_geofence_config() -> (f64, f64, f64, f64, f64, f64) {
    let default = (
        37.0_f64, 38.0_f64, -123.0_f64, -122.0_f64, 0.0_f64, 120.0_f64,
    );
    let Ok(raw) = std::env::var("AMF_UAV_GEOFENCE") else {
        return default;
    };
    let vals: Vec<f64> = raw
        .split(',')
        .filter_map(|s| s.trim().parse::<f64>().ok())
        .collect();
    if vals.len() == 6 {
        (vals[0], vals[1], vals[2], vals[3], vals[4], vals[5])
    } else {
        default
    }
}

/// Notify the UTM / USS (UAS Service Supplier) of a UAV authorization
/// (Rel-18, TS 23.256). The external USS / UTM interface (e.g. over the UAV
/// flight authorization API) is a documented stub in this stack: it logs the
/// authorization rather than calling an external NF. Replace with a real USS
/// client when the UTM interface is productionized.
fn notify_uss_authorization(caa_id: &str, suci: &str) {
    log::info!("[UAV UTM stub] USS authorization accepted (stub): CAA-ID={caa_id}, SUCI={suci}");
}

/// Whether a UEContextReleaseRequest Cause is a COMMUNICATION FAILURE rather than an
/// expected release (#397).
///
/// TS 23.502 table 4.15.3.1-1 (`23502-k20.txt:28570-28577`) defines the event this
/// gates as *"an unexpected termination of the communication"* — TS 29.518 §6.2's
/// wording at `29518-k00.txt:5130-5131`. So the classification is not "did the RAN
/// release the UE" (it always did, that is why the message arrived) but "was the
/// release unexpected".
///
/// Pure, and separate from the handler, because this mapping IS the conformance
/// decision and it is what the unit test pins. The same reasoning
/// `validate_initial_registration_cleartext` is factored out for.
///
/// # Why an EXPECTED-cause allowlist rather than a failure list
///
/// `CauseRadioNetwork` has 47 values and TS 38.413 §9.3.1.2 adds no "is this a
/// failure" bit, so either direction is a judgement. The allowlist is the safe one: a
/// cause nobody classified is reported as a failure, which a consumer can investigate,
/// whereas the inverse would silently swallow every future failure cause.
///
/// The expected causes, all `CauseRadioNetwork`:
///
/// - `user-inactivity` (20): the AS release TS 38.300 §9.2.1 performs when a UE has
///   nothing to send. The single most common reason a gNB releases a UE, and the
///   normal path into CM-IDLE — `start_reachability_supervision` exists to handle it.
/// - `successful-handover` (2) and `ngran-generated-reason` (3): a handover completed
///   or the NG-RAN released for its own housekeeping. The UE has not lost service.
/// - `5gc-generated-reason` (4): this AMF asked for the release; reporting it as a
///   failure would have the AMF report its own request back to a consumer.
/// - `partial-handover` (6), `ho-cancelled` (5), `ue-context-transfer` (35),
///   `ng-intra-system-handover-triggered` (31), `ng-inter-system-handover-triggered`
///   (32), `xn-handover-triggered` (33), `redirection` (41): mobility in progress, not
///   a loss of communication.
///
/// Everything else IS a failure, and `radio-connection-with-ue-lost` (21) is the
/// canonical one: the radio link is gone with no orderly release.
///
/// Non-`radioNetwork` groups are all failures. `transport` means the SCTP/GTP path
/// failed, `protocol` means the peers disagreed on the encoding, and `misc` carries
/// hardware failure and overload — none of which is an expected release. `nas` is
/// included deliberately: this is the gNB-INITIATED release, so a NAS cause here is
/// the RAN attributing the release to a NAS condition it observed, not the AMF's own
/// orderly deregistration (that path is `release_ue`, which never reaches here).
fn is_communication_failure_cause(group: u8, value: i64) -> bool {
    if group != ngap_handler::cause_group::RADIO_NETWORK {
        return true;
    }
    use ngap_handler::radio_network_cause as rn;
    !matches!(
        value,
        rn::SUCCESSFUL_HANDOVER
            | rn::RELEASE_DUE_TO_NGRAN_GENERATED_REASON
            | rn::RELEASE_DUE_TO_5GC_GENERATED_REASON
            | rn::HANDOVER_CANCELLED
            | rn::PARTIAL_HANDOVER
            | rn::USER_INACTIVITY
            | rn::NG_INTRA_SYSTEM_HANDOVER_TRIGGERED
            | rn::NG_INTER_SYSTEM_HANDOVER_TRIGGERED
            | rn::XN_HANDOVER_TRIGGERED
            | rn::UE_CONTEXT_TRANSFER
            | rn::REDIRECTION
    )
}

/// Whether a SUCI belongs to an SNPN onboarding subscription (TS 23.003).
///
/// Onboarding SUPIs use the reserved onboarding routing/credential indicator;
/// a minimal heuristic flags the configured onboarding marker. Replace with the
/// full onboarding-SUCI parse when onboarding credentials are productionized.
fn is_snpn_onboarding_suci(suci: &str) -> bool {
    suci.contains("onboarding")
}

/// Parse a plain Registration Request NAS PDU
/// The session IEs of a SERVICE REQUEST (#518): Uplink data status (TS 24.501
/// §9.11.3.57) and PDU session status (§9.11.3.44), as PSI bitmaps (bit n = PSI n).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub(crate) struct ServiceRequestSessionIes {
    pub uplink_data_status: Option<u16>,
    pub pdu_session_status: Option<u16>,
}

/// Read them from a decoded SERVICE REQUEST. A UE in CM-IDLE sends these
/// non-cleartext IEs only inside the NAS message container (TS 24.501 §4.4.6), so
/// the container's full message wins when it is present.
pub(crate) fn service_request_session_ies(
    plain: &[u8],
    decipher_container: &dyn Fn(&mut Vec<u8>),
) -> ServiceRequestSessionIes {
    use nextgcore_nas::fiveg::message::{parse_5gmm_message, FiveGmmMessage};
    let parse = |bytes: &[u8]| match parse_5gmm_message(&mut bytes::Bytes::copy_from_slice(bytes)) {
        Ok(FiveGmmMessage::ServiceRequest(sr)) => Some(sr),
        _ => None,
    };
    let Some(outer) = parse(plain) else {
        return ServiceRequestSessionIes::default();
    };
    let sr = outer
        .nas_message_container
        .as_ref()
        .and_then(|c| {
            let mut value = c.data.clone();
            decipher_container(&mut value);
            parse(&value)
        })
        .unwrap_or(outer);
    ServiceRequestSessionIes {
        uplink_data_status: sr.uplink_data_status.map(|u| u.psi),
        pdu_session_status: sr.pdu_session_status.map(|p| p.psi),
    }
}

/// The sessions a CM-CONNECTED Service Request re-activates: each PSI in the
/// Uplink data status that the AMF holds an SM context for (TS 23.502 §4.2.3.2).
/// Release on PDU session status is the CM-IDLE path's job.
pub(crate) fn connected_sessions_to_activate(
    amf_ue_ngap_id: u64,
    held: &[(u8, Option<String>, crate::context::SNssai)],
    uplink_data_status: Option<u16>,
) -> Vec<(u8, String, crate::context::SNssai)> {
    let plan = plan_service_request_sessions(
        &held.iter().map(|(psi, _, _)| *psi).collect::<Vec<_>>(),
        ServiceRequestSessionIes {
            uplink_data_status,
            pdu_session_status: None,
        },
        &[],
    );
    plan.activate
        .into_iter()
        .filter_map(|psi| match held.iter().find(|(p, _, _)| *p == psi) {
            Some((_, Some(r), s_nssai)) => Some((psi, r.clone(), s_nssai.clone())),
            _ => {
                log::warn!(
                    "UE {amf_ue_ngap_id}: Service Request asks to activate PSI {psi}, which has \
                     no SM context"
                );
                None
            }
        })
        .collect()
}

/// What a Service Request asks of the AMF's sessions (#518).
#[derive(Debug, Default, PartialEq, Eq)]
pub(crate) struct ServiceRequestSessionPlan {
    /// Held by the AMF but reported inactive by the UE: released locally and at
    /// the SMF (TS 24.501 §5.6.1.4.1).
    pub release: Vec<u8>,
    /// In the Uplink data status: user plane to re-activate (TS 23.502 §4.2.3.2
    /// step 4). PSIs the AMF does not hold are kept so they are reported as
    /// failed re-activations.
    pub activate: Vec<u8>,
}

/// Decide the plan from the PSIs the AMF holds, the request's IEs, and the PSIs
/// the page already carries (which need no second activation).
pub(crate) fn plan_service_request_sessions(
    held: &[u8],
    ies: ServiceRequestSessionIes,
    already: &[u8],
) -> ServiceRequestSessionPlan {
    let mut plan = ServiceRequestSessionPlan::default();
    if let Some(status) = ies.pdu_session_status {
        for &psi in held {
            if status & (1 << psi) == 0 && !already.contains(&psi) {
                plan.release.push(psi);
            }
        }
    }
    if let Some(status) = ies.uplink_data_status {
        for psi in 1..=15u8 {
            if status & (1 << psi) != 0 && !already.contains(&psi) && !plan.release.contains(&psi) {
                plan.activate.push(psi);
            }
        }
    }
    plan
}

/// Extract the value of the NAS message container IE (IEI 0x71, TLV-E format:
/// IEI(1) | length(2, big-endian) | value) from a 5GMM plain message body such
/// as Security Mode Complete (TS 24.501 Section 9.11.3.33). Returns the
/// contained NAS message (the replayed initial RegistrationRequest).
fn extract_nas_message_container(nas: &[u8]) -> Option<Vec<u8>> {
    // 5GMM header: EPD(1) | security-header-type(1) | message-type(1).
    let mut pos = 3;
    while pos < nas.len() {
        let iei = nas[pos];
        match iei {
            // NAS message container (0x71) — TLV-E
            0x71 => {
                if pos + 3 > nas.len() {
                    return None;
                }
                let len = ((nas[pos + 1] as usize) << 8) | (nas[pos + 2] as usize);
                if pos + 3 + len > nas.len() {
                    return None;
                }
                return Some(nas[pos + 3..pos + 3 + len].to_vec());
            }
            // IMEISV (0x77) — TLV-E: skip over it
            0x77 => {
                if pos + 3 > nas.len() {
                    return None;
                }
                let len = ((nas[pos + 1] as usize) << 8) | (nas[pos + 2] as usize);
                pos += 3 + len;
            }
            // Any other IE: cannot reliably skip an unknown format, so advance
            // by one octet and keep scanning for the container IEI.
            _ => pos += 1,
        }
    }
    None
}

/// Should this HandoverRequired be refused because it is an INTER-SYSTEM handover?
///
/// Returns the NGAP cause and a label for the log, or `None` when the preparation may
/// **proceed** — which is intra-5GS always, and `fivegs-to-eps` when a Forward Relocation can
/// actually be driven (#408 criterion 4).
///
/// Split out from `handle_handover_required` so the DECISION is assertable without the
/// transmission: driving that handler needs an SCTP-connected gNB the unit harness does
/// not have (`context.rs` says so in as many words -- "amfd has no harness that drives
/// `handle_handover_required`"). The same decision/transmission split this tree uses for
/// #70, #91, #48 and #69.
///
/// # `fivegs-to-eps` is now CONDITIONAL, and the condition is the whole point
///
/// #347 refused it unconditionally and said why: *"replacing the refusal with routing before
/// #408 would forward a preparation the AMF cannot complete, which is strictly worse than the
/// current honest refusal"*. #408 criterion 4 lifts that **only** where the premise no longer
/// holds — when the leg is enabled AND a Forward Relocation can actually be driven. That test
/// is [`crate::n26_path::forward_relocation_drivable`], and it is three conjuncts rather than
/// one: the switch alone is satisfied by a process whose socket bind FAILED, and a bound socket
/// alone is satisfied by a process with no MME peer to send to. The function's own doc carries
/// the enumeration.
///
/// # `eps-to-5gs` stays refused unconditionally, and that is not an oversight
///
/// A `HandoverRequired` with `HandoverType = eps-to-5gs` arriving from a **gNB** is malformed.
/// TS 38.413 §9.3.1.22 (`38413-j30.txt:19660-19662`) defines the type as *"which kind of
/// handover was triggered in the source"*, and an EPS→5GS handover is triggered in the
/// **E-UTRAN**: it reaches this AMF as a GTPv2-C Forward Relocation Request over N26, or as a
/// `Namf_Communication_RelocateUEContext` from an initial AMF (TS 23.502 §4.11.1.2.2.2 step 3
/// and step 8a), and never as an NGAP `HandoverRequired`. So there is no state of this AMF in
/// which routing it would be right, and refusing is not a ceiling but the correct answer.
///
/// # Why this cause
///
/// `ho-target-not-allowed` (TS 38.413 CauseRadioNetwork 8) is the accurate cause: the
/// target system is not one this AMF may hand over to. Deliberately NOT `unknown-target-id`,
/// which is what the pre-#116 code ended up answering by falling through to the connected-gNB
/// search -- that cause says "I do not know that gNB" about a target which is an MME, and it
/// would send an operator looking for a RAN misconfiguration.
fn inter_system_handover_refusal(
    handover_type: nextgcore_ngap::types::HandoverType,
) -> Option<(nextgcore_ngap::types::CauseRadioNetwork, &'static str)> {
    inter_system_handover_refusal_with(
        handover_type,
        crate::n26_path::forward_relocation_drivable(),
    )
}

/// What the HANDOVER COMMAND for a completed 5GS→EPS preparation carries (#408 criterion 6).
///
/// Returned as the DECISION rather than being built inline, so it is assertable without an
/// SCTP-connected gNB — the same decision/transmission split
/// [`inter_system_handover_refusal`] uses.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct InterSystemHandoverCommand {
    /// The Target-to-Source transparent container, relayed byte for byte.
    ///
    /// TS 38.413 §9.3.1.21 (`38413-j30.txt:5952-5955`): for inter-system handover to LTE this
    /// *"shall be encoded according to the definition of the Target eNB to Source eNB
    /// Transparent Container IE as specified in TS 36.413"* — an E-UTRAN structure the AMF has
    /// no business decoding.
    pub target_to_source_container: Vec<u8>,
    /// The `PDU Session Resource Handover List`, **always empty** in this direction.
    ///
    /// Each item would carry a `HandoverCommandTransfer` whose
    /// `dLForwardingUP-TNLInformation` is the forwarding endpoint. This tree has no encoder for
    /// that structure, so the list is empty — which TS 38.413 §9.2.3.2 permits
    /// (`38413-j30.txt:38763` makes the IE `PRESENCE optional`, criticality `ignore`). The UE
    /// still gets its bearers: §4.11.1.2.1 step 11 has it correlate QoS flows with the EPS
    /// Bearer IDs the MME set up, and that correlation does not depend on forwarding.
    pub forwarding_sessions: Vec<u8>,
    /// The EBIs handed over **without** data forwarding, for the log that names them.
    pub bearers_without_forwarding: Vec<u8>,
    /// The 8 LSB of the downlink NAS COUNT the mapped `K_ASME'` used.
    ///
    /// TS 33.501 §8.3.2 step 7 (`33501-k20.txt:11409-11412`) has the AMF put this in the
    /// HANDOVER COMMAND's `NAS Security Parameters from NG-RAN` IE so the UE can estimate the
    /// COUNT and derive the same key; `build_fivegs_to_eps_handover_command_asn1` does (#476).
    pub nas_count_lsb: u8,
}

/// Decide the HANDOVER COMMAND for a 5GS→EPS preparation the target MME accepted
/// (#408 criterion 6, third site).
///
/// # The data-forwarding decision, recorded
///
/// `forwarding_sessions` is **empty** and `bearers_without_forwarding` names every EBI, so the
/// caller logs precisely which bearers lose in-flight downlink data. That is the #185 posture:
/// a node that cannot do something answers with what is true and says which traffic is
/// affected, rather than claiming success. The two reasons, each pinned:
///
/// - **direct forwarding** needs `HandoverCommandTransfer.dLForwardingUP-TNLInformation`
///   (`38413-j30.txt:48917-48930`), and this tree has no encoder for it;
/// - **indirect forwarding** needs the UPF-allocated *"Data Forwarding tunnel Info"* of
///   TS 23.502 §4.11.1.2.1 step 10b-10c, and smfd's `UpdateSMContext` implements only the
///   `hoState` machine.
///
/// So the AMF never sets the Direct Forwarding Indication in the request either
/// (`n26_build::forward_relocation_indication`), and the two halves of the decision cannot
/// disagree because each reads the other's reason rather than a duplicated flag.
///
/// # The NAS Security Parameters from NG-RAN IE
///
/// [`InterSystemHandoverCommand::nas_count_lsb`] is the octet TS 33.501 §8.3.2 step 7 requires
/// the UE be given. TS 38.413 §9.2.3.2 makes the IE that carries it `C-iftoEPSUTRA`, and
/// §9.3.3.26 says it *"Refers to the N1 mode to S1 mode NAS transparent container IE"*, whose
/// value part is a single `Sequence number` octet (TS 24.501 §9.11.2.7).
/// `build_fivegs_to_eps_handover_command_asn1` puts it on the wire (#476); before that it was
/// computed and only logged, so a real UE could not derive the same `K_ASME'`.
pub fn inter_system_handover_command(
    outcome: &crate::n26_path::ForwardRelocationOutcome,
) -> Option<InterSystemHandoverCommand> {
    let crate::n26_path::ForwardRelocationOutcome::Accepted {
        target_to_source_container,
        admitted_ebis,
        dl_count_used,
        ..
    } = outcome
    else {
        // A refusal produces a HandoverPreparationFailure, not a command.
        return None;
    };
    Some(InterSystemHandoverCommand {
        target_to_source_container: target_to_source_container.clone(),
        // Empty, deliberately. See the doc above.
        forwarding_sessions: Vec::new(),
        bearers_without_forwarding: admitted_ebis.clone(),
        // The 8 LSB of the COUNT the key was derived from -- the PRE-increment value, carried
        // through the pending record rather than re-read, because by now the stored count has
        // advanced and step 7 asks for the one that WAS used.
        nas_count_lsb: (*dl_count_used & 0xFF) as u8,
    })
}

/// The refusal decision as a pure function of the handover type and whether a Forward
/// Relocation is drivable (#408 criterion 4).
///
/// Separated from [`inter_system_handover_refusal`] so the full truth table can be asserted
/// without installing a socket: `n26_path::N26_SERVER` is a `OnceLock` that a test cannot
/// toggle back to empty, so a test driving the real reader could only ever exercise the states
/// reachable after the first `set`. The revert-verification for this function found that
/// exact gap — a forced-`true` `socket_bound` conjunct passed the whole amfd suite because no
/// case distinguished "switch set, bind failed", which is the one real production path where
/// `enabled()` is true and there is no socket.
fn inter_system_handover_refusal_with(
    handover_type: nextgcore_ngap::types::HandoverType,
    forward_relocation_drivable: bool,
) -> Option<(nextgcore_ngap::types::CauseRadioNetwork, &'static str)> {
    use nextgcore_ngap::types::HandoverType as Ht;
    let target_system = match handover_type {
        Ht::Intra5gs => return None,
        Ht::FivegsToEps => {
            if forward_relocation_drivable {
                // The N26 leg is up, a socket is bound and a target MME is configured, so the
                // preparation CAN be completed: `handle_handover_required` drives a Forward
                // Relocation Request instead of refusing (#408).
                return None;
            }
            "EPS (fivegs-to-eps)"
        }
        // Unconditional: see the doc above. An `eps-to-5gs` HandoverRequired from a gNB names a
        // procedure whose source is the E-UTRAN, so it cannot legitimately arrive here.
        Ht::EpsTo5gs => "5GS (eps-to-5gs)",
    };
    Some((
        nextgcore_ngap::types::CauseRadioNetwork::HoTargetNotAllowed,
        target_system,
    ))
}

fn parse_registration_request_pdu(nas: &[u8]) -> Option<ParsedRegistrationRequest> {
    // EPD + sec hdr + msg type + (ngKSI | 5GS registration type) + LV-E identity
    if nas.len() < 6 {
        return None;
    }
    let mut req = ParsedRegistrationRequest {
        registration_type: nas[3] & 0x07,
        tsc: (nas[3] >> 7) & 0x01,
        ksi: (nas[3] >> 4) & 0x07,
        ..Default::default()
    };

    // 5GS mobile identity (LV-E: 2-byte length)
    let id_len = ((nas[4] as usize) << 8) | (nas[5] as usize);
    if id_len == 0 || nas.len() < 6 + id_len {
        return None;
    }
    let identity = &nas[6..6 + id_len];
    req.identity_type = identity[0] & 0x07;
    match req.identity_type {
        t if t == mobile_identity_type::SUCI => {
            if let Some((suci, plmn)) = parse_suci_identity(identity) {
                req.suci = Some(suci);
                req.plmn = Some(plmn);
            }
        }
        t if t == mobile_identity_type::GUTI => {
            req.guti = crate::gmm_handler::parse_guti(identity);
        }
        _ => {}
    }

    // Optional IEs
    let mut pos = 6 + id_len;
    while pos < nas.len() {
        let iei = nas[pos];
        match iei {
            // UE security capability (IEI 0x2E, TLV)
            0x2E => {
                if pos + 1 >= nas.len() {
                    break;
                }
                let len = nas[pos + 1] as usize;
                if len >= 2 && pos + 2 + len <= nas.len() {
                    req.sec_cap = Some(UeSecurityCapability {
                        ea: nas[pos + 2],
                        ia: nas[pos + 3],
                        eea: if len >= 3 { nas[pos + 4] } else { 0 },
                        eia: if len >= 4 { nas[pos + 5] } else { 0 },
                    });
                    req.presencemask |= reg_present::UE_SECURITY_CAPABILITY;
                }
                pos += 2 + len;
            }
            // Requested NSSAI (IEI 0x2F, TLV)
            0x2F => {
                if pos + 1 >= nas.len() {
                    break;
                }
                let len = nas[pos + 1] as usize;
                if pos + 2 + len <= nas.len() {
                    req.requested_nssai = parse_nssai_value(&nas[pos + 2..pos + 2 + len]);
                    // Requested NSSAI is a NON-cleartext IE (TS 24.501 §4.4.6).
                    req.presencemask |= reg_present::REQUESTED_NSSAI;
                }
                pos += 2 + len;
            }
            // SNPN NID (IEI 0xA6, TLV): UE-included SNPN Network Identifier
            // (Rel-17, TS 23.501 §5.30) carried as the 44-bit packed NID of
            // TS 23.003 §12.7 (6 octets). Parse before the generic Type-1 arm.
            0xA6 => {
                if pos + 1 >= nas.len() {
                    break;
                }
                let len = nas[pos + 1] as usize;
                if pos + 2 + len <= nas.len() {
                    if let Some(nid) = decode_nid_44bit(&nas[pos + 2..pos + 2 + len]) {
                        req.snpn_nid = Some(nid);
                    }
                }
                pos += 2 + len;
            }
            // MINT disaster-roaming indication (IEI 0xA7, TLV): Rel-18,
            // TS 23.761 §4.2. A single value octet whose bit 1 is the
            // disaster-roaming flag. Parse before the generic Type-1 arm.
            0xA7 => {
                if pos + 1 >= nas.len() {
                    break;
                }
                let len = nas[pos + 1] as usize;
                if len >= 1 && pos + 2 + len <= nas.len() {
                    req.disaster_roaming = nas[pos + 2] & 0x01 == 0x01;
                }
                pos += 2 + len;
            }
            // Service-level-AA container (IEI 0x72, TLV-E): Rel-17/18,
            // TS 24.501 §9.11.2.10 / §8.2.6. Type-6 IE with a 2-octet length;
            // contents carry the UAS CAA-level UAV ID as the Service-level
            // device ID parameter (0x10, UTF-8). Parse before the generic arms.
            0x72 => {
                if pos + 2 >= nas.len() {
                    break;
                }
                let len = ((nas[pos + 1] as usize) << 8) | nas[pos + 2] as usize;
                if pos + 3 + len <= nas.len() {
                    req.uav_indication =
                        decode_service_level_aa_container(&nas[pos + 3..pos + 3 + len]);
                }
                pos += 3 + len;
            }
            // RedCap indication (IEI 0xA9, TLV): Rel-17, TS 38.101. A single
            // value octet whose bit 0 marks a reduced-capability device. Parse
            // before the generic Type-1 arm.
            0xA9 => {
                if pos + 1 >= nas.len() {
                    break;
                }
                let len = nas[pos + 1] as usize;
                if len >= 1 && pos + 2 + len <= nas.len() {
                    req.redcap_indication = nas[pos + 2] & 0x01 == 0x01;
                }
                pos += 2 + len;
            }
            // Last visited registered TAI (IEI 0x52, TV, 7 bytes total).
            // NON-cleartext IE (TS 24.501 §4.4.6).
            0x52 => {
                req.presencemask |= reg_present::LAST_VISITED_TAI;
                pos += 7;
            }
            // 5GMM capability (IEI 0x10, TLV, TS 24.501 §9.11.3.1). Parsed for its
            // octet-3 bit 1 (`S1 mode` / EPC NAS supported), which §5.5.1.2.4 makes
            // the precondition for signalling IWK N26 back (#116). Must precede the
            // default TLV arm, which used to walk straight past it.
            0x10 => {
                if pos + 1 >= nas.len() {
                    break;
                }
                let len = nas[pos + 1] as usize;
                if pos + 2 + len <= nas.len() {
                    let contents = &nas[pos + 2..pos + 2 + len];
                    req.s1_mode = nextgcore_nas::interworking::claims_s1_mode(contents);
                    req.racs_supported = crate::racs::gmm_capability_supports_racs(contents);
                }
                pos += 2 + len;
            }
            // UE radio capability ID (IEI 0x67, TLV, TS 24.501 §9.11.3.68), #570.
            0x67 => {
                if pos + 1 >= nas.len() {
                    break;
                }
                let len = nas[pos + 1] as usize;
                if len > 0 && pos + 2 + len <= nas.len() {
                    req.ue_radio_capability_id = Some(nas[pos + 2..pos + 2 + len].to_vec());
                }
                pos += 2 + len;
            }
            // TLV-E IEs (2-byte length): EPS NAS container (0x70),
            // NAS message container (0x71), additional GUTI (0x77),
            // payload containers (0x7B/0x7C)
            0x70 | 0x71 | 0x77 | 0x7B | 0x7C => {
                if pos + 2 >= nas.len() {
                    break;
                }
                let len = ((nas[pos + 1] as usize) << 8) | (nas[pos + 2] as usize);
                match iei {
                    // EPS NAS message container (§9.11.3.24). KEPT, not skipped
                    // (#116): its presence is how the AMF learns the 5GS mobile
                    // identity holds a GUTI mapped from EPS, and its contents are the
                    // ATTACH / TAU REQUEST the MME would have handled. Bounds-checked
                    // rather than trusted -- `len` came off the wire.
                    0x70 => {
                        if pos + 3 + len <= nas.len() {
                            req.eps_nas_message_container =
                                Some(nas[pos + 3..pos + 3 + len].to_vec());
                        }
                    }
                    // NAS message container (TS 24.501 §4.4.6): not permitted in
                    // an unprotected initial NAS message.
                    0x71 => req.nas_message_container_present = true,
                    // Additional GUTI — cleartext IE. Decoded (#116), not just
                    // counted: on the EPS→5GS path this carries the UE's NATIVE
                    // 5G-GUTI, so it is the one that may be treated as native.
                    0x77 => {
                        req.presencemask |= reg_present::ADDITIONAL_GUTI;
                        if pos + 3 + len <= nas.len() {
                            req.additional_guti =
                                crate::gmm_handler::parse_guti(&nas[pos + 3..pos + 3 + len]);
                        }
                    }
                    // Payload container (#91): kept, not skipped. Bounds-checked
                    // here rather than trusted, since `len` comes off the wire.
                    0x7B => {
                        if pos + 3 + len <= nas.len() {
                            req.payload_container = Some(nas[pos + 3..pos + 3 + len].to_vec());
                        }
                    }
                    _ => {}
                }
                pos += 3 + len;
            }
            // Type-1 TV (IEI in high nibble)
            b if b & 0x80 != 0 => {
                // Payload container type (#91): IEI `8-`, value in the low nibble.
                if b & 0xF0 == 0x80 {
                    req.payload_container_type = Some(b & 0x0F);
                }
                pos += 1;
            }
            // Default: assume TLV
            _ => {
                if pos + 1 >= nas.len() {
                    break;
                }
                let len = nas[pos + 1] as usize;
                pos += 2 + len;
            }
        }
    }

    Some(req)
}

/// Parse a UAV tracking report NAS PDU (Rel-18, TS 23.256).
///
/// Layout (matching the nextgsim UE `build_uav_tracking_report`): 5GMM header
/// (EPD, sec-hdr, msg-type = 3 octets), then a length-prefixed CAA-level ID,
/// then latitude/longitude as i32 1e-7-degree fixed point, altitude as i32
/// 0.1 m fixed point, and a flight-status octet.
fn parse_uav_tracking_report(
    amf_ue_ngap_id: u64,
    ran_ue_ngap_id: u32,
    inner: &[u8],
) -> Option<crate::ngap_handler::UavTrackingReport> {
    // 3-octet header + 1-octet ID length
    if inner.len() < 4 {
        return None;
    }
    let id_len = inner[3] as usize;
    let pos = 4 + id_len;
    // CAA ID + 4 (lat) + 4 (lon) + 4 (alt) + 1 (status)
    if inner.len() < pos + 13 {
        return None;
    }
    let uav_id = std::str::from_utf8(&inner[4..4 + id_len]).ok()?.to_string();
    let lat_raw = i32::from_be_bytes(inner[pos..pos + 4].try_into().ok()?);
    let lon_raw = i32::from_be_bytes(inner[pos + 4..pos + 8].try_into().ok()?);
    let alt_raw = i32::from_be_bytes(inner[pos + 8..pos + 12].try_into().ok()?);
    let flight_status = inner[pos + 12];
    let timestamp = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    Some(crate::ngap_handler::UavTrackingReport {
        amf_ue_ngap_id,
        ran_ue_ngap_id: ran_ue_ngap_id as u64,
        uav_id,
        latitude: lat_raw as f64 / 1e7,
        longitude: lon_raw as f64 / 1e7,
        altitude: alt_raw as f64 / 10.0,
        timestamp,
        flight_status,
    })
}

/// Parse an NSSAI IE value into S-NSSAIs (TS 24.501 Section 9.11.3.37)
fn parse_nssai_value(data: &[u8]) -> Vec<SNssai> {
    let mut out = Vec::new();
    let mut pos = 0;
    while pos < data.len() {
        let len = data[pos] as usize;
        if len == 0 || pos + 1 + len > data.len() {
            break;
        }
        let sst = data[pos + 1];
        let sd = if len >= 4 {
            Some(
                ((data[pos + 2] as u32) << 16)
                    | ((data[pos + 3] as u32) << 8)
                    | data[pos + 4] as u32,
            )
        } else {
            None
        };
        out.push(SNssai { sst, sd });
        pos += 1 + len;
    }
    out
}

/// Parse a SUCI mobile identity content (TS 24.501 Section 9.11.3.4)
///
/// Returns the SUCI in the string form
/// `suci-0-<mcc>-<mnc>-<routing>-<scheme>-<hnkey>-<schemeoutput>` plus the
/// home PLMN.
fn parse_suci_identity(content: &[u8]) -> Option<(String, PlmnId)> {
    if content.len() < 9 {
        return None;
    }
    let supi_format = (content[0] >> 4) & 0x07;
    if supi_format != 0 {
        // Only IMSI-format SUCI supported here (network-specific NAI deferred)
        return None;
    }
    let plmn = PlmnId {
        mcc1: content[1] & 0x0f,
        mcc2: (content[1] >> 4) & 0x0f,
        mcc3: content[2] & 0x0f,
        mnc3: (content[2] >> 4) & 0x0f,
        mnc1: content[3] & 0x0f,
        mnc2: (content[3] >> 4) & 0x0f,
    };
    let (mcc, mnc) = plmn_mcc_mnc_strings(&plmn);
    let routing = decode_bcd_digits(&content[4..6]);
    let scheme = content[6] & 0x0f;
    let hn_key = content[7];
    // Scheme output encoding (TS 24.501 Section 9.11.3.4 / TS 23.003 §28.7.3):
    //   - null scheme (0): the scheme output IS the MSIN, carried as TBCD with
    //     swapped nibbles and 0xF fillers -> decode to cleartext digits.
    //   - ECIES profile A (1) / profile B (2): the scheme output is an opaque
    //     octet string (ephemeral public key || ciphertext || MAC). It must be
    //     carried verbatim and reversibly, so hex-encode the raw bytes. The UDM
    //     recovers them with hex_str_to_bytes (context.rs) before deconcealment.
    //     A BCD decode here would silently drop any nibble > 9, corrupting the
    //     ciphertext.
    let scheme_output = if scheme == SUCI_PROTECTION_SCHEME_NULL {
        decode_bcd_digits(&content[8..])
    } else {
        encode_hex_lower(&content[8..])
    };

    let suci = format!("suci-0-{mcc}-{mnc}-{routing}-{scheme}-{hn_key}-{scheme_output}");
    Some((suci, plmn))
}

/// SUCI protection scheme identifier for the null scheme (TS 33.501 Annex C).
const SUCI_PROTECTION_SCHEME_NULL: u8 = 0;

/// Lowercase, fixed-width (two chars/byte) hex encoding. Used for the ECIES
/// SUCI scheme output so it round-trips through `hex_str_to_bytes` on the UDM.
fn encode_hex_lower(data: &[u8]) -> String {
    let mut s = String::with_capacity(data.len() * 2);
    for b in data {
        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
        s.push(char::from_digit((b & 0x0f) as u32, 16).unwrap());
    }
    s
}

/// Derive a SUPI string from a **null-scheme** SUCI
/// ("suci-0-mcc-mnc-routing-0-hnkey-msin" -> "imsi-mccmncmsin"), or pass an
/// already-plain `imsi-` SUPI through.
///
/// Returns `None` for anything from which a real SUPI cannot be recovered
/// without the home network private key. That is the whole point of the
/// function: only a null-scheme (scheme id 0) SUCI exposes the MSIN in
/// cleartext (TS 23.003 Section 2.2A / Section 6.2.2). For an ECIES-protected
/// SUCI the scheme output is ciphertext, so concatenating it would yield a
/// FABRICATED SUPI -- and callers feed this value into `nextgcore_kdf_kamf`
/// and UECM registration, so a fabricated identity silently derives the wrong
/// keys and registers the wrong subscriber (TS 33.501 Section 6.1.3: the SUPI
/// is recovered only after de-concealment).
///
/// The scheme id is checked FIRST and is the load-bearing gate: an all-digit
/// check alone is not sufficient, because a hex-encoded ciphertext can be
/// all decimal digits by chance.
///
/// Mirrors `supi_from_suci` in nextgcore-udmd's context.rs, which already
/// returned `Option` for exactly this reason.
fn supi_from_suci(suci: &str) -> Option<String> {
    if let Some(rest) = suci.strip_prefix("imsi-") {
        // Already de-concealed by the AUSF/UDM.
        return if !rest.is_empty() && rest.bytes().all(|b| b.is_ascii_digit()) {
            Some(suci.to_string())
        } else {
            None
        };
    }

    let parts: Vec<&str> = suci.split('-').collect();
    if parts.len() < 8 || parts[0] != "suci" {
        return None;
    }
    // parts: suci-<supi type>-<mcc>-<mnc>-<routing>-<scheme>-<hnkey>-<output>
    if parts[1] != "0" {
        // Only the IMSI SUPI type yields an imsi- SUPI.
        return None;
    }
    let Ok(scheme) = parts[5].parse::<u8>() else {
        return None;
    };
    if scheme != SUCI_PROTECTION_SCHEME_NULL {
        log::error!(
            "SUCI protection scheme {scheme} is not the null scheme: the scheme output is \
             ciphertext, so no SUPI can be derived without de-concealment"
        );
        return None;
    }
    let msin = parts[7];
    if msin.is_empty() || !msin.bytes().all(|b| b.is_ascii_digit()) {
        log::error!("null-scheme SUCI carries a non-digit MSIN; refusing to derive a SUPI");
        return None;
    }
    if parts[2].is_empty() || parts[3].is_empty() {
        return None;
    }
    Some(format!("imsi-{}{}{}", parts[2], parts[3], msin))
}

/// Decode a PEI (IMEI or IMEISV) from the content of a 5GS mobile identity IE
/// (TS 24.501 Section 9.11.3.4) and format it per the TS 29.571 `Pei` pattern.
///
/// The identity digits do NOT start at `content[1]`. Octet 4 of the IE -- which
/// is `content[0]` here -- carries the type of identity in bits 1-3, the
/// odd/even indicator in bit 4, and **identity digit 1 in bits 5-8**. Slicing
/// from `content[1]` therefore drops the first digit and yields a value one
/// digit short, which is the defect this helper exists to prevent.
///
/// Returns `(pei, digits)`, where `pei` is `imei-<15 digits>` or
/// `imeisv-<16 digits>` -- the prefix is chosen from the type-of-identity
/// field, never assumed -- and `digits` is the bare identity.
///
/// Returns `None` when the content is too short, the type is neither IMEI nor
/// IMEISV, digit 1 is not a decimal digit, or the recovered digit count does
/// not match the type. A malformed identity yields NO PEI rather than one that
/// violates the `Pei` pattern: absent is checkable by a peer, wrong is not.
///
/// Both the Identity Response and the Security Mode Complete paths route
/// through here so the two cannot diverge again.
fn decode_pei(content: &[u8]) -> Option<(String, String)> {
    if content.len() < 2 {
        return None;
    }
    let (prefix, expected_digits) = match content[0] & 0x07 {
        t if t == mobile_identity_type::IMEI => ("imei", 15),
        t if t == mobile_identity_type::IMEISV => ("imeisv", 16),
        _ => return None,
    };

    // Identity digit 1 shares octet 4 with the type-of-identity field.
    let digit1 = (content[0] >> 4) & 0x0f;
    if digit1 > 9 {
        return None;
    }
    let mut digits = String::with_capacity(expected_digits);
    digits.push((b'0' + digit1) as char);
    digits.push_str(&decode_bcd_digits(&content[1..]));

    if digits.len() != expected_digits {
        return None;
    }
    Some((format!("{prefix}-{digits}"), digits))
}

/// Decode (nibble-swapped) BCD digits, skipping 0xF fillers
fn decode_bcd_digits(data: &[u8]) -> String {
    let mut s = String::with_capacity(data.len() * 2);
    for b in data {
        let lo = b & 0x0f;
        let hi = (b >> 4) & 0x0f;
        if lo <= 9 {
            s.push((b'0' + lo) as char);
        }
        if hi <= 9 {
            s.push((b'0' + hi) as char);
        }
    }
    s
}

/// MCC/MNC digit strings from a PLMN ID
fn plmn_mcc_mnc_strings(plmn: &PlmnId) -> (String, String) {
    let mcc = format!("{}{}{}", plmn.mcc1, plmn.mcc2, plmn.mcc3);
    let mnc = if plmn.mnc3 == 0xf {
        format!("{}{}", plmn.mnc1, plmn.mnc2)
    } else {
        format!("{}{}{}", plmn.mnc1, plmn.mnc2, plmn.mnc3)
    };
    (mcc, mnc)
}

/// Parse a TS 29.571 BitRate string ("<number> <unit>", e.g. "1 Gbps") into
/// bits per second. Supported units: bps, Kbps, Mbps, Gbps, Tbps (decimal,
/// 10^3 steps per TS 29.571 §5.5). Returns None for malformed input.
fn parse_bitrate_bps(s: &str) -> Option<u64> {
    let mut parts = s.split_whitespace();
    let value: f64 = parts.next()?.parse().ok()?;
    if !value.is_finite() || value < 0.0 {
        return None;
    }
    let unit = parts.next()?;
    if parts.next().is_some() {
        return None;
    }
    let multiplier: f64 = match unit {
        "bps" => 1.0,
        "Kbps" => 1e3,
        "Mbps" => 1e6,
        "Gbps" => 1e9,
        "Tbps" => 1e12,
        _ => return None,
    };
    Some((value * multiplier) as u64)
}

/// Serving network name (TS 24.501 Section 9.12.1 / TS 33.501 Section 6.1.1.4)
fn serving_network_name_from_plmn(plmn: &PlmnId) -> String {
    let (mcc, mnc) = plmn_mcc_mnc_strings(plmn);
    format!("5G:mnc{mnc:0>3}.mcc{mcc:0>3}.3gppnetwork.org")
}

/// Serving network name for a standalone non-public network
/// (TS 33.501 Annex I.3.2, #115).
///
/// §6.1.1.4.1 makes the serving network name the service code `"5G"` concatenated with
/// the SN Id by `":"`. Annex I.3.2 then redefines the SN Id for an SNPN:
///
/// > `SN Id = PLMN ID:NID`
///
/// so the name gains one further `":"`-separated component. Everything that consumes it
/// — K_SEAF, K_AUSF, CK'/IK' and (X)RES* — is bound to the serving network through this
/// string, which is why Annex I.3.1 says the definition "needs modification for
/// standalone non-public networks": without the NID, two SNPNs sharing a PLMN ID derive
/// the *same* anchor key, and a UE authenticated to one would be accepted by the other.
///
/// # Why this is here and not in ausfd
///
/// §6.1.1.4.3 makes constructing this the SEAF's job, and the AUSF only receives it (in
/// `servingNetworkName`) and passes it to the UDM. #115 asks for the SNPN work in
/// `ausfd::AusfUe::derive_kausf_with_nid`, and that function was wrong on three counts:
/// the AUSF does not derive K_AUSF at all (§6.1.3.2 has the UDM/ARPF do it and send the
/// 5G HE AV), it built `5G:{name}:NID-{nid}` where `{name}` already began with `5G:` —
/// so `5G:5G:mnc…:NID-x`, neither the spec's separator nor its component — and it had no
/// callers. It is removed and replaced by this, in the NF that owns the construction.
fn snpn_serving_network_name(plmn: &PlmnId, nid: &str) -> String {
    format!("{}:{nid}", serving_network_name_from_plmn(plmn))
}

/// The serving network name for this UE: SNPN-augmented when it is authenticating to a
/// standalone non-public network, the plain PLMN form otherwise (#115).
fn serving_network_name_for_ue(amf_ue: &crate::context::AmfUe) -> String {
    match amf_ue.snpn_nid.as_deref().filter(|n| !n.trim().is_empty()) {
        Some(nid) => snpn_serving_network_name(&amf_ue.nr_tai.plmn_id, nid),
        None => serving_network_name_from_plmn(&amf_ue.nr_tai.plmn_id),
    }
}

/// Convert a wire-format security capability octet (bit 8 = algorithm 0,
/// TS 24.501 Section 9.11.3.54) into the bit-N = algorithm-N mask used by
/// the algorithm selection helpers
pub(crate) fn wire_caps_to_mask(wire: u8) -> u8 {
    let mut mask = 0u8;
    for n in 0..8 {
        if wire & (0x80 >> n) != 0 {
            mask |= 1 << n;
        }
    }
    mask
}

/// Map the stored NAS UE security-capability octets (5G/EPS EA/IA bitmaps,
/// MSB = the null algorithm xEA0/xIA0) to the 16-bit NGAP UESecurityCapabilities
/// bitstrings (TS 38.413 Section 9.3.1.86). The NGAP first bit is 128-xEA1 and
/// the null algorithm is not representable, so the NAS MSB (xEA0) is dropped and
/// the remaining bits are left-aligned (shift 9): NAS bit 7 (128-xEA1) -> NGAP MSB.
fn ue_caps_to_ngap(caps: &UeSecurityCapability) -> nextgcore_ngap::types::UeSecurityCapabilities {
    let to_bits = |octet: u8| -> u16 { (octet as u16) << 9 };
    nextgcore_ngap::types::UeSecurityCapabilities {
        nr_encryption_algorithms: to_bits(caps.ea),
        nr_integrity_algorithms: to_bits(caps.ia),
        eutra_encryption_algorithms: to_bits(caps.eea),
        eutra_integrity_algorithms: to_bits(caps.eia),
    }
}

/// The UE security capabilities this AMF conveys to the RAN for `amf_ue`.
///
/// Ordinarily the UE's own replayed set (TS 38.413 §9.3.1.86). For an UNAUTHENTICATED
/// emergency session it is narrowed to the NULL set, per TS 33.501 §6.7.3.6, which requires
/// the AMF to "Set the UE 5G security capabilities to only contain EIA0, EEA0, NIA0 and NEA0
/// when sending these to the gNB/ng-eNB in the following messages: NGAP UE INITIAL CONTEXT
/// SETUP, NGAP UE CONTEXT MODIFICATION REQUEST, NGAP HANDOVER REQUEST" (#361).
///
/// "Only contain the null algorithms" renders as ALL-ZERO bitstrings, and that is not a
/// shortcut: the NGAP UESecurityCapabilities bitstring starts at 128-xEA1 and has no position
/// for the null algorithm at all (see `ue_caps_to_ngap`, which drops the NAS MSB for exactly
/// this reason). An empty set is therefore the only encoding of "nothing but the null
/// algorithms are available", and it is the right one: it stops the gNB selecting a real AS
/// algorithm keyed on a KgNB whose root the UE never agreed to, which is the concrete failure
/// §6.7.3.6 exists to prevent.
///
/// The UE's advertised capabilities on the AmfUe are left untouched, because the Security Mode
/// Command must still replay them verbatim for the anti-bidding-down check (§6.7.2). This
/// narrowing applies only to what crosses N2.
fn ue_caps_to_ngap_for_ue(amf_ue: &AmfUe) -> nextgcore_ngap::types::UeSecurityCapabilities {
    if amf_ue.unauthenticated_emergency {
        return nextgcore_ngap::types::UeSecurityCapabilities {
            nr_encryption_algorithms: 0,
            nr_integrity_algorithms: 0,
            eutra_encryption_algorithms: 0,
            eutra_integrity_algorithms: 0,
        };
    }
    ue_caps_to_ngap(&amf_ue.ue_security_capability)
}

/// Encode a PlmnId into the 3-byte NGAP PLMN Identity (TS 23.003 / TS 38.413).
fn plmn_id_to_ngap_bytes(plmn: &PlmnId) -> [u8; 3] {
    [
        (plmn.mcc2 << 4) | plmn.mcc1,
        (plmn.mnc3 << 4) | plmn.mcc3,
        (plmn.mnc2 << 4) | plmn.mnc1,
    ]
}

/// Decode a 3-byte NGAP PLMN Identity into a PlmnId (inverse of
/// `plmn_id_to_ngap_bytes`).
fn plmn_id_from_ngap_bytes(bytes: &[u8; 3]) -> PlmnId {
    PlmnId {
        mcc1: bytes[0] & 0x0F,
        mcc2: bytes[0] >> 4,
        mcc3: bytes[1] & 0x0F,
        mnc1: bytes[2] & 0x0F,
        mnc2: bytes[2] >> 4,
        mnc3: bytes[1] >> 4,
    }
}

/// Store a UE's location from an NGAP `UserLocationInformation`, refreshing BOTH
/// the tracking area and the cell identity (#406).
///
/// # Why one helper rather than the destructure repeated at each site
///
/// Every NGAP message that reports a location reports the same two things, and a
/// truthful `LOCATION_REPORT` needs both: TS 29.571 §5.4.4.9's `NrLocation` makes
/// `tai` and `ncgi` each `M` (`29571-k00.txt:4674`, `:4689`). The TAC arrives as
/// three big-endian octets and has to be reassembled, which is exactly the kind of
/// expression that ends up subtly different in its fourth copy. Before #406 the
/// unpacking existed once, inline in `handle_handover_notify`, and the other three
/// sites either dropped the value or stored half of it.
///
/// Callers: `handle_uplink_nas_transport` (the SERVICE REQUEST and every other UL
/// NAS message), `handle_path_switch_request` (Xn handover) and
/// `handle_handover_notify` (N2 handover). `handle_initial_ue_message` does not use
/// it because `parse_initial_ue_message_asn1` has already flattened the IE into
/// `InitialUeMessageData`'s own fields, so no `UserLocationInformation` survives to
/// that site.
///
/// Takes `&mut AmfUe` rather than the store, so the caller decides the locking: at
/// every call site this runs inside a `UeStore::with_mut` closure, because
/// `UeStore::get` hands back a CLONE (`ue_store.rs:113-115`) and a location written
/// to a dropped clone is the same defect as not writing it at all.
/// A HANDOVER NOTIFY as the generated decoder hands it over (#417): the User
/// Location Information is criticality ignore, so it may be absent.
struct HandoverNotifyDecoded {
    amf_ue_ngap_id: u64,
    ran_ue_ngap_id: u32,
    user_location_info: Option<nextgcore_ngap::types::UserLocationInformation>,
}

/// The released-list items for `sessions`, each a PathSwitchRequestUnsuccessfulTransfer
/// carrying `cause` (TS 38.413 §9.3.4.11). `None` when there is nothing to release.
fn released_items(
    sessions: &[u8],
    cause: nextgcore_ngap::types::Cause,
) -> Option<Vec<nextgcore_ngap::types::PduSessionResourceReleasedItem>> {
    let transfer = crate::ngap_asn1::path_switch_unsuccessful_transfer(cause)?;
    (!sessions.is_empty()).then(|| {
        sessions
            .iter()
            .map(
                |psi| nextgcore_ngap::types::PduSessionResourceReleasedItem {
                    pdu_session_id: *psi,
                    transfer: transfer.clone(),
                },
            )
            .collect()
    })
}

/// A PATH SWITCH REQUEST FAILURE releasing `sessions` with `cause`; `None`
/// when there is no session to name (the released list is mandatory).
fn path_switch_failure(
    amf_ue_ngap_id: u64,
    ran_ue_ngap_id: u32,
    sessions: &[u8],
    cause: nextgcore_ngap::types::Cause,
    diagnostics: &[crate::ngap_asn1::IeDiagnostic],
) -> Option<Vec<u8>> {
    crate::ngap_asn1::build_path_switch_request_failure_generated(
        amf_ue_ngap_id,
        ran_ue_ngap_id,
        &released_items(sessions, cause)?,
        diagnostics,
    )
}

/// `host:port` -> (host, port); `None` when the port is missing or invalid.
fn split_authority(authority: &str) -> Option<(String, u16)> {
    let (host, port) = authority.rsplit_once(':')?;
    Some((
        host.trim_matches(['[', ']']).to_string(),
        port.parse().ok()?,
    ))
}

/// The NAS context an Uplink-NAS-borne PLAIN initial REGISTRATION REQUEST gets
/// when its NG connection has none (#675), or `None` for anything else. Mirrors the
/// Initial UE Message path: location from the message's mandatory User Location
/// Information, 3GPP access, a fresh security canary.
fn fresh_context_for_initial_registration(
    association_id: u64,
    ul_nas: &crate::ngap_asn1::UplinkNasTransportData,
) -> Option<UeNasContext> {
    let nas = &ul_nas.nas_pdu;
    let is_plain_initial_registration = nas.len() >= 4
        && nas[0] == 0x7E
        && nas[1] == security_header::PLAIN_NAS_MESSAGE
        && nas[2] == message_type::REGISTRATION_REQUEST
        && nas[3] & 0x07 == crate::gmm_build::registration_type::INITIAL;
    if !is_plain_initial_registration {
        return None;
    }
    let mut state = UeNasContext::new(
        ul_nas.amf_ue_ngap_id,
        ul_nas.ran_ue_ngap_id,
        association_id,
        crate::context::nas_security_canary(),
    );
    if let Some(location) = &ul_nas.user_location_info {
        apply_user_location(&mut state.amf_ue, location);
    }
    state.amf_ue.access_type = 1; // 3GPP access
    Some(state)
}

fn apply_user_location(
    amf_ue: &mut AmfUe,
    location: &nextgcore_ngap::types::UserLocationInformation,
) {
    let nextgcore_ngap::types::UserLocationInformation::Nr {
        nr_cgi_plmn,
        nr_cell_identity,
        tai_plmn,
        tai_tac,
    } = location;
    amf_ue.nr_cgi.plmn_id = plmn_id_from_ngap_bytes(nr_cgi_plmn);
    amf_ue.nr_cgi.cell_id = *nr_cell_identity;
    amf_ue.nr_tai.plmn_id = plmn_id_from_ngap_bytes(tai_plmn);
    amf_ue.nr_tai.tac =
        ((tai_tac[0] as u32) << 16) | ((tai_tac[1] as u32) << 8) | tai_tac[2] as u32;
}

/// Convert a configured algorithm preference order into a support mask;
/// `default_mask` when no order is configured
///
/// `pub(crate)` so #363's one-context test can assert the NAS algorithm selection
/// through the SAME reader the registration path uses, rather than reimplementing the
/// mask arithmetic in the test and proving only that two copies of it agree.
pub(crate) fn algorithm_order_to_mask(order: &[u8], default_mask: u8) -> u8 {
    if order.is_empty() {
        return default_mask;
    }
    let mut mask = 0u8;
    for alg in order {
        if *alg < 8 {
            mask |= 1 << *alg;
        }
    }
    mask
}

/// Map an SBI error to a 5GMM reject cause (TS 24.501 Annex A; mirrors the
/// Open5GS gmm_cause_from_sbi mapping — no blanket "unspecified")
fn gmm_cause_from_sbi_error(err: &crate::sbi_path::SbiError) -> GmmCause {
    use crate::sbi_path::SbiError;
    match err {
        SbiError::RequestFailed(msg) => {
            if msg.contains("404") {
                // Subscriber unknown
                GmmCause::UeIdentityCannotBeDerivedByTheNetwork
            } else if msg.contains("403") {
                GmmCause::FiveGsServicesNotAllowed
            } else if msg.contains("400") {
                GmmCause::SemanticallyIncorrectMessage
            } else {
                // Peer unreachable / 5xx: the payload could not be forwarded
                GmmCause::PayloadWasNotForwarded
            }
        }
        SbiError::Timeout | SbiError::GatewayTimeout => GmmCause::PayloadWasNotForwarded,
        SbiError::NfInstanceNotFound | SbiError::ServiceNotFound(_) => {
            GmmCause::PayloadWasNotForwarded
        }
        SbiError::ResponseParseError(_) => GmmCause::SemanticallyIncorrectMessage,
        SbiError::InvalidState => GmmCause::MessageNotCompatibleWithTheProtocolState,
    }
}

/// NGAP server wrapper with mutable SCTP access
pub struct NgapServerHandle {
    inner: Arc<Mutex<NgapServer>>,
}

impl NgapServerHandle {
    pub async fn new(
        bind_addr: SocketAddr,
        backend: SctpBackend,
        event_tx: mpsc::Sender<AmfEvent>,
    ) -> Result<Self> {
        let server = NgapServer::new(bind_addr, backend, event_tx).await?;
        Ok(Self {
            inner: Arc::new(Mutex::new(server)),
        })
    }

    pub async fn poll(&self) -> Result<bool> {
        let mut server = self.inner.lock().await;
        server.poll().await
    }

    pub async fn local_addr(&self) -> SocketAddr {
        let server = self.inner.lock().await;
        server.local_addr()
    }

    pub async fn num_gnbs(&self) -> usize {
        let server = self.inner.lock().await;
        server.num_gnbs().await
    }
}

// ============================================================================
// NGAP Path Functions (Open5GS-style API)
// ============================================================================

/// Global NGAP server instance
static NGAP_SERVER: once_cell::sync::OnceCell<NgapServerHandle> = once_cell::sync::OnceCell::new();

/// Initialize NGAP path
pub async fn amf_ngap_open(
    bind_addr: Option<SocketAddr>,
    backend: SctpBackend,
    event_tx: mpsc::Sender<AmfEvent>,
) -> Result<()> {
    let addr = bind_addr.unwrap_or_else(|| {
        format!("{DEFAULT_NGAP_ADDR}:{NEXTGCORE_NGAP_SCTP_PORT}")
            .parse()
            .expect("value expected")
    });

    let handle = NgapServerHandle::new(addr, backend, event_tx).await?;
    let local_addr = handle.local_addr().await;

    let _ = NGAP_SERVER.set(handle);

    log::info!("NGAP path opened on {local_addr} ({})", backend.label());
    Ok(())
}

/// Close NGAP path
pub async fn amf_ngap_close() {
    if let Some(_server) = NGAP_SERVER.get() {
        log::info!("NGAP path closed");
    }
}

/// Get the NGAP server (if initialized)
pub fn get_ngap_server() -> Option<&'static NgapServerHandle> {
    NGAP_SERVER.get()
}

/// Poll for NGAP events
pub async fn amf_ngap_poll() -> Result<bool> {
    if let Some(server) = NGAP_SERVER.get() {
        server.poll().await
    } else {
        Ok(false)
    }
}

/// Which intra-5GS N2 handover step an SMF answer belongs to (#964).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum N2HandoverStep {
    /// `hoState: PREPARING`, answered with the Handover Request Transfer.
    Preparing,
    /// `hoState: PREPARED`, answered with the Handover Command Transfer.
    Prepared,
    /// `hoState: PREPARED` for a session the target could not admit
    /// (`HANDOVER_RES_ALLOC_FAIL`), answered with the Handover Preparation Unsuccessful
    /// Transfer (`HANDOVER_PREP_FAIL`) the HANDOVER COMMAND's release list carries.
    AllocationFailed,
}

/// The SMF's answer to one N2 handover step for one PDU session (#964).
#[derive(Debug)]
pub(crate) struct N2HandoverAnswer {
    pub(crate) amf_ue_ngap_id: u64,
    pub(crate) psi: u8,
    /// The step's generation: an answer for a preparation since cancelled or superseded
    /// finds no match and is dropped.
    pub(crate) generation: u64,
    pub(crate) step: N2HandoverStep,
    /// The N2 SM information the step needs from the SMF, or why there is none.
    pub(crate) result: std::result::Result<Vec<u8>, String>,
}

/// An intra-5GS preparation waiting for its SMFs' Handover Request Transfers (#964).
#[derive(Debug)]
struct HoPreparation {
    generation: u64,
    /// TS 23.502 §4.9.1.3.2 step 8: when the AMF stops waiting for PREPARING answers.
    deadline: Instant,
    source_assoc: u64,
    target_assoc: u64,
    required: nextgcore_ngap::types::HandoverRequired,
    awaiting: HashSet<u8>,
    ready: Vec<(u8, Vec<u8>)>,
}

/// A target's Acknowledge waiting for its SMFs' Handover Command Transfers (#964).
#[derive(Debug)]
struct HoCommandPending {
    generation: u64,
    /// When the AMF stops waiting for PREPARED answers (#964 review).
    deadline: Instant,
    source_assoc: u64,
    target_assoc: u64,
    target_ran: u32,
    target_to_source_container: Vec<u8>,
    /// Each admitted session's Handover Request Acknowledge Transfer.
    admitted: Vec<(u8, Vec<u8>)>,
    awaiting: HashSet<u8>,
    /// Each session's Handover Command Transfer from its SMF.
    ready: Vec<(u8, Vec<u8>)>,
    /// The sessions the source listed in its HandoverRequired.
    offered: Vec<u8>,
    /// Each refused session's Handover Preparation Unsuccessful Transfer from its SMF.
    released: Vec<(u8, Vec<u8>)>,
}

/// How long a failed `hoState: COMPLETED` waits before its one retry (#964 review).
const HANDOVER_COMPLETED_RETRY: Duration = Duration::from_millis(200);

/// The default SMF wait of each N2 handover step (TS 23.502 §4.9.1.3.2 step 8, NOTE 2:
/// locally configured): well inside the source's TNGRELOCprep.
const DEFAULT_HANDOVER_SMF_WAIT: Duration = Duration::from_millis(1000);

/// An N2 handover step's SMF wait from `var`, in milliseconds (#964 review). Unset or
/// unparsable is the default; 0 means "do not wait at all", so only answers already in
/// are used.
fn handover_smf_wait_from_env(var: &str) -> Duration {
    match std::env::var(var) {
        Ok(v) => match v.trim().parse::<u64>() {
            Ok(ms) => Duration::from_millis(ms),
            Err(_) => {
                log::warn!(
                    "{var}={v:?} is not a number of milliseconds; using {DEFAULT_HANDOVER_SMF_WAIT:?}"
                );
                DEFAULT_HANDOVER_SMF_WAIT
            }
        },
        Err(_) => DEFAULT_HANDOVER_SMF_WAIT,
    }
}

/// The `NgRanTargetId` (TS 29.571) of an intra-5GS HandoverRequired's target, for the
/// PREPARING step (#964); `None` for a target that is not a gNB.
fn handover_target_id_json(target: &nextgcore_ngap::types::TargetId) -> Option<serde_json::Value> {
    let nextgcore_ngap::types::TargetId::TargetRanNodeId {
        global_ran_node_id:
            nextgcore_ngap::types::GlobalRanNodeId::GlobalGnbId {
                plmn_identity,
                gnb_id,
                gnb_id_len,
            },
        selected_tai,
    } = target
    else {
        return None;
    };
    let plmn = crate::ngap_asn1::decode_plmn_id(plmn_identity);
    let tai_plmn = crate::ngap_asn1::decode_plmn_id(&selected_tai.tai_plmn);
    let tac = u32::from_be_bytes([
        0,
        selected_tai.tai_tac[0],
        selected_tai.tai_tac[1],
        selected_tai.tai_tac[2],
    ]);
    Some(serde_json::json!({
        "ranNodeId": crate::namf_server::global_ran_node_id_json(&plmn, *gnb_id, *gnb_id_len),
        "tai": {
            "plmnId": { "mcc": tai_plmn.mcc(), "mnc": tai_plmn.mnc() },
            "tac": format!("{tac:06x}"),
        },
    }))
}

/// The stream of a UE-associated NGAP PDU keyed by `key` on an association with
/// `outbound` negotiated outbound streams (TS 38.412 §7, #813): `1..outbound`, spread by
/// key, or 0 when the peer allowed no second stream.
fn ue_associated_stream(key: u64, outbound: u16) -> u16 {
    if outbound < 2 {
        return 0;
    }
    1 + (key % u64::from(outbound - 1)) as u16
}

