    // ------------------------------------------------------------------
    // NAS parsing round-trips (TS 24.501)
    // ------------------------------------------------------------------

    /// Synthetic Registration Request: SUCI (mcc 999 / mnc 70), UE security
    /// capability EA0-3/IA0-3, requested NSSAI SST=1
    fn sample_registration_request() -> Vec<u8> {
        let mut nas = vec![
            0x7E, 0x00, 0x41, // 5GMM plain Registration Request
            0x09, // ngKSI=0 (native), 5GS registration type = initial(1) + FOR
        ];
        // 5GS mobile identity (LV-E): SUCI, IMSI format
        let suci = vec![
            0x01, // SUPI format IMSI, type SUCI
            0x99, 0xF9, 0x07, // PLMN 999/70 (mcc 999, 2-digit mnc 70, filler F)
            0xF0, 0xFF, // routing indicator "0"
            0x00, // protection scheme: null
            0x00, // home network public key id
            0x00, 0x00, 0x00, 0x00, 0x10, // MSIN BCD
        ];
        nas.extend_from_slice(&(suci.len() as u16).to_be_bytes());
        nas.extend_from_slice(&suci);
        // UE security capability (IEI 0x2E): EA0-3, IA0-3
        nas.extend_from_slice(&[0x2E, 0x02, 0xF0, 0xF0]);
        // Requested NSSAI (IEI 0x2F): one S-NSSAI, SST=1
        nas.extend_from_slice(&[0x2F, 0x02, 0x01, 0x01]);
        nas
    }

    /// A Registration Request from a UE arriving from EPS (TS 24.501 §5.5.1.2.2):
    /// the 5GS mobile identity holds a 5G-GUTI **mapped** from the UE's 4G-GUTI, and
    /// an ATTACH REQUEST rides in the EPS NAS message container IE.
    ///
    /// The GUTI bytes are built by mapping a chosen 4G-GUTI FORWARD through
    /// TS 23.003 §2.10.2.2.2, exactly as the UE would, so the test's fixture is not
    /// produced by the code under test -- the AMF's reverse mapping has something
    /// independent to be checked against.
    fn eps_mobility_registration_request(with_additional_guti: bool) -> (Vec<u8>, (u16, u8, u32)) {
        // The 4G-GUTI the (imaginary) MME issued.
        const MME_GID: u16 = 0xAB9B;
        const MME_CODE: u8 = 0b0110_1010;
        const M_TMSI: u32 = 0x1234_5678;

        // UE-side mapping, §2.10.2.2.2: MME GID 15..8 -> AMF Region ID;
        // GID 7..0 -> Set ID 9..2; Code 7..6 -> Set ID 1..0; Code 5..0 -> Pointer.
        let region = (MME_GID >> 8) as u8;
        let set_id = ((MME_GID & 0x00FF) << 2) | ((MME_CODE >> 6) as u16 & 0x03);
        let pointer = MME_CODE & 0x3F;

        let mut nas = vec![0x7E, 0x00, 0x41, 0x09];
        // 5GS mobile identity (LV-E): type 2 = 5G-GUTI, PLMN 001/01.
        let guti = vec![
            0xF2, // spare | type 5G-GUTI (2)
            0x00,
            0xF1,
            0x10, // PLMN 001/01
            region,
            (set_id >> 2) as u8,
            (((set_id & 0x03) as u8) << 6) | pointer,
            (M_TMSI >> 24) as u8,
            (M_TMSI >> 16) as u8,
            (M_TMSI >> 8) as u8,
            M_TMSI as u8,
        ];
        nas.extend_from_slice(&(guti.len() as u16).to_be_bytes());
        nas.extend_from_slice(&guti);
        // 5GMM capability (IEI 0x10, TLV): octet 3 bit 1 = S1 mode supported.
        nas.extend_from_slice(&[0x10, 0x01, 0x01]);
        // EPS NAS message container (IEI 0x70, TLV-E) holding a stand-in ATTACH REQUEST.
        let attach: &[u8] = &[0x07, 0x41, 0x71, 0x0B];
        nas.push(0x70);
        nas.extend_from_slice(&(attach.len() as u16).to_be_bytes());
        nas.extend_from_slice(attach);
        if with_additional_guti {
            // Additional GUTI (IEI 0x77, TLV-E): the UE's NATIVE 5G-GUTI, deliberately
            // a different TMSI so it cannot be confused with the mapped one.
            let native = vec![
                0xF2, 0x00, 0xF1, 0x10, 0x01, 0x00, 0x40, 0xDE, 0xAD, 0xBE, 0xEF,
            ];
            nas.push(0x77);
            nas.extend_from_slice(&(native.len() as u16).to_be_bytes());
            nas.extend_from_slice(&native);
        }
        (nas, (MME_GID, MME_CODE, M_TMSI))
    }

    /// #116 criterion 7: an inter-system HandoverRequired is declined with the correct
    /// cause instead of being treated as intra-5GS.
    ///
    /// #116's text describes an unconditional `handover_type != 0` reject in
    /// `ngap_handler` at a cited line pair. **That reject no longer exists** -- only the
    /// `HO_TARGET_NOT_ALLOWED` constant survives -- and its absence was worse than the
    /// reject: the type was logged and then passed STRAIGHT INTO the `HandoverRequest`,
    /// so a 5GS→EPS preparation was resolved against connected gNBs and either failed
    /// with `unknown-target-id` (a cause that misdescribes an MME as an unknown gNB) or
    /// was forwarded to a gNB as a handover this AMF cannot carry out.
    #[test]
    fn an_inter_system_handover_is_declined_with_ho_target_not_allowed() {
        use nextgcore_ngap::types::CauseRadioNetwork as Cr;
        use nextgcore_ngap::types::HandoverType as Ht;

        assert_eq!(
            inter_system_handover_refusal(Ht::Intra5gs),
            None,
            "intra-5GS handover is handled, not refused: this must stay the ONLY \
             accepted type, or the refusal would break working N2 handover"
        );

        for (ht, label) in [
            (Ht::FivegsToEps, "EPS (fivegs-to-eps)"),
            (Ht::EpsTo5gs, "5GS (eps-to-5gs)"),
        ] {
            let (cause, target) = inter_system_handover_refusal(ht)
                .unwrap_or_else(|| panic!("{ht:?} must be refused, not forwarded to a gNB"));
            assert_eq!(
                cause,
                Cr::HoTargetNotAllowed,
                "{ht:?}: the target system is not one this AMF may hand over to -- it has \
                 no N26 leg (#62). NOT UnknownTargetId, which would blame RAN config"
            );
            assert_eq!(target, label);
        }

        // The cause's wire value, against the spec table rather than the enum name:
        // an enum renamed or reordered must not silently change what goes on the wire.
        assert_eq!(
            Cr::HoTargetNotAllowed as i64,
            8,
            "ho-target-not-allowed is CauseRadioNetwork 8 (TS 38.413 §9.3.1.2)"
        );
    }

    /// **#408 criterion 4**: the refusal routes ONLY when a Forward Relocation can actually be
    /// driven, and still refuses when it cannot.
    ///
    /// # Why all eight combinations
    ///
    /// The criterion is a conjunction of three conditions, so there are eight states and the
    /// conjunction is only pinned if every one of them is checked. The first draft of this test
    /// exercised four — the convenient ones, always with a bound socket — and forcing the
    /// `socket_bound` conjunct to `true` **passed the whole amfd suite**. That gap is the
    /// finding, not a footnote: "switch set, bind failed" is a real production path
    /// (`lib.rs`'s `n26_open` error branch logs and continues), and with the conjunct dropped
    /// the AMF would route a preparation into a socket that does not exist. Enumerating all
    /// eight is what makes each row of the revert-verification table true rather than
    /// aspirational.
    #[test]
    fn inter_system_handover_refusal_routes_only_when_a_forward_relocation_can_be_driven() {
        use nextgcore_ngap::types::CauseRadioNetwork as Cr;
        use nextgcore_ngap::types::HandoverType as Ht;

        for switch_on in [false, true] {
            for socket_bound in [false, true] {
                for has_peer in [false, true] {
                    let drivable = crate::n26_path::is_forward_relocation_drivable(
                        switch_on,
                        socket_bound,
                        has_peer,
                    );
                    let all_three = switch_on && socket_bound && has_peer;
                    assert_eq!(
                        drivable, all_three,
                        "drivability is the CONJUNCTION of all three \
                         (switch_on={switch_on}, socket_bound={socket_bound}, \
                         has_peer={has_peer}). Any conjunct silently dropped to `true` makes \
                         this disagree in exactly the state that conjunct guards."
                    );

                    // Intra-5GS is never refused, in any of the eight states -- the N26 leg's
                    // configuration must not affect working N2 handover.
                    assert_eq!(
                        inter_system_handover_refusal_with(Ht::Intra5gs, drivable),
                        None,
                        "intra-5GS handover must stay accepted regardless of N26 state \
                         (switch_on={switch_on}, socket_bound={socket_bound}, \
                         has_peer={has_peer})"
                    );

                    // fivegs-to-eps: routed iff drivable.
                    let fivegs = inter_system_handover_refusal_with(Ht::FivegsToEps, drivable);
                    if all_three {
                        assert_eq!(
                            fivegs, None,
                            "fivegs-to-eps must ROUTE when the switch is on, a socket is bound \
                             and a target MME is configured: the preparation CAN be completed, \
                             and refusing it would be the #116 defect in the other direction"
                        );
                    } else {
                        let (cause, label) = fivegs.unwrap_or_else(|| {
                            panic!(
                                "fivegs-to-eps must still be REFUSED when a Forward Relocation \
                                 cannot be driven (switch_on={switch_on}, \
                                 socket_bound={socket_bound}, has_peer={has_peer}) -- routing \
                                 it would forward a preparation the AMF cannot complete, which \
                                 is strictly worse than an honest refusal"
                            )
                        });
                        assert_eq!(cause, Cr::HoTargetNotAllowed);
                        assert_eq!(label, "EPS (fivegs-to-eps)");
                    }

                    // eps-to-5gs: refused UNCONDITIONALLY, including when drivable.
                    //
                    // Not an oversight. TS 38.413 §9.3.1.22 (38413-j30.txt:19660-19662) defines
                    // HandoverType as "which kind of handover was triggered in the SOURCE", and
                    // an EPS-to-5GS handover is triggered in the E-UTRAN -- it reaches this AMF
                    // as a Forward Relocation Request over N26 or as a RelocateUEContext from an
                    // initial AMF, never as an NGAP HandoverRequired from a gNB. So there is no
                    // state in which routing it is right.
                    let (cause, label) = inter_system_handover_refusal_with(Ht::EpsTo5gs, drivable)
                        .unwrap_or_else(|| {
                            panic!(
                                "eps-to-5gs must be refused in ALL eight states, including \
                                 drivable={drivable}: a HandoverRequired naming it comes from a \
                                 gNB, and that procedure's source is the E-UTRAN"
                            )
                        });
                    assert_eq!(cause, Cr::HoTargetNotAllowed);
                    assert_eq!(label, "5GS (eps-to-5gs)");
                }
            }
        }
    }

    /// **#408 criterion 6**: the HANDOVER COMMAND for an accepted 5GS→EPS preparation declines
    /// forwarding and names which bearers lose data.
    ///
    /// # What this pins that a weaker test would not
    ///
    /// The forwarding decision is `Vec::new()` — a value a careless refactor could produce by
    /// accident — so the assertion that earns its keep is the second one: the bearers are
    /// **named**, so the site has something specific to log, and the refusal holds **even when
    /// the MME offered an endpoint**. The gNB's own `direct-path-available` is now parsed
    /// (#408), and a later change that wired the Direct Forwarding Indication to it without also
    /// writing a `HandoverCommandTransfer` encoder would fail here.
    #[test]
    fn a_5gs_to_eps_handover_command_declines_forwarding_and_says_which_bearers_lose_data() {
        let _guard = crate::test_support::CONTEXT_GUARD.blocking_lock();

        // Literal values distinct from every sibling test's: the AMF context is process-global
        // and keyed by identity, so a shared UE id would let two tests resolve each other's
        // state. `0x408` marks these as this issue's.
        const UE: u64 = 0x0408_4001;
        const DL_COUNT: u32 = 0x0408_12AB;

        let accepted = crate::n26_path::ForwardRelocationOutcome::Accepted {
            mme_teid: Some(0x0408_5001),
            peer: "10.4.8.9:2123".parse().expect("a literal address parses"),
            target_to_source_container: vec![0xE0, 0xE8],
            admitted_ebis: vec![5, 6],
            dl_count_used: DL_COUNT,
        };

        let command = inter_system_handover_command(&accepted)
            .expect("an accepted relocation must yield a HandoverCommand decision");

        // The container is relayed byte for byte -- TS 38.413 §9.3.1.21 makes it a TS 36.413
        // E-UTRAN structure, so any re-encoding here corrupts what the source gNB decodes.
        assert_eq!(
            command.target_to_source_container,
            vec![0xE0, 0xE8],
            "the Target-to-Source container must be relayed VERBATIM"
        );

        // THE forwarding decision.
        assert!(
            command.forwarding_sessions.is_empty(),
            "the PDU Session Resource Handover List must be EMPTY: each item would carry a \
             HandoverCommandTransfer whose dLForwardingUP-TNLInformation (38413-j30.txt:48917) \
             this tree has no encoder for, and TS 38.413 §9.2.3.2 makes the list \
             `PRESENCE optional` (:38763) so an empty one is conformant"
        );
        assert_eq!(
            command.bearers_without_forwarding,
            vec![5, 6],
            "and every admitted bearer must be NAMED, so the site logs WHICH bearers lose \
             in-flight downlink data rather than reporting a count. That is the #185 posture: \
             state what is affected, not merely that something is."
        );

        // The COUNT the UE would need, computed and reported -- the ceiling is that it is not
        // encoded, not that it is unknown.
        assert_eq!(
            command.nas_count_lsb,
            (DL_COUNT & 0xFF) as u8,
            "the 8 LSB of the downlink NAS COUNT used for K_ASME' must be the PRE-increment \
             value TS 33.501 §8.3.2 step 7 names (33501-k20.txt:11409-11412). It is carried \
             through the pending record rather than re-read, because by now the stored count \
             has advanced -- re-reading is the nextgsim-#203 defect."
        );

        // The forwarding refusal must NOT depend on what the MME offered. An accepted outcome
        // whose bearers carried endpoints still yields an empty list, because the missing piece
        // is the AMF's own encoder rather than the MME's answer.
        let with_offer = crate::n26_path::ForwardRelocationOutcome::Accepted {
            mme_teid: Some(0x0408_5002),
            peer: "10.4.8.9:2123".parse().expect("a literal address parses"),
            target_to_source_container: vec![0xE0, 0xE8],
            admitted_ebis: vec![7],
            dl_count_used: DL_COUNT,
        };
        let offered = inter_system_handover_command(&with_offer).expect("accepted");
        assert!(
            offered.forwarding_sessions.is_empty(),
            "the refusal to forward must hold regardless of what the target MME offered: the \
             blocker is this AMF's missing HandoverCommandTransfer encoder, so a change that \
             wired the Direct Forwarding Indication to the gNB's parsed \
             direct-path-available without also writing that encoder must fail here"
        );
        assert_eq!(offered.bearers_without_forwarding, vec![7]);

        // And a REFUSED relocation yields no command at all -- it produces a
        // HandoverPreparationFailure, which is a different message.
        let refused = crate::n26_path::ForwardRelocationOutcome::Refused { cause: 81 };
        assert!(
            inter_system_handover_command(&refused).is_none(),
            "a refused relocation must NOT yield a HandoverCommand: the source gNB gets a \
             HandoverPreparationFailure, and a command here would tell it to move a UE the \
             target declined"
        );
        let _ = UE;
    }

    /// #570: the RACS bit (5GMM capability octet 4 bit 8, TS 24.501 §9.11.3.1) and the
    /// UE radio capability ID IE (0x67, §9.11.3.68) are read from a Registration
    /// Request; octet 3 alone does not set RACS.
    #[test]
    fn the_parser_reads_the_racs_bit_and_the_ue_radio_capability_id() {
        let (mut nas, _) = eps_mobility_registration_request(false);
        let req = parse_registration_request_pdu(&nas).expect("parse");
        assert!(!req.racs_supported, "the fixture's capability is one octet");
        assert_eq!(req.ue_radio_capability_id, None);
        // 5GMM capability as nextgsim sends it with RACS: 10 02 00 80; then the ID.
        nas.extend_from_slice(&[0x10, 0x02, 0x00, 0x80]);
        nas.extend_from_slice(&[0x67, 0x07, 0x01, 0x05, 0x00, 0x00, 0x00, 0x00, 0x10]);
        let req = parse_registration_request_pdu(&nas).expect("parse");
        assert!(req.racs_supported);
        assert_eq!(
            req.ue_radio_capability_id.as_deref(),
            Some(&[0x01, 0x05, 0x00, 0x00, 0x00, 0x00, 0x10][..])
        );
    }

    /// #116 criterion 2: the LIVE parser captures the UE's S1-mode capability.
    ///
    /// The parser #116's text cites (`gmm_handler`'s) has only test callers -- its own
    /// `handle_registration_request` is called from three places, all inside
    /// `mod tests` -- so implementing this there would have been a correct fix in an
    /// unreachable place. This is the parser `handle_registration_request_nas` uses.
    #[test]
    fn the_live_parser_captures_ue_s1_mode_capability() {
        let (nas, _) = eps_mobility_registration_request(false);
        let req = parse_registration_request_pdu(&nas).expect("parse");
        assert!(
            req.s1_mode,
            "5GMM capability IEI 0x10 with octet 3 bit 1 set means S1 mode supported \
             (TS 24.501 §9.11.3.1); it used to be walked past by the default TLV arm"
        );

        // And the bit is read, not merely the IE's presence: HO attach (bit 2) is not
        // S1 mode. Same IE, one bit over.
        let mut ho_attach_only = nas.clone();
        let iei = ho_attach_only
            .windows(3)
            .position(|w| w == [0x10, 0x01, 0x01])
            .expect("the capability IE is in the fixture");
        ho_attach_only[iei + 2] = 0x02;
        let req = parse_registration_request_pdu(&ho_attach_only).expect("parse");
        assert!(
            !req.s1_mode,
            "octet 3 bit 2 is HO attach, not S1 mode -- a presence-only check would \
             pass here and advertise IWK N26 to a UE that never claimed EPC NAS"
        );
    }

    /// #116 criterion 4: a mapped EPS-GUTI is recognised AS mapped, and is not stored
    /// as a native 5G-GUTI.
    #[test]
    fn a_mapped_eps_guti_is_recognised_as_mapped_and_reverse_maps_to_the_4g_guti() {
        let (nas, (mme_gid, mme_code, m_tmsi)) = eps_mobility_registration_request(false);
        let req = parse_registration_request_pdu(&nas).expect("parse");

        assert_eq!(
            req.identity_type,
            mobile_identity_type::GUTI,
            "precondition: the identity is a GUTI"
        );
        assert_eq!(
            req.eps_nas_message_container.as_deref(),
            Some(&[0x07u8, 0x41, 0x71, 0x0B][..]),
            "the EPS NAS message container must be KEPT, not skipped: it carries the \
             ATTACH/TAU REQUEST, and its presence is the discriminator"
        );
        assert!(
            req.guti_is_mapped_from_eps(),
            "a GUTI plus an EPS NAS message container is a MAPPED 5G-GUTI \
             (TS 24.501 §5.5.1.2.2, §5.5.1.3.4 c.2), not a native one"
        );

        // The reverse mapping (§2.10.2.1.3) must recover the MME's own 4G-GUTI --
        // the fixture computed the 5GS fields forward, independently of this code.
        let g = req.guti.as_ref().expect("guti");
        let eps = nextgcore_nas::interworking::five_g_guti_to_eps_guti(
            &nextgcore_nas::fiveg::types::FiveGGuti {
                plmn_id: crate::gmm_build::to_nextgcore_plmn(&g.plmn_id),
                amf_region_id: g.amf_region_id,
                amf_set_id: g.amf_set_id,
                amf_pointer: g.amf_pointer,
                tmsi: g.tmsi,
            },
        );
        assert_eq!(eps.mme_gid, mme_gid, "MME Group ID must round-trip");
        assert_eq!(eps.mme_code, mme_code, "MME Code must round-trip");
        assert_eq!(eps.m_tmsi, m_tmsi, "M-TMSI must round-trip");

        // A GUTI with NO EPS NAS message container is native, and must not be
        // mistaken for mapped -- otherwise every ordinary mobility registration
        // would be treated as an inter-system move.
        let mut native_only = nas.clone();
        let at = native_only
            .windows(3)
            .position(|w| w == [0x70, 0x00, 0x04])
            .expect("container IEI in fixture");
        native_only.drain(at..at + 3 + 4);
        let req = parse_registration_request_pdu(&native_only).expect("parse");
        assert!(req.guti.is_some(), "still a GUTI");
        assert!(
            !req.guti_is_mapped_from_eps(),
            "without an EPS NAS message container the GUTI is NATIVE"
        );
    }

    /// The Additional GUTI IE is decoded, because on the EPS→5GS path that -- not the
    /// mobile identity -- is the UE's native 5G-GUTI (TS 24.501 §5.5.1.2.2).
    #[test]
    fn the_additional_guti_ie_is_decoded_not_just_counted() {
        let (nas, _) = eps_mobility_registration_request(true);
        let req = parse_registration_request_pdu(&nas).expect("parse");
        let native = req
            .additional_guti
            .expect("additional GUTI must be decoded");
        assert_eq!(
            native.tmsi, 0xDEAD_BEEF,
            "the Additional GUTI's own TMSI, distinct from the mapped identity's"
        );
        assert_ne!(
            native.tmsi,
            req.guti.as_ref().expect("guti").tmsi,
            "the two identities must not be conflated"
        );
        assert!(
            req.presencemask & reg_present::ADDITIONAL_GUTI != 0,
            "and the §4.4.6 presence bit is still set"
        );
    }

    #[test]
    fn test_parse_registration_request_suci_caps_nssai() {
        let nas = sample_registration_request();
        let req = parse_registration_request_pdu(&nas).expect("parse");

        assert_eq!(req.registration_type, 1); // initial
        assert_eq!(req.identity_type, mobile_identity_type::SUCI);
        let suci = req.suci.expect("suci");
        assert!(suci.starts_with("suci-0-999-70-"), "{suci}");
        let cap = req.sec_cap.expect("sec cap");
        assert_eq!(cap.ea, 0xF0);
        assert_eq!(cap.ia, 0xF0);
        assert_eq!(req.requested_nssai.len(), 1);
        assert_eq!(req.requested_nssai[0].sst, 1);
    }

    /// A cleartext-only initial Registration Request (TS 24.501 §4.4.6): SUCI
    /// identity + UE security capability, but no Requested NSSAI IE.
    fn cleartext_only_registration_request() -> Vec<u8> {
        let mut nas = vec![0x7E, 0x00, 0x41, 0x09];
        let suci = vec![
            0x01, 0x99, 0xF9, 0x07, 0xF0, 0xFF, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x10,
        ];
        nas.extend_from_slice(&(suci.len() as u16).to_be_bytes());
        nas.extend_from_slice(&suci);
        // UE security capability (IEI 0x2E) — a cleartext IE.
        nas.extend_from_slice(&[0x2E, 0x02, 0xF0, 0xF0]);
        nas
    }

    #[test]
    fn test_parse_registration_request_sets_presencemask() {
        // sample_registration_request carries UE security capability (cleartext)
        // and Requested NSSAI (non-cleartext).
        let req = parse_registration_request_pdu(&sample_registration_request()).expect("parse");
        assert_ne!(req.presencemask & reg_present::UE_SECURITY_CAPABILITY, 0);
        assert_ne!(req.presencemask & reg_present::REQUESTED_NSSAI, 0);
        assert!(!req.nas_message_container_present);

        // Cleartext-only request: no non-cleartext bit set.
        let clear =
            parse_registration_request_pdu(&cleartext_only_registration_request()).expect("parse");
        assert_eq!(clear.presencemask & !REGISTRATION_CLEARTEXT_PRESENT, 0);
    }

    #[test]
    fn test_validate_initial_registration_cleartext_rejects_non_cleartext() {
        // Unprotected initial Registration Request with a Requested-NSSAI IE
        // (non-cleartext) -> Registration Reject #95 (TS 24.501 §4.4.6).
        let req = parse_registration_request_pdu(&sample_registration_request()).expect("parse");
        assert_eq!(
            validate_initial_registration_cleartext(&req, false),
            Some(GmmCause::SemanticallyIncorrectMessage)
        );
    }

    #[test]
    fn test_validate_initial_registration_cleartext_accepts_cleartext_only() {
        // A cleartext-only initial registration is accepted (matches the
        // nextgsim UE, which sends no Requested-NSSAI in the clear).
        let req =
            parse_registration_request_pdu(&cleartext_only_registration_request()).expect("parse");
        assert_eq!(validate_initial_registration_cleartext(&req, false), None);
    }

    #[test]
    fn test_validate_initial_registration_cleartext_protected_allows_all() {
        // When integrity-protected (the SMC replay or a mobility update over an
        // existing security context), all IEs are permitted.
        let req = parse_registration_request_pdu(&sample_registration_request()).expect("parse");
        assert_eq!(validate_initial_registration_cleartext(&req, true), None);
    }

    #[test]
    fn test_validate_initial_registration_cleartext_rejects_unprotected_container() {
        // A NAS message container in an unprotected initial NAS message is a
        // §4.4.6 violation even with no other non-cleartext IE.
        let mut req = ParsedRegistrationRequest {
            identity_type: mobile_identity_type::SUCI,
            ..Default::default()
        };
        req.nas_message_container_present = true;
        assert_eq!(
            validate_initial_registration_cleartext(&req, false),
            Some(GmmCause::SemanticallyIncorrectMessage)
        );
        // Same message, integrity-protected -> accepted.
        assert_eq!(validate_initial_registration_cleartext(&req, true), None);
    }

    #[test]
    fn test_parse_registration_request_snpn_nid() {
        // SNPN (Rel-17, TS 23.501 §5.30): the AMF parser extracts the NID IE,
        // carried as the 44-bit packed NID of TS 23.003 §12.7 (6 octets).
        let mut nas = sample_registration_request();
        // "7AB01234567" packed MSB-first, trailing nibble spare.
        let packed = [0x7A, 0xB0, 0x12, 0x34, 0x56, 0x70];
        nas.push(0xA6); // SNPN NID IEI
        nas.push(packed.len() as u8); // 6
        nas.extend_from_slice(&packed);

        let req = parse_registration_request_pdu(&nas).expect("parse");
        assert_eq!(req.snpn_nid.as_deref(), Some("7AB01234567"));
        // The other IEs still parse correctly after the NID IE.
        assert_eq!(req.requested_nssai.len(), 1);
    }

    #[test]
    fn test_decode_nid_44bit() {
        // Mirrors the sim encoder; rejects short input (strict).
        assert_eq!(
            decode_nid_44bit(&[0x7A, 0xB0, 0x12, 0x34, 0x56, 0x70]).as_deref(),
            Some("7AB01234567")
        );
        assert_eq!(
            decode_nid_44bit(&[0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xF0]).as_deref(),
            Some("FFFFFFFFFFF")
        );
        assert!(decode_nid_44bit(&[0x00; 5]).is_none());
    }

    #[test]
    fn test_parse_registration_request_service_level_aa_container() {
        // UAS (Rel-17/18, TS 24.501 §9.11.2.10): the AMF extracts the CAA-level
        // UAV ID from the Service-level-AA container (IEI 0x72, TLV-E) via the
        // Service-level device ID parameter (0x10, UTF-8).
        let mut nas = sample_registration_request();
        let caa = b"FAA-N12345";
        let contents = [&[0x10u8, caa.len() as u8][..], caa].concat(); // device-ID param
        nas.push(0x72); // Service-level-AA container IEI
        nas.push((contents.len() >> 8) as u8); // 2-octet length, hi
        nas.push((contents.len() & 0xFF) as u8); // lo
        nas.extend_from_slice(&contents);

        let req = parse_registration_request_pdu(&nas).expect("parse");
        assert_eq!(req.uav_indication.as_deref(), Some("FAA-N12345"));
        // The other IEs still parse correctly after the TLV-E container.
        assert_eq!(req.requested_nssai.len(), 1);
    }

    #[test]
    fn test_decode_service_level_aa_container() {
        assert_eq!(
            decode_service_level_aa_container(&[0x10, 0x03, b'A', b'B', b'C']).as_deref(),
            Some("ABC")
        );
        // Unknown leading param skipped; device ID still found.
        assert_eq!(
            decode_service_level_aa_container(&[0x30, 0x01, 0xAA, 0x10, 0x02, b'X', b'Y'])
                .as_deref(),
            Some("XY")
        );
        assert!(decode_service_level_aa_container(&[0x30, 0x01, 0xAA]).is_none());
    }

    #[test]
    fn test_snpn_allowed_nids_and_validation() {
        // Empty allowed list accepts any NID (validate_nid empty-list semantics).
        let amf_ue = AmfUe::new(1, 1);
        assert!(amf_ue.validate_nid("7AB01234567", &[]));
        // Non-empty list gates on membership.
        let allowed = vec!["7AB01234567".to_string()];
        assert!(amf_ue.validate_nid("7AB01234567", &allowed));
        assert!(!amf_ue.validate_nid("FFFFFFFFFFF", &allowed));
    }

    #[test]
    fn test_is_snpn_onboarding_suci() {
        assert!(is_snpn_onboarding_suci("suci-0-999-70-onboarding-1"));
        assert!(!is_snpn_onboarding_suci("suci-0-999-70-0-0-1"));
    }

    #[test]
    fn test_parse_registration_request_rejects_truncated() {
        // Strict peer behaviour: missing mandatory mobile identity -> None
        assert!(parse_registration_request_pdu(&[0x7E, 0x00, 0x41, 0x09]).is_none());
        // Identity length larger than buffer -> None
        assert!(
            parse_registration_request_pdu(&[0x7E, 0x00, 0x41, 0x09, 0x00, 0x20, 0x01]).is_none()
        );
    }

    #[test]
    fn test_registration_accept_mandatory_ies_and_protection() {
        let mut amf_ue = AmfUe::new(1, 1);
        amf_ue.access_type = 1;
        amf_ue.nr_tai = crate::context::Tai5gs {
            plmn_id: PlmnId::new("999", "70"),
            tac: 1,
        };
        amf_ue.allowed_nssai = vec![SNssai { sst: 1, sd: None }];
        amf_ue.generate_new_guti();
        let tmsi = amf_ue.next_guti.tmsi;
        assert_ne!(tmsi, 0);

        let plain = gmm_build::build_registration_accept(&amf_ue).expect("accept");
        // Plain inner: EPD + plain hdr + msg type + result LV
        assert_eq!(&plain[..3], &[0x7E, 0x00, 0x42]);
        assert_eq!(plain[3], 1); // result length
        assert_eq!(plain[4] & 0x07, 1); // 3GPP access

        // Mandatory registration-area IEs present
        assert!(plain.contains(&0x54), "TAI list IEI missing");
        assert!(plain.contains(&0x15), "Allowed NSSAI IEI missing");
        assert!(plain.contains(&0x77), "5G-GUTI IEI missing");

        // Strict peer: protect with NIA2/NEA2 and verify the security header
        amf_ue.selected_int_algorithm = 2;
        amf_ue.selected_enc_algorithm = 2;
        amf_ue.knas_int = [0x11; 16];
        amf_ue.knas_enc = [0x22; 16];
        let protected = nas_security::nas_5gs_security_encode(
            &mut amf_ue,
            &plain,
            security_header::INTEGRITY_PROTECTED_AND_CIPHERED,
        )
        .expect("protected");

        assert_eq!(protected[0], 0x7E);
        assert_eq!(
            protected[1],
            security_header::INTEGRITY_PROTECTED_AND_CIPHERED
        );
        assert_eq!(protected.len(), plain.len() + 7);
        // MAC must be non-zero with NIA2
        assert_ne!(&protected[2..6], &[0, 0, 0, 0]);
        // Ciphered payload must differ from the plain message
        assert_ne!(&protected[7..], &plain[..]);
    }

    #[test]
    fn test_smc_replays_actual_ue_capabilities() {
        let mut amf_ue = AmfUe::new(1, 1);
        // Deliberately unusual capability pattern: must be replayed verbatim
        amf_ue.ue_security_capability = UeSecurityCapability {
            ea: 0x55,
            ia: 0xAA,
            eea: 0,
            eia: 0,
        };
        amf_ue.selected_int_algorithm = 2;
        amf_ue.selected_enc_algorithm = 0;

        let smc = gmm_build::build_security_mode_command(&amf_ue).expect("smc");
        assert_eq!(&smc[..3], &[0x7E, 0x00, 0x5D]);
        // Selected NAS security algorithms (TS 24.501 9.11.3.34):
        // ciphering high nibble (NEA0), integrity low nibble (NIA2)
        assert_eq!(smc[3], 0x02);
        // Replayed capability LV: find [len, 0x55, 0xAA]
        assert!(
            smc.windows(3).any(|w| w == [0x02, 0x55, 0xAA]),
            "SMC must replay the UE's actual security capabilities: {smc:02x?}"
        );
        // The hardcoded 0xF0/0xF0 pattern must NOT appear
        assert!(!smc.windows(2).any(|w| w == [0xF0, 0xF0]));
    }

    #[test]
    fn test_strict_peer_rejects_tampered_mac() {
        // Build an uplink-protected message the way the UE would, then check
        // that the AMF-side decode flags a tampered MAC
        let mut ue_side = AmfUe::new(1, 1);
        ue_side.selected_int_algorithm = 2;
        ue_side.selected_enc_algorithm = 0;
        ue_side.knas_int = [0x11; 16];
        ue_side.security_context_available = true;
        ue_side.access_type = 1;

        let inner = vec![0x7E, 0x00, 0x43]; // Registration Complete
        let sqn: u8 = 0;
        let mut mac_data = vec![sqn];
        mac_data.extend_from_slice(&inner);
        let mac = nas_security::nas_mac_calculate(
            2,
            &ue_side.knas_int,
            0,
            1,
            nas_security::direction::UPLINK,
            &mac_data,
        );

        let mut protected = vec![0x7E, security_header::INTEGRITY_PROTECTED];
        protected.extend_from_slice(&mac);
        protected.push(sqn);
        protected.extend_from_slice(&inner);

        // Valid MAC decodes to the plaintext, no mac_failed (amfd-03 happy path).
        let mut amf_side = ue_side.clone();
        amf_side.ul_count = 0;
        let out = nas_security::nas_5gs_security_decode(&mut amf_side, protected[1], &protected)
            .expect("decode");
        assert_eq!(out, inner);
        assert!(!amf_side.mac_failed, "valid MAC must pass");

        // amfd-03 (fail-closed): a tampered MAC now hard-rejects with
        // Err(MacVerificationFailed) — the plaintext is never produced — and the
        // UL COUNT is not advanced (amfd-04 commit-after-verify).
        let mut tampered = protected.clone();
        tampered[2] ^= 0xFF;
        let mut amf_side2 = ue_side.clone();
        amf_side2.ul_count = 0;
        let res = nas_security::nas_5gs_security_decode(&mut amf_side2, tampered[1], &tampered);
        assert!(
            matches!(
                res,
                Err(nas_security::NasSecurityError::MacVerificationFailed)
            ),
            "tampered MAC must fail closed with Err, got {res:?}"
        );
        assert_eq!(
            amf_side2.ul_count, 0,
            "tampered MAC must not advance UL COUNT"
        );
    }

    #[test]
    fn test_random_tmsi_is_not_ngap_id() {
        let a = crate::context::generate_random_tmsi();
        let b = crate::context::generate_random_tmsi();
        assert_ne!(a, 0);
        assert_ne!(a, u32::MAX);
        // Two consecutive draws colliding is a 2^-32 event
        assert_ne!(a, b);
    }

    #[test]
    fn test_wire_caps_to_mask() {
        assert_eq!(wire_caps_to_mask(0xF0), 0x0F); // EA0-3 -> algorithms 0..3
        assert_eq!(wire_caps_to_mask(0x80), 0x01); // EA0 only
        assert_eq!(wire_caps_to_mask(0x20), 0x04); // EA2 only
                                                   // Selection from EA0-3 with default AMF mask prefers NEA2/NIA2
        assert_eq!(
            nas_security::select_integrity_algorithm(wire_caps_to_mask(0xF0), 0x0E),
            Some(2)
        );
    }

    #[test]
    fn test_supi_from_suci() {
        assert_eq!(
            supi_from_suci("suci-0-999-70-0-0-0-0000000001").as_deref(),
            Some("imsi-999700000000001")
        );
        // Already-de-concealed SUPIs pass through
        assert_eq!(
            supi_from_suci("imsi-001010000000001").as_deref(),
            Some("imsi-001010000000001")
        );
    }

    /// A protected (ECIES) SUCI carries ciphertext, not the MSIN, so no SUPI
    /// can be derived from it -- and the derived value would otherwise seed
    /// `nextgcore_kdf_kamf` and UECM registration (#73 criterion 5).
    ///
    /// The scheme id is the load-bearing gate, which is why the profile-A and
    /// profile-B cases below use an ALL-DIGIT scheme output: a digits-only
    /// check would pass them, and only reading the scheme id rejects them.
    #[test]
    fn supi_from_suci_refuses_a_protected_suci() {
        // ECIES profile A (scheme 1) with a scheme output that is all digits.
        assert_eq!(
            supi_from_suci("suci-0-999-70-0-1-1-0123456789012345678901234567890123456789"),
            None
        );
        // ECIES profile B (scheme 2), likewise all digits.
        assert_eq!(supi_from_suci("suci-0-999-70-0-2-1-9876543210"), None);
        // An unknown or future scheme is refused rather than treated as null.
        assert_eq!(supi_from_suci("suci-0-999-70-0-7-1-1234567890"), None);
        // A non-numeric scheme id is not silently read as the null scheme.
        assert_eq!(supi_from_suci("suci-0-999-70-0-x-1-1234567890"), None);

        // The null scheme with the SAME shape is still accepted, so the
        // rejections above are attributable to the scheme id and nothing else.
        assert_eq!(
            supi_from_suci("suci-0-999-70-0-0-1-9876543210").as_deref(),
            Some("imsi-999709876543210")
        );
    }

    #[test]
    fn supi_from_suci_refuses_malformed_input() {
        // Hex ciphertext that is not all digits (the common case).
        assert_eq!(supi_from_suci("suci-0-999-70-0-0-0-deadbeef"), None);
        // Empty MSIN.
        assert_eq!(supi_from_suci("suci-0-999-70-0-0-0-"), None);
        // Too few fields.
        assert_eq!(supi_from_suci("suci-0-999-70-0-0"), None);
        // Non-IMSI SUPI type (network-specific identifier).
        assert_eq!(supi_from_suci("suci-1-999-70-0-0-0-1234567890"), None);
        // Neither a SUCI nor an imsi- SUPI.
        assert_eq!(supi_from_suci("nai-user@example.com"), None);
        // An imsi- SUPI whose digits are not digits.
        assert_eq!(supi_from_suci("imsi-unknown"), None);
        assert_eq!(supi_from_suci("imsi-"), None);
    }

    /// Identity digit 1 lives in the HIGH NIBBLE of octet 4, alongside the
    /// type-of-identity field, so the digits do not start at `content[1]`
    /// (TS 24.501 Section 9.11.3.4). Decoding from `content[1..]` drops digit 1
    /// and yields a value one digit short (#73 criterion 4).
    ///
    /// These vectors assert the FULL digit string, so reverting the fix makes
    /// them fail on both the count and the value -- not merely on a prefix.
    #[test]
    fn decode_pei_recovers_digit_one_and_selects_the_prefix_by_type() {
        // IMEISV 1234567890123456: 16 digits, so digit 1 in octet 4's high
        // nibble plus 15 digits over 8 octets, the last high nibble a filler.
        //   octet 4 = digit1(1) << 4 | even/odd(0) | type(IMEISV=5) = 0x15
        let imeisv = [0x15, 0x32, 0x54, 0x76, 0x98, 0x10, 0x32, 0x54, 0xf6];
        let (pei, digits) = decode_pei(&imeisv).expect("IMEISV decodes");
        assert_eq!(digits, "1234567890123456");
        assert_eq!(pei, "imeisv-1234567890123456");

        // IMEI 123456789012345: 15 digits, digit 1 plus 14 over 7 octets.
        //   octet 4 = digit1(1) << 4 | odd(1) << 3 | type(IMEI=3) = 0x1b
        let imei = [0x1b, 0x32, 0x54, 0x76, 0x98, 0x10, 0x32, 0x54];
        let (pei, digits) = decode_pei(&imei).expect("IMEI decodes");
        assert_eq!(digits, "123456789012345");
        assert_eq!(pei, "imei-123456789012345");
    }

    /// Both emitted forms must satisfy the TS 29.571 `Pei` pattern
    /// (`imei-[0-9]{15}` / `imeisv-[0-9]{16}`), which is what the old
    /// unconditional `imeisv-` prefix violated for a 15-digit IMEI.
    #[test]
    fn decode_pei_output_matches_the_pei_pattern() {
        for (content, prefix, len) in [
            (
                vec![0x15, 0x32, 0x54, 0x76, 0x98, 0x10, 0x32, 0x54, 0xf6],
                "imeisv-",
                16,
            ),
            (
                vec![0x1b, 0x32, 0x54, 0x76, 0x98, 0x10, 0x32, 0x54],
                "imei-",
                15,
            ),
        ] {
            let (pei, _) = decode_pei(&content).expect("decodes");
            let digits = pei.strip_prefix(prefix).expect("expected prefix");
            assert_eq!(digits.len(), len, "{pei} has the wrong digit count");
            assert!(
                digits.bytes().all(|b| b.is_ascii_digit()),
                "{pei} is not all digits"
            );
        }
    }

    #[test]
    fn decode_pei_refuses_malformed_identities() {
        // Right type, wrong digit count (an IMEI's octets labelled IMEISV):
        // emitting this would break the `Pei` pattern.
        assert_eq!(
            decode_pei(&[0x15, 0x32, 0x54, 0x76, 0x98, 0x10, 0x32, 0x54]),
            None
        );
        // Digit 1 is a 0xF filler, not a digit.
        assert_eq!(
            decode_pei(&[0xf5, 0x32, 0x54, 0x76, 0x98, 0x10, 0x32, 0x54, 0xf6]),
            None
        );
        // Not an equipment identity at all (SUCI type).
        assert_eq!(decode_pei(&[0x11, 0x32, 0x54]), None);
        // Too short to carry a type plus any digits.
        assert_eq!(decode_pei(&[0x15]), None);
        assert_eq!(decode_pei(&[]), None);
    }

